                const payload = buildNeedBarSnapshot(npc, {
                    type: npc.isNPC ? 'npc' : 'player'
                });
                payload.applied = applied;

                res.json({
                    success: true,
                    message: applied.length ? 'Need bars updated successfully' : 'No need bar changes applied',
                    ...payload
                });
