        app.delete('/api/stubs/:id', (req, res) => {
            try {
                const stubIdRaw = req.params.id;
                const stubId = typeof stubIdRaw === 'string' ? stubIdRaw.trim() : '';
                if (!stubId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Stub ID is required'
                    });
                }
                const stubLocation = getStubLocationById(stubId);
                if (!stubLocation) {
                    return res.status(404).json({
                        success: false,
                        error: `Stub '${stubId}' not found`
                    });
                }

                const npcSummaries = listNpcsAtLocation(stubId);
                const deletedNpcIds = [];
                for (const npc of npcSummaries) {
                    const result = deleteNpcById(npc.id, { skipNotFound: true, reason: 'stub_deleted', deleteInventory: true });
                    if (result?.success) {
                        deletedNpcIds.push(npc.id);
                    }
                }

                const removedExitIds = [];
                const targetRegionId = stubLocation?.stubMetadata?.targetRegionId || stubLocation?.stubMetadata?.regionId || null;

                for (const location of gameLocations.values()) {
                    if (!location || location === stubLocation || typeof location.getAvailableDirections !== 'function') {
                        continue;
                    }
                    const directions = location.getAvailableDirections();
                    for (const direction of directions) {
                        const exit = location.getExit(direction);
                        if (!exit) {
                            continue;
                        }

                        const isDirectStubExit = exit.destination === stubId;
                        const pointsToStubRegion = Boolean(
                            targetRegionId
                            && exit.destinationRegion === targetRegionId
                            && (
                                !exit.destination // region-only reference
                                || exit.destination === stubId
                                || (getStubLocationById(exit.destination)?.stubMetadata?.targetRegionId === targetRegionId)
                            )
                        );

                        if (isDirectStubExit || pointsToStubRegion) {
                            try {
                                removeExitStrict(location, direction, exit.id || null);
                                if (exit.id) {
                                    removedExitIds.push(exit.id);
                                }
                            } catch (error) {
                                console.warn(`Failed to remove inbound exit ${exit.id || direction} pointing to stub ${stubId}:`, error?.message || error);
                            }
                        }
                    }
                }

                if (targetRegionId && pendingRegionStubs.has(targetRegionId)) {
                    pendingRegionStubs.delete(targetRegionId);
                }

                const stubRemoval = deleteStubLocation(stubLocation);
                if (stubRemoval?.removedExitIds?.length) {
                    removedExitIds.push(...stubRemoval.removedExitIds);
                }

                res.json({
                    success: true,
                    stubId,
                    targetRegionId: targetRegionId || null,
                    removedExitIds: Array.from(new Set(removedExitIds.filter(Boolean))),
                    deletedNpcIds,
                    npcSummaries
                });
            } catch (error) {
                console.error('Failed to delete stub:', error);
                return res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to delete stub'
                });
            }
        });

        app.post('/api/locations/:id/npcs', async (req, res) => {
            try {
                const locationId = req.params.id;
                if (!locationId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Location ID is required'
                    });
                }

                const location = Location.get(locationId);
                if (!location) {
                    return res.status(404).json({
                        success: false,
                        error: `Location with ID '${locationId}' not found`
                    });
                }

                const payload = req.body || {};
                const imageDataUrl = typeof payload.imageDataUrl === 'string'
                    ? payload.imageDataUrl.trim()
                    : '';
                const imageDataUrlOriginal = typeof payload.imageDataUrlOriginal === 'string'
                    ? payload.imageDataUrlOriginal.trim()
                    : '';
                const hasDownscaledImage = Boolean(imageDataUrl);
                const hasOriginalImage = Boolean(imageDataUrlOriginal);
                if (hasDownscaledImage !== hasOriginalImage) {
                    return res.status(400).json({
                        success: false,
                        error: 'NPC image uploads must include both downscaled and original image data URLs.'
                    });
                }
                if (imageDataUrl && !/^data:image\/[a-z0-9.+-]+;base64,/i.test(imageDataUrl)) {
                    return res.status(400).json({
                        success: false,
                        error: 'NPC image must be a base64-encoded data URL.'
                    });
                }
                if (imageDataUrlOriginal && !/^data:image\/[a-z0-9.+-]+;base64,/i.test(imageDataUrlOriginal)) {
                    return res.status(400).json({
                        success: false,
                        error: 'NPC original image must be a base64-encoded data URL.'
                    });
                }
                if (imageDataUrlOriginal) {
                    const originalMatch = imageDataUrlOriginal.match(/^data:(image\/[a-z0-9.+-]+);base64,/i);
                    if (!originalMatch || originalMatch[1].toLowerCase() !== 'image/png') {
                        return res.status(400).json({
                            success: false,
                            error: 'NPC portrait image must be a PNG data URL.'
                        });
                    }
                }
                const nameValue = typeof payload.name === 'string' ? payload.name.trim() : '';
                const region = findRegionByLocationId(location.id) || null;
                const trimText = (value) => {
                    if (typeof value !== 'string') {
                        return '';
                    }
                    const trimmed = value.trim();
                    return trimmed.length ? trimmed : '';
                };

                const npcSeed = { name: nameValue };

                const description = trimText(payload.description);
                if (description) {
                    npcSeed.description = description;
                }

                const aiNotes = trimText(payload.aiNotes);
                if (aiNotes) {
                    npcSeed.aiNotes = aiNotes;
                }

                const notes = trimText(payload.notes);

                const shortDescription = trimText(payload.shortDescription);
                if (shortDescription) {
                    npcSeed.shortDescription = shortDescription;
                }

                const role = trimText(payload.role);
                if (role) {
                    npcSeed.role = role;
                }

                const className = trimText(payload.class);
                if (className) {
                    npcSeed.class = className;
                }

                const race = trimText(payload.race);
                if (race) {
                    npcSeed.race = race;
                }

                if (Object.prototype.hasOwnProperty.call(payload, 'isHostile')) {
                    npcSeed.isHostile = Boolean(payload.isHostile);
                }

                if (payload.currency !== undefined && payload.currency !== null && payload.currency !== '') {
                    const currencyValue = Number(payload.currency);
                    if (Number.isFinite(currencyValue) && currencyValue >= 0) {
                        npcSeed.currency = Math.max(0, Math.round(currencyValue));
                    }
                }

                if (payload.level !== undefined && payload.level !== null && payload.level !== '') {
                    const absoluteLevel = Number(payload.level);
                    if (Number.isFinite(absoluteLevel)) {
                        const locationBaseLevel = Number.isFinite(Number(location.baseLevel))
                            ? Number(location.baseLevel)
                            : (Number.isFinite(region?.averageLevel) ? Number(region.averageLevel) : (currentPlayer?.level || 1));
                        npcSeed.relativeLevel = absoluteLevel - locationBaseLevel;
                    }
                }

                const generatedNpc = await generateNpcFromEvent({
                    name: nameValue,
                    npc: npcSeed,
                    location,
                    region,
                    imageDataUrl,
                    portraitImageDataUrl: imageDataUrlOriginal,
                    additionalInstructions: notes
                });

                if (!generatedNpc) {
                    throw new Error('Failed to generate NPC');
                }

                const locationData = buildLocationResponse(location);
                const npcStatus = typeof generatedNpc.getStatus === 'function'
                    ? serializeNpcForClient(generatedNpc)
                    : null;

                res.json({
                    success: true,
                    npc: npcStatus,
                    location: locationData,
                    message: `${generatedNpc.name || nameValue} has been created.`
                });
            } catch (error) {
                console.error('Error generating NPC:', error);
                res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to generate NPC'
                });
            }
        });

        app.post('/api/locations/:id/things', async (req, res) => {
            try {
                const locationId = req.params.id;
                if (!locationId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Location ID is required'
                    });
                }

                let location = null;
                try {
                    location = Location.get(locationId);
                } catch (_) {
                    location = null;
                }

                if (!location) {
                    return res.status(404).json({
                        success: false,
                        error: `Location with ID '${locationId}' not found`
                    });
                }

                const payload = req.body || {};
                const rawSeed = payload.seed || {};
                const rawName = typeof rawSeed.name === 'string' ? rawSeed.name.trim() : '';

                const region = findRegionByLocationId(location.id) || null;

                const normalizeSeedString = (value) => {
                    if (typeof value !== 'string') {
                        return '';
                    }
                    const trimmed = value.trim();
                    return trimmed.length ? trimmed : '';
                };

                const seed = {
                    description: normalizeSeedString(rawSeed.description),
                    shortDescription: normalizeSeedString(rawSeed.shortDescription),
                    type: normalizeSeedString(rawSeed.type),
                    slot: normalizeSeedString(rawSeed.slot),
                    rarity: normalizeSeedString(rawSeed.rarity),
                    isVehicle: Boolean(rawSeed.isVehicle),
                    isHarvestable: Boolean(rawSeed.isHarvestable),
                    isCraftingStation: Boolean(rawSeed.isCraftingStation),
                    isProcessingStation: Boolean(rawSeed.isProcessingStation),
                    isSalvageable: Boolean(rawSeed.isSalvageable),
                    isContainer: Boolean(rawSeed.isContainer),
                    requiresCheckToOpen: Boolean(rawSeed.requiresCheckToOpen)
                };
                if (rawName) {
                    seed.name = rawName;
                }

                const notes = normalizeSeedString(rawSeed.notes || payload.notes);
                if (notes) {
                    seed.notes = notes;
                }

                const rawItemOrScenery = normalizeSeedString(rawSeed.itemOrScenery);
                if (rawItemOrScenery) {
                    const normalizedItemOrScenery = rawItemOrScenery.toLowerCase();
                    if (normalizedItemOrScenery !== 'item' && normalizedItemOrScenery !== 'scenery') {
                        return res.status(400).json({
                            success: false,
                            error: `Invalid itemOrScenery "${rawItemOrScenery}". Use "item", "scenery", or omit it.`
                        });
                    }
                    seed.itemOrScenery = normalizedItemOrScenery;
                }

                if (rawSeed.value !== undefined && rawSeed.value !== null && rawSeed.value !== '') {
                    const numericValue = Number(rawSeed.value);
                    seed.value = Number.isFinite(numericValue) ? numericValue : rawSeed.value;
                }

                if (rawSeed.weight !== undefined && rawSeed.weight !== null && rawSeed.weight !== '') {
                    const numericWeight = Number(rawSeed.weight);
                    seed.weight = Number.isFinite(numericWeight) ? numericWeight : rawSeed.weight;
                }

                let absoluteLevel = null;
                if (payload.level !== undefined && payload.level !== null && payload.level !== '') {
                    const levelValue = Number(payload.level);
                    if (Number.isFinite(levelValue)) {
                        absoluteLevel = Math.max(1, Math.round(levelValue));
                    }
                } else if (rawSeed.level !== undefined && rawSeed.level !== null && rawSeed.level !== '') {
                    const levelValue = Number(rawSeed.level);
                    if (Number.isFinite(levelValue)) {
                        absoluteLevel = Math.max(1, Math.round(levelValue));
                    }
                }

                if (Number.isFinite(absoluteLevel)) {
                    const baseReference = Number.isFinite(Number(location.baseLevel))
                        ? Number(location.baseLevel)
                        : (Number.isFinite(Number(location.level))
                            ? Number(location.level)
                            : (Number.isFinite(Number(region?.averageLevel))
                                ? Number(region.averageLevel)
                                : (Number.isFinite(Number(currentPlayer?.level))
                                    ? Number(currentPlayer.level)
                                    : 1)));

                    const relativeLevel = absoluteLevel - baseReference;
                    seed.relativeLevel = Math.max(-10, Math.min(10, Math.round(relativeLevel)));
                } else if (rawSeed.relativeLevel !== undefined && rawSeed.relativeLevel !== null && rawSeed.relativeLevel !== '') {
                    const relativeCandidate = Number(rawSeed.relativeLevel);
                    if (Number.isFinite(relativeCandidate)) {
                        seed.relativeLevel = Math.max(-10, Math.min(10, Math.round(relativeCandidate)));
                    }
                }

                const createdItems = await generateItemsByNames({
                    itemNames: rawName ? [rawName] : [],
                    location,
                    region,
                    seeds: [seed]
                });

                let generatedThing = null;
                if (Array.isArray(createdItems) && createdItems.length) {
                    generatedThing = createdItems[0];
                }
                if (!generatedThing && rawName) {
                    generatedThing = findThingByName(rawName);
                }
                if (!generatedThing) {
                    throw new Error('Failed to generate item.');
                }

                if (seed.shortDescription) {
                    try {
                        generatedThing.shortDescription = seed.shortDescription;
                    } catch (shortDescriptionError) {
                        console.warn('Failed to set short description on generated item:', shortDescriptionError.message);
                    }
                }

                const locationData = buildLocationResponse(location);
                const thingJson = typeof generatedThing.toJSON === 'function'
                    ? generatedThing.toJSON()
                    : generatedThing;

                res.json({
                    success: true,
                    thing: thingJson,
                    location: locationData,
                    message: `${thingJson.name || rawName || 'Item'} has been created.`
                });
            } catch (error) {
                console.error('Error generating item:', error);
                res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to generate item'
                });
            }
        });

        // Preview player fast-travel timing without moving the player.
        app.get('/api/player/fast-travel-preview', (req, res) => {
            try {
                if (!currentPlayer) {
                    return res.status(404).json({
                        success: false,
                        error: 'No current player found'
                    });
                }

                const destinationId = typeof req.query?.destinationId === 'string'
                    ? req.query.destinationId.trim()
                    : '';
                if (!destinationId) {
                    return res.status(400).json({
                        success: false,
                        error: 'destinationId is required.'
                    });
                }

                const sourceLocationId = typeof currentPlayer.currentLocation === 'string'
                    ? currentPlayer.currentLocation.trim()
                    : '';
                if (!sourceLocationId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Current player location is unavailable.'
                    });
                }

                const resolveLocationById = (locationId) => {
                    if (!locationId) {
                        return null;
                    }
                    if (gameLocations instanceof Map && gameLocations.has(locationId)) {
                        return gameLocations.get(locationId) || null;
                    }
                    try {
                        return Location.get(locationId) || null;
                    } catch (_) {
                        return null;
                    }
                };

                const resolveLocationRegionName = (location) => {
                    const regionId = location?.regionId || location?.stubMetadata?.regionId || null;
                    if (!regionId || !(regions instanceof Map)) {
                        return null;
                    }
                    const region = regions.get(regionId);
                    const rawName = typeof region?.name === 'string' ? region.name.trim() : '';
                    return rawName || null;
                };

                const sourceLocation = resolveLocationById(sourceLocationId);
                if (!sourceLocation) {
                    return res.status(404).json({
                        success: false,
                        error: `Current location '${sourceLocationId}' not found.`
                    });
                }

                const destinationLocation = resolveLocationById(destinationId);
                if (!destinationLocation) {
                    return res.status(404).json({
                        success: false,
                        error: `Destination location '${destinationId}' not found.`
                    });
                }

                const fastTravelTimeMinutes = resolveFastTravelTimeForTraversal({
                    sourceLocation,
                    destinationLocation
                });

                res.json({
                    success: true,
                    origin: {
                        id: sourceLocation.id,
                        name: sourceLocation.name || sourceLocation.id,
                        regionName: resolveLocationRegionName(sourceLocation)
                    },
                    destination: {
                        id: destinationLocation.id,
                        name: destinationLocation.name || destinationLocation.id,
                        regionName: resolveLocationRegionName(destinationLocation)
                    },
                    travelTimeMinutes: fastTravelTimeMinutes
                });
            } catch (error) {
                console.error('Error previewing player fast travel:', error);
                res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to preview fast travel.'
                });
            }
        });

        // Move player to a connected location
        app.post('/api/player/move', async (req, res) => {
            let releasePlayerMoveLock = null;
            try {
                if (!currentPlayer) {
                    return res.status(404).json({
                        success: false,
                        error: 'No current player found'
                    });
                }
                if (typeof Globals.clearPlayerArrivalVisitStates === 'function') {
                    Globals.clearPlayerArrivalVisitStates();
                }

                const currentPlayerId = typeof currentPlayer.id === 'string' ? currentPlayer.id.trim() : '';
                if (!currentPlayerId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Current player is missing a valid id.'
                    });
                }

                const pendingAbilitySelection = await resolvePendingPlayerAbilitySelection({
                    ensureOptionsForNext: false
                });
                if (pendingAbilitySelection) {
                    return res.status(409).json({
                        success: false,
                        error: 'Player ability selection is required before moving.',
                        pendingAbilitySelection,
                        player: serializeNpcForClient(currentPlayer)
                    });
                }

                releasePlayerMoveLock = tryAcquirePlayerMoveLock(currentPlayerId, '/api/player/move');
                if (!releasePlayerMoveLock) {
                    return res.status(409).json({
                        success: false,
                        error: 'Another move is already in progress for this player.'
                    });
                }

	                const { destinationId, direction, expectedOriginLocationId } = req.body || {};
	                const accompanyingCharacters = req.body?.accompanyingCharacters === undefined
	                    ? []
	                    : req.body.accompanyingCharacters;
	                if (!Array.isArray(accompanyingCharacters)
	                    || accompanyingCharacters.some(name => typeof name !== 'string' || !name.trim())) {
	                    return res.status(400).json({
	                        success: false,
	                        error: 'accompanyingCharacters must be an array of non-empty exact names or aliases.'
	                    });
	                }
	                const clientId = typeof req.body?.clientId === 'string' && req.body.clientId.trim()
	                    ? req.body.clientId.trim()
	                    : null;
                if (!destinationId && !direction) {
                    return res.status(400).json({
                        success: false,
                        error: 'Destination ID or direction is required'
                    });
                }

                const normalizedExpectedOrigin = typeof expectedOriginLocationId === 'string'
                    ? expectedOriginLocationId.trim()
                    : '';
                if (!normalizedExpectedOrigin) {
                    return res.status(400).json({
                        success: false,
                        error: 'expectedOriginLocationId is required.'
                    });
                }

                const currentLocationId = currentPlayer.currentLocation;
                if (currentLocationId !== normalizedExpectedOrigin) {
                    return res.status(409).json({
                        success: false,
                        error: `Move origin mismatch (expected '${normalizedExpectedOrigin}', current '${currentLocationId || 'none'}').`
                    });
                }
                const currentLocation = currentLocationId ? gameLocations.get(currentLocationId) : null;
                if (!currentLocation) {
                    return res.status(400).json({
                        success: false,
                        error: 'Current location not found in game world'
                    });
                }

                const preMoveRegionMembershipConflict = findFirstLocationRegionMembershipConflict();
                if (preMoveRegionMembershipConflict) {
                    return res.status(409).json(
                        buildLocationRegionMembershipConflictResponse(preMoveRegionMembershipConflict)
                    );
                }

                const vehicleArrivalsThisTurn = await processDueVehicleArrivals();
                const npcIdsSharingPlayerLocationAtTurnStart = Player.getNpcIdsSharingPlayerLocation({
                    player: currentPlayer,
                    locationId: currentLocationId
                });

                const directions = currentLocation.getAvailableDirections();
                let matchedExit = null;
                let matchedDirection = null;
                for (const dir of directions) {
                    const exit = currentLocation.getExit(dir);
                    if (!exit) continue;
                    if (destinationId && exit.destination === destinationId) {
                        matchedExit = exit;
                        matchedDirection = dir;
                        break;
                    }
                    if (!destinationId && direction && dir === direction) {
                        matchedExit = exit;
                        matchedDirection = dir;
                        break;
                    }
                }

                if (!matchedExit) {
                    return res.status(404).json({
                        success: false,
                        error: 'Requested exit not found from the current location.'
                    });
                }

	                let destinationLocation = gameLocations.get(matchedExit.destination);
	                if (!destinationLocation) {
	                    return res.status(404).json({
                        success: false,
                        error: 'Destination location not found'
                    });
                }

                if (destinationLocation.isStub && destinationLocation.stubMetadata?.isRegionEntryStub) {
                    try {
                        const expanded = await expandRegionEntryStub(destinationLocation);
                        if (expanded) {
                            destinationLocation = expanded;
                        } else {
                            return res.status(500).json({
                                success: false,
                                error: 'Failed to generate destination region.'
                            });
                        }
                    } catch (expansionError) {
                        console.error('Failed to expand region entry stub:', expansionError);
                        return res.status(500).json({
                            success: false,
                            error: `Failed to expand region: ${expansionError.message}`,
                            trace: expansionError.stack || String(expansionError)
                        });
                    }
                }

                if (destinationLocation.isStub && !destinationLocation.stubMetadata?.isRegionEntryStub) {
                    try {
                        await scheduleStubExpansion(destinationLocation);
                        destinationLocation = gameLocations.get(destinationLocation.id);
                    } catch (expansionError) {
                        return res.status(500).json({
                            success: false,
                            error: `Failed to expand destination location: ${expansionError.message}`
                        });
                    }
                }

                try {
                    const transitBlock = resolveVehicleExitTransitBlock({
                        exit: matchedExit,
                        sourceLocation: currentLocation,
                        destinationLocation,
                        destinationRegionId: matchedExit.destinationRegion || null,
                        contextLabel: `Player move exit "${matchedExit.id || matchedDirection || matchedExit.destination}"`
                    });
	                    if (transitBlock.blocked) {
	                        const errorMessage = transitBlock.reason === 'source_underway'
	                            ? 'Cannot disembark while the vehicle is underway.'
                            : transitBlock.reason === 'source_arrival_pending'
                                ? 'Cannot disembark while the vehicle arrival is still being processed.'
                                : transitBlock.reason === 'destination_arrival_pending'
                                    ? 'Cannot board a vehicle while its arrival is still being processed.'
                                    : 'Cannot board a vehicle while it is underway.';
                        return res.status(409).json({
                            success: false,
                            error: errorMessage
                        });
                    }
	                } catch (vehicleTransitError) {
	                    return res.status(500).json({
	                        success: false,
	                        error: vehicleTransitError?.message || 'Failed to evaluate vehicle transit state.'
	                    });
	                }

		                const matchedExitId = typeof matchedExit?.id === 'string' ? matchedExit.id.trim() : '';
	                const currentLocationVehicleExitId = typeof currentLocation?.vehicleInfo?.vehicleExitId === 'string'
	                    ? currentLocation.vehicleInfo.vehicleExitId.trim()
                    : '';
                const matchedTrackedVehicleExit = Boolean(
                    currentLocation?.isVehicle === true
                    && matchedExitId
                    && currentLocationVehicleExitId
                    && matchedExitId === currentLocationVehicleExitId
                );
                if (matchedExit.isVehicle === true || matchedTrackedVehicleExit) {
                    const activeVehicleArrivalsThisTurn = filterVehicleArrivalRecordsForContext(
                        vehicleArrivalsThisTurn,
                        { location: currentLocation }
                    );
                    if (activeVehicleArrivalsThisTurn.length > 0) {
                        const destinationMatchRecord = buildmoveTurnResultDestinationMatchRecord({
                            resolvedLocation: destinationLocation
                        });
                        const arrivedThisTurn = activeVehicleArrivalsThisTurn.some(arrival =>
                            vehicleArrivalMatchesDestinationRecord(arrival, destinationMatchRecord)
                        );
                        if (arrivedThisTurn) {
                            return res.status(409).json({
                                success: false,
                                error: 'Cannot disembark on the same turn the vehicle arrives. Try again next turn.'
                            });
	                        }
	                    }
	                }

	                await maybeBackfillRegionExitTravelTimesForArrival({
	                    originLocation: currentLocation,
	                    destinationLocation,
	                    findRegionByLocationId,
	                    backfillRegionExitTravelTimes
	                });

	                const exitTravelTimeMinutes = resolveExitTravelTimeForTraversal({
	                    exit: matchedExit,
	                    sourceLocation: currentLocation
	                });

	                const previousLocationIdForMemories = currentPlayer.currentLocation || null;
                let exitTravelTimeAdjustment = null;

                if (typeof Globals.recordPlayerArrivalVisitState === 'function') {
                    Globals.recordPlayerArrivalVisitState(destinationLocation);
                }
                currentPlayer.setLocation(destinationLocation.id);
                if (currentPlayer.currentLocation !== destinationLocation.id) {
                    throw new Error(`Player did not reach direct-move destination "${destinationLocation.id}".`);
                }
                movePlayerActionAccompanyingCharacters({
                    characterNames: accompanyingCharacters,
                    currentPlayer,
                    originLocation: currentLocation,
                    destinationLocation,
                    players,
                    gameLocations
                });

                if (currentPlayer?.lastActionWasTravel) {
                    const travelEntry = findMostRecentTravelEntry();
                    if (!travelEntry) {
                        throw new Error('Travel action entry not found for traveledToLocationId.');
                    }
                    applyTraveledToLocationMetadata(travelEntry, destinationLocation.id, 'travel destination');
                }

                if (typeof currentPlayer.getPartyMembers === 'function') {
                    const partyMemberIds = currentPlayer.getPartyMembers();
                    if (Array.isArray(partyMemberIds) || partyMemberIds instanceof Set) {
                        const memberIds = Array.isArray(partyMemberIds)
                            ? partyMemberIds
                            : Array.from(partyMemberIds);

                        for (const memberId of memberIds) {
                            const member = players.get(memberId);
                            if (!member) {
                                continue;
                            }

                            const previousLocationId = member.currentLocation;
                            if (previousLocationId && gameLocations.has(previousLocationId)) {
                                const previousLocation = gameLocations.get(previousLocationId);
                                if (previousLocation && typeof previousLocation.removeNpcId === 'function') {
                                    previousLocation.removeNpcId(member.id);
                                }
                            }

                            try {
                                member.setLocation(null);
                            } catch (memberError) {
                                console.warn(`Failed to preserve off-location party ownership for ${member.name || member.id}:`, memberError.message);
                                continue;
                            }

                            if (member.isNPC && typeof destinationLocation.removeNpcId === 'function') {
                                destinationLocation.removeNpcId(member.id);
                            }
                        }
                    }
                }

                if (exitTravelTimeMinutes > 0) {
                    exitTravelTimeAdjustment = await adjustWorldTimeByMinutes(exitTravelTimeMinutes, {
                        source: 'location_exit_travel',
                        emitClientRefresh: false
                    });
                }

                assertMovementGraphIntegrity({
                    player: currentPlayer,
                    context: '/api/player/move'
                });

                queueNpcAssetsForLocation(destinationLocation);
                try {
                    queueLocationThingImages(destinationLocation);
                } catch (thingQueueError) {
                    console.warn('Failed to queue thing images after moving:', thingQueueError.message);
                }

                // Populate region secrets if missing when entering a non-stub region
                try {
                    const destinationRegionId = destinationLocation.regionId
                        || destinationLocation.stubMetadata?.regionId
                        || destinationLocation.stubMetadata?.targetRegionId
                        || null;
                    if (destinationRegionId && regions.has(destinationRegionId)) {
                        const destinationRegion = regions.get(destinationRegionId);
                        if (!destinationRegion?.isStub && Array.isArray(destinationRegion?.secrets) && destinationRegion.secrets.length === 0) {
                            Globals.region = destinationRegion;
                            triggerRegionSecretsForCurrentRegion();
                        }
                    }
                } catch (secretError) {
                    console.warn('Failed to ensure region secrets after move:', secretError?.message || secretError);
                }

	                const whileYouWereAwayResult = await runWhileYouWereAwayPrompt({
	                    locationOverride: destinationLocation,
	                    originLocationOverride: currentLocation,
	                    locationId: destinationLocation.id,
	                    returnEntries: true,
	                    clientId,
	                    locationWasVisitedBeforeArrival: typeof Globals.getPlayerArrivalWasVisitedBeforeMove === 'function'
	                        ? Globals.getPlayerArrivalWasVisitedBeforeMove(destinationLocation.id)
	                        : undefined,
                    locationLastVisitedTimeBeforeArrival: typeof Globals.getPlayerArrivalLastVisitedTimeBeforeMove === 'function'
                        ? Globals.getPlayerArrivalLastVisitedTimeBeforeMove(destinationLocation.id)
                        : undefined
                });
                const travelSummaryParentEntry = whileYouWereAwayResult?.visibleEntry
                    || findMostRecentTravelDrawerParentEntry();
                const travelSummaryParentId = travelSummaryParentEntry?.id || null;

                const directTravelSummaryItem = buildFastTravelSummaryItem({
                    originLocation: currentLocation,
                    destinationLocation,
                    travelTimeMinutes: exitTravelTimeMinutes,
                    includeDuration: false
                });
                if (directTravelSummaryItem) {
                    recordEventSummaryEntry({
                        label: '📋 Events',
                        events: [directTravelSummaryItem],
                        timeProgress: exitTravelTimeAdjustment?.timeProgress || null,
                        timestamp: travelSummaryParentEntry?.timestamp || new Date().toISOString(),
                        parentId: travelSummaryParentId,
                        locationId: destinationLocation.id
                    });
                }

                const lastActionWasTravel = Boolean(currentPlayer?.lastActionWasTravel);
                const consecutiveTravelActions = Number(currentPlayer?.consecutiveTravelActions) || 0;

                if (!(lastActionWasTravel && consecutiveTravelActions >= 2)
                    && previousLocationIdForMemories
                    && previousLocationIdForMemories !== destinationLocation.id) {
                    generateNpcMemoriesForLocationChange({
                        previousLocationId: previousLocationIdForMemories,
                        newLocationId: destinationLocation.id,
                        player: currentPlayer
                    }).catch(memoryError => {
                        console.warn('Failed to generate NPC memories after direct move:', memoryError.message || memoryError);
                    });
                } else if (lastActionWasTravel && consecutiveTravelActions >= 2) {
                    console.log('🧠 Skipping NPC memory generation: consecutive travel actions detected during move request.');
                }

                await runAutomaticHiddenNpcChecksForCurrentPlayer({
                    player: currentPlayer,
                    locationId: destinationLocation.id,
                    previouslySharedNpcIds: npcIdsSharingPlayerLocationAtTurnStart,
                    parentId: travelSummaryParentId,
                    requestId: null
                });

                const locationData = buildLocationResponse(destinationLocation);
                if (!locationData) {
                    return res.status(500).json({
                        success: false,
                        error: 'Failed to serialize destination location.'
                    });
                }

                Player.recordNpcSightingsForCurrentPlayer({
                    player: currentPlayer,
                    locationId: destinationLocation.id,
                    previouslySharedNpcIds: npcIdsSharingPlayerLocationAtTurnStart
                });

                res.json({
                    success: true,
                    location: locationData,
                    player: serializeNpcForClient(currentPlayer),
                    worldTime: exitTravelTimeAdjustment?.worldTime || buildWorldTimePayload(),
                    timeProgress: exitTravelTimeAdjustment?.timeProgress || null,
                    message: `Moved to ${locationData.name || locationData.id}`,
                    direction: matchedDirection
                });
            } catch (error) {
                console.error('Error moving player:', error);
                if (error?.code === LOCATION_REGION_MEMBERSHIP_CONFLICT_CODE) {
                    return res.status(409).json(buildLocationRegionMembershipConflictResponse(error.conflict));
                }
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            } finally {
                if (typeof releasePlayerMoveLock === 'function') {
                    releasePlayerMoveLock();
                    releasePlayerMoveLock = null;
                }
            }
        });

        function resolveVehicleIconFromInfoForMap(vehicleInfo) {
            if (!vehicleInfo || typeof vehicleInfo !== 'object' || Array.isArray(vehicleInfo)) {
                return null;
            }
            const rawIcon = typeof vehicleInfo.icon === 'string' ? vehicleInfo.icon.trim() : '';
            return rawIcon || null;
        }

        function buildMapLocationSummary(location) {
            if (!location) {
                return null;
            }

            const availableDirections = typeof location.getAvailableDirections === 'function'
                ? Array.from(location.getAvailableDirections())
                : [];

            const stubMetadata = location.stubMetadata || {};
            const resolvedName = typeof location.name === 'string' && location.name.trim()
                ? location.name.trim()
                : (
                    typeof stubMetadata.shortDescription === 'string' && stubMetadata.shortDescription.trim()
                        ? stubMetadata.shortDescription.trim()
                        : (
                            typeof stubMetadata.targetRegionName === 'string' && stubMetadata.targetRegionName.trim()
                                ? stubMetadata.targetRegionName.trim()
                                : (typeof location.description === 'string' && location.description.trim()
                                    ? location.description.trim()
                                    : location.id)
                        )
                );
            const locationRepresentsVehicle = Boolean(
                location.isVehicle === true
                || (location.vehicleInfo && typeof location.vehicleInfo === 'object' && !Array.isArray(location.vehicleInfo))
            );
            const sourceRegionId = location.regionId || stubMetadata.regionId || null;
            const sourceRegion = sourceRegionId && regions instanceof Map && regions.has(sourceRegionId)
                ? regions.get(sourceRegionId)
                : null;
            const sourceRegionRepresentsVehicle = Boolean(
                sourceRegion
                && (
                    sourceRegion.isVehicle === true
                    || (sourceRegion.vehicleInfo && typeof sourceRegion.vehicleInfo === 'object' && !Array.isArray(sourceRegion.vehicleInfo))
                )
            );
            const sourceContextIsVehicle = Boolean(locationRepresentsVehicle || sourceRegionRepresentsVehicle);
            const sourceLocationVehicleExitId = typeof location?.vehicleInfo?.vehicleExitId === 'string'
                ? location.vehicleInfo.vehicleExitId.trim()
                : '';
            const locationVehicleIcon = locationRepresentsVehicle
                ? (resolveVehicleIconFromInfoForMap(location.vehicleInfo) || '🚗')
                : null;

            const exits = availableDirections.map(direction => {
                const exit = typeof location.getExit === 'function' ? location.getExit(direction) : null;
                const destinationRegionId = exit?.destinationRegion || null;
                const destinationLocation = exit?.destination && gameLocations instanceof Map
                    ? gameLocations.get(exit.destination)
                    : null;
                const destinationName = destinationLocation?.name
                    || destinationLocation?.stubMetadata?.blueprintDescription
                    || null;
                const destinationIsStub = Boolean(destinationLocation?.isStub);
                const destinationIsRegionEntryStub = Boolean(destinationLocation?.stubMetadata?.isRegionEntryStub);
                const destinationVisited = destinationLocation
                    ? Boolean(destinationLocation.visited)
                    : false;
                const pendingRegion = destinationRegionId && typeof pendingRegionStubs !== 'undefined' && pendingRegionStubs?.get
                    ? pendingRegionStubs.get(destinationRegionId)
                    : null;
                const destinationStubMetadata = destinationLocation?.stubMetadata || null;
                const destinationRegion = destinationRegionId && regions instanceof Map && regions.has(destinationRegionId)
                    ? regions.get(destinationRegionId)
                    : null;
                const destinationLocationRepresentsVehicle = Boolean(
                    destinationLocation
                    && (
                        destinationLocation.isVehicle === true
                        || (destinationLocation.vehicleInfo && typeof destinationLocation.vehicleInfo === 'object' && !Array.isArray(destinationLocation.vehicleInfo))
                    )
                );
                const destinationRegionRepresentsVehicle = Boolean(
                    destinationRegion
                    && (
                        destinationRegion.isVehicle === true
                        || (destinationRegion.vehicleInfo && typeof destinationRegion.vehicleInfo === 'object' && !Array.isArray(destinationRegion.vehicleInfo))
                    )
                );
                const pendingRegionRepresentsVehicle = Boolean(
                    pendingRegion
                    && pendingRegion.vehicleInfo
                    && typeof pendingRegion.vehicleInfo === 'object'
                    && !Array.isArray(pendingRegion.vehicleInfo)
                );
                const destinationStubRepresentsVehicle = Boolean(
                    destinationStubMetadata
                    && destinationStubMetadata.vehicleInfo
                    && typeof destinationStubMetadata.vehicleInfo === 'object'
                    && !Array.isArray(destinationStubMetadata.vehicleInfo)
                );

                let destinationRegionName = null;
                let destinationRegionExpanded = false;
                const isVehicleExit = Boolean(exit?.isVehicle);
                const exitId = typeof exit?.id === 'string' ? exit.id.trim() : '';
                const matchesTrackedLocationVehicleExit = Boolean(
                    locationRepresentsVehicle
                    && !sourceRegionRepresentsVehicle
                    && exitId
                    && sourceLocationVehicleExitId
                    && exitId === sourceLocationVehicleExitId
                );
                let isVehicleOutbound = Boolean(isVehicleExit && sourceContextIsVehicle);
                const isVehicleInbound = Boolean(isVehicleExit && !sourceContextIsVehicle);
                let vehicleIcon = null;

                if (isVehicleExit || matchesTrackedLocationVehicleExit) {
                    let hideVehicleExit = false;
                    try {
                        hideVehicleExit = shouldHideVehicleExitFromList({
                            exit,
                            sourceLocation: location,
                            destinationLocation,
                            destinationRegionId,
                            pendingRegion,
                            contextLabel: `Map exit "${exit?.id || direction}" from "${location.id}"`
                        });
                    } catch (vehicleTransitError) {
                        console.warn(
                            `Failed to evaluate vehicle transit state for map exit "${exit?.id || direction}" from "${location.id}":`,
                            vehicleTransitError?.message || vehicleTransitError
                        );
                    }

                    if (hideVehicleExit) {
                        logVehicleDebug('buildMapLocationSummary vehicle exit hidden (vehicle in transit)', {
                            sourceLocationId: location.id,
                            sourceRegionId,
                            destinationId: exit?.destination || null,
                            destinationRegionId,
                            isVehicleOutbound,
                            isVehicleInbound
                        });
                        return null;
                    }
                }

                if (destinationRegionId) {
                    if (regions instanceof Map && regions.has(destinationRegionId)) {
                        const targetRegion = regions.get(destinationRegionId);
                        destinationRegionName = targetRegion?.name || null;
                        destinationRegionExpanded = true;
                    } else if (pendingRegion) {
                        if (pendingRegion) {
                            destinationRegionName = pendingRegion.name || null;
                        }
                    }
                }

                const destinationRepresentsVehicle = destinationLocationRepresentsVehicle
                    || (destinationRegionId
                        ? (destinationRegionExpanded
                            ? destinationRegionRepresentsVehicle
                            : (pendingRegionRepresentsVehicle || destinationStubRepresentsVehicle))
                        : destinationStubRepresentsVehicle);
                const suppressCurrentRegionVehicleIconCandidate = shouldSuppressCurrentRegionVehicleIconCandidate({
                    sourceRegionId,
                    sourceRegionRepresentsVehicle,
                    destinationRegionId
                });
                const suppressDestinationVehicleIcon = shouldSuppressCurrentRegionVehicleDestinationIcon({
                    sourceRegionId,
                    sourceRegionRepresentsVehicle,
                    destinationRegionId,
                    destinationLocationRepresentsVehicle,
                    pendingRegionRepresentsVehicle,
                    destinationStubRepresentsVehicle
                });
                const isLocationVehicleOutbound = Boolean(
                    locationRepresentsVehicle
                    && !sourceRegionRepresentsVehicle
                    && !destinationRepresentsVehicle
                    && (
                        !sourceLocationVehicleExitId
                        || matchesTrackedLocationVehicleExit
                    )
                );
                isVehicleOutbound = Boolean(isVehicleOutbound || isLocationVehicleOutbound);

                if (destinationRepresentsVehicle && !suppressDestinationVehicleIcon) {
                    vehicleIcon = resolveVehicleIconFromInfoForMap(destinationLocation?.vehicleInfo);
                    if (!vehicleIcon && destinationRegion && !suppressCurrentRegionVehicleIconCandidate) {
                        vehicleIcon = resolveVehicleIconFromInfoForMap(destinationRegion?.vehicleInfo);
                    }
                    if (!vehicleIcon && destinationRegionId && pendingRegion) {
                        vehicleIcon = resolveVehicleIconFromInfoForMap(pendingRegion?.vehicleInfo);
                    }
                    if (!vehicleIcon) {
                        vehicleIcon = resolveVehicleIconFromInfoForMap(destinationLocation?.stubMetadata?.vehicleInfo);
                    }
                }
                if (!vehicleIcon && destinationRepresentsVehicle && !suppressDestinationVehicleIcon) {
                    vehicleIcon = '🚗';
                }

                if (isVehicleExit) {
                    logVehicleDebug('buildMapLocationSummary vehicle exit resolved', {
                        sourceLocationId: location.id,
                        sourceRegionId,
                        sourceContextIsVehicle,
                        destinationId: exit?.destination || null,
                        destinationRegionId,
                        isVehicleOutbound,
                        isVehicleInbound,
                        vehicleIcon: vehicleIcon || null,
                        suppressCurrentRegionVehicleIconCandidate,
                        suppressDestinationVehicleIcon
                    });
                }

                return {
                    id: exit?.id || `${location.id}_${direction}`,
                    destination: exit?.destination || null,
                    destinationRegion: destinationRegionId,
                    travelTimeMinutes: Number.isInteger(exit?.travelTimeMinutes) ? exit.travelTimeMinutes : 0,
                    destinationRegionName,
                    destinationRegionExpanded,
                    destinationName,
                    bidirectional: exit?.bidirectional !== false,
                    isVehicle: isVehicleExit,
                    isVehicleOutbound,
                    isVehicleInbound,
                    vehicleType: exit?.vehicleType || null,
                    vehicleIcon,
                    destinationIsStub,
                    destinationIsRegionEntryStub,
                    destinationVisited
                };
            }).filter(Boolean);

            const payload = {
                id: location.id,
                name: resolvedName,
                isStub: Boolean(location.isStub),
                isVehicle: locationRepresentsVehicle,
                vehicleIcon: locationVehicleIcon,
                visited: Boolean(location.visited),
                favorite: Boolean(location.favorite),
                regionId: location.regionId || stubMetadata.regionId || null,
                exits
            };

            if (location.imageId) {
                const metadata = generatedImages?.get ? generatedImages.get(location.imageId) : null;
                const firstImage = metadata?.images?.[0];
                payload.image = firstImage
                    ? { id: location.imageId, url: firstImage.url }
                    : { id: location.imageId, url: null };
            }

            return payload;
        }

        app.get('/api/map/region', (req, res) => {
            try {
                let requestedRegionId = null;
                if (req.query && typeof req.query.regionId === 'string') {
                    requestedRegionId = req.query.regionId.trim() || null;
                }

                if (!currentPlayer && !requestedRegionId) {
                    return res.status(404).json({
                        success: false,
                        error: 'No current player found'
                    });
                }

                const currentLocationId = currentPlayer ? currentPlayer.currentLocation : null;
                const currentLocation = currentLocationId ? gameLocations.get(currentLocationId) : null;

                let region = null;

                if (requestedRegionId) {
                    if (regions.has(requestedRegionId)) {
                        region = regions.get(requestedRegionId);
                    } else {
                        return res.status(404).json({
                            success: false,
                            error: `Region with ID '${requestedRegionId}' not found`
                        });
                    }
                } else {
                    if (!currentLocation) {
                        return res.status(404).json({
                            success: false,
                            error: 'Current location not found'
                        });
                    }

                    const regionId = currentLocation.stubMetadata?.regionId;
                    if (regionId && regions.has(regionId)) {
                        region = regions.get(regionId);
                    } else {
                        region = Array.from(regions.values()).find(r => r.locationIds.includes(currentLocationId)) || null;
                    }
                }

                if (!region) {
                    return res.status(404).json({
                        success: false,
                        error: 'Region not found for mapping'
                    });
                }

                const locations = region.locationIds
                    .map(id => gameLocations.get(id))
                    .filter(Boolean);

                const payload = {
                    regionId: region.id,
                    regionName: region.name,
                    currentLocationId,
                    locations: locations
                        .map(loc => buildMapLocationSummary(loc))
                        .filter(Boolean)
                };

                res.json({ success: true, region: payload });
            } catch (error) {
                console.error('Error building map data:', error);
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.get('/api/map/world', (req, res) => {
            try {
                if (!(regions instanceof Map) || regions.size === 0) {
                    return res.status(404).json({
                        success: false,
                        error: 'World map unavailable: no regions registered'
                    });
                }

                const allLocations = gameLocations instanceof Map
                    ? Array.from(gameLocations.values())
                    : [];

                if (allLocations.length === 0) {
                    return res.status(404).json({
                        success: false,
                        error: 'World map unavailable: no locations registered'
                    });
                }

                const regionList = Array.from(regions.values());
                const currentLocationId = currentPlayer ? currentPlayer.currentLocation || null : null;

                const regionSummaries = regionList.map(region => {
                    const locationIds = Array.isArray(region.locationIds)
                        ? [...region.locationIds]
                        : [];
                    const parentRegionId = typeof region.parentRegionId === 'string' && region.parentRegionId.trim()
                        ? region.parentRegionId.trim()
                        : null;
                    const regionRepresentsVehicle = Boolean(
                        region.isVehicle === true
                        || (region.vehicleInfo && typeof region.vehicleInfo === 'object' && !Array.isArray(region.vehicleInfo))
                    );
                    const regionVehicleIcon = regionRepresentsVehicle
                        ? (resolveVehicleIconFromInfoForMap(region.vehicleInfo) || '🚗')
                        : null;

                    return {
                        id: region.id,
                        name: region.name,
                        parentRegionId,
                        isVehicle: regionRepresentsVehicle,
                        vehicleIcon: regionVehicleIcon,
                        isStub: Boolean(region.isStub),
                        locationIds,
                        locationCount: locationIds.length,
                        averageLevel: Number.isFinite(region.averageLevel) ? region.averageLevel : null
                    };
                });

                const regionIdSet = new Set(regionSummaries.map(region => region.id));
                const childLookup = new Map();
                for (const summary of regionSummaries) {
                    if (summary.parentRegionId && regionIdSet.has(summary.parentRegionId)) {
                        const children = childLookup.get(summary.parentRegionId) || [];
                        children.push(summary.id);
                        childLookup.set(summary.parentRegionId, children);
                    }
                }
                for (const summary of regionSummaries) {
                    summary.childRegionIds = childLookup.get(summary.id) || [];
                }

                const locationSummaries = allLocations
                    .map(loc => buildMapLocationSummary(loc))
                    .filter(summary => summary && summary.regionId);

                if (!locationSummaries.length) {
                    return res.status(404).json({
                        success: false,
                        error: 'World map unavailable: no mapped locations found'
                    });
                }

                res.json({
                    success: true,
                    world: {
                        currentLocationId,
                        regions: regionSummaries,
                        locations: locationSummaries
                    }
                });
            } catch (error) {
                console.error('Error building world map data:', error);
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/craft', async (req, res) => {
            let corpseProcessingRan = false;

            res.on('finish', () => {
                if (corpseProcessingRan) {
                    return;
                }
                try {
                    processNpcCorpses({ reason: 'craft:finish' });
                } catch (error) {
                    console.warn('Failed to process NPC corpses after crafting response:', error?.message || error);
                }
            });

            try {
                if (!currentPlayer) {
                    return res.status(400).json({
                        success: false,
                        error: 'No active player available for crafting.'
                    });
                }

                try {
                    await runAutosaveIfEnabled();
                } catch (autosaveError) {
                    console.warn('Autosave before crafting failed:', autosaveError?.message || autosaveError);
                }

                const payload = req.body && typeof req.body === 'object' ? req.body : {};
                const parseNoProseFlag = (value) => {
                    if (value === undefined || value === null || value === '') {
                        return false;
                    }
                    if (typeof value === 'boolean') {
                        return value;
                    }
                    if (typeof value === 'number') {
                        if (value === 1) {
                            return true;
                        }
                        if (value === 0) {
                            return false;
                        }
                        throw new Error('Invalid numeric noProse value. Use 1 or 0.');
                    }
                    if (typeof value === 'string') {
                        const normalized = value.trim().toLowerCase();
                        if (!normalized) {
                            return false;
                        }
                        if (normalized === 'true' || normalized === '1' || normalized === 'yes' || normalized === 'y' || normalized === 'on') {
                            return true;
                        }
                        if (normalized === 'false' || normalized === '0' || normalized === 'no' || normalized === 'n' || normalized === 'off') {
                            return false;
                        }
                        throw new Error(`Invalid noProse value "${value}".`);
                    }
                    throw new Error(`Unsupported noProse value type: ${typeof value}`);
                };
                const isNoProseRequest = parseNoProseFlag(payload.noProse);
                const slotEntries = Array.isArray(payload.slots) ? payload.slots : [];

                const slotItems = [];
                for (const entry of slotEntries) {
                    if (!entry || typeof entry !== 'object') {
                        continue;
                    }
                    const thingId = typeof entry.thingId === 'string' ? entry.thingId.trim() : '';
                    if (!thingId) {
                        continue;
                    }
                    const thing = things.get(thingId) || (typeof Thing.getById === 'function' ? Thing.getById(thingId) : null);
                    if (!thing) {
                        return res.status(400).json({
                            success: false,
                            error: `Selected item '${thingId}' was not found.`
                        });
                    }
                    if (isNonEmptyCraftingContainer(thing)) {
                        return res.status(400).json({
                            success: false,
                            error: `Selected container "${thing.name || thingId}" must be emptied before it can be used for crafting.`
                        });
                    }
                    const slotIndex = Number.isFinite(Number(entry.slotIndex))
                        ? Number(entry.slotIndex)
                        : 0;
                    slotItems.push({ slotIndex, thing });
                }

                const locationId = currentPlayer.currentLocation || null;
                const locationRecord = locationId
                    ? (gameLocations.get(locationId) || (typeof Location.get === 'function' ? Location.get(locationId) : null))
                    : null;
                const resolvedLocationId = requireLocationId(locationRecord?.id || locationId, 'crafting action');
                const locationThingIds = collectLocationCraftingThingIds(locationRecord);
                const playerInventoryThingIds = collectPlayerInventoryCraftingThingIds(currentPlayer);
                const isThingInCurrentPlayerInventory = (thing) => (
                    Boolean(thing?.id)
                    && playerInventoryThingIds.has(thing.id)
                );
                const isThingInCurrentLocation = (thing) => {
                    if (!thing?.id) {
                        return false;
                    }
                    if (locationThingIds.has(thing.id)) {
                        return true;
                    }
                    const metadataLocationId = typeof thing.metadata?.locationId === 'string'
                        ? thing.metadata.locationId.trim()
                        : '';
                    return Boolean(metadataLocationId && metadataLocationId === resolvedLocationId);
                };
                for (const { thing } of slotItems) {
                    const inPlayerInventory = isThingInCurrentPlayerInventory(thing);
                    const inCurrentLocation = isThingInCurrentLocation(thing);
                    if (!inPlayerInventory && !inCurrentLocation) {
                        return res.status(400).json({
                            success: false,
                            error: `${thing.name || thing.id} is not in the current player's inventory, a container in the current player's inventory, current location, or a container in the current location.`
                        });
                    }
                    if (inPlayerInventory && Boolean(thing?.isEquipped || thing?.equippedSlot)) {
                        return res.status(400).json({
                            success: false,
                            error: `${thing.name || thing.id} must be unequipped before it can be used for crafting.`
                        });
                    }
                }
                const resolvedRegion = locationRecord?.regionId && regions instanceof Map
                    ? regions.get(locationRecord.regionId) || null
                    : (Globals.region || null);
                const npcIdsSharingPlayerLocationAtTurnStart = Player.getNpcIdsSharingPlayerLocation({
                    player: currentPlayer,
                    locationId: resolvedLocationId
                });

                const intendedItemName = typeof payload.intendedItemName === 'string'
                    ? payload.intendedItemName.trim()
                    : '';
                const craftingRollState = { value: null };
                const extractInlineDieRollFromCraftText = (value) => {
                    if (typeof value !== 'string' || !value.length) {
                        return '';
                    }
                    let parsedDieRoll = null;
                    const stripped = value.replace(/<(-?\d+)>/g, (_, rawValue) => {
                        if (parsedDieRoll === null) {
                            parsedDieRoll = Number.parseInt(rawValue, 10);
                        }
                        return '';
                    });
                    if (craftingRollState.value === null && Number.isInteger(parsedDieRoll)) {
                        craftingRollState.value = parsedDieRoll;
                    }
                    return stripped
                        .replace(/[ \t]{2,}/g, ' ')
                        .replace(/ *\n */g, '\n')
                        .trim();
                };
                const craftingNotes = extractInlineDieRollFromCraftText(
                    typeof payload.notes === 'string' ? payload.notes.trim() : ''
                );
                const craftTargetTypeInput = typeof payload.craftTargetType === 'string'
                    ? payload.craftTargetType.trim().toLowerCase()
                    : '';
                const craftTargetType = craftTargetTypeInput === 'scenery'
                    ? 'scenery'
                    : (craftTargetTypeInput === 'item' ? 'item' : null);
                let craftingMode = 'craft';
                if (payload.mode === 'process') {
                    craftingMode = 'process';
                } else if (payload.mode === 'salvage') {
                    craftingMode = 'salvage';
                } else if (payload.mode === 'harvest') {
                    craftingMode = 'harvest';
                }
                const actionTypeInput = typeof payload.actionType === 'string' ? payload.actionType.trim().toLowerCase() : '';
                const effectiveActionType = (() => {
                    if (actionTypeInput === 'salvage' || actionTypeInput === 'harvest') {
                        return actionTypeInput;
                    }
                    if (craftingMode === 'salvage' || craftingMode === 'harvest') {
                        return craftingMode;
                    }
                    return craftingMode === 'process' ? 'process' : 'craft';
                })();
                const isSalvageAction = effectiveActionType === 'salvage';
                const isHarvestAction = effectiveActionType === 'harvest';
                if (isSalvageAction) {
                    craftingMode = 'salvage';
                } else if (isHarvestAction) {
                    craftingMode = 'harvest';
                }
                const effectiveCraftTargetType = (!isSalvageAction && !isHarvestAction && craftingMode === 'craft')
                    ? craftTargetType
                    : null;
                const stationThingId = typeof payload.stationThingId === 'string' ? payload.stationThingId.trim() : '';
                const stationThing = stationThingId
                    ? (things.get(stationThingId) || (typeof Thing.getById === 'function' ? Thing.getById(stationThingId) : null))
                    : null;
                const stationName = (typeof payload.stationName === 'string' && payload.stationName.trim())
                    ? payload.stationName.trim()
                    : (stationThing?.name || (isSalvageAction ? 'Salvage Station' : 'Crafting Station'));

                const salvageItemId = typeof payload.salvageItemId === 'string' ? payload.salvageItemId.trim() : '';
                const salvageItemName = typeof payload.salvageItemName === 'string' ? payload.salvageItemName.trim() : '';
                const salvageItemDescription = typeof payload.salvageItemDescription === 'string' ? payload.salvageItemDescription.trim() : '';
                const salvageNotes = extractInlineDieRollFromCraftText(
                    typeof payload.salvageNotes === 'string' ? payload.salvageNotes.trim() : ''
                );
                const harvestItemId = typeof payload.harvestItemId === 'string' ? payload.harvestItemId.trim() : '';
                const harvestItemName = typeof payload.harvestItemName === 'string' ? payload.harvestItemName.trim() : '';
                const harvestItemDescription = typeof payload.harvestItemDescription === 'string' ? payload.harvestItemDescription.trim() : '';
                const harvestNotes = extractInlineDieRollFromCraftText(
                    typeof payload.harvestNotes === 'string' ? payload.harvestNotes.trim() : ''
                );

                if ((isSalvageAction || isHarvestAction) && slotItems.length !== 1) {
                    return res.status(400).json({
                        success: false,
                        error: isHarvestAction
                            ? 'Harvesting requires exactly one target item.'
                            : 'Salvaging requires exactly one target item.'
                    });
                }

                const salvageTargetThing = (isSalvageAction || isHarvestAction) && slotItems[0]?.thing
                    ? slotItems[0].thing
                    : null;

                if (isHarvestAction && salvageTargetThing?.isHarvestable !== true) {
                    return res.status(400).json({
                        success: false,
                        error: `${salvageTargetThing?.name || 'Selected target'} is not harvestable.`
                    });
                }

                const craftingItemsForPrompt = slotItems.map(({ thing }) => ({
                    name: thing.name,
                    description: thing.description,
                    rarity: thing.rarity,
                    thingType: thing.thingType
                }));

                const baseContext = await prepareBasePromptContext({
                    locationOverride: locationRecord,
                    omitCraftHistory: true
                });

                const promptPayload = {
                    ...baseContext,
                    promptType: isSalvageAction ? 'plausibility-check-salvage' : 'plausibility-check-craft',
                    intendedItemName: isSalvageAction
                        ? (salvageTargetThing?.name || salvageItemName || intendedItemName || 'Recovered components')
                        : intendedItemName,
                    stationName,
                    craftingItems: craftingItemsForPrompt,
                    craftingNotes,
                    craftTargetType: effectiveCraftTargetType,
                    omitGameHistory: true
                };

                if (isSalvageAction) {
                    promptPayload.salvageTarget = salvageTargetThing
                        ? {
                            name: salvageTargetThing.name,
                            description: salvageTargetThing.description,
                            rarity: salvageTargetThing.rarity,
                            thingType: salvageTargetThing.thingType
                        }
                        : null;
                    promptPayload.salvageTargetName = salvageTargetThing?.name || salvageItemName || null;
                    promptPayload.salvageItemName = salvageTargetThing?.name || salvageItemName || null;
                    promptPayload.salvageItemDescription = salvageTargetThing?.description || salvageItemDescription || null;
                    promptPayload.salvageNotes = salvageNotes || craftingNotes;
                    promptPayload.salvageStationName = stationName;
                    promptPayload.salvageStationThing = stationThing
                        ? {
                            name: stationThing.name,
                            description: stationThing.description
                        }
                        : null;
                } else if (isHarvestAction) {
                    promptPayload.promptType = 'plausibility-check-harvest';
                    promptPayload.harvestTarget = salvageTargetThing
                        ? {
                            name: salvageTargetThing.name,
                            description: salvageTargetThing.description,
                            rarity: salvageTargetThing.rarity,
                            thingType: salvageTargetThing.thingType,
                            pastHarvests: Array.isArray(salvageTargetThing.previouslyHarvestedItems)
                                ? salvageTargetThing.previouslyHarvestedItems.map(itemName => ({ itemName }))
                                : []
                        }
                        : null;
                    promptPayload.harvestTargetName = salvageTargetThing?.name || harvestItemName || null;
                    promptPayload.harvestItemName = salvageTargetThing?.name || harvestItemName || null;
                    promptPayload.harvestItemDescription = salvageTargetThing?.description || harvestItemDescription || null;
                    promptPayload.lastHarvestTime = salvageTargetThing?.getLastHarvestedAgoText?.() || null;
                    promptPayload.harvestNotes = harvestNotes || craftingNotes || '';
                    promptPayload.harvestStationName = stationName;
                }

                const plausibilityRendered = promptEnv.render('base-context.xml.njk', promptPayload);

                const plausibilityTemplate = parseXMLTemplate(plausibilityRendered);
                if (!plausibilityTemplate?.systemPrompt || !plausibilityTemplate?.generationPrompt) {
                    throw new Error('Crafting plausibility template did not produce prompts.');
                }

                const plausibilityResponse = await LLMClient.chatCompletion({
                    messages: [
                        { role: 'system', content: plausibilityTemplate.systemPrompt },
                        { role: 'user', content: plausibilityTemplate.generationPrompt }
                    ],
                    metadataLabel: 'craft_plausibility',
                    expectedXmlRootTag: 'response'
                });

                LLMClient.logPrompt({
                    metadataLabel: 'craft_plausibility',
                    systemPrompt: plausibilityTemplate.systemPrompt,
                    generationPrompt: plausibilityTemplate.generationPrompt,
                    response: plausibilityResponse
                });

                if (!plausibilityResponse || !plausibilityResponse.trim()) {
                    throw new Error('Crafting plausibility analysis returned no response.');
                }

                const plausibility = parsePlausibilityOutcome(plausibilityResponse);
                if (!plausibility) {
                    throw new Error('Unable to parse crafting plausibility response.');
                }

                const craftingResults = await parseCraftingResultsResponse(plausibilityResponse);
                const baseSuccessResult = craftingResults.get('success');
                if (!baseSuccessResult) {
                    throw new Error('Craft plausibility response missing a standard success result.');
                }

                const actionOutcome = resolveActionOutcome({
                    plausibility,
                    player: currentPlayer,
                    dieRollOverride: craftingRollState.value
                });
                if (!actionOutcome) {
                    throw new Error('Failed to resolve crafting outcome.');
                }

                const mappedLevel = mapOutcomeDegreeToCraftLevel(
                    actionOutcome.degree,
                    Number.isFinite(actionOutcome.roll?.die) ? actionOutcome.roll.die : null,
                    actionOutcome.difficulty?.label || null,
                    { level: actionOutcome.locationLevel }
                );
                if (mappedLevel === 'implausible') {
                    return res.status(400).json({
                        success: false,
                        error: plausibility.reason || 'That crafting attempt is implausible.'
                    });
                }

                console.log(`🛠️ Crafting plausibility check: success=${actionOutcome.success}, degree=${actionOutcome.degree}, mappedLevel=${mappedLevel}`);
                // dump craftingResults for debugging
                //console.log('Raw crafting results from AI response:', craftingResults);
                /*
                console.log('Crafting Results from AI:', Array.from(craftingResults.entries()).map(([key, value]) => ({
                resultLevel: key,
                    itemsRecovered: Array.isArray(value.itemsRecovered)
                        ? value.itemsRecovered.map(item => item.name || 'Unnamed Item')
                        : [],
                        itemsConsumed: Array.isArray(value.itemsConsumed)
                            ? value.itemsConsumed
                            : []
                })));*/
                let effectiveResults = craftingResults;
                const availableThings = slotItems.map(entry => entry.thing);

                if (mappedLevel && mappedLevel !== 'success') {
                    const degreeMode = isHarvestAction ? 'harvest' : (isSalvageAction ? 'salvage' : craftingMode);
                    const degreeTargetName = isHarvestAction
                        ? (promptPayload.harvestTargetName || harvestItemName || harvestItemDescription || 'harvest target')
                        : (isSalvageAction
                            ? (promptPayload.salvageTargetName || salvageItemName || salvageItemDescription || 'salvage target')
                            : (intendedItemName || stationName || 'crafted item'));

                    const degreeResult = await renderCraftOutcomeForDegree({
                        baseContext,
                        baseOutcomeXml: plausibilityResponse,
                        successOrFailure: mappedLevel,
                        mode: degreeMode,
                        stationName,
                        intendedItemName: promptPayload.intendedItemName || intendedItemName,
                        craftTargetType: effectiveCraftTargetType,
                        targetName: degreeTargetName,
                        inputItems: craftingItemsForPrompt,
                        validateResults: ({ selectedResult: candidateResult }) => {
                            const candidateConsumedNames = Array.isArray(candidateResult.itemsConsumed)
                                ? candidateResult.itemsConsumed.filter(name => typeof name === 'string' && name.trim())
                                : [];
                            resolveCraftConsumedThings({
                                inputThings: availableThings,
                                consumedNames: candidateConsumedNames,
                                mode: craftingMode,
                                allowFallbackConsumeFirst: isSalvageAction
                            });
                        }
                    });
                    effectiveResults = degreeResult.results;
                }

                let selectedResult = mappedLevel ? effectiveResults.get(mappedLevel) : null;
                if (!selectedResult) {
                    selectedResult = effectiveResults.get('success') || null;
                }
                if (!selectedResult && effectiveResults.size) {
                    selectedResult = effectiveResults.values().next().value;
                }
                if (!selectedResult) {
                    throw new Error('AI response did not include crafting results.');
                }

                const consumedNameList = Array.isArray(selectedResult.itemsConsumed)
                    ? selectedResult.itemsConsumed.filter(name => typeof name === 'string' && name.trim())
                    : [];
                if (isSalvageAction && !consumedNameList.length && salvageTargetThing?.name) {
                    consumedNameList.push(salvageTargetThing.name);
                }

                // Print created and consumed items for crafting log
                console.log(`🎨 Crafting action at ${stationName}:`);
                console.log(`   - Success: ${actionOutcome.success} (Degree: ${actionOutcome.degree || 'N/A'})`);
                console.log(`   - Created items: ${Array.isArray(selectedResult.itemsRecovered) && selectedResult.itemsRecovered.length
                    ? selectedResult.itemsRecovered.map(item => item.name || 'Unnamed Item').join(', ')
                    : 'None'}`);
                console.log(`   - Consumed items: ${consumedNameList.length ? consumedNameList.join(', ') : 'None'}`);
                console.log(`   - Crafting mode: ${craftingMode}`);

                const {
                    consumedThings,
                    unmatchedConsumedNames
                } = resolveCraftConsumedThings({
                    inputThings: availableThings,
                    consumedNames: consumedNameList,
                    mode: craftingMode,
                    allowFallbackConsumeFirst: isSalvageAction
                });

                consumedThings.forEach(match => {
                    console.log(`🗑️ Consuming item for crafting: ${match.name} (ID: ${match.id})`);
                });

                const instantiateThingFromBlueprint = (itemBlueprint, {
                    defaultName = 'Crafted Item',
                    defaultDescription = null
                } = {}) => {
                    if (!itemBlueprint) {
                        return null;
                    }
                    const rawType = (itemBlueprint.thingType || itemBlueprint.itemOrScenery || itemBlueprint.thingCategory || 'item').toLowerCase();
                    const thingType = rawType === 'scenery' ? 'scenery' : 'item';
                    const levelForBonuses = Number.isFinite(itemBlueprint.level)
                        ? itemBlueprint.level
                        : (Number.isFinite(currentPlayer?.level) ? currentPlayer.level : 1);
                    const rawAttributeBonuses = thingType === 'item'
                        ? normalizeAttributeBonusesForItem(
                            Array.isArray(itemBlueprint.attributeBonuses) ? itemBlueprint.attributeBonuses : []
                        )
                        : [];
                    const attributeBonuses = thingType === 'item'
                        ? scaleAttributeBonusesForItem(
                            rawAttributeBonuses,
                            { level: levelForBonuses, rarity: itemBlueprint.rarity }
                        )
                        : [];
                    const targetEffect = itemBlueprint.causeStatusEffectOnTarget
                        || (itemBlueprint.causeStatusEffect?.applyToTarget ? itemBlueprint.causeStatusEffect : null)
                        || null;
                    const equipperEffect = itemBlueprint.causeStatusEffectOnEquipper
                        || (itemBlueprint.causeStatusEffect?.applyToEquipper ? itemBlueprint.causeStatusEffect : null)
                        || null;
                    const combinedCauseEffect = (() => {
                        const entries = [];
                        if (targetEffect) {
                            entries.push({ ...targetEffect, applyToTarget: true });
                        }
                        if (equipperEffect) {
                            entries.push({ ...equipperEffect, applyToEquipper: true });
                        }
                        if (!entries.length && itemBlueprint.causeStatusEffect) {
                            entries.push(itemBlueprint.causeStatusEffect);
                        }
                        return entries.length ? entries : null;
                    })();
                    const registeredBlueprintFields = extractRegisteredThingBlueprintFields(itemBlueprint);

                    const metadata = sanitizeMetadataObject({
                        rarity: itemBlueprint.rarity || null,
                        itemType: itemBlueprint.type || null,
                        value: itemBlueprint.value ?? null,
                        weight: itemBlueprint.weight ?? null,
                        properties: itemBlueprint.properties || null,
                        attributeBonuses: attributeBonuses.length ? attributeBonuses : undefined,
                        unscaledAttributeBonuses: rawAttributeBonuses.length ? rawAttributeBonuses : undefined,
                        causeStatusEffectOnTarget: targetEffect || undefined,
                        causeStatusEffectOnEquipper: equipperEffect || undefined,
                        ownerId: currentPlayer.id
                    });

                    return new Thing({
                        name: itemBlueprint.name || defaultName,
                        description: itemBlueprint.description || defaultDescription || `An item crafted at ${stationName}.`,
                        shortDescription: itemBlueprint.shortDescription ?? null,
                        thingType,
                        rarity: itemBlueprint.rarity || null,
                        itemTypeDetail: itemBlueprint.type || null,
                        slot: registeredBlueprintFields.shouldClearSlot ? null : (itemBlueprint.slot || null),
                        attributeBonuses: attributeBonuses.length ? attributeBonuses : null,
                        unscaledAttributeBonuses: rawAttributeBonuses,
                        causeStatusEffect: combinedCauseEffect,
                        count: itemBlueprint.count ?? 1,
                        level: Number.isFinite(itemBlueprint.level) ? itemBlueprint.level : null,
                        relativeLevel: Number.isFinite(itemBlueprint.relativeLevel) ? itemBlueprint.relativeLevel : null,
                        containerContents: itemBlueprint.containerContents,
                        metadata,
                        isVehicle: itemBlueprint.isVehicle,
                        isCraftingStation: itemBlueprint.isCraftingStation,
                        isProcessingStation: itemBlueprint.isProcessingStation,
                        isHarvestable: itemBlueprint.isHarvestable,
                        isSalvageable: itemBlueprint.isSalvageable,
                        isContainer: itemBlueprint.isContainer,
                        requiresCheckToOpen: itemBlueprint.requiresCheckToOpen,
                        ...registeredBlueprintFields.values
                    });
                };

                // Level formula: ceil(avg(top two ingredients + station + player counted twice)) plus relative delta.
                const computeCraftedItemLevel = (itemBlueprint) => {
                    if (!itemBlueprint || isSalvageAction || isHarvestAction) {
                        return Number.isFinite(itemBlueprint?.level) ? itemBlueprint.level : null;
                    }

                    const fallbackLevel = Number.isFinite(currentPlayer?.level) && currentPlayer.level > 0
                        ? currentPlayer.level
                        : 1;
                    const locationLevel = Number.isFinite(locationRecord?.baseLevel)
                        ? locationRecord.baseLevel
                        : fallbackLevel;
                    const stationLevel = Number.isFinite(stationThing?.level)
                        ? stationThing.level
                        : locationLevel;
                    const ingredientLevels = slotItems
                        .map(({ thing }) => (Number.isFinite(thing?.level) && thing.level > 0) ? thing.level : fallbackLevel)
                        .sort((a, b) => b - a);

                    const topIngredient = ingredientLevels[0] ?? fallbackLevel;
                    const secondIngredient = ingredientLevels[1] ?? topIngredient;
                    const weightedSum = topIngredient + secondIngredient + stationLevel + (fallbackLevel * 2);
                    const averaged = weightedSum / 5;
                    const roundedBase = Math.ceil(averaged);
                    const relativeDelta = Number.isFinite(itemBlueprint.relativeLevel) ? itemBlueprint.relativeLevel : 0;
                    const finalLevel = Math.max(1, roundedBase + relativeDelta);

                    return finalLevel;
                };

                const consumedThingIds = [];
                const consumedThingNames = [];
                consumedThings.forEach(thing => {
                    if (!thing) {
                        console.log(`❌ Consumed item is null or undefined.`);
                        return;
                    }

                    const consumption = consumeThingById(thing.id);
                    const actionLabel = consumption.decremented
                        ? `Decrementing consumed item stack from ${consumption.priorCount} to ${consumption.remainingCount}`
                        : 'Removing consumed item from world';
                    console.log(`🗑️ ${actionLabel}:`, thing.name || 'Unnamed Item', `(ID: ${thing.id})`);

                    consumedThingIds.push(consumption.consumedThingId);
                    consumedThingNames.push(consumption.consumedThingName);
                });

                const craftedThingInstances = [];
                let craftedThing = null;
                const recoveredThingInstances = [];
                if (isSalvageAction || isHarvestAction) {
                    const salvageBlueprints = Array.isArray(selectedResult.itemsRecovered) && selectedResult.itemsRecovered.length
                        ? selectedResult.itemsRecovered
                        : (selectedResult.item ? [selectedResult.item] : []);
                    const defaultDescription = salvageTargetThing?.name
                        ? `Recovered material from ${salvageTargetThing.name}.`
                        : 'Recovered component.';
                    salvageBlueprints.forEach(blueprint => {
                        const recoveredBlueprint = { ...blueprint };
                        if (!Number.isFinite(recoveredBlueprint.level)) {
                            recoveredBlueprint.level = Number.isFinite(salvageTargetThing?.level)
                                ? salvageTargetThing.level
                                : (Number.isFinite(currentPlayer?.level) ? currentPlayer.level : 1);
                        }
                        const recoveredThing = instantiateThingFromBlueprint(recoveredBlueprint, {
                            defaultName: blueprint?.name || (isHarvestAction ? 'Harvested Material' : 'Recovered Component'),
                            defaultDescription
                        });
                        if (!recoveredThing) {
                            return;
                        }
                        things.set(recoveredThing.id, recoveredThing);
                        if (typeof currentPlayer.addInventoryItem === 'function') {
                            currentPlayer.addInventoryItem(recoveredThing, { suppressNpcEquip: true });
                        }
                        const recoveredMetadata = recoveredThing.metadata && typeof recoveredThing.metadata === 'object'
                            ? { ...recoveredThing.metadata }
                            : {};
                        recoveredMetadata.ownerId = currentPlayer.id;
                        recoveredMetadata.locationId = null;
                        recoveredThing.metadata = recoveredMetadata;
                        recoveredThingInstances.push(recoveredThing);
                    });
                } else {
                    const craftedBlueprints = Array.isArray(selectedResult.itemsRecovered) && selectedResult.itemsRecovered.length
                        ? selectedResult.itemsRecovered
                        : (selectedResult.item ? [selectedResult.item] : []);

                    craftedBlueprints.forEach(blueprint => {
                        const craftedBlueprint = { ...blueprint };
                        if (effectiveCraftTargetType) {
                            craftedBlueprint.itemOrScenery = effectiveCraftTargetType;
                            craftedBlueprint.thingType = effectiveCraftTargetType;
                            if (effectiveCraftTargetType === 'scenery') {
                                craftedBlueprint.type = 'scenery';
                                craftedBlueprint.slot = null;
                                craftedBlueprint.attributeBonuses = [];
                                craftedBlueprint.causeStatusEffectOnTarget = null;
                                craftedBlueprint.causeStatusEffectOnEquipper = null;
                            }
                        }
                        const resolvedCraftLevel = computeCraftedItemLevel(craftedBlueprint);
                        if (Number.isFinite(resolvedCraftLevel)) {
                            craftedBlueprint.level = resolvedCraftLevel;
                        }
                        const crafted = instantiateThingFromBlueprint(craftedBlueprint);
                        if (!crafted) {
                            return;
                        }
                        things.set(crafted.id, crafted);
                        const craftedMetadata = crafted.metadata && typeof crafted.metadata === 'object'
                            ? { ...crafted.metadata }
                            : {};

                        if ((crafted.thingType || craftedBlueprint.itemOrScenery) === 'scenery') {
                            craftedMetadata.locationId = resolvedLocationId;
                            craftedMetadata.ownerId = null;
                            crafted.metadata = craftedMetadata;

                            const locationTarget = locationRecord || (resolvedLocationId ? gameLocations.get(resolvedLocationId) : null);
                            if (locationTarget && typeof locationTarget.addThingId === 'function') {
                                try {
                                    locationTarget.addThingId(crafted.id);
                                } catch (error) {
                                    console.warn(`Failed to attach crafted scenery ${crafted.name || crafted.id} to location:`, error?.message || error);
                                }
                            }
                        } else {
                            if (typeof currentPlayer.addInventoryItem === 'function') {
                                currentPlayer.addInventoryItem(crafted, { suppressNpcEquip: true });
                            }
                            craftedMetadata.ownerId = currentPlayer.id;
                            craftedMetadata.locationId = null;
                            crafted.metadata = craftedMetadata;
                        }
                        craftedThingInstances.push(crafted);
                    });

                    craftedThing = craftedThingInstances[0] || null;
                }

                const createdThings = [...recoveredThingInstances, ...craftedThingInstances].filter(Boolean);
                if (createdThings.length) {
                    if (typeof Globals.ensureThingNamesAllowed !== 'function') {
                        throw new Error('Globals.ensureThingNamesAllowed is unavailable for item name validation.');
                    }
                    await Globals.ensureThingNamesAllowed({
                        things: createdThings,
                        location: locationRecord || null,
                        region: resolvedRegion
                    });
                }

                const consumedNamesForPrompt = consumedThingNames.length
                    ? consumedThingNames
                    : consumedNameList;

                const producedItemDescriptor = (() => {
                    if (isSalvageAction) {
                        if (recoveredThingInstances.length) {
                            const descriptions = recoveredThingInstances
                                .map(item => item.description)
                                .filter(Boolean);
                            return {
                                name: recoveredThingInstances.map(item => item.name || 'Recovered Item').join(', '),
                                description: descriptions.join(' ') || `Recovered components salvaged from ${salvageTargetThing?.name || 'an item'}.`
                            };
                        }
                        if (Array.isArray(selectedResult.itemsRecovered) && selectedResult.itemsRecovered.length) {
                            return {
                                name: selectedResult.itemsRecovered.map(item => item?.name || 'Recovered Item').join(', '),
                                description: `Recovered components salvaged from ${salvageTargetThing?.name || 'an item'}.`
                            };
                        }
                        return null;
                    }
                    if (craftedThingInstances.length) {
                        const names = craftedThingInstances.map(item => item.name || 'Crafted Item');
                        const descriptions = craftedThingInstances.map(item => item.description || '').filter(Boolean);
                        return {
                            name: names.join(', '),
                            description: descriptions.join(' ') || null
                        };
                    }
                    if (selectedResult.itemsRecovered && selectedResult.itemsRecovered.length) {
                        const names = selectedResult.itemsRecovered.map(item => item?.name || 'Crafted Item');
                        const descriptions = selectedResult.itemsRecovered.map(item => item?.description || '').filter(Boolean);
                        return {
                            name: names.join(', '),
                            description: descriptions.join(' ') || null
                        };
                    }
                    if (selectedResult.item) {
                        return {
                            name: selectedResult.item.name,
                            description: selectedResult.item.description
                        };
                    }
                    return null;
                })();

                const actorName = currentPlayer.name || 'The player';
                const recoveredNames = recoveredThingInstances.map(item => item.name || 'Recovered Item');
                const craftedNames = craftedThingInstances.map(item => item.name || 'Crafted Item');
                const harvestSourceName = salvageTargetThing?.name || 'a resource';
                const salvageSourceName = salvageTargetThing?.name || 'an item';
                const processSourceNames = slotItems
                    .map(entry => entry?.thing?.name)
                    .filter(name => typeof name === 'string' && name.trim())
                    .map(name => name.trim());
                const processSourceLabel = processSourceNames.length ? processSourceNames.join(', ') : 'materials';
                const craftUsingLabel = consumedNamesForPrompt.length
                    ? consumedNamesForPrompt.join(', ')
                    : 'available materials';

                const buildPrimaryActionSummaryText = () => {
                    if (isHarvestAction) {
                        if (recoveredNames.length) {
                            return `${actorName} harvested ${recoveredNames.join(', ')} from ${harvestSourceName}.`;
                        }
                        return `${actorName} attempted to harvest ${harvestSourceName} but obtained nothing usable.`;
                    }
                    if (isSalvageAction) {
                        if (recoveredNames.length) {
                            return `${actorName} salvaged ${recoveredNames.join(', ')} from ${salvageSourceName}.`;
                        }
                        return `${actorName} attempted to salvage from ${salvageSourceName} but recovered nothing usable.`;
                    }
                    if (craftingMode === 'process') {
                        if (craftedNames.length) {
                            return `${actorName} processed ${craftedNames.join(', ')} using ${processSourceLabel}.`;
                        }
                        return `${actorName} attempted to process using ${processSourceLabel} but produced nothing usable.`;
                    }
                    if (craftedNames.length) {
                        return `${actorName} crafted ${craftedNames.join(', ')} using ${craftUsingLabel}.`;
                    }
                    return `${actorName} attempted to craft using ${craftUsingLabel} but produced nothing usable.`;
                };

                const primaryActionSummaryText = buildPrimaryActionSummaryText();
                const selectedTimeTakenMinutes = Number(selectedResult.timeTakenMinutes);
                const appliedTimeTakenMinutes = Number.isFinite(selectedTimeTakenMinutes) && selectedTimeTakenMinutes > 0
                    ? Math.round(selectedTimeTakenMinutes)
                    : MIN_CRAFT_TIME_ADVANCE_MINUTES;
                let playerActionDescription = '';
                let playerOtherEffect = selectedResult.other || '';
                let chatEntry = null;

                if (isNoProseRequest) {
                    playerActionDescription = primaryActionSummaryText;
                    playerOtherEffect = '';
                } else {
                    let playerActionResponse = '';
                    let craftingLiveDeslopInfo = null;
                    const useTinyBrainCraftNarrative = isTinyBrainPromptEnabled(
                        Globals.config,
                        'craft_player_action'
                    );
                    try {
                        const craftNarrativeContext = {
                            ...baseContext,
                            promptType: 'player-action-craft',
                            characterName: actorName,
                            intendedItemName: isSalvageAction
                                ? (salvageTargetThing?.name || salvageItemName || intendedItemName || 'Recovered components')
                                : intendedItemName,
                            stationName,
                            inputItems: craftingItemsForPrompt,
                            success_or_failure: actionOutcome.label || actionOutcome.degree || '',
                            producedItem: producedItemDescriptor,
                            consumedItems: consumedNamesForPrompt.map(name => ({ name })),
                            otherEffect: selectedResult.other || null,
                            recoveredItems: recoveredThingInstances.map(item => ({ name: item.name })) || [],
                            craftingNotes,
                            targetName: salvageTargetThing?.name,
                            mode: craftingMode,
                            craftTargetType: effectiveCraftTargetType,
                            authoritativeTimePassedMinutes: appliedTimeTakenMinutes
                        };
                        const tinyBrain = useTinyBrainCraftNarrative
                            ? configureTinyBrainPromptContext(
                                craftNarrativeContext,
                                'craft_player_action'
                            )
                            : null;
                        const playerActionRendered = promptEnv.render(
                            'base-context.xml.njk',
                            craftNarrativeContext
                        );

                        const playerActionTemplate = parseXMLTemplate(playerActionRendered);
                        if (!playerActionTemplate?.systemPrompt || !playerActionTemplate?.generationPrompt) {
                            throw new Error('Player action craft template missing prompts.');
                        }

                        const craftNarrativeRequestOptions = {
                            messages: [
                                { role: 'system', content: playerActionTemplate.systemPrompt },
                                { role: 'user', content: playerActionTemplate.generationPrompt }
                            ],
                            metadataLabel: 'craft_player_action',
                            metadata: {
                                clientId: typeof payload.clientId === 'string' ? payload.clientId.trim() || null : null,
                                __codexQuotaCountAsTurn: true,
                                __codexQuotaTurnKey: (typeof payload.requestId === 'string' && payload.requestId.trim())
                                    ? payload.requestId.trim()
                                    : `craft_turn_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`
                            },
                            expectedXmlRootTag: 'result'
                        };
                        if (useTinyBrainCraftNarrative) {
                            const tinyBrainRun = await runTinyBrainNarrativePrompt({
                                family: 'craft_player_action',
                                initialRenderedTemplate: playerActionRendered,
                                templateContext: craftNarrativeContext,
                                tinyBrain,
                                metadataLabel: 'craft_player_action',
                                resultBuilders: {
                                    craft_result: buildCraftResult
                                },
                                finalParser: response => parseCraftNarrativeResult(response, {
                                    requireOtherEffect: Boolean(selectedResult.other),
                                    expectedDurationMinutes: appliedTimeTakenMinutes
                                }),
                                requestOptions: craftNarrativeRequestOptions
                            });
                            playerActionResponse = tinyBrainRun.result.aiResponse;
                            craftingLiveDeslopInfo = tinyBrainRun.liveDeslopController?.getDiagnostics() || null;
                        } else {
                            playerActionResponse = await LLMClient.chatCompletion(
                                craftNarrativeRequestOptions
                            );
                            LLMClient.logPrompt({
                                metadataLabel: 'craft_player_action',
                                systemPrompt: playerActionTemplate.systemPrompt,
                                generationPrompt: playerActionTemplate.generationPrompt,
                                response: playerActionResponse
                            });
                        }

                        const narrative = parseCraftingNarrativeResponse(playerActionResponse);
                        if (narrative?.description) {
                            playerActionDescription = narrative.description;
                        }
                        if (narrative?.otherEffectDescription) {
                            playerOtherEffect = narrative.otherEffectDescription;
                        }
                    } catch (actionError) {
                        if (useTinyBrainCraftNarrative) {
                            throw actionError;
                        }
                        console.warn('Failed to generate crafting narrative:', actionError?.message || actionError);
                    }

                    if (!playerActionDescription) {
                        console.warn('Falling back to default crafting narrative.');
                        console.trace();
                        const attemptLabel = isSalvageAction
                            ? 'salvaging'
                            : (craftingMode === 'process' ? 'processing' : 'crafting');
                        playerActionDescription = actionOutcome.success
                            ? `${actorName} successfully completes the ${attemptLabel} attempt at ${stationName}.`
                            : `${actorName} struggles with the ${attemptLabel} attempt and comes away empty-handed.`;
                    }

                    if (!playerOtherEffect && selectedResult.other) {
                        playerOtherEffect = selectedResult.other;
                    }

                    let narrativeContent = playerActionDescription || '';
                    let craftingSlopRemovalInfo = null;
                    if (Globals.config?.slop_buster === true && narrativeContent.trim()) {
                        const slopResult = await applySlopRemoval(narrativeContent, { returnDiagnostics: true });
                        narrativeContent = slopResult.text;
                        if (slopResult.ran) {
                            craftingSlopRemovalInfo = {
                                slopWords: slopResult.slopWords || [],
                                slopRegexes: slopResult.slopRegexes || [],
                                slopNgrams: slopResult.slopNgrams || []
                            };
                        }
                    }
                    if (craftingLiveDeslopInfo?.ran) {
                        craftingSlopRemovalInfo = {
                            ...(craftingSlopRemovalInfo || {}),
                            slopWords: Array.from(new Set([
                                ...(craftingSlopRemovalInfo?.slopWords || []),
                                ...(craftingLiveDeslopInfo.slopWords || [])
                            ])),
                            slopRegexes: Array.from(new Set([
                                ...(craftingSlopRemovalInfo?.slopRegexes || []),
                                ...(craftingLiveDeslopInfo.slopRegexes || [])
                            ])),
                            slopNgrams: Array.from(new Set([
                                ...(craftingSlopRemovalInfo?.slopNgrams || []),
                                ...(craftingLiveDeslopInfo.slopNgrams || [])
                            ])),
                            liveCorrections: [...(craftingLiveDeslopInfo.corrections || [])]
                        };
                    }

                    chatEntry = pushChatEntry({
                        role: 'assistant',
                        type: 'player-action',
                        content: narrativeContent,
                        metadata: {
                            craftingMode,
                            actionType: isSalvageAction ? 'salvage' : craftingMode,
                            stationName,
                            intendedItemName: (isSalvageAction
                                ? (salvageTargetThing?.name || salvageItemName || intendedItemName || null)
                                : intendedItemName) || null,
                            craftingNotes: (isSalvageAction ? (salvageNotes || craftingNotes || null) : (craftingNotes || null)),
                            salvageRecoveredItemIds: isSalvageAction ? recoveredThingInstances.map(item => item.id) : undefined
                        }
                    }, null, resolvedLocationId);

                    if (chatEntry) {
                        recordPlausibilityEntry({
                            data: {
                                raw: plausibilityResponse,
                                structured: plausibility
                            },
                            parentId: chatEntry.id,
                            locationId: resolvedLocationId
                        });

                        if (craftingSlopRemovalInfo) {
                            recordSlopRemovalEntry({
                                data: craftingSlopRemovalInfo,
                                parentId: chatEntry.id,
                                locationId: resolvedLocationId
                            });
                        }
                        notifyVisibleProseEntryStored(chatEntry, {
                            clientId: payload.clientId,
                            requestId: payload.requestId,
                            proseType: 'crafting-action'
                        });
                    }
                }

                const craftCheckLabel = isHarvestAction
                    ? 'Harvesting'
                    : (isSalvageAction
                        ? 'Salvaging'
                        : (craftingMode === 'process' ? 'Processing' : 'Crafting'));
                recordActionOutcomeCheckResultsEntry({
                    resolution: actionOutcome,
                    actorName,
                    skillLabel: craftCheckLabel,
                    reason: primaryActionSummaryText,
                    promptLabel: craftCheckLabel,
                    parentId: chatEntry?.id || null,
                    locationId: resolvedLocationId,
                    requestId: payload.requestId
                });

                if (!isNoProseRequest) {
                    const eventItems = [];
                    if (isHarvestAction) {
                        if (recoveredNames.length) {
                            eventItems.push({
                                icon: '🌾',
                                description: `${actorName} harvested ${recoveredNames.join(', ')} from ${harvestSourceName}.`,
                                category: 'inventory'
                            });
                        } else {
                            eventItems.push({
                                icon: '🌾',
                                description: `${actorName} attempted to harvest ${harvestSourceName} but obtained nothing usable.`,
                                category: 'inventory'
                            });
                        }
                    } else if (isSalvageAction) {
                        if (recoveredNames.length) {
                            eventItems.push({
                                icon: '♻️',
                                description: `${actorName} salvaged ${recoveredNames.join(', ')} from ${salvageSourceName}.`,
                                category: 'inventory'
                            });
                        } else {
                            eventItems.push({
                                icon: '♻️',
                                description: `${actorName} attempted to salvage from ${salvageSourceName} but recovered nothing usable.`,
                                category: 'inventory'
                            });
                        }
                    } else if (craftingMode === 'process') {
                        if (craftedThingInstances.length) {
                            eventItems.push({
                                icon: '🛠️',
                                description: `${actorName} processed ${craftedNames.join(', ')} using ${processSourceLabel}.`,
                                category: 'inventory'
                            });
                        } else {
                            eventItems.push({
                                icon: '🛠️',
                                description: `${actorName} attempted to process using ${processSourceLabel} but produced nothing usable.`,
                                category: 'inventory'
                            });
                        }
                    } else {
                        if (craftedThingInstances.length) {
                            eventItems.push({
                                icon: '🛠️',
                                description: `${actorName} crafted ${craftedNames.join(', ')} using ${craftUsingLabel}.`,
                                category: 'inventory'
                            });
                        } else {
                            eventItems.push({
                                icon: '🛠️',
                                description: `${actorName} attempted to craft using ${craftUsingLabel} but produced nothing usable.`,
                                category: 'inventory'
                            });
                        }
                    }
                    const consumedSummaryNames = consumedThingNames.length
                        ? consumedThingNames
                        : consumedNameList;
                    if (consumedSummaryNames.length) {
                        consumedSummaryNames.forEach(name => {
                            eventItems.push({
                                icon: '♻️',
                                description: `Consumed ${name}.`,
                                category: 'inventory'
                            });
                        });

                        const appliedConsumeEffects = [];
                        if (actionOutcome.success && Array.isArray(consumedThings)) {
                            for (const thing of consumedThings) {
                                // Apply every inflict effect the consumed item carries, not just the first.
                                const targetEffects = Array.isArray(thing?.causeStatusEffectsOnTarget) && thing.causeStatusEffectsOnTarget.length
                                    ? thing.causeStatusEffectsOnTarget
                                    : (() => {
                                        const single = thing?.causeStatusEffectOnTarget || thing?.metadata?.causeStatusEffectOnTarget || null;
                                        return single ? [single] : [];
                                    })();
                                for (const targetEffect of targetEffects) {
                                    if (!targetEffect || typeof currentPlayer?.addStatusEffect !== 'function') {
                                        continue;
                                    }
                                    try {
                                        const applied = currentPlayer.addStatusEffect(targetEffect, targetEffect.duration ?? 1);
                                        if (applied) {
                                            appliedConsumeEffects.push(applied);
                                        }
                                    } catch (error) {
                                        console.warn(`Failed to apply consumed item status effect from ${thing?.name || 'consumed item'}:`, error?.message || error);
                                    }
                                }
                            }
                        }
                        if (appliedConsumeEffects.length) {
                            appliedConsumeEffects.forEach(effect => {
                                eventItems.push({
                                    type: 'status_effect_change',
                                    icon: '✨',
                                    description: `Gained status effect: ${effect.name || effect.description || 'Unknown Effect'}`,
                                    effect: {
                                        name: effect.name || null,
                                        description: effect.description || '',
                                        duration: effect.duration ?? null
                                    }
                                });
                            });
                        }
                    }
                    const expectedConsumption = !isHarvestAction && slotItems.length > 0;
                    if (expectedConsumption && consumedSummaryNames.length === 0 && actionOutcome.success) {
                        eventItems.push({
                            icon: '✨',
                            description: 'Through exceptional care, the ingredients were preserved.',
                            category: 'inventory'
                        });
                    }

                    if (actionOutcome.success && Array.isArray(selectedResult.abilities)) {
                        selectedResult.abilities
                            .filter(ability => ability && ability.name && ability.effect)
                            .forEach(ability => {
                                eventItems.push({
                                    icon: '✨',
                                    description: `${ability.name}: ${ability.effect}`,
                                    category: 'inventory'
                                });
                            });
                    }

                    if (eventItems.length) {
                        recordEventSummaryEntry({
                            label: isHarvestAction
                                ? '🌾 Harvest Results'
                                : (isSalvageAction ? '♻️ Salvage Results' : '🛠️ Crafting Results'),
                            events: eventItems,
                            timeProgress: { advancedMinutes: appliedTimeTakenMinutes },
                            parentId: chatEntry ? chatEntry.id : null,
                            locationId: resolvedLocationId
                        });
                    }

                    let additionalEffectEntry = null;
                    if (playerOtherEffect && playerOtherEffect.trim()) {
                        const trimmedEffect = playerOtherEffect.trim();
                        additionalEffectEntry = pushChatEntry({
                            role: 'assistant',
                            type: 'player-action',
                            content: trimmedEffect,
                            parentId: chatEntry ? chatEntry.id : null
                        }, null, resolvedLocationId);
                        notifyVisibleProseEntryStored(additionalEffectEntry, {
                            clientId: payload.clientId,
                            requestId: payload.requestId,
                            proseType: 'crafting-additional-effect'
                        });

                        try {
                            const additionalEvents = await Events.runEventChecks({ textToCheck: trimmedEffect });
                            const hasAdditionalEvents = additionalEvents
                                && (
                                    (Array.isArray(additionalEvents.events) && additionalEvents.events.length)
                                    || (Array.isArray(additionalEvents.experienceAwards) && additionalEvents.experienceAwards.length)
                                    || (Array.isArray(additionalEvents.currencyChanges) && additionalEvents.currencyChanges.length)
                                    || (Array.isArray(additionalEvents.environmentalDamageEvents) && additionalEvents.environmentalDamageEvents.length)
                                    || (Array.isArray(additionalEvents.needBarChanges) && additionalEvents.needBarChanges.length)
                                    || (Array.isArray(additionalEvents.dispositionChanges) && additionalEvents.dispositionChanges.length)
                                    || (Array.isArray(additionalEvents.factionReputationChanges) && additionalEvents.factionReputationChanges.length)
                                );
                            if (hasAdditionalEvents) {
                                recordEventSummaryEntry({
                                    label: '✨ Additional Effects',
                                    events: additionalEvents.events || null,
                                    experienceAwards: additionalEvents.experienceAwards || null,
                                    currencyChanges: additionalEvents.currencyChanges || null,
                                    environmentalDamageEvents: additionalEvents.environmentalDamageEvents || null,
                                    needBarChanges: additionalEvents.needBarChanges || null,
                                    dispositionChanges: additionalEvents.dispositionChanges || null,
                                    factionReputationChanges: additionalEvents.factionReputationChanges || null,
                                    parentId: (additionalEffectEntry && additionalEffectEntry.id) || (chatEntry ? chatEntry.id : null),
                                    locationId: resolvedLocationId
                                });
                            }
                        } catch (extraEventError) {
                            console.warn('Failed to process additional crafting effects:', extraEventError?.message || extraEventError);
                        }
                    }
                }

                let questResult = null;
                try {
                    questResult = await Events.runQuestChecks({
                        allowWithoutEventChecks: true,
                        recentTextOverride: isNoProseRequest ? primaryActionSummaryText : null
                    });
                } catch (questError) {
                    console.warn('Failed to run quest checks after crafting:', questError?.message || questError);
                }

                if (questResult) {
                    try {
                        const questCompletionEntries = Events.parseQuestObjectiveStatusXml(questResult);
                        if (Array.isArray(questCompletionEntries) && questCompletionEntries.length) {
                            const questProcessingContext = {
                                player: currentPlayer,
                                location: locationRecord || null,
                                region: resolvedRegion || null,
                                stream: null,
                                experienceAwards: [],
                                currencyChanges: [],
                                environmentalDamageEvents: [],
                                needBarChanges: [],
                                dispositionChanges: [],
                                factionReputationChanges: [],
                                questCompletionRewards: [],
                                completedQuestObjectives: [],
                                followupResults: [],
                                allowEnvironmentalEffects: false,
                                isNpcTurn: false
                            };

                            await Events.processQuestObjectiveCompletionEntries(
                                questCompletionEntries,
                                questProcessingContext
                            );

                            if (Array.isArray(questProcessingContext.questCompletionRewards)
                                && questProcessingContext.questCompletionRewards.length) {
                                for (const rewardEntry of questProcessingContext.questCompletionRewards) {
                                    if (!rewardEntry || typeof rewardEntry.message !== 'string') {
                                        continue;
                                    }

                                    const parsedReward = parseQuestRewardMessage(rewardEntry.message);
                                    if (parsedReward?.rewards?.length) {
                                        const summaryLabel = rewardEntry.questName
                                            ? `🏆 Quest Completed – ${rewardEntry.questName}`
                                            : '🏆 Quest Completed';
                                        const summaryItems = parsedReward.rewards.map(line => ({
                                            description: line,
                                            icon: '🎁',
                                            category: 'quest_reward'
                                        }));
                                        recordEventSummaryEntry({
                                            label: summaryLabel,
                                            events: summaryItems,
                                            timestamp: chatEntry?.timestamp || new Date().toISOString(),
                                            parentId: chatEntry?.id || null,
                                            locationId: resolvedLocationId
                                        });
                                    }

	                                    const questRewardEntry = pushChatEntry({
	                                        role: 'assistant',
	                                        content: rewardEntry.message,
	                                        type: 'quest-reward',
	                                        locationId: resolvedLocationId,
	                                        metadata: {
	                                            questId: rewardEntry.questId || null,
	                                            questName: rewardEntry.questName || null
	                                        }
	                                    }, null, resolvedLocationId);
	                                    notifyVisibleProseEntryStored(questRewardEntry, {
	                                        clientId: payload.clientId,
	                                        requestId: payload.requestId,
	                                        proseType: 'quest-reward'
	                                    });
	                                }
	                            }

                            if (Array.isArray(questProcessingContext.completedQuestObjectives)
                                && questProcessingContext.completedQuestObjectives.length) {
                                const groupedObjectives = new Map();
                                for (const objective of questProcessingContext.completedQuestObjectives) {
                                    if (!objective) {
                                        continue;
                                    }
                                    const questLabel = objective.questName || objective.questId || 'Quest';
                                    if (!groupedObjectives.has(questLabel)) {
                                        groupedObjectives.set(questLabel, []);
                                    }
                                    groupedObjectives.get(questLabel).push(objective);
                                }

                                for (const [questLabel, objectives] of groupedObjectives.entries()) {
                                    const summaryItems = objectives.map(item => {
                                        const hasIndex = Number.isFinite(item.objectiveIndex);
                                        const displayNumber = hasIndex ? item.objectiveIndex + 1 : null;
                                        const description = item.objectiveDescription || (displayNumber !== null ? `Objective ${displayNumber}` : 'Objective completed');
                                        let label = displayNumber !== null ? `Objective ${displayNumber}: ${description}` : description;
                                        const reason = typeof item.reason === 'string' ? item.reason.trim() : '';
                                        if (reason) {
                                            label = `${label} - ${reason}`;
                                        }
                                        if (item.questJustCompleted || (!item.questJustCompleted && item.questCompleted)) {
                                            label = `${label} (Quest complete!)`;
                                        }
                                        return {
                                            description: label,
                                            icon: '✅',
                                            category: 'quest_reward'
                                        };
                                    });

                                    recordEventSummaryEntry({
                                        label: `✅ Quest Update – ${questLabel}`,
                                        events: summaryItems,
                                        timestamp: chatEntry?.timestamp || new Date().toISOString(),
                                        parentId: chatEntry?.id || null,
                                        locationId: resolvedLocationId
                                    });
                                }
                            }
                        }
                    } catch (questProcessingError) {
                        console.warn('Failed to process quest checks after crafting:', questProcessingError?.message || questProcessingError);
                    }
                }

                const craftingTimeProgress = Globals.advanceTime(appliedTimeTakenMinutes, { source: 'craft_action' });
                try {
                    Player.applyStatusEffectNeedBarsToAll();
                } catch (timeEffectError) {
                    console.warn('Failed to apply time-based need/health changes after crafting:', timeEffectError?.message || timeEffectError);
                }
                if (isHarvestAction && salvageTargetThing && recoveredThingInstances.length) {
                    salvageTargetThing.recordSuccessfulHarvest(
                        recoveredThingInstances.map(item => item.name || 'Harvested Material'),
                        { harvestedAtMinutes: Globals.getTotalWorldMinutes() }
                    );
                }
                await processDueVehicleArrivals();
                await processDueScheduledEvents({
                    entryCollector: null,
                    parentEntryId: chatEntry?.id || null,
                    source: 'craft_action'
                });

                const automaticHiddenNpcChecks = await runAutomaticHiddenNpcChecksForCurrentPlayer({
                    player: currentPlayer,
                    locationId: resolvedLocationId,
                    previouslySharedNpcIds: npcIdsSharingPlayerLocationAtTurnStart,
                    parentId: chatEntry?.id || null,
                    requestId: null
                });
                Player.recordNpcSightingsForCurrentPlayer({
                    player: currentPlayer,
                    locationId: resolvedLocationId,
                    previouslySharedNpcIds: npcIdsSharingPlayerLocationAtTurnStart
                });

                try {
                    await runAutosaveIfEnabled();
                } catch (autosaveError) {
                    console.warn('Autosave after crafting failed:', autosaveError?.message || autosaveError);
                }

                res.json({
                    success: true,
                    outcome: actionOutcome,
                    resultLevel: mappedLevel,
                    craftedItem: craftedThing ? craftedThing.toJSON() : null,
                    craftedItems: craftedThingInstances.map(item => item.toJSON ? item.toJSON() : item),
                    recoveredItems: recoveredThingInstances.map(item => item.toJSON ? item.toJSON() : item),
                    consumedThingIds,
                    narrative: {
                        description: playerActionDescription,
                        otherEffect: playerOtherEffect || null
                    },
                    plausibility: {
                        type: plausibility.type,
                        reason: plausibility.reason || null
                    },
                    unmatchedConsumedNames,
                    timeTakenMinutes: appliedTimeTakenMinutes,
                    timeProgress: craftingTimeProgress,
                    locationRefreshRequested: automaticHiddenNpcChecks.length > 0,
                    worldTime: buildWorldTimePayload({
                        transitions: Array.isArray(craftingTimeProgress?.transitions)
                            ? craftingTimeProgress.transitions
                            : []
                    })
                });
            } catch (error) {
                console.error('Error processing crafting request:', error);
                res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to process crafting request.'
                });
            }
        });

        app.post('/api/locations/:id/modify', async (req, res) => {
            let corpseProcessingRan = false;

            res.on('finish', () => {
                if (corpseProcessingRan) {
                    return;
                }
                try {
                    processNpcCorpses({ reason: 'location-modify:finish' });
                } catch (error) {
                    console.warn('Failed to process NPC corpses after location modification response:', error?.message || error);
                }
            });

            try {
                if (!currentPlayer) {
                    return res.status(400).json({
                        success: false,
                        error: 'No active player available for location modification.'
                    });
                }

                const locationId = typeof req.params.id === 'string' ? req.params.id.trim() : '';
                if (!locationId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Location ID is required.'
                    });
                }

                const locationRecord = gameLocations.get(locationId) || (typeof Location.get === 'function' ? Location.get(locationId) : null);
                if (!locationRecord) {
                    return res.status(404).json({
                        success: false,
                        error: `Location with ID '${locationId}' not found.`
                    });
                }

                const currentLocationId = typeof currentPlayer.currentLocation === 'string'
                    ? currentPlayer.currentLocation.trim()
                    : '';
                if (!currentLocationId || currentLocationId !== locationRecord.id) {
                    return res.status(400).json({
                        success: false,
                        error: 'Location modification can only target the current location.'
                    });
                }

                try {
                    await runAutosaveIfEnabled();
                } catch (autosaveError) {
                    console.warn('Autosave before location modification failed:', autosaveError?.message || autosaveError);
                }

                const payload = req.body && typeof req.body === 'object' ? req.body : {};
                const parseNoProseFlag = (value) => {
                    if (value === undefined || value === null || value === '') {
                        return false;
                    }
                    if (typeof value === 'boolean') {
                        return value;
                    }
                    if (typeof value === 'number') {
                        if (value === 1) {
                            return true;
                        }
                        if (value === 0) {
                            return false;
                        }
                        throw new Error('Invalid numeric noProse value. Use 1 or 0.');
                    }
                    if (typeof value === 'string') {
                        const normalized = value.trim().toLowerCase();
                        if (!normalized) {
                            return false;
                        }
                        if (normalized === 'true' || normalized === '1' || normalized === 'yes' || normalized === 'y' || normalized === 'on') {
                            return true;
                        }
                        if (normalized === 'false' || normalized === '0' || normalized === 'no' || normalized === 'n' || normalized === 'off') {
                            return false;
                        }
                        throw new Error(`Invalid noProse value "${value}".`);
                    }
                    throw new Error(`Unsupported noProse value type: ${typeof value}`);
                };
                const isNoProseRequest = parseNoProseFlag(payload.noProse);
                const slotEntries = Array.isArray(payload.slots) ? payload.slots : [];
                const slotItems = slotEntries
                    .map(entry => {
                        if (!entry || typeof entry !== 'object') {
                            return null;
                        }
                        const thingId = typeof entry.thingId === 'string' ? entry.thingId.trim() : '';
                        if (!thingId) {
                            return null;
                        }
                        const thing = things.get(thingId) || (typeof Thing.getById === 'function' ? Thing.getById(thingId) : null);
                        if (!thing) {
                            throw new Error(`Selected item '${thingId}' was not found.`);
                        }
                        if (typeof currentPlayer.hasInventoryItem !== 'function' || !currentPlayer.hasInventoryItem(thing)) {
                            throw new Error(`${thing.name || thing.id} is not in the current player's inventory.`);
                        }
                        if (Boolean(thing?.isEquipped || thing?.equippedSlot)) {
                            throw new Error(`${thing.name || thing.id} must be unequipped before it can be used to modify a location.`);
                        }
                        const slotIndex = Number.isFinite(Number(entry.slotIndex))
                            ? Number(entry.slotIndex)
                            : 0;
                        return { slotIndex, thing };
                    })
                    .filter(Boolean);

                const modificationRollState = { value: null };
                const modificationNotes = extractInlineDieRollFromLocationModifyText(
                    typeof payload.notes === 'string' ? payload.notes.trim() : '',
                    modificationRollState
                );

                const resolvedLocationId = requireLocationId(locationRecord.id, 'location modification');
                const resolvedRegion = locationRecord?.regionId && regions instanceof Map
                    ? regions.get(locationRecord.regionId) || null
                    : (Globals.region || null);
                const npcIdsSharingPlayerLocationAtTurnStart = Player.getNpcIdsSharingPlayerLocation({
                    player: currentPlayer,
                    locationId: resolvedLocationId
                });
                const modificationItemsForPrompt = slotItems.map(({ thing }) => ({
                    name: thing.name,
                    description: thing.description,
                    rarity: thing.rarity,
                    thingType: thing.thingType,
                    level: thing.level
                }));
                const modifiedLocationForPrompt = {
                    id: locationRecord.id,
                    name: locationRecord.name || null,
                    description: locationRecord.description || null,
                    shortDescription: locationRecord.shortDescription || null,
                    baseLevel: Number.isFinite(locationRecord.baseLevel) ? locationRecord.baseLevel : null
                };

                const baseContext = await prepareBasePromptContext({
                    locationOverride: locationRecord,
                    omitCraftHistory: true
                });

                const plausibilityRendered = promptEnv.render('base-context.xml.njk', {
                    ...baseContext,
                    promptType: 'plausibility-check-modify-location',
                    modifiedLocation: modifiedLocationForPrompt,
                    modificationNotes,
                    inputItems: modificationItemsForPrompt,
                    omitGameHistory: true
                });

                const plausibilityTemplate = parseXMLTemplate(plausibilityRendered);
                if (!plausibilityTemplate?.systemPrompt || !plausibilityTemplate?.generationPrompt) {
                    throw new Error('Location modification plausibility template did not produce prompts.');
                }

                const plausibilityResponse = await LLMClient.chatCompletion({
                    messages: [
                        { role: 'system', content: plausibilityTemplate.systemPrompt },
                        { role: 'user', content: plausibilityTemplate.generationPrompt }
                    ],
                    metadataLabel: 'location_modify_plausibility',
                    expectedXmlRootTag: 'response'
                });

                LLMClient.logPrompt({
                    metadataLabel: 'location_modify_plausibility',
                    systemPrompt: plausibilityTemplate.systemPrompt,
                    generationPrompt: plausibilityTemplate.generationPrompt,
                    response: plausibilityResponse
                });

                if (!plausibilityResponse || !plausibilityResponse.trim()) {
                    throw new Error('Location modification plausibility analysis returned no response.');
                }

                const plausibility = parsePlausibilityOutcome(plausibilityResponse);
                if (!plausibility) {
                    throw new Error('Unable to parse location modification plausibility response.');
                }

                const actionOutcome = resolveActionOutcome({
                    plausibility,
                    player: currentPlayer,
                    dieRollOverride: modificationRollState.value
                });
                if (!actionOutcome) {
                    throw new Error('Failed to resolve location modification outcome.');
                }

                const mappedLevel = mapOutcomeDegreeToCraftLevel(
                    actionOutcome.degree,
                    Number.isFinite(actionOutcome.roll?.die) ? actionOutcome.roll.die : null,
                    actionOutcome.difficulty?.label || null,
                    { level: actionOutcome.locationLevel }
                );
                if (mappedLevel === 'implausible') {
                    return res.status(400).json({
                        success: false,
                        error: plausibility.reason || 'That location modification attempt is implausible.'
                    });
                }

                let effectiveResults = await parseLocationModificationResultsResponse(plausibilityResponse);
                if (!effectiveResults.has('success')) {
                    throw new Error('Location modification plausibility response missing a standard success result.');
                }

                if (mappedLevel && mappedLevel !== 'success') {
                    const degreeResult = await renderLocationModificationOutcomeForDegree({
                        baseContext,
                        baseOutcomeXml: plausibilityResponse,
                        successOrFailure: mappedLevel,
                        location: modifiedLocationForPrompt,
                        modificationNotes,
                        inputItems: modificationItemsForPrompt
                    });
                    effectiveResults = degreeResult.results;
                    if (!effectiveResults.has(mappedLevel)) {
                        throw new Error(`Location modification success-degree response missing result for level '${mappedLevel}'.`);
                    }
                }

                let selectedResult = mappedLevel ? effectiveResults.get(mappedLevel) : null;
                if (!selectedResult) {
                    selectedResult = effectiveResults.get('success') || null;
                }
                if (!selectedResult && effectiveResults.size) {
                    selectedResult = effectiveResults.values().next().value;
                }
                if (!selectedResult) {
                    throw new Error('AI response did not include location modification results.');
                }

                const consumedNameList = Array.isArray(selectedResult.itemsConsumed)
                    ? selectedResult.itemsConsumed.filter(name => typeof name === 'string' && name.trim())
                    : [];
                const receivedNameList = Array.isArray(selectedResult.itemsReceived)
                    ? Array.from(new Set(
                        selectedResult.itemsReceived
                            .map(name => (typeof name === 'string' ? name.trim() : ''))
                            .filter(Boolean)
                    ))
                    : [];
                const availableThings = slotItems.map(entry => entry.thing);
                validateLocationModificationReceivedItemNames({
                    receivedNames: receivedNameList,
                    inputThings: availableThings
                });
                const {
                    consumedThings,
                    unmatchedConsumedNames
                } = resolveCraftConsumedThings({
                    inputThings: availableThings,
                    consumedNames: consumedNameList,
                    mode: 'location modification',
                    allowFallbackConsumeFirst: false
                });

                for (const thing of consumedThings) {
                    if (thing?.isContainer && typeof thing.getInventoryItems === 'function' && thing.getInventoryItems().length > 0) {
                        throw new Error(`Cannot consume non-empty container "${thing.name || thing.id}" while modifying a location.`);
                    }
                }

                const actorName = currentPlayer.name || 'The player';
                const locationNameBefore = locationRecord.name || 'the location';
                const alterationText = typeof selectedResult.alteration === 'string' ? selectedResult.alteration.trim() : '';
                let alterationSummary = null;
                const previousImageId = typeof locationRecord.imageId === 'string' ? locationRecord.imageId : null;

                if (selectedResult.locationChanged) {
                    if (!alterationText) {
                        throw new Error('Location modification result changed the location but did not include an alteration description.');
                    }
                    alterationSummary = await alterLocationByEvent({
                        location: locationRecord,
                        alteration: alterationText,
                        preserveBaseLevel: true
                    });
                    if (alterationSummary?.changed && pendingLocationImages && typeof pendingLocationImages.delete === 'function') {
                        pendingLocationImages.delete(locationRecord.id);
                    }
                }

                const consumedThingIds = [];
                const consumedThingNames = [];
                consumedThings.forEach(thing => {
                    const consumption = consumeThingById(thing.id);
                    consumedThingIds.push(consumption.consumedThingId);
                    consumedThingNames.push(consumption.consumedThingName);
                });

                const receivedThingIds = [];
                const receivedThingNames = [];
                if (receivedNameList.length) {
                    const generatedReceivedItems = await generateItemsByNames({
                        itemNames: receivedNameList,
                        owner: currentPlayer
                    });
                    if (!Array.isArray(generatedReceivedItems) || generatedReceivedItems.length !== receivedNameList.length) {
                        const generatedLabel = Array.isArray(generatedReceivedItems) && generatedReceivedItems.length
                            ? generatedReceivedItems.map(item => item?.name || item?.id || 'unnamed item').join(', ')
                            : '(none)';
                        throw new Error(
                            'Location modification failed to generate all received items. '
                            + `Requested: ${receivedNameList.join(', ')}. Generated: ${generatedLabel}.`
                        );
                    }
                    generatedReceivedItems.forEach(item => {
                        if (!item || typeof item.id !== 'string' || !item.id.trim()) {
                            throw new Error('Location modification generated a received item without an id.');
                        }
                        receivedThingIds.push(item.id);
                        receivedThingNames.push(item.name || item.id);
                    });
                }

                const consumedNamesForPrompt = consumedThingNames.length
                    ? consumedThingNames
                    : consumedNameList;
                const receivedNamesForPrompt = receivedThingNames.length
                    ? receivedThingNames
                    : receivedNameList;
                const primaryActionSummaryText = selectedResult.locationChanged
                    ? `${actorName} modified ${locationNameBefore}: ${alterationText}`
                    : `${actorName} attempted to modify ${locationNameBefore}, but the location did not change.`;
                const selectedTimeTakenMinutes = Number(selectedResult.timeTakenMinutes);
                const appliedTimeTakenMinutes = Number.isFinite(selectedTimeTakenMinutes) && selectedTimeTakenMinutes > 0
                    ? Math.round(selectedTimeTakenMinutes)
                    : MIN_CRAFT_TIME_ADVANCE_MINUTES;
                let playerActionDescription = '';
                let playerOtherEffect = selectedResult.other || '';
                let chatEntry = null;

                if (isNoProseRequest) {
                    playerActionDescription = primaryActionSummaryText;
                    playerOtherEffect = '';
                } else {
                    let playerActionResponse = '';
                    let locationModifyLiveDeslopInfo = null;
                    const useTinyBrainLocationModifyNarrative = isTinyBrainPromptEnabled(
                        Globals.config,
                        'location_modify_player_action'
                    );
                    try {
                        const locationModifyNarrativeContext = {
                            ...baseContext,
                            promptType: 'player-action-modify-location',
                            characterName: actorName,
                            modifiedLocation: modifiedLocationForPrompt,
                            modificationNotes,
                            alteration: alterationText,
                            consumedItems: consumedNamesForPrompt.map(name => ({ name })),
                            receivedItems: receivedNamesForPrompt.map(name => ({ name })),
                            otherEffect: selectedResult.other || null,
                            success_or_failure: actionOutcome.label || actionOutcome.degree || '',
                            authoritativeTimePassedMinutes: appliedTimeTakenMinutes
                        };
                        const tinyBrain = useTinyBrainLocationModifyNarrative
                            ? configureTinyBrainPromptContext(
                                locationModifyNarrativeContext,
                                'location_modify_player_action'
                            )
                            : null;
                        const playerActionRendered = promptEnv.render(
                            'base-context.xml.njk',
                            locationModifyNarrativeContext
                        );

                        const playerActionTemplate = parseXMLTemplate(playerActionRendered);
                        if (!playerActionTemplate?.systemPrompt || !playerActionTemplate?.generationPrompt) {
                            throw new Error('Player action location modification template missing prompts.');
                        }

                        const locationModifyRequestOptions = {
                            messages: [
                                { role: 'system', content: playerActionTemplate.systemPrompt },
                                { role: 'user', content: playerActionTemplate.generationPrompt }
                            ],
                            metadataLabel: 'location_modify_player_action',
                            metadata: {
                                clientId: typeof payload.clientId === 'string' ? payload.clientId.trim() || null : null,
                                __codexQuotaCountAsTurn: true,
                                __codexQuotaTurnKey: (typeof payload.requestId === 'string' && payload.requestId.trim())
                                    ? payload.requestId.trim()
                                    : `location_modify_turn_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`
                            },
                            expectedXmlRootTag: 'result'
                        };
                        if (useTinyBrainLocationModifyNarrative) {
                            const tinyBrainRun = await runTinyBrainNarrativePrompt({
                                family: 'location_modify_player_action',
                                initialRenderedTemplate: playerActionRendered,
                                templateContext: locationModifyNarrativeContext,
                                tinyBrain,
                                metadataLabel: 'location_modify_player_action',
                                resultBuilders: {
                                    location_modification_result: buildLocationModificationResult
                                },
                                finalParser: response => parseLocationModificationNarrativeResult(
                                    response,
                                    { expectedDurationMinutes: appliedTimeTakenMinutes }
                                ),
                                requestOptions: locationModifyRequestOptions
                            });
                            playerActionResponse = tinyBrainRun.result.aiResponse;
                            locationModifyLiveDeslopInfo = tinyBrainRun.liveDeslopController?.getDiagnostics() || null;
                        } else {
                            playerActionResponse = await LLMClient.chatCompletion(
                                locationModifyRequestOptions
                            );
                            LLMClient.logPrompt({
                                metadataLabel: 'location_modify_player_action',
                                systemPrompt: playerActionTemplate.systemPrompt,
                                generationPrompt: playerActionTemplate.generationPrompt,
                                response: playerActionResponse
                            });
                        }

                        const narrative = parseCraftingNarrativeResponse(playerActionResponse);
                        if (narrative?.description) {
                            playerActionDescription = narrative.description;
                        }
                        if (narrative?.otherEffectDescription && narrative.otherEffectDescription.toLowerCase() !== 'n/a') {
                            playerOtherEffect = narrative.otherEffectDescription;
                        }
                    } catch (actionError) {
                        if (useTinyBrainLocationModifyNarrative) {
                            throw actionError;
                        }
                        console.warn('Failed to generate location modification narrative:', actionError?.message || actionError);
                    }

                    if (!playerActionDescription) {
                        playerActionDescription = primaryActionSummaryText;
                    }
                    if (!playerOtherEffect && selectedResult.other) {
                        playerOtherEffect = selectedResult.other;
                    }

                    let narrativeContent = playerActionDescription || '';
                    let slopRemovalInfo = null;
                    if (Globals.config?.slop_buster === true && narrativeContent.trim()) {
                        const slopResult = await applySlopRemoval(narrativeContent, { returnDiagnostics: true });
                        narrativeContent = slopResult.text;
                        if (slopResult.ran) {
                            slopRemovalInfo = {
                                slopWords: slopResult.slopWords || [],
                                slopRegexes: slopResult.slopRegexes || [],
                                slopNgrams: slopResult.slopNgrams || []
                            };
                        }
                    }
                    if (locationModifyLiveDeslopInfo?.ran) {
                        slopRemovalInfo = {
                            ...(slopRemovalInfo || {}),
                            slopWords: Array.from(new Set([
                                ...(slopRemovalInfo?.slopWords || []),
                                ...(locationModifyLiveDeslopInfo.slopWords || [])
                            ])),
                            slopRegexes: Array.from(new Set([
                                ...(slopRemovalInfo?.slopRegexes || []),
                                ...(locationModifyLiveDeslopInfo.slopRegexes || [])
                            ])),
                            slopNgrams: Array.from(new Set([
                                ...(slopRemovalInfo?.slopNgrams || []),
                                ...(locationModifyLiveDeslopInfo.slopNgrams || [])
                            ])),
                            liveCorrections: [...(locationModifyLiveDeslopInfo.corrections || [])]
                        };
                    }

                    chatEntry = pushChatEntry({
                        role: 'assistant',
                        type: 'player-action',
                        content: narrativeContent,
                        metadata: {
                            actionType: 'modify_location',
                            locationId: resolvedLocationId,
                            locationName: locationNameBefore,
                            modificationNotes: modificationNotes || null,
                            alteration: alterationText || null,
                            receivedItems: receivedNamesForPrompt
                        }
                    }, null, resolvedLocationId);

                    if (chatEntry) {
                        recordPlausibilityEntry({
                            data: {
                                raw: plausibilityResponse,
                                structured: plausibility
                            },
                            parentId: chatEntry.id,
                            locationId: resolvedLocationId
                        });

                        if (slopRemovalInfo) {
                            recordSlopRemovalEntry({
                                data: slopRemovalInfo,
                                parentId: chatEntry.id,
                                locationId: resolvedLocationId
                            });
                        }
                        notifyVisibleProseEntryStored(chatEntry, {
                            clientId: payload.clientId,
                            requestId: payload.requestId,
                            proseType: 'location-modification'
                        });
                    }
                }

                recordActionOutcomeCheckResultsEntry({
                    resolution: actionOutcome,
                    actorName,
                    skillLabel: 'Location Modification',
                    reason: primaryActionSummaryText,
                    promptLabel: 'Location Modification',
                    parentId: chatEntry?.id || null,
                    locationId: resolvedLocationId,
                    requestId: payload.requestId
                });

                if (!isNoProseRequest) {
                    const eventItems = [{
                        icon: '🛠️',
                        description: primaryActionSummaryText,
                        category: 'location_world'
                    }];
                    consumedNamesForPrompt.forEach(name => {
                        eventItems.push({
                            icon: '♻️',
                            description: `Consumed ${name}.`,
                            category: 'inventory'
                        });
                    });
                    receivedNamesForPrompt.forEach(name => {
                        eventItems.push({
                            icon: '🎁',
                            description: `Received ${name}.`,
                            category: 'inventory'
                        });
                    });
                    if (slotItems.length > 0 && consumedNamesForPrompt.length === 0 && actionOutcome.success) {
                        eventItems.push({
                            icon: '✨',
                            description: 'The selected materials and tools were preserved.',
                            category: 'inventory'
                        });
                    }
                    if (actionOutcome.success && Array.isArray(selectedResult.abilities)) {
                        selectedResult.abilities
                            .filter(ability => ability && ability.name && (ability.effect || ability.description))
                            .forEach(ability => {
                                eventItems.push({
                                    icon: '✨',
                                    description: `${ability.name}: ${ability.effect || ability.description}`,
                                    category: 'location_world'
                                });
                            });
                    }

                    recordEventSummaryEntry({
                        label: '🛠️ Location Modification Results',
                        events: eventItems,
                        timeProgress: { advancedMinutes: appliedTimeTakenMinutes },
                        parentId: chatEntry ? chatEntry.id : null,
                        locationId: resolvedLocationId
                    });

                    let additionalEffectEntry = null;
                    if (playerOtherEffect && playerOtherEffect.trim()) {
                        const trimmedEffect = playerOtherEffect.trim();
                        additionalEffectEntry = pushChatEntry({
                            role: 'assistant',
                            type: 'player-action',
                            content: trimmedEffect,
                            parentId: chatEntry ? chatEntry.id : null
                        }, null, resolvedLocationId);
                        notifyVisibleProseEntryStored(additionalEffectEntry, {
                            clientId: payload.clientId,
                            requestId: payload.requestId,
                            proseType: 'location-modification-additional-effect'
                        });

                        try {
                            const additionalEvents = await Events.runEventChecks({ textToCheck: trimmedEffect });
                            const hasAdditionalEvents = additionalEvents
                                && (
                                    (Array.isArray(additionalEvents.events) && additionalEvents.events.length)
                                    || (Array.isArray(additionalEvents.experienceAwards) && additionalEvents.experienceAwards.length)
                                    || (Array.isArray(additionalEvents.currencyChanges) && additionalEvents.currencyChanges.length)
                                    || (Array.isArray(additionalEvents.environmentalDamageEvents) && additionalEvents.environmentalDamageEvents.length)
                                    || (Array.isArray(additionalEvents.needBarChanges) && additionalEvents.needBarChanges.length)
                                    || (Array.isArray(additionalEvents.dispositionChanges) && additionalEvents.dispositionChanges.length)
                                    || (Array.isArray(additionalEvents.factionReputationChanges) && additionalEvents.factionReputationChanges.length)
                                );
                            if (hasAdditionalEvents) {
                                recordEventSummaryEntry({
                                    label: '✨ Additional Effects',
                                    events: additionalEvents.events || null,
                                    experienceAwards: additionalEvents.experienceAwards || null,
                                    currencyChanges: additionalEvents.currencyChanges || null,
                                    environmentalDamageEvents: additionalEvents.environmentalDamageEvents || null,
                                    needBarChanges: additionalEvents.needBarChanges || null,
                                    dispositionChanges: additionalEvents.dispositionChanges || null,
                                    factionReputationChanges: additionalEvents.factionReputationChanges || null,
                                    parentId: (additionalEffectEntry && additionalEffectEntry.id) || (chatEntry ? chatEntry.id : null),
                                    locationId: resolvedLocationId
                                });
                            }
                        } catch (extraEventError) {
                            console.warn('Failed to process additional location modification effects:', extraEventError?.message || extraEventError);
                        }
                    }
                }

                let questResult = null;
                try {
                    questResult = await Events.runQuestChecks({
                        allowWithoutEventChecks: true,
                        recentTextOverride: isNoProseRequest ? primaryActionSummaryText : null
                    });
                } catch (questError) {
                    console.warn('Failed to run quest checks after location modification:', questError?.message || questError);
                }

                if (questResult) {
                    try {
                        const questCompletionEntries = Events.parseQuestObjectiveStatusXml(questResult);
                        if (Array.isArray(questCompletionEntries) && questCompletionEntries.length) {
                            const questProcessingContext = {
                                player: currentPlayer,
                                location: locationRecord || null,
                                region: resolvedRegion || null,
                                stream: null,
                                experienceAwards: [],
                                currencyChanges: [],
                                environmentalDamageEvents: [],
                                needBarChanges: [],
                                dispositionChanges: [],
                                factionReputationChanges: [],
                                questCompletionRewards: [],
                                completedQuestObjectives: [],
                                followupResults: [],
                                allowEnvironmentalEffects: false,
                                isNpcTurn: false
                            };

                            await Events.processQuestObjectiveCompletionEntries(
                                questCompletionEntries,
                                questProcessingContext
                            );

                            if (Array.isArray(questProcessingContext.questCompletionRewards)
                                && questProcessingContext.questCompletionRewards.length) {
                                for (const rewardEntry of questProcessingContext.questCompletionRewards) {
                                    if (!rewardEntry || typeof rewardEntry.message !== 'string') {
                                        continue;
                                    }

                                    const parsedReward = parseQuestRewardMessage(rewardEntry.message);
                                    if (parsedReward?.rewards?.length) {
                                        const summaryLabel = rewardEntry.questName
                                            ? `🏆 Quest Completed – ${rewardEntry.questName}`
                                            : '🏆 Quest Completed';
                                        const summaryItems = parsedReward.rewards.map(line => ({
                                            description: line,
                                            icon: '🎁',
                                            category: 'quest_reward'
                                        }));
                                        recordEventSummaryEntry({
                                            label: summaryLabel,
                                            events: summaryItems,
                                            timestamp: chatEntry?.timestamp || new Date().toISOString(),
                                            parentId: chatEntry?.id || null,
                                            locationId: resolvedLocationId
                                        });
                                    }

	                                    const questRewardEntry = pushChatEntry({
	                                        role: 'assistant',
	                                        content: rewardEntry.message,
	                                        type: 'quest-reward',
	                                        locationId: resolvedLocationId,
	                                        metadata: {
	                                            questId: rewardEntry.questId || null,
	                                            questName: rewardEntry.questName || null
	                                        }
	                                    }, null, resolvedLocationId);
	                                    notifyVisibleProseEntryStored(questRewardEntry, {
	                                        clientId: payload.clientId,
	                                        requestId: payload.requestId,
	                                        proseType: 'quest-reward'
	                                    });
	                                }
	                            }

                            if (Array.isArray(questProcessingContext.completedQuestObjectives)
                                && questProcessingContext.completedQuestObjectives.length) {
                                const groupedObjectives = new Map();
                                for (const objective of questProcessingContext.completedQuestObjectives) {
                                    if (!objective) {
                                        continue;
                                    }
                                    const questLabel = objective.questName || objective.questId || 'Quest';
                                    if (!groupedObjectives.has(questLabel)) {
                                        groupedObjectives.set(questLabel, []);
                                    }
                                    groupedObjectives.get(questLabel).push(objective);
                                }

                                for (const [questLabel, objectives] of groupedObjectives.entries()) {
                                    const summaryItems = objectives.map(item => {
                                        const hasIndex = Number.isFinite(item.objectiveIndex);
                                        const displayNumber = hasIndex ? item.objectiveIndex + 1 : null;
                                        const description = item.objectiveDescription || (displayNumber !== null ? `Objective ${displayNumber}` : 'Objective completed');
                                        let label = displayNumber !== null ? `Objective ${displayNumber}: ${description}` : description;
                                        const reason = typeof item.reason === 'string' ? item.reason.trim() : '';
                                        if (reason) {
                                            label = `${label} - ${reason}`;
                                        }
                                        if (item.questJustCompleted || (!item.questJustCompleted && item.questCompleted)) {
                                            label = `${label} (Quest complete!)`;
                                        }
                                        return {
                                            description: label,
                                            icon: '✅',
                                            category: 'quest_reward'
                                        };
                                    });

                                    recordEventSummaryEntry({
                                        label: `✅ Quest Update – ${questLabel}`,
                                        events: summaryItems,
                                        timestamp: chatEntry?.timestamp || new Date().toISOString(),
                                        parentId: chatEntry?.id || null,
                                        locationId: resolvedLocationId
                                    });
                                }
                            }
                        }
                    } catch (questProcessingError) {
                        console.warn('Failed to process quest checks after location modification:', questProcessingError?.message || questProcessingError);
                    }
                }

                const modificationTimeProgress = Globals.advanceTime(appliedTimeTakenMinutes, { source: 'location_modify_action' });
                try {
                    Player.applyStatusEffectNeedBarsToAll();
                } catch (timeEffectError) {
                    console.warn('Failed to apply time-based need/health changes after location modification:', timeEffectError?.message || timeEffectError);
                }
                await processDueVehicleArrivals();
                await processDueScheduledEvents({
                    entryCollector: null,
                    parentEntryId: chatEntry?.id || null,
                    source: 'location_modify_action'
                });

                const automaticHiddenNpcChecks = await runAutomaticHiddenNpcChecksForCurrentPlayer({
                    player: currentPlayer,
                    locationId: resolvedLocationId,
                    previouslySharedNpcIds: npcIdsSharingPlayerLocationAtTurnStart,
                    parentId: chatEntry?.id || null,
                    requestId: null
                });
                Player.recordNpcSightingsForCurrentPlayer({
                    player: currentPlayer,
                    locationId: resolvedLocationId,
                    previouslySharedNpcIds: npcIdsSharingPlayerLocationAtTurnStart
                });

                const locationPayload = buildLocationResponse(locationRecord);
                if (!locationPayload) {
                    throw new Error('Failed to serialize location after modification.');
                }

                const imageCleared = Boolean(alterationSummary?.changed && previousImageId && !locationRecord.imageId);

                res.json({
                    success: true,
                    location: locationPayload,
                    outcome: actionOutcome,
                    resultLevel: mappedLevel,
                    plausibility: {
                        type: plausibility.type,
                        reason: plausibility.reason || null
                    },
                    modification: {
                        locationChanged: Boolean(selectedResult.locationChanged),
                        alteration: alterationText || null,
                        alterationSummary
                    },
                    consumedThingIds,
                    consumedThingNames,
                    receivedThingIds,
                    receivedThingNames,
                    narrative: {
                        description: playerActionDescription,
                        otherEffect: playerOtherEffect || null
                    },
                    unmatchedConsumedNames,
                    timeTakenMinutes: appliedTimeTakenMinutes,
                    timeProgress: modificationTimeProgress,
                    locationRefreshRequested: automaticHiddenNpcChecks.length > 0,
                    worldTime: buildWorldTimePayload({
                        transitions: Array.isArray(modificationTimeProgress?.transitions)
                            ? modificationTimeProgress.transitions
                            : []
                    }),
                    imageCleared
                });
            } catch (error) {
                console.error('Error processing location modification request:', error);
                const message = error?.message || 'Failed to process location modification request.';
                const status = /not found/i.test(message)
                    ? 404
                    : (/inventory|equipped|Select at least|current location|Location ID|required/i.test(message) ? 400 : 500);
                res.status(status).json({
                    success: false,
                    error: message
                });
            }
        });

        // ==================== LOCATION GENERATION FUNCTIONALITY ====================

        // Generate a new region using AI
        app.post('/api/regions/generate', async (req, res) => {
            const body = req.body || {};
            const stream = createStreamEmitter({ clientId: body.clientId, requestId: body.requestId });

            try {
                const { regionName, regionDescription, regionNotes } = body;
                const activeSetting = getActiveSettingSnapshot();

                const options = {
                    setting: describeSettingForPrompt(activeSetting),
                    regionName: regionName && regionName.trim() ? regionName.trim() : null,
                    regionDescription: regionDescription || null,
                    regionNotes: regionDescription || null,
                    report: (stage, info = {}) => {
                        const message = info.message || `Stage: ${stage}`;
                        stream.emit('generation_status', {
                            scope: 'region',
                            stage,
                            message
                        });
                    }
                };

                console.log('🏗️  Starting region generation with options derived from current setting:', options);

                const result = await generateRegionFromPrompt(options);

                stream.emit('generation_status', {
                    scope: 'region',
                    stage: 'region:complete',
                    message: `Region "${result.region.name}" ready.`
                });

                if (stream.isEnabled) {
                    stream.emit('region_generated', {
                        region: result.region.toJSON(),
                        createdLocationIds: result.region.locationIds,
                        entranceLocationId: result.region.entranceLocationId || result.entranceLocationId
                    });
                }

                const payload = {
                    success: true,
                    region: result.region.toJSON(),
                    createdLocationIds: result.region.locationIds,
                    createdLocations: result.createdLocations.map(loc => loc.toJSON()),
                    entranceLocationId: result.region.entranceLocationId || result.entranceLocationId,
                    message: `Region "${result.region.name}" generated with ${result.region.locationIds.length} stub locations.`
                };

                if (stream.requestId) {
                    payload.requestId = stream.requestId;
                }

                res.json(payload);
            } catch (error) {
                console.error('Error generating region:', error);
                stream.emit('generation_status', {
                    scope: 'region',
                    stage: 'error',
                    message: error.message || 'Region generation failed.'
                });
                const errorPayload = {
                    success: false,
                    error: error.message
                };
                if (stream.requestId) {
                    errorPayload.requestId = stream.requestId;
                }
                res.status(500).json(errorPayload);
            }
        });

        // Generate a new location using AI
        app.post('/api/locations/generate', async (req, res) => {
            const body = req.body || {};
            const stream = createStreamEmitter({ clientId: body.clientId, requestId: body.requestId });

            try {
                const activeSetting = getActiveSettingSnapshot();
                const derivedLocationStyle = resolveLocationStyle(body.locationStyle, activeSetting);
                const settingDescription = describeSettingForPrompt(activeSetting);
                const shortDescription = buildLocationShortDescription(derivedLocationStyle, activeSetting);
                const locationPurpose = buildLocationPurpose(derivedLocationStyle, activeSetting);
                const playerLevel = getSuggestedPlayerLevel(activeSetting);

                const options = {
                    setting: settingDescription,
                    theme: derivedLocationStyle,
                    locationTheme: derivedLocationStyle,
                    locationStyle: derivedLocationStyle,
                    shortDescription,
                    locationPurpose,
                    playerLevel,
                    settingInfoId: activeSetting?.id || null
                };

                console.log('🏗️  Starting location generation with options derived from current setting:', options);

                stream.emit('generation_status', {
                    scope: 'location',
                    stage: 'start',
                    message: 'Generating new location.'
                });

                const result = await generateLocationFromPrompt(options);

                stream.emit('generation_status', {
                    scope: 'location',
                    stage: 'complete',
                    message: `Location "${result.location.name || result.location.id}" generated.`
                });

                const locationData = result.location.toJSON();
                locationData.pendingImageJobId = pendingLocationImages.get(result.location.id) || null;
                locationData.npcs = buildNpcProfiles(result.location);
                locationData.things = buildThingProfiles(result.location);

                if (stream.isEnabled) {
                    stream.emit('location_generated', {
                        location: locationData,
                        locationId: result.location.id
                    });
                }

                const payload = {
                    success: true,
                    location: locationData,
                    locationId: result.location.id,
                    locationName: result.location.name,
                    gameWorldStats: {
                        totalLocations: gameLocations.size,
                        totalLocationExits: gameLocationExits.size,
                        totalThings: things.size
                    },
                    generationInfo: {
                        aiResponse: result.aiResponse,
                        options: result.generationOptions,
                        activeSetting,
                        requestedLocationStyle: derivedLocationStyle,
                        newStubs: result.newStubs || []
                    },
                    message: `Location "${result.location.name || result.location.id}" generated successfully`
                };

                if (stream.requestId) {
                    payload.requestId = stream.requestId;
                }

                res.json(payload);

            } catch (error) {
                console.error('Error in location generation API:', error);

                let errorMessage = error.message;
                let statusCode = 500;

                if (error.code === 'ECONNABORTED') {
                    errorMessage = 'Request timeout - AI API took too long to respond';
                    statusCode = 408;
                } else if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
                    errorMessage = 'Cannot connect to AI API - check your endpoint URL';
                    statusCode = 503;
                } else if (error.response) {
                    const apiStatusCode = error.response.status;
                    const apiErrorMessage = error.response.data?.error?.message || 'API request failed';
                    errorMessage = `AI API Error (${apiStatusCode}): ${apiErrorMessage}`;
                    statusCode = apiStatusCode;
                }

                stream.emit('generation_status', {
                    scope: 'location',
                    stage: 'error',
                    message: errorMessage
                });

                const errorPayload = {
                    success: false,
                    error: errorMessage,
                    details: error.message
                };

                if (stream.requestId) {
                    errorPayload.requestId = stream.requestId;
                }

                res.status(statusCode).json(errorPayload);
            }
        });

        // ==================== THING MANAGEMENT API ENDPOINTS ====================

        const THING_FLAG_KEY_TO_FLAG = Thing.booleanFlagMap;
        const THING_BOOLEAN_FLAG_KEYS = Thing.booleanFlagKeys;

        function parseThingBooleanFlagValue(value, key) {
            if (value === undefined) {
                return undefined;
            }
            if (value === null) {
                return null;
            }
            if (typeof value === 'boolean') {
                return value;
            }
            if (typeof value === 'number') {
                if (value === 1) {
                    return true;
                }
                if (value === 0) {
                    return false;
                }
                throw new Error(`Invalid numeric value for ${key}. Use 1 or 0.`);
            }
            if (typeof value === 'string') {
                const normalized = value.trim().toLowerCase();
                if (!normalized || normalized === 'null') {
                    return null;
                }
                if (normalized === 'true' || normalized === '1' || normalized === 'yes' || normalized === 'y' || normalized === 'on') {
                    return true;
                }
                if (normalized === 'false' || normalized === '0' || normalized === 'no' || normalized === 'n' || normalized === 'off') {
                    return false;
                }
                throw new Error(`Invalid boolean string value "${value}" for ${key}.`);
            }
            throw new Error(`Unsupported value type for ${key}: ${typeof value}`);
        }

        function extractThingBooleanFlagsFromPayload(payload = {}) {
            const flags = {};
            for (const key of THING_BOOLEAN_FLAG_KEYS) {
                if (Object.prototype.hasOwnProperty.call(payload, key)) {
                    flags[key] = parseThingBooleanFlagValue(payload[key], key);
                }
            }
            return flags;
        }

        function applyThingBooleanFlagsToInstance(thing, flags = {}) {
            if (!thing || typeof thing !== 'object') {
                return;
            }
            const entries = Object.entries(flags).filter(([, value]) => value !== undefined);
            if (!entries.length) {
                return;
            }
            let mutated = false;
            for (const [key, value] of entries) {
                const flagName = THING_FLAG_KEY_TO_FLAG[key] || null;
                const enabled = value === null ? false : Boolean(value);
                if (flagName && typeof thing.hasFlag === 'function' && typeof thing.setFlag === 'function') {
                    const current = thing.hasFlag(flagName);
                    if (current !== enabled) {
                        thing.setFlag(flagName, enabled);
                        mutated = true;
                    }
                } else if (key in thing) {
                    if (thing[key] !== enabled) {
                        thing[key] = enabled;
                        mutated = true;
                    }
                }
            }
        }

        // Create a new thing
        app.post('/api/things', async (req, res) => {
            try {
                const {
                    name,
                    description,
                    shortDescription,
                    thingType,
                    imageId,
                    rarity,
                    itemTypeDetail,
                    metadata,
                    slot,
                    attributeBonuses,
                    causeStatusEffect,
                    causeStatusEffectOnTarget,
                    causeStatusEffectOnEquipper,
                    count,
                    level,
                    relativeLevel,
                    containerContents,
                    statusEffects
                } = req.body || {};
                const normalizedShortDescription = shortDescription ?? null;
                const booleanFlags = extractThingBooleanFlagsFromPayload(req.body || {});
                const registeredCreateFields = getRegisteredThingPayloadFields({ create: true, edit: true });
                const registeredCreateFieldPayload = extractRegisteredThingPayloadFieldValues(req.body || {}, registeredCreateFields);

                const thing = new Thing({
                    name,
                    description,
                    shortDescription: normalizedShortDescription,
                    thingType,
                    imageId,
                    rarity,
                    itemTypeDetail,
                    metadata,
                    slot: registeredCreateFieldPayload.shouldClearSlot ? null : slot,
                    attributeBonuses,
                    causeStatusEffect: (function buildCauseEffect() {
                        if (causeStatusEffectOnTarget || causeStatusEffectOnEquipper) {
                            const entries = [];
                            if (causeStatusEffectOnTarget) {
                                entries.push({ ...causeStatusEffectOnTarget, applyToTarget: true });
                            }
                            if (causeStatusEffectOnEquipper) {
                                entries.push({ ...causeStatusEffectOnEquipper, applyToEquipper: true });
                            }
                            return entries;
                        }
                        return causeStatusEffect;
                    }()),
                    count,
                    level,
                    relativeLevel,
                    containerContents,
                    statusEffects,
                    ...registeredCreateFieldPayload.values,
                    ...booleanFlags
                });

                things.set(thing.id, thing);

                if (typeof Globals.ensureThingNamesAllowed !== 'function') {
                    throw new Error('Globals.ensureThingNamesAllowed is unavailable for item name validation.');
                }
                await Globals.ensureThingNamesAllowed({
                    things: [thing],
                    location: Globals.location || null,
                    region: Globals.region || null
                });

                const imageEligible = shouldGenerateThingImage(thing);
                if (!imageEligible) {
                    console.log(`🎒 Skipping automatic image generation for ${thing.name} (${thing.id}) - not in player inventory`);
                } else {
                    thing.imageId = null;
                }

                res.json({
                    success: true,
                    thing: thing.toJSON(),
                    message: 'Thing created successfully',
                    imageNeedsGeneration: Boolean(imageEligible)
                });
            } catch (error) {
                res.status(400).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Get all things (with optional type filtering)
        app.get('/api/things', (req, res) => {
            try {
                const { type } = req.query;
                let result = Array.from(things.values()).map(thing => thing.toJSON());

                if (type) {
                    if (!Thing.validTypes.includes(type)) {
                        return res.status(400).json({
                            success: false,
                            error: `Invalid type. Must be one of: ${Thing.validTypes.join(', ')}`
                        });
                    }
                    result = result.filter(thing => thing.thingType === type);
                }

                res.json({
                    success: true,
                    things: result,
                    count: result.length
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        function createAiItemSearchValidationError(message) {
            const error = new Error(message);
            error.statusCode = 400;
            return error;
        }

        function normalizeAiItemSearchText(value, fieldName) {
            if (value === undefined || value === null) {
                return '';
            }
            if (typeof value === 'string') {
                return value.trim();
            }
            if (typeof value === 'number' || typeof value === 'boolean') {
                return String(value).trim();
            }
            throw createAiItemSearchValidationError(`AI item search ${fieldName} must be a string, number, boolean, or blank value.`);
        }

        function normalizeAiItemSearchItem(rawItem, index) {
            if (!rawItem || typeof rawItem !== 'object' || Array.isArray(rawItem)) {
                throw createAiItemSearchValidationError(`AI item search item ${index + 1} must be an object.`);
            }

            const id = normalizeAiItemSearchText(rawItem.id, `item ${index + 1} id`);
            const name = normalizeAiItemSearchText(rawItem.name, `item ${index + 1} name`);
            if (!id) {
                throw createAiItemSearchValidationError(`AI item search item ${index + 1} is missing id.`);
            }
            if (!name) {
                throw createAiItemSearchValidationError(`AI item search item ${index + 1} is missing name.`);
            }

            return {
                id,
                name,
                description: normalizeAiItemSearchText(rawItem.description, `item ${index + 1} description`),
                level: normalizeAiItemSearchText(rawItem.level, `item ${index + 1} level`),
                quality: normalizeAiItemSearchText(rawItem.quality, `item ${index + 1} quality`),
                quantity: normalizeAiItemSearchText(rawItem.quantity, `item ${index + 1} quantity`),
                equipmentSlot: normalizeAiItemSearchText(rawItem.equipmentSlot, `item ${index + 1} equipment slot`)
            };
        }

        function parseAiItemSearchResponse(responseText) {
            const resultsBlock = Utils.extractFinalXmlRootBlock(responseText || '', 'results');
            if (!resultsBlock) {
                throw new Error('AI item search response did not include a <results> block.');
            }

            const doc = Utils.parseXmlDocument(resultsBlock, 'text/xml');
            const parserError = doc.getElementsByTagName('parsererror')[0];
            if (parserError) {
                throw new Error(`Failed to parse AI item search results: ${parserError.textContent}`);
            }

            return Array.from(doc.getElementsByTagName('item'))
                .map(node => (node?.textContent || '').trim())
                .filter(Boolean);
        }

        app.post('/api/things/ai-search', async (req, res) => {
            let parsedTemplate = null;
            let responseText = '';
            const metadataLabel = 'ai_item_search';
            try {
                const criteria = normalizeAiItemSearchText(req.body?.criteria, 'criteria');
                if (!criteria) {
                    return res.status(400).json({
                        success: false,
                        error: 'AI item search criteria are required.'
                    });
                }

                if (!Array.isArray(req.body?.items)) {
                    return res.status(400).json({
                        success: false,
                        error: 'AI item search items must be an array.'
                    });
                }

                const items = req.body.items.map((item, index) => normalizeAiItemSearchItem(item, index));
                if (!items.length) {
                    return res.json({
                        success: true,
                        criteria,
                        resultNames: [],
                        matchedIds: [],
                        unmatchedNames: [],
                        response: ''
                    });
                }

                const mode = req.body?.mode === 'lenient' ? 'lenient' : 'strict';
                const renderedTemplate = promptEnv.render('ai-item-search.xml.njk', {
                    items,
                    criteria,
                    mode
                });
                parsedTemplate = parseXMLTemplate(renderedTemplate, { metadataLabel });
                responseText = await LLMClient.chatCompletion({
                    messages: [
                        { role: 'system', content: parsedTemplate.systemPrompt },
                        { role: 'user', content: parsedTemplate.generationPrompt }
                    ],
                    temperature: parsedTemplate.temperature,
                    metadataLabel,
                    validateXML: false,
                    expectedXmlRootTag: 'results',
                    requiredRegex: /<results[\s\S]*<\/results>/i
                });

                LLMClient.logPrompt({
                    prefix: metadataLabel,
                    metadataLabel,
                    systemPrompt: parsedTemplate.systemPrompt,
                    generationPrompt: parsedTemplate.generationPrompt,
                    response: responseText
                });

                const resultNames = parseAiItemSearchResponse(responseText);
                const normalizedResultNames = new Set(resultNames.map(name => name.toLowerCase()));
                const matchedIds = items
                    .filter(item => normalizedResultNames.has(item.name.toLowerCase()))
                    .map(item => item.id);
                const availableNames = new Set(items.map(item => item.name.toLowerCase()));
                const unmatchedNames = resultNames.filter(name => !availableNames.has(name.toLowerCase()));

                res.json({
                    success: true,
                    criteria,
                    mode,
                    resultNames,
                    matchedIds,
                    unmatchedNames,
                    response: responseText
                });
            } catch (error) {
                if (parsedTemplate) {
                    LLMClient.logPrompt({
                        prefix: metadataLabel,
                        metadataLabel,
                        systemPrompt: parsedTemplate.systemPrompt || '',
                        generationPrompt: parsedTemplate.generationPrompt || '',
                        response: responseText || '',
                        sections: [
                            {
                                title: 'Error',
                                content: error?.stack || error?.message || String(error)
                            }
                        ]
                    });
                }
                const statusCode = Number.isInteger(error?.statusCode) ? error.statusCode : 500;
                res.status(statusCode).json({
                    success: false,
                    error: error.message || 'AI item search failed.'
                });
            }
        });

        function createAiItemCombinerValidationError(message) {
            const error = new Error(message);
            error.statusCode = 400;
            return error;
        }

        function normalizeAiItemCombinerText(value, fieldName) {
            if (value === undefined || value === null) {
                return '';
            }
            if (typeof value === 'string') {
                return value.trim();
            }
            if (typeof value === 'number' || typeof value === 'boolean') {
                return String(value).trim();
            }
            throw createAiItemCombinerValidationError(`AI item combiner ${fieldName} must be a string, number, boolean, or blank value.`);
        }

        function formatAiItemCombinerModifierValue(value) {
            const numeric = Number(value);
            if (Number.isFinite(numeric)) {
                return numeric > 0 ? `+${numeric}` : String(numeric);
            }
            const text = normalizeAiItemCombinerText(value, 'modifier value');
            return text || '0';
        }

        function formatAiItemCombinerNamedModifier(entry, nameKeys, valueKeys) {
            if (!entry || typeof entry !== 'object') {
                return '';
            }
            const name = nameKeys
                .map(key => normalizeAiItemCombinerText(entry[key], key))
                .find(Boolean) || '';
            if (!name) {
                return '';
            }
            const rawValue = valueKeys
                .map(key => entry[key])
                .find(value => value !== undefined && value !== null && value !== '');
            return `${name} ${formatAiItemCombinerModifierValue(rawValue)}`;
        }

        function formatAiItemCombinerStatusEffect(effect, label) {
            if (!effect) {
                return '';
            }
            if (typeof effect === 'string') {
                const text = effect.trim();
                return text ? `- ${label}: ${text}` : '';
            }
            if (typeof effect !== 'object') {
                return '';
            }

            const name = normalizeAiItemCombinerText(effect.name, 'status effect name');
            const description = normalizeAiItemCombinerText(effect.description, 'status effect description');
            const duration = normalizeAiItemCombinerText(effect.duration, 'status effect duration');
            const base = [name, description].filter(Boolean).join(' - ');
            if (!base) {
                return '';
            }

            const details = [];
            if (duration) {
                details.push(`duration: ${duration}`);
            }
            const attributeModifiers = Array.isArray(effect.attributes)
                ? effect.attributes
                    .map(entry => formatAiItemCombinerNamedModifier(entry, ['attribute', 'name'], ['modifier', 'bonus', 'value']))
                    .filter(Boolean)
                : [];
            if (attributeModifiers.length) {
                details.push(`attributes: ${attributeModifiers.join(', ')}`);
            }
            const skillModifiers = Array.isArray(effect.skills)
                ? effect.skills
                    .map(entry => formatAiItemCombinerNamedModifier(entry, ['skill', 'name'], ['modifier', 'bonus', 'value']))
                    .filter(Boolean)
                : [];
            if (skillModifiers.length) {
                details.push(`skills: ${skillModifiers.join(', ')}`);
            }
            const needBarModifiers = Array.isArray(effect.needBars)
                ? effect.needBars
                    .map(entry => formatAiItemCombinerNamedModifier(entry, ['name'], ['delta', 'modifier', 'bonus', 'value']))
                    .filter(Boolean)
                : [];
            if (needBarModifiers.length) {
                details.push(`need bars: ${needBarModifiers.join(', ')}`);
            }

            return `- ${label}: ${base}${details.length ? ` (${details.join('; ')})` : ''}`;
        }

        function formatAiItemCombinerStatusEffects(thing, fallbackText = '') {
            const metadata = thing?.metadata && typeof thing.metadata === 'object' ? thing.metadata : {};
            const lines = [];
            const addLine = (line) => {
                const text = typeof line === 'string' ? line.trim() : '';
                if (text && !lines.includes(text)) {
                    lines.push(text);
                }
            };

            const ownEffects = typeof thing?.getStatusEffects === 'function'
                ? thing.getStatusEffects()
                : (Array.isArray(thing?.statusEffects)
                    ? thing.statusEffects
                    : (Array.isArray(metadata.statusEffects) ? metadata.statusEffects : []));
            ownEffects.forEach(effect => addLine(formatAiItemCombinerStatusEffect(effect, 'self')));

            const targetEffect = thing?.causeStatusEffectOnTarget || metadata.causeStatusEffectOnTarget || null;
            const equipperEffect = thing?.causeStatusEffectOnEquipper || metadata.causeStatusEffectOnEquipper || null;
            addLine(formatAiItemCombinerStatusEffect(targetEffect, 'target'));
            addLine(formatAiItemCombinerStatusEffect(equipperEffect, 'equipper'));

            const legacyEffect = thing?.causeStatusEffect || metadata.causeStatusEffect || null;
            if (legacyEffect && !targetEffect && !equipperEffect) {
                const appliesToTarget = Boolean(legacyEffect.applyToTarget);
                const appliesToEquipper = Boolean(legacyEffect.applyToEquipper);
                const label = appliesToTarget && appliesToEquipper
                    ? 'target/equipper'
                    : (appliesToEquipper ? 'equipper' : (appliesToTarget ? 'target' : 'status'));
                addLine(formatAiItemCombinerStatusEffect(legacyEffect, label));
            }

            return lines.length ? lines.join('\n') : normalizeAiItemCombinerText(fallbackText, 'status effects');
        }

        function formatAiItemCombinerStatModifiers(thing, fallbackText = '') {
            const metadata = thing?.metadata && typeof thing.metadata === 'object' ? thing.metadata : {};
            const bonuses = Array.isArray(thing?.attributeBonuses)
                ? thing.attributeBonuses
                : (Array.isArray(metadata.attributeBonuses) ? metadata.attributeBonuses : []);
            const lines = bonuses
                .map(entry => formatAiItemCombinerNamedModifier(entry, ['attribute', 'name'], ['bonus', 'value', 'modifier']))
                .filter(Boolean)
                .map(text => `- ${text}`);
            return lines.length ? lines.join('\n') : normalizeAiItemCombinerText(fallbackText, 'stat modifiers');
        }

        function normalizeAiItemCombinerItem(rawItem, index) {
            if (!rawItem || typeof rawItem !== 'object' || Array.isArray(rawItem)) {
                throw createAiItemCombinerValidationError(`AI item combiner item ${index + 1} must be an object.`);
            }

            const id = normalizeAiItemCombinerText(rawItem.id, `item ${index + 1} id`);
            const name = normalizeAiItemCombinerText(rawItem.name, `item ${index + 1} name`);
            if (!id) {
                throw createAiItemCombinerValidationError(`AI item combiner item ${index + 1} is missing id.`);
            }
            if (!name) {
                throw createAiItemCombinerValidationError(`AI item combiner item ${index + 1} is missing name.`);
            }

            return {
                id,
                name,
                description: normalizeAiItemCombinerText(rawItem.description, `item ${index + 1} description`),
                level: normalizeAiItemCombinerText(rawItem.level, `item ${index + 1} level`),
                quality: normalizeAiItemCombinerText(rawItem.quality, `item ${index + 1} quality`),
                quantity: normalizeAiItemCombinerText(rawItem.quantity, `item ${index + 1} quantity`),
                equipmentSlot: normalizeAiItemCombinerText(rawItem.equipmentSlot, `item ${index + 1} equipment slot`),
                statusEffects: normalizeAiItemCombinerText(rawItem.statusEffects, `item ${index + 1} status effects`),
                statModifiers: normalizeAiItemCombinerText(
                    rawItem.statModifiers ?? rawItem.statBonuses,
                    `item ${index + 1} stat modifiers`
                )
            };
        }

        function parseAiItemCombinerResponse(responseText) {
            const groupsBlock = Utils.extractFinalXmlRootBlock(responseText || '', 'combinationGroups');
            if (!groupsBlock) {
                throw new Error('AI item combiner response did not include a <combinationGroups> block.');
            }

            const doc = Utils.parseXmlDocumentStrict(groupsBlock, 'text/xml');
            const parserError = doc.getElementsByTagName('parsererror')[0];
            if (parserError) {
                throw new Error(`Failed to parse AI item combiner groups: ${parserError.textContent}`);
            }

            const seenItemIds = new Set();
            return Array.from(doc.getElementsByTagName('group')).map((groupNode, index) => {
                const itemIds = Array.from(groupNode.getElementsByTagName('itemId'))
                    .map(node => (node?.textContent || '').trim())
                    .filter(Boolean);
                const uniqueItemIds = Array.from(new Set(itemIds));
                if (uniqueItemIds.length < 2) {
                    throw new Error(`AI item combiner group ${index + 1} must include at least two itemId entries.`);
                }

                for (const itemId of uniqueItemIds) {
                    if (seenItemIds.has(itemId)) {
                        throw new Error(`AI item combiner item id "${itemId}" appeared in more than one group.`);
                    }
                    seenItemIds.add(itemId);
                }

                const reasonNode = groupNode.getElementsByTagName('reason')[0];
                return {
                    reason: (reasonNode?.textContent || '').trim(),
                    itemIds: uniqueItemIds
                };
            });
        }

        function getItemCombinerQualityKey(thing) {
            const metadata = thing?.metadata && typeof thing.metadata === 'object' ? thing.metadata : {};
            const candidates = [
                thing?.rarity,
                thing?.quality,
                metadata.rarity,
                metadata.quality
            ];
            for (const candidate of candidates) {
                if (typeof candidate === 'string' && candidate.trim()) {
                    return candidate.trim().toLowerCase();
                }
            }
            if (typeof Thing !== 'undefined' && Thing && typeof Thing.getDefaultRarityKey === 'function') {
                const fallback = Thing.getDefaultRarityKey();
                if (typeof fallback === 'string' && fallback.trim()) {
                    return fallback.trim().toLowerCase();
                }
            }
            return 'default';
        }

        function getItemCombinerHolderKey(context) {
            if (context?.container?.id) {
                return `container:${context.container.id}`;
            }
            if (context?.owner?.id) {
                return `owner:${context.owner.id}`;
            }
            if (context?.location?.id) {
                return `location:${context.location.id}`;
            }
            throw new Error('Item stack does not have a resolvable holder.');
        }

        function validateItemCombinerMergeSet(keepThing, mergeThings, contextResolver = resolveThingContainerContext) {
            if (!keepThing?.id) {
                throw createAiItemCombinerValidationError('A kept item stack id is required.');
            }
            if (!Array.isArray(mergeThings) || mergeThings.length === 0) {
                throw createAiItemCombinerValidationError('At least one item stack to merge is required.');
            }
            if (typeof contextResolver !== 'function') {
                throw new Error('Item combiner holder resolver is unavailable.');
            }

            const allThings = [keepThing, ...mergeThings];
            const seenIds = new Set();
            let qualityKey = null;
            let holderKey = null;
            let owner = null;
            let container = null;
            let location = null;

            for (const thing of allThings) {
                if (!thing?.id) {
                    throw createAiItemCombinerValidationError('Every item stack in a combine request must have an id.');
                }
                if (seenIds.has(thing.id)) {
                    throw createAiItemCombinerValidationError(`Duplicate item stack "${thing.id}" cannot be combined with itself.`);
                }
                seenIds.add(thing.id);

                if ((thing.thingType || '').trim().toLowerCase() !== 'item') {
                    throw createAiItemCombinerValidationError('Only item-type stacks can be combined.');
                }
                if (thing.isContainer) {
                    throw createAiItemCombinerValidationError('Containers cannot be combined.');
                }
                if (thing.isEquipped || thing.equippedSlot) {
                    throw createAiItemCombinerValidationError('Equipped items cannot be combined.');
                }

                const currentQualityKey = getItemCombinerQualityKey(thing);
                if (qualityKey === null) {
                    qualityKey = currentQualityKey;
                } else if (currentQualityKey !== qualityKey) {
                    throw createAiItemCombinerValidationError('All item stacks in a combine group must have the same quality level.');
                }

                const context = contextResolver(thing);
                const currentHolderKey = getItemCombinerHolderKey(context);
                if (holderKey === null) {
                    holderKey = currentHolderKey;
                    owner = context?.owner || null;
                    container = context?.container || null;
                    location = context?.location || null;
                } else if (currentHolderKey !== holderKey) {
                    throw createAiItemCombinerValidationError('All item stacks in a combine group must be in the same holder.');
                }
            }

            return {
                qualityKey,
                holderKey,
                owner,
                container,
                location
            };
        }

        function resolveItemCombinerThingById(thingId) {
            const normalizedId = typeof thingId === 'string' ? thingId.trim() : '';
            if (!normalizedId) {
                return null;
            }
            return things.get(normalizedId) || Thing.getById(normalizedId) || null;
        }

        function isItemCombinerCandidateThing(thing) {
            return Boolean(
                thing
                && (thing.thingType || '').trim().toLowerCase() === 'item'
                && !thing.isContainer
                && !thing.isEquipped
                && !thing.equippedSlot
            );
        }

        app.post('/api/things/ai-combine-candidates', async (req, res) => {
            let parsedTemplate = null;
            let responseText = '';
            const metadataLabel = 'ai_item_combiner';
            try {
                if (!Array.isArray(req.body?.items)) {
                    return res.status(400).json({
                        success: false,
                        error: 'AI item combiner items must be an array.'
                    });
                }

                const requestItems = req.body.items.map((item, index) => normalizeAiItemCombinerItem(item, index));
                const eligiblePromptItems = [];
                const eligibleThingsById = new Map();
                const excludedItemIds = [];

                for (const requestItem of requestItems) {
                    const thing = resolveItemCombinerThingById(requestItem.id);
                    if (!thing) {
                        const error = createAiItemCombinerValidationError(`Thing "${requestItem.id}" was not found.`);
                        error.statusCode = 404;
                        throw error;
                    }
                    if (!isItemCombinerCandidateThing(thing)) {
                        excludedItemIds.push(requestItem.id);
                        continue;
                    }
                    eligibleThingsById.set(requestItem.id, thing);
                    eligiblePromptItems.push({
                        ...requestItem,
                        quality: getItemCombinerQualityKey(thing),
                        quantity: normalizeAiItemCombinerText(thing.count ?? requestItem.quantity, `item ${requestItem.id} quantity`),
                        statusEffects: formatAiItemCombinerStatusEffects(thing, requestItem.statusEffects),
                        statModifiers: formatAiItemCombinerStatModifiers(thing, requestItem.statModifiers)
                    });
                }

                if (eligiblePromptItems.length < 2) {
                    return res.json({
                        success: true,
                        groups: [],
                        excludedItemIds,
                        response: ''
                    });
                }

                const renderedTemplate = promptEnv.render('ai-item-combiner.xml.njk', {
                    items: eligiblePromptItems
                });
                parsedTemplate = parseXMLTemplate(renderedTemplate, { metadataLabel });
                responseText = await LLMClient.chatCompletion({
                    messages: [
                        { role: 'system', content: parsedTemplate.systemPrompt },
                        { role: 'user', content: parsedTemplate.generationPrompt }
                    ],
                    temperature: parsedTemplate.temperature,
                    metadataLabel,
                    validateXML: false,
                    expectedXmlRootTag: 'combinationGroups',
                    requiredRegex: /<combinationGroups[\s\S]*<\/combinationGroups>/i
                });

                LLMClient.logPrompt({
                    prefix: metadataLabel,
                    metadataLabel,
                    systemPrompt: parsedTemplate.systemPrompt,
                    generationPrompt: parsedTemplate.generationPrompt,
                    response: responseText
                });

                const parsedGroups = parseAiItemCombinerResponse(responseText);
                const groups = parsedGroups.map((group, index) => {
                    const groupThings = group.itemIds.map(itemId => {
                        const thing = eligibleThingsById.get(itemId);
                        if (!thing) {
                            throw new Error(`AI item combiner group ${index + 1} referenced unknown or ineligible item id "${itemId}".`);
                        }
                        return thing;
                    });
                    validateItemCombinerMergeSet(groupThings[0], groupThings.slice(1), resolveThingContainerContext);
                    return {
                        reason: group.reason || '',
                        itemIds: group.itemIds,
                        items: groupThings.map(thing => thing.toJSON())
                    };
                });

                res.json({
                    success: true,
                    groups,
                    excludedItemIds,
                    response: responseText
                });
            } catch (error) {
                if (parsedTemplate) {
                    LLMClient.logPrompt({
                        prefix: metadataLabel,
                        metadataLabel,
                        systemPrompt: parsedTemplate.systemPrompt || '',
                        generationPrompt: parsedTemplate.generationPrompt || '',
                        response: responseText || '',
                        sections: [
                            {
                                title: 'Error',
                                content: error?.stack || error?.message || String(error)
                            }
                        ]
                    });
                }
                const statusCode = Number.isInteger(error?.statusCode) ? error.statusCode : 500;
                res.status(statusCode).json({
                    success: false,
                    error: error.message || 'AI item combiner failed.'
                });
            }
        });

        app.post('/api/things/combine-stacks', (req, res) => {
            try {
                const keepThingId = normalizeAiItemCombinerText(req.body?.keepThingId, 'keepThingId');
                if (!keepThingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'keepThingId is required.'
                    });
                }
                if (!Array.isArray(req.body?.mergeThingIds)) {
                    return res.status(400).json({
                        success: false,
                        error: 'mergeThingIds must be an array.'
                    });
                }
                const mergeThingIds = req.body.mergeThingIds
                    .map((value, index) => normalizeAiItemCombinerText(value, `mergeThingIds[${index}]`))
                    .filter(Boolean);
                if (!mergeThingIds.length) {
                    return res.status(400).json({
                        success: false,
                        error: 'At least one mergeThingIds entry is required.'
                    });
                }

                const keepThing = resolveItemCombinerThingById(keepThingId);
                if (!keepThing) {
                    return res.status(404).json({
                        success: false,
                        error: `Thing "${keepThingId}" was not found.`
                    });
                }

                const mergeThings = mergeThingIds.map(thingId => {
                    const thing = resolveItemCombinerThingById(thingId);
                    if (!thing) {
                        const error = createAiItemCombinerValidationError(`Thing "${thingId}" was not found.`);
                        error.statusCode = 404;
                        throw error;
                    }
                    return thing;
                });

                const {
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation
                } = validateItemCombinerMergeSet(keepThing, mergeThings, resolveThingContainerContext);

                let mergedCount = Number.isInteger(keepThing.count) && keepThing.count > 0
                    ? keepThing.count
                    : 1;
                const mergedThingIds = [];

                for (const mergeThing of mergeThings) {
                    mergedCount += Number.isInteger(mergeThing.count) && mergeThing.count > 0
                        ? mergeThing.count
                        : 1;
                    const deleteResult = deleteThingById(mergeThing.id);
                    if (!deleteResult?.success) {
                        throw new Error(deleteResult?.error || `Failed to remove stack "${mergeThing.name || mergeThing.id}" during combine.`);
                    }
                    mergedThingIds.push(mergeThing.id);
                }

                keepThing.count = mergedCount;
                keepThing.metadata = {
                    ...(keepThing.metadata && typeof keepThing.metadata === 'object'
                        ? keepThing.metadata
                        : {}),
                    count: keepThing.count
                };

                return res.json(buildThingMutationResponsePayload({
                    things: [keepThing],
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation,
                    message: `${keepThing.name || 'Item'} stacks combined successfully.`,
                    extra: {
                        sourceThingId: keepThing.id,
                        keptThingId: keepThing.id,
                        mergedThingIds,
                        noChanges: false
                    }
                }));
            } catch (error) {
                console.error('Failed to combine item stacks:', error);
                const statusCode = Number.isInteger(error?.statusCode) ? error.statusCode : 500;
                return res.status(statusCode).json({
                    success: false,
                    error: error?.message || 'Failed to combine item stacks'
                });
            }
        });

        // Get a specific thing by ID
        app.get('/api/things/:id', (req, res) => {
            try {
                const { id } = req.params;
                const thing = things.get(id);

                if (!thing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }

                res.json({
                    success: true,
                    thing: thing.toJSON()
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/mod-thing-context-actions/:actionId', async (req, res) => {
            try {
                const actionId = typeof req.params.actionId === 'string' ? req.params.actionId.trim() : '';
                if (!actionId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Thing context action id is required.'
                    });
                }

                const registry = modExtensionRegistry || Globals.modExtensionRegistry || null;
                if (!registry || typeof registry.getThingContextActionRecord !== 'function') {
                    throw new Error('Mod Thing context action registry is unavailable.');
                }

                const action = registry.getThingContextActionRecord(actionId);
                if (!action) {
                    return res.status(404).json({
                        success: false,
                        error: `Thing context action "${actionId}" is not registered.`
                    });
                }

                const thingId = typeof req.body?.thingId === 'string' ? req.body.thingId.trim() : '';
                if (!thingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'thingId is required.'
                    });
                }
                const thing = things.get(thingId) || (typeof Thing.getById === 'function' ? Thing.getById(thingId) : null);
                if (!thing) {
                    return res.status(404).json({
                        success: false,
                        error: `Thing "${thingId}" was not found.`
                    });
                }

                const actor = resolveActorForThingContextAction(req.body || {});
                const result = await action.handler({
                    action,
                    thing,
                    actor,
                    currentPlayer,
                    context: typeof req.body?.context === 'string' ? req.body.context.trim() : '',
                    requestBody: req.body || {},
                    players,
                    things,
                    locations: gameLocations,
                    Globals
                });
                const resultActor = result?.actor || actor || null;
                const resultLocation = result?.location || null;
                let resultLocationPayload = null;
                if (resultLocation && typeof buildLocationResponse === 'function') {
                    resultLocationPayload = buildLocationResponse(resultLocation);
                }
                const refreshedThing = things.get(thingId) || thing;
                res.json({
                    success: true,
                    actionId: action.fullId,
                    result: result || null,
                    thing: refreshedThing && typeof refreshedThing.toJSON === 'function'
                        ? refreshedThing.toJSON()
                        : refreshedThing,
                    actor: resultActor && typeof serializeNpcForClient === 'function'
                        ? serializeNpcForClient(resultActor)
                        : (resultActor && typeof resultActor.getStatus === 'function' ? resultActor.getStatus() : null),
                    location: resultLocationPayload
                });
            } catch (error) {
                res.status(400).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.get('/api/gear-slots', (req, res) => {
            try {
                const definitions = Player.gearSlotDefinitions;
                const slotTypes = [];

                if (definitions?.byType instanceof Map) {
                    for (const type of definitions.byType.keys()) {
                        if (typeof type === 'string' && type.trim()) {
                            slotTypes.push(type.trim());
                        }
                    }
                }

                slotTypes.sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));

                res.json({
                    success: true,
                    slotTypes
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: 'Failed to load gear slot definitions',
                    details: error.message
                });
            }
        });

        app.get('/api/attributes', (req, res) => {
            try {
                const template = new Player({ name: 'Attribute Loader' });
                const definitions = template.attributeDefinitions || {};
                const attributes = Object.entries(definitions)
                    .filter(([key]) => typeof key === 'string' && key.trim())
                    .map(([key, def]) => {
                        const trimmed = key.trim();
                        return {
                            key: trimmed,
                            label: def?.label || trimmed,
                            description: def?.description || '',
                            abbreviation: def?.abbreviation || ''
                        };
                    })
                    .sort((a, b) => a.key.localeCompare(b.key, undefined, { sensitivity: 'base' }));

                res.json({
                    success: true,
                    attributes
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: 'Failed to load attribute definitions',
                    details: error.message
                });
            }
        });

        // Update a thing
        app.put('/api/things/:id', async (req, res) => {
            try {
                const { id } = req.params;
                const {
                    name,
                    description,
                    shortDescription,
                    thingType,
                    imageId,
                    imagePrompt,
                    rarity,
                    itemTypeDetail,
                    metadata,
                    slot,
                    attributeBonuses,
                    causeStatusEffect,
                    causeStatusEffectOnTarget,
                    causeStatusEffectOnEquipper,
                    count,
                    level,
                    relativeLevel,
                    containerContents,
                    statusEffects
                } = req.body || {};
                const booleanFlags = extractThingBooleanFlagsFromPayload(req.body || {});
                const registeredEditFields = getRegisteredThingPayloadFields({ edit: true });
                const registeredEditFieldPayload = extractRegisteredThingPayloadFieldValues(req.body || {}, registeredEditFields);
                const thing = things.get(id);

                if (!thing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }

                // Update properties if provided
                let shouldRegenerateImage = false;
                if (name !== undefined) {
                    thing.name = name;
                    shouldRegenerateImage = true;
                }
                if (description !== undefined) {
                    thing.description = description;
                    shouldRegenerateImage = true;
                }
                if (shortDescription !== undefined) {
                    if (shortDescription === null) {
                        thing.shortDescription = null;
                    } else if (typeof shortDescription === 'string') {
                        thing.shortDescription = shortDescription;
                    } else {
                        return res.status(400).json({
                            success: false,
                            error: 'Short description must be a string or null.'
                        });
                    }
                }
                if (thingType !== undefined) {
                    thing.thingType = thingType;
                    shouldRegenerateImage = true;
                }
                if (rarity !== undefined) {
                    thing.rarity = rarity;
                    shouldRegenerateImage = true;
                }
                if (itemTypeDetail !== undefined) {
                    thing.itemTypeDetail = itemTypeDetail;
                    shouldRegenerateImage = true;
                }
                if (metadata !== undefined) {
                    if (metadata === null) {
                        thing.metadata = {};
                        shouldRegenerateImage = true;
                    } else if (metadata && typeof metadata === 'object' && !Array.isArray(metadata)) {
                        thing.metadata = metadata;
                        shouldRegenerateImage = true;
                    } else {
                        return res.status(400).json({
                            success: false,
                            error: 'Metadata must be an object.'
                        });
                    }
                }
                if (imageId !== undefined) thing.imageId = imageId;
                if (imagePrompt !== undefined) {
                    if (typeof imagePrompt !== 'string') {
                        return res.status(400).json({
                            success: false,
                            error: 'Image prompt must be a string.'
                        });
                    }
                    thing.imagePrompt = imagePrompt;
                }

                if (slot !== undefined) {
                    thing.slot = registeredEditFieldPayload.shouldClearSlot ? null : slot;
                } else if (registeredEditFieldPayload.shouldClearSlot) {
                    thing.slot = null;
                }
                applyRegisteredThingPayloadFieldValues(thing, registeredEditFieldPayload.values);

                if (attributeBonuses !== undefined) {
                    if (Array.isArray(attributeBonuses)) {
                        thing.attributeBonuses = attributeBonuses;
                    } else if (attributeBonuses === null) {
                        thing.attributeBonuses = [];
                    } else {
                        return res.status(400).json({
                            success: false,
                            error: 'Attribute bonuses must be provided as an array.'
                        });
                    }

                    if (metadata && typeof metadata === 'object' && !Array.isArray(metadata)
                        && Object.prototype.hasOwnProperty.call(metadata, 'unscaledAttributeBonuses')) {
                        thing.unscaledAttributeBonuses = metadata.unscaledAttributeBonuses;
                    }
                }

                if (causeStatusEffect !== undefined
                    || causeStatusEffectOnTarget !== undefined
                    || causeStatusEffectOnEquipper !== undefined) {
                    thing.setCauseStatusEffects({
                        target: causeStatusEffectOnTarget ?? null,
                        equipper: causeStatusEffectOnEquipper ?? null,
                        legacy: causeStatusEffect ?? null
                    });
                }

                if (count !== undefined) {
                    thing.count = count;
                }

                if (level !== undefined) {
                    thing.level = level;
                }

                if (relativeLevel !== undefined) {
                    thing.relativeLevel = relativeLevel;
                }

                applyThingBooleanFlagsToInstance(thing, booleanFlags);

                if (containerContents !== undefined) {
                    thing.containerContents = containerContents;
                }

                if (statusEffects !== undefined) {
                    if (Array.isArray(statusEffects)) {
                        thing.setStatusEffects(statusEffects);
                    } else if (statusEffects === null) {
                        thing.setStatusEffects([]);
                    } else {
                        return res.status(400).json({
                            success: false,
                            error: 'Status effects must be provided as an array.'
                        });
                    }
                }

                // Trigger image regeneration if visual properties changed (only when relevant)
                let imageNeedsUpdate = false;
                if (shouldRegenerateImage && imageId === undefined) {
                    if (shouldGenerateThingImage(thing)) {
                        thing.imageId = null;
                        imageNeedsUpdate = true;
                    } else {
                        console.log(`🎒 Skipping ${thing.thingType} image regeneration for ${thing.name} - not in player inventory`);
                    }
                }

                res.json({
                    success: true,
                    thing: thing.toJSON(),
                    message: 'Thing updated successfully',
                    imageNeedsUpdate
                });
            } catch (error) {
                res.status(400).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/things/:id/separate', async (req, res) => {
            const stagedThings = [];
            try {
                const rawThingId = req.params.id;
                const thingId = typeof rawThingId === 'string' ? rawThingId.trim() : '';
                if (!thingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Thing ID is required'
                    });
                }

                const sourceThing = things.get(thingId) || Thing.getById(thingId);
                if (!sourceThing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }

                const sourceThingType = typeof sourceThing.thingType === 'string'
                    ? sourceThing.thingType.trim().toLowerCase()
                    : '';
                const canSeparateSource = sourceThingType === 'item' || sourceThingType === 'scenery';
                if (!canSeparateSource) {
                    return res.status(400).json({
                        success: false,
                        error: 'Only item or scenery things can be separated.'
                    });
                }
                if (sourceThing.isContainer && typeof sourceThing.getInventoryItems === 'function' && sourceThing.getInventoryItems().length > 0) {
                    return res.status(400).json({
                        success: false,
                        error: 'Non-empty containers cannot be separated.'
                    });
                }

                if (typeof separateThingByPrompt !== 'function') {
                    throw new Error('Thing separation prompt helper is unavailable.');
                }

                const isStackSplitShortcut = Number.isInteger(sourceThing.count) && sourceThing.count > 1;
                const separatedItems = await separateThingByPrompt({ thing: sourceThing });
                if (!Array.isArray(separatedItems)) {
                    throw new Error('Thing separation did not return a thing list.');
                }

                if (separatedItems.length === 0) {
                    return res.json({
                        success: true,
                        noChanges: true,
                        things: [],
                        message: `${sourceThing.name || 'Thing'} could not be separated further.`
                    });
                }

                const {
                    metadata: sourceMetadata,
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation,
                    region: sourceRegion
                } = resolveThingContainerContext(sourceThing);
                const sourceStatusEffects = typeof sourceThing.getStatusEffects === 'function'
                    ? sourceThing.getStatusEffects()
                    : [];

                const originalRelativeLevel = Number.isFinite(sourceThing.relativeLevel)
                    ? sourceThing.relativeLevel
                    : (Number.isFinite(sourceMetadata.relativeLevel) ? sourceMetadata.relativeLevel : 0);
                const originalLevel = Number.isFinite(sourceThing.level)
                    ? sourceThing.level
                    : (Number.isFinite(sourceMetadata.level) ? sourceMetadata.level : null);
                const baseReferenceLevel = Number.isFinite(originalLevel) && Number.isFinite(originalRelativeLevel)
                    ? originalLevel - originalRelativeLevel
                    : (Number.isFinite(originalLevel)
                        ? originalLevel
                        : (Number.isFinite(sourceOwner?.level)
                            ? sourceOwner.level
                            : (Number.isFinite(sourceLocation?.baseLevel)
                                ? sourceLocation.baseLevel
                                : (Number.isFinite(sourceRegion?.averageLevel) ? sourceRegion.averageLevel : 1))));

                const buildCauseStatusEffects = (itemData) => {
                    const entries = [];
                    if (itemData?.causeStatusEffectOnTarget) {
                        entries.push({ ...itemData.causeStatusEffectOnTarget, applyToTarget: true });
                    }
                    if (itemData?.causeStatusEffectOnEquipper) {
                        entries.push({ ...itemData.causeStatusEffectOnEquipper, applyToEquipper: true });
                    }
                    if (!entries.length && itemData?.causeStatusEffect) {
                        entries.push(itemData.causeStatusEffect);
                    }
                    return entries.length ? entries : null;
                };

                for (const itemData of separatedItems) {
                    if (!itemData || typeof itemData !== 'object') {
                        throw new Error('Thing separation returned an invalid thing entry.');
                    }
                    if (typeof itemData.name !== 'string' || !itemData.name.trim()) {
                        throw new Error('Thing separation returned a thing without a valid name.');
                    }

                    const preserveOriginalStats = Boolean(itemData.__preserveOriginalStats);
                    const normalizedType = (itemData.itemOrScenery || itemData.thingType || 'item').trim().toLowerCase() === 'scenery'
                        ? 'scenery'
                        : 'item';
                    const effectiveThingType = preserveOriginalStats
                        ? (sourceThingType === 'scenery' ? 'scenery' : 'item')
                        : normalizedType;

                    if ((sourceOwner || sourceContainer) && effectiveThingType !== 'item') {
                        throw new Error(`Thing separation returned scenery "${itemData.name}" for an inventory-bound source thing.`);
                    }

                    const count = itemData.count ?? 1;
                    if (!Number.isInteger(count) || count < 1) {
                        throw new Error(`Thing separation returned invalid count "${count}" for "${itemData.name}".`);
                    }

                    const relativeLevel = preserveOriginalStats
                        ? originalRelativeLevel
                        : (Number.isFinite(itemData.relativeLevel)
                            ? itemData.relativeLevel
                            : originalRelativeLevel);
                    const computedLevel = preserveOriginalStats
                        ? (Number.isFinite(originalLevel)
                            ? originalLevel
                            : (Number.isFinite(baseReferenceLevel + relativeLevel)
                                ? Math.max(1, Math.round(baseReferenceLevel + relativeLevel))
                                : 1))
                        : (Number.isFinite(baseReferenceLevel + relativeLevel)
                            ? Math.max(1, Math.round(baseReferenceLevel + relativeLevel))
                            : (Number.isFinite(originalLevel) ? originalLevel : 1));

                    const effectiveRarity = preserveOriginalStats
                        ? (sourceThing.rarity || sourceMetadata.rarity || null)
                        : (itemData.rarity || null);
                    const effectiveItemTypeDetail = preserveOriginalStats
                        ? (sourceThing.itemTypeDetail || sourceMetadata.itemTypeDetail || sourceMetadata.itemType || null)
                        : (itemData.type || null);
                    const effectiveSlot = preserveOriginalStats
                        ? (sourceThing.slot || sourceMetadata.slot || null)
                        : (itemData.slot || null);
                    const effectiveProperties = preserveOriginalStats
                        ? (sourceMetadata.properties ?? null)
                        : (itemData.properties ?? null);
                    const effectiveValue = (preserveOriginalStats || isStackSplitShortcut)
                        ? (sourceMetadata.value ?? null)
                        : (itemData.value ?? null);
                    const effectiveWeight = preserveOriginalStats
                        ? (sourceMetadata.weight ?? null)
                        : (itemData.weight ?? null);
                    const effectiveTargetStatusEffect = preserveOriginalStats
                        ? (sourceThing.causeStatusEffectOnTarget || sourceMetadata.causeStatusEffectOnTarget || null)
                        : (itemData.causeStatusEffectOnTarget || null);
                    const effectiveEquipperStatusEffect = preserveOriginalStats
                        ? (sourceThing.causeStatusEffectOnEquipper || sourceMetadata.causeStatusEffectOnEquipper || null)
                        : (itemData.causeStatusEffectOnEquipper || null);
                    const preservedOrDerivedUnscaledAttributeBonuses = (() => {
                        const storedUnscaled = Array.isArray(sourceThing.unscaledAttributeBonuses) && sourceThing.unscaledAttributeBonuses.length
                            ? sourceThing.unscaledAttributeBonuses.map(entry => ({ ...entry }))
                            : normalizeAttributeBonusesForItem(
                                Array.isArray(sourceMetadata.unscaledAttributeBonuses) ? sourceMetadata.unscaledAttributeBonuses : []
                            );
                        if (storedUnscaled.length) {
                            return storedUnscaled;
                        }

                        const scaledBonuses = normalizeAttributeBonusesForItem(
                            Array.isArray(sourceThing.attributeBonuses) ? sourceThing.attributeBonuses : []
                        );
                        if (!scaledBonuses.length) {
                            return [];
                        }

                        const maxBonus = Utils.roundAwayFromZero(Thing.getMaxAttributeBonus(effectiveRarity, computedLevel));
                        if (!Number.isFinite(maxBonus) || maxBonus === 0) {
                            return [];
                        }

                        return scaledBonuses.map(({ attribute, bonus }) => ({
                            attribute,
                            bonus: bonus / maxBonus * 4
                        }));
                    })();
                    const effectiveUnscaledAttributeBonuses = effectiveThingType === 'item'
                        ? (preserveOriginalStats
                            ? preservedOrDerivedUnscaledAttributeBonuses
                            : normalizeAttributeBonusesForItem(
                                Array.isArray(itemData.attributeBonuses) ? itemData.attributeBonuses : []
                            ))
                        : [];
                    const effectiveAttributeBonuses = effectiveThingType === 'item'
                        ? (preserveOriginalStats
                            ? (Array.isArray(sourceThing.attributeBonuses)
                                ? sourceThing.attributeBonuses.map(entry => ({ ...entry }))
                                : [])
                            : scaleAttributeBonusesForItem(
                                effectiveUnscaledAttributeBonuses,
                                { level: computedLevel, rarity: effectiveRarity },
                            ))
                        : [];
                    const effectiveStatusEffects = (preserveOriginalStats || isStackSplitShortcut)
                        ? sourceStatusEffects.map(effect => ({ ...effect }))
                        : [];

                    const booleanFlags = preserveOriginalStats
                        ? {
                            isVehicle: Boolean(sourceThing.isVehicle),
                            isCraftingStation: Boolean(sourceThing.isCraftingStation),
                            isProcessingStation: Boolean(sourceThing.isProcessingStation),
                            isHarvestable: Boolean(sourceThing.isHarvestable),
                            isSalvageable: Boolean(sourceThing.isSalvageable),
                            isContainer: Boolean(sourceThing.isContainer),
                            requiresCheckToOpen: Boolean(sourceThing.requiresCheckToOpen)
                        }
                        : extractThingBooleanFlagsFromPayload(itemData);
                    const metadata = sanitizeMetadataObject({
                        rarity: effectiveRarity,
                        itemType: effectiveItemTypeDetail,
                        itemTypeDetail: effectiveItemTypeDetail,
                        value: effectiveValue,
                        weight: effectiveWeight,
                        properties: effectiveProperties,
                        slot: effectiveSlot,
                        attributeBonuses: effectiveAttributeBonuses.length ? effectiveAttributeBonuses : undefined,
                        unscaledAttributeBonuses: effectiveUnscaledAttributeBonuses.length ? effectiveUnscaledAttributeBonuses : undefined,
                        causeStatusEffectOnTarget: effectiveTargetStatusEffect,
                        causeStatusEffectOnEquipper: effectiveEquipperStatusEffect,
                        level: computedLevel,
                        relativeLevel,
                        ...(sourceOwner
                            ? { ownerId: sourceOwner.id }
                            : (sourceContainer
                                ? { containerId: sourceContainer.id }
                                : {
                                locationId: sourceLocation.id,
                                locationName: sourceLocation.name || sourceLocation.id
                                })),
                        ...booleanFlags
                    });

                    const stagedThing = (preserveOriginalStats || isStackSplitShortcut)
                        ? sourceThing.copy({
                            name: itemData.name,
                            description: itemData.description || `A separated thing recovered from ${sourceThing.name}.`,
                            shortDescription: itemData.shortDescription ?? sourceThing.shortDescription ?? null,
                            count,
                            metadataOverrides: metadata,
                        })
                        : new Thing({
                            name: itemData.name,
                            description: itemData.description || `A separated thing recovered from ${sourceThing.name}.`,
                            shortDescription: itemData.shortDescription ?? null,
                            thingType: effectiveThingType,
                            imageId: null,
                            rarity: effectiveRarity,
                            itemTypeDetail: effectiveItemTypeDetail,
                            slot: effectiveSlot,
                            attributeBonuses: effectiveThingType === 'item' ? effectiveAttributeBonuses : [],
                            unscaledAttributeBonuses: effectiveUnscaledAttributeBonuses,
                            causeStatusEffect: buildCauseStatusEffects({
                                causeStatusEffectOnTarget: effectiveTargetStatusEffect,
                                causeStatusEffectOnEquipper: effectiveEquipperStatusEffect
                            }),
                            count,
                            level: computedLevel,
                            relativeLevel,
                            statusEffects: effectiveStatusEffects,
                            containerContents: itemData.containerContents,
                            metadata,
                            ...booleanFlags,
                            enrichStatusEffects: true
                        });
                    stagedThings.push(stagedThing);
                }

                if (typeof Globals.ensureThingNamesAllowed !== 'function') {
                    throw new Error('Globals.ensureThingNamesAllowed is unavailable for item name validation.');
                }
                await Globals.ensureThingNamesAllowed({
                    things: stagedThings,
                    location: sourceLocation || null,
                    region: sourceRegion || null
                });

                const separatedOutputContainer = stagedThings.find(entry => Boolean(entry?.isContainer)) || null;
                const canNestSeparatedThing = (thing) => thing && thing !== separatedOutputContainer && thing.thingType === 'item';
                const nestedSeparatedThings = separatedOutputContainer
                    ? stagedThings.filter(canNestSeparatedThing)
                    : [];
                const destinationSeparatedThings = separatedOutputContainer
                    ? stagedThings.filter(entry => entry === separatedOutputContainer || !canNestSeparatedThing(entry))
                    : stagedThings;

                const deleteResult = deleteThingById(sourceThing.id);
                if (!deleteResult?.success) {
                    throw new Error(deleteResult?.error || `Failed to remove original thing "${sourceThing.name}".`);
                }

                for (const stagedThing of stagedThings) {
                    things.set(stagedThing.id, stagedThing);
                }

                if (separatedOutputContainer) {
                    for (const nestedThing of nestedSeparatedThings) {
                        separatedOutputContainer.addInventoryItem(nestedThing, { mergeStacks: false });
                    }
                }

                for (const stagedThing of destinationSeparatedThings) {
                    if (sourceOwner) {
                        const added = sourceOwner.addInventoryItem(stagedThing, { suppressNpcEquip: true, mergeStacks: false });
                        if (!added) {
                            throw new Error(`Failed to add separated thing "${stagedThing.name}" to ${sourceOwner.name || sourceOwner.id}.`);
                        }
                    } else if (sourceContainer) {
                        sourceContainer.addInventoryItem(stagedThing, { mergeStacks: false });
                    } else if (sourceLocation) {
                        sourceLocation.addThingId(stagedThing.id, { mergeStacks: false });
                    } else {
                        throw new Error(`No destination available for separated thing "${stagedThing.name}".`);
                    }
                }

                const responsePayload = {
                    success: true,
                    noChanges: false,
                    sourceThingId: sourceThing.id,
                    things: stagedThings.map(entry => entry.toJSON()),
                    message: `${sourceThing.name || 'Thing'} separated successfully.`
                };

                if (sourceLocation && typeof buildLocationResponse === 'function') {
                    responsePayload.location = buildLocationResponse(sourceLocation);
                }

                if (sourceOwner && typeof serializeNpcForClient === 'function') {
                    responsePayload.owner = serializeNpcForClient(sourceOwner);
                }

                if (sourceContainer && typeof sourceContainer.toJSON === 'function') {
                    responsePayload.container = sourceContainer.toJSON();
                    responsePayload.contents = sourceContainer.getInventoryItems().map(item => item.toJSON());
                }

                res.json(responsePayload);
            } catch (error) {
                for (const stagedThing of stagedThings) {
                    try {
                        things.delete(stagedThing.id);
                        stagedThing.delete();
                    } catch (cleanupError) {
                        console.warn('Failed to clean up staged separated thing:', cleanupError?.message || cleanupError);
                    }
                }

                console.error('Failed to separate thing:', error);
                res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to separate thing'
                });
            }
        });

        app.post('/api/things/:id/split-stack', (req, res) => {
            let splitThing = null;
            try {
                const rawThingId = req.params.id;
                const thingId = typeof rawThingId === 'string' ? rawThingId.trim() : '';
                if (!thingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Thing ID is required'
                    });
                }

                const sourceThing = things.get(thingId) || Thing.getById(thingId);
                if (!sourceThing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }

                if (sourceThing.thingType !== 'item') {
                    return res.status(400).json({
                        success: false,
                        error: 'Only item-type things can be split.'
                    });
                }
                if (sourceThing.isContainer && typeof sourceThing.getInventoryItems === 'function' && sourceThing.getInventoryItems().length > 0) {
                    return res.status(400).json({
                        success: false,
                        error: 'Non-empty containers cannot be split.'
                    });
                }

                const sourceCount = Number.isInteger(sourceThing.count) && sourceThing.count > 0
                    ? sourceThing.count
                    : 1;
                if (sourceCount <= 1) {
                    return res.status(400).json({
                        success: false,
                        error: `${sourceThing.name || 'Item'} is not a stack.`
                    });
                }

                const rawQuantity = req.body?.quantity;
                const splitQuantity = Number(rawQuantity);
                if (!Number.isInteger(splitQuantity)) {
                    return res.status(400).json({
                        success: false,
                        error: 'Split quantity must be an integer.'
                    });
                }
                if (splitQuantity < 1) {
                    return res.status(400).json({
                        success: false,
                        error: 'Split quantity must be at least 1.'
                    });
                }
                if (splitQuantity >= sourceCount) {
                    return res.status(400).json({
                        success: false,
                        error: `Split quantity must be less than the source stack size (${sourceCount}).`
                    });
                }

                const {
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation
                } = resolveThingContainerContext(sourceThing);

                splitThing = sourceThing.copy({
                    count: splitQuantity,
                    metadataOverrides: {
                        count: splitQuantity
                    }
                });

                sourceThing.count = sourceCount - splitQuantity;
                sourceThing.metadata = {
                    ...(sourceThing.metadata && typeof sourceThing.metadata === 'object'
                        ? sourceThing.metadata
                        : {}),
                    count: sourceThing.count
                };

                things.set(splitThing.id, splitThing);
                if (sourceOwner) {
                    const added = sourceOwner.addInventoryItem(splitThing, { suppressNpcEquip: true, mergeStacks: false });
                    if (!added) {
                        throw new Error(`Failed to add split stack "${splitThing.name}" to ${sourceOwner.name || sourceOwner.id}.`);
                    }
                } else if (sourceContainer) {
                    sourceContainer.addInventoryItem(splitThing, { mergeStacks: false });
                } else if (sourceLocation) {
                    sourceLocation.addThingId(splitThing.id, { mergeStacks: false });
                } else {
                    throw new Error(`No destination available for split stack "${splitThing.name}".`);
                }

                return res.json(buildThingMutationResponsePayload({
                    things: [sourceThing, splitThing],
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation,
                    message: `${sourceThing.name || 'Item'} stack split successfully.`,
                    extra: {
                        sourceThingId: sourceThing.id,
                        splitThingId: splitThing.id,
                        noChanges: false
                    }
                }));
            } catch (error) {
                if (splitThing) {
                    try {
                        things.delete(splitThing.id);
                        splitThing.delete();
                    } catch (cleanupError) {
                        console.warn('Failed to clean up split stack after error:', cleanupError?.message || cleanupError);
                    }
                }
                console.error('Failed to split stack:', error);
                return res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to split stack'
                });
            }
        });

        app.post('/api/things/:id/merge-stacks', (req, res) => {
            try {
                const rawThingId = req.params.id;
                const thingId = typeof rawThingId === 'string' ? rawThingId.trim() : '';
                if (!thingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Thing ID is required'
                    });
                }

                const sourceThing = things.get(thingId) || Thing.getById(thingId);
                if (!sourceThing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }

                if (sourceThing.thingType !== 'item') {
                    return res.status(400).json({
                        success: false,
                        error: 'Only item-type things can be merged.'
                    });
                }

                if (sourceThing.isContainer) {
                    return res.status(400).json({
                        success: false,
                        error: 'Containers cannot be merged.'
                    });
                }

                if (sourceThing.isEquipped) {
                    return res.status(400).json({
                        success: false,
                        error: 'Equipped items cannot be merged.'
                    });
                }

                const {
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation
                } = resolveThingContainerContext(sourceThing);

                const mergeCandidates = Thing.getAllByName(sourceThing.name)
                    .filter(candidate => {
                        if (!candidate || candidate.id === sourceThing.id) {
                            return false;
                        }
                        if (candidate.thingType !== 'item' || candidate.isEquipped) {
                            return false;
                        }
                        if (candidate.isContainer) {
                            return false;
                        }
                        if (candidate.checksum !== sourceThing.checksum) {
                            return false;
                        }

                        try {
                            const candidateContext = resolveThingContainerContext(candidate);
                            if (sourceOwner) {
                                return candidateContext.owner?.id === sourceOwner.id;
                            }
                            if (sourceContainer) {
                                return candidateContext.container?.id === sourceContainer.id;
                            }
                            if (sourceLocation) {
                                return !candidateContext.owner && !candidateContext.container && candidateContext.location?.id === sourceLocation.id;
                            }
                        } catch (_) {
                            return false;
                        }

                        return false;
                    });

                if (!mergeCandidates.length) {
                    return res.json(buildThingMutationResponsePayload({
                        things: [sourceThing],
                        owner: sourceOwner,
                        container: sourceContainer,
                        location: sourceLocation,
                        message: `No matching stacks found for ${sourceThing.name || 'item'}.`,
                        extra: {
                            sourceThingId: sourceThing.id,
                            mergedThingIds: [],
                            noChanges: true
                        }
                    }));
                }

                const mergedThingIds = [];
                let mergedCount = Number.isInteger(sourceThing.count) && sourceThing.count > 0
                    ? sourceThing.count
                    : 1;

                for (const candidate of mergeCandidates) {
                    mergedCount += Number.isInteger(candidate.count) && candidate.count > 0
                        ? candidate.count
                        : 1;
                    const deleteResult = deleteThingById(candidate.id);
                    if (!deleteResult?.success) {
                        throw new Error(deleteResult?.error || `Failed to remove stack "${candidate.name || candidate.id}" during merge.`);
                    }
                    mergedThingIds.push(candidate.id);
                }

                sourceThing.count = mergedCount;
                sourceThing.metadata = {
                    ...(sourceThing.metadata && typeof sourceThing.metadata === 'object'
                        ? sourceThing.metadata
                        : {}),
                    count: sourceThing.count
                };

                return res.json(buildThingMutationResponsePayload({
                    things: [sourceThing],
                    owner: sourceOwner,
                    container: sourceContainer,
                    location: sourceLocation,
                    message: `${sourceThing.name || 'Item'} stacks merged successfully.`,
                    extra: {
                        sourceThingId: sourceThing.id,
                        mergedThingIds,
                        noChanges: false
                    }
                }));
            } catch (error) {
                console.error('Failed to merge stacks:', error);
                return res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to merge stacks'
                });
            }
        });

        function resolveRequestContainer(containerId) {
            const normalizedContainerId = typeof containerId === 'string' ? containerId.trim() : '';
            if (!normalizedContainerId) {
                const error = new Error('Container ID is required');
                error.status = 400;
                throw error;
            }
            const container = things.get(normalizedContainerId) || Thing.getById(normalizedContainerId);
            if (!container) {
                const error = new Error('Container not found');
                error.status = 404;
                throw error;
            }
            if (!container.isContainer) {
                const error = new Error(`Thing "${container.name || normalizedContainerId}" is not a container.`);
                error.status = 400;
                throw error;
            }
            return container;
        }

        function createContainerMoveError(message, status = 400) {
            const error = new Error(message);
            error.status = status;
            return error;
        }

        function resolveContainerMoveThingIds(body = {}) {
            const requestBody = body && typeof body === 'object' ? body : {};
            const rawThingIds = Array.isArray(requestBody.thingIds)
                ? requestBody.thingIds
                : [requestBody.thingId];
            const thingIds = rawThingIds.map(value => (typeof value === 'string' ? value.trim() : ''));
            if (thingIds.length === 0 || thingIds.some(thingId => !thingId)) {
                throw createContainerMoveError(Array.isArray(requestBody.thingIds) ? 'thingIds must be a non-empty array of strings' : 'thingId is required', 400);
            }
            const seen = new Set();
            for (const thingId of thingIds) {
                if (seen.has(thingId)) {
                    throw createContainerMoveError(`Duplicate thingId "${thingId}" is not allowed.`, 400);
                }
                seen.add(thingId);
            }
            return thingIds;
        }

        function resolveContainerMoveItems(thingIds) {
            return thingIds.map(thingId => {
                const item = things.get(thingId) || Thing.getById(thingId);
                if (!item) {
                    throw createContainerMoveError(`Thing "${thingId}" not found`, 404);
                }
                return item;
            });
        }

        function isContainerMoveItemInLocation(item, location) {
            if (!item?.id || !location) {
                return false;
            }

            const locationId = typeof location.id === 'string' ? location.id.trim() : '';
            const directThingIds = Array.isArray(location.thingIds)
                ? location.thingIds
                : (typeof location.thingIds === 'function' ? location.thingIds() : []);
            if (Array.isArray(directThingIds) && directThingIds.includes(item.id)) {
                return true;
            }

            const locationThings = Array.isArray(location.things)
                ? location.things
                : [];
            if (locationThings.some(thing => thing && thing.id === item.id)) {
                return true;
            }

            const metadataLocationId = typeof item.metadata?.locationId === 'string'
                ? item.metadata.locationId.trim()
                : '';
            return Boolean(locationId && metadataLocationId && metadataLocationId === locationId);
        }

        function validateContainerMoveInItems(container, items, { source = 'player', location = null } = {}) {
            const normalizedSource = source === 'location' ? 'location' : 'player';
            for (const item of items) {
                if (item.thingType !== 'item') {
                    throw createContainerMoveError('Only item-type things can be placed in containers.', 400);
                }
                if (item.id === container.id) {
                    throw createContainerMoveError('A container cannot contain itself.', 400);
                }
                if (normalizedSource === 'location' && !isContainerMoveItemInLocation(item, location)) {
                    throw createContainerMoveError(`${item.name || 'Item'} is not in the current location.`, 409);
                }
                if (
                    normalizedSource === 'player'
                    && (!currentPlayer || typeof currentPlayer.hasInventoryItem !== 'function' || !currentPlayer.hasInventoryItem(item.id))
                ) {
                    throw createContainerMoveError(`${item.name || 'Item'} is not in the current player's inventory.`, 409);
                }
                if (item.isEquipped) {
                    throw createContainerMoveError('Equipped items cannot be placed in containers.', 400);
                }
                if (container.hasInventoryItem(item.id)) {
                    throw createContainerMoveError(`${item.name || 'Item'} is already in ${container.name || 'container'}.`, 409);
                }
                if (item.isContainer && item.containsThingRecursive(container.id)) {
                    throw createContainerMoveError('Cannot place a container inside one of its own descendants.', 400);
                }
            }
        }

        function getRegisteredThingPayloadFields({ create = false, edit = false } = {}) {
            const registry = modExtensionRegistry || Globals.modExtensionRegistry || null;
            if (!registry || typeof registry.getEntityFields !== 'function') {
                return [];
            }
            return registry.getEntityFields('thing')
                .filter(field => (
                    (create && field.exposeToCreateTool === true)
                    || (edit && field.exposeToEditModal === true)
                ));
        }

        function parseRegisteredThingPayloadFieldValue(rawValue, field) {
            if (rawValue === undefined) {
                return undefined;
            }
            if (rawValue === null) {
                return null;
            }
            const fieldType = typeof field?.type === 'string' ? field.type.trim().toLowerCase() : 'string';
            if (fieldType === 'boolean') {
                return parseThingBooleanFlagValue(rawValue, field.fieldName);
            }
            if (typeof rawValue === 'string' && !rawValue.trim()) {
                return null;
            }
            if (fieldType === 'string') {
                return String(rawValue).trim();
            }
            if (fieldType === 'number') {
                const numeric = Number(rawValue);
                if (!Number.isFinite(numeric)) {
                    throw new Error(`Registered Thing field "${field.fieldName}" must be a finite number.`);
                }
                return numeric;
            }
            if (fieldType === 'integer') {
                const numeric = Number(rawValue);
                if (!Number.isInteger(numeric)) {
                    throw new Error(`Registered Thing field "${field.fieldName}" must be an integer.`);
                }
                return numeric;
            }
            if (fieldType === 'array') {
                if (Array.isArray(rawValue)) {
                    return rawValue;
                }
                const parsed = JSON.parse(String(rawValue));
                if (!Array.isArray(parsed)) {
                    throw new Error(`Registered Thing field "${field.fieldName}" must be an array.`);
                }
                return parsed;
            }
            if (fieldType === 'object') {
                if (rawValue && typeof rawValue === 'object' && !Array.isArray(rawValue)) {
                    return rawValue;
                }
                const parsed = JSON.parse(String(rawValue));
                if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                    throw new Error(`Registered Thing field "${field.fieldName}" must be an object.`);
                }
                return parsed;
            }
            throw new Error(`Registered Thing field "${field.fieldName}" has unsupported type "${fieldType}".`);
        }

        function hasMeaningfulRegisteredThingPayloadValue(value) {
            if (value === undefined || value === null) {
                return false;
            }
            if (typeof value === 'string') {
                const normalized = value.trim().toLowerCase();
                return Boolean(normalized && normalized !== 'n/a' && normalized !== 'none');
            }
            if (Array.isArray(value)) {
                return value.length > 0;
            }
            if (typeof value === 'object') {
                return Object.keys(value).length > 0;
            }
            return true;
        }

        function extractRegisteredThingPayloadFieldValues(payload = {}, fields = []) {
            const values = {};
            let shouldClearSlot = false;
            for (const field of fields) {
                if (!field || typeof field.fieldName !== 'string') {
                    continue;
                }
                if (!Object.prototype.hasOwnProperty.call(payload, field.fieldName)) {
                    continue;
                }
                const value = parseRegisteredThingPayloadFieldValue(payload[field.fieldName], field);
                values[field.fieldName] = value;
                if (
                    field.clearThingSlotWhenPresent === true
                    && hasMeaningfulRegisteredThingPayloadValue(value)
                ) {
                    shouldClearSlot = true;
                }
            }
            return { values, shouldClearSlot };
        }

        function applyRegisteredThingPayloadFieldValues(thing, values = {}) {
            for (const [fieldName, value] of Object.entries(values)) {
                if (typeof thing.setExtensionField === 'function') {
                    thing.setExtensionField(fieldName, value);
                } else {
                    thing[fieldName] = value;
                }
            }
        }

        function resolveActorForThingContextAction(body = {}) {
            const ownerId = typeof body.ownerId === 'string' ? body.ownerId.trim() : '';
            const npcId = typeof body.npcId === 'string' ? body.npcId.trim() : '';
            const context = typeof body.context === 'string' ? body.context.trim() : '';
            const ids = [ownerId, npcId].filter(Boolean);
            for (const id of ids) {
                if (currentPlayer && currentPlayer.id === id) {
                    return currentPlayer;
                }
                if (players instanceof Map && players.has(id)) {
                    return players.get(id);
                }
                if (typeof Player.getById === 'function') {
                    const actor = Player.getById(id);
                    if (actor) {
                        return actor;
                    }
                }
            }
            if (context === 'player-inventory' || context === 'container-player-inventory') {
                return currentPlayer || null;
            }
            return null;
        }

        function validateContainerMoveOutItems(container, items) {
            for (const item of items) {
                if (!container.hasInventoryItem(item.id)) {
                    throw createContainerMoveError(`${item.name || 'Item'} is not in ${container.name || 'container'}.`, 409);
                }
                if (item.thingType !== 'item') {
                    throw createContainerMoveError('Only item-type things can be moved into player inventory.', 400);
                }
                if (currentPlayer.hasInventoryItem(item.id)) {
                    throw createContainerMoveError(`${item.name || 'Item'} is already in the current player's inventory.`, 409);
                }
            }
        }

        function resolveContainerTransferName(value, label) {
            if (!value || typeof value !== 'object') {
                throw createContainerMoveError(`Container transfer ${label} is missing.`, 500);
            }
            const name = typeof value.name === 'string' && value.name.trim()
                ? value.name.trim()
                : (typeof value.id === 'string' && value.id.trim() ? value.id.trim() : '');
            if (!name) {
                throw createContainerMoveError(`Container transfer ${label} is missing a name.`, 500);
            }
            return name;
        }

        function formatContainerTransferItemForStory(item) {
            const name = resolveContainerTransferName(item, 'item');
            const count = Number(item.count);
            return Number.isInteger(count) && count > 1 ? `${name} (x${count})` : name;
        }

        function buildContainerTransferChatEntry({
            direction,
            playerName = null,
            container,
            items,
            locationId
        } = {}) {
            if (direction !== 'in' && direction !== 'out') {
                throw createContainerMoveError('Container transfer direction must be "in" or "out".', 500);
            }
            const actorName = typeof playerName === 'string' && playerName.trim()
                ? playerName.trim()
                : (typeof currentPlayer?.name === 'string' && currentPlayer.name.trim() ? currentPlayer.name.trim() : '');
            if (!actorName) {
                throw createContainerMoveError('Container transfer entry requires a player name.', 500);
            }
            const containerName = resolveContainerTransferName(container, 'container');
            if (!Array.isArray(items) || items.length === 0) {
                throw createContainerMoveError('Container transfer entry requires at least one item.', 500);
            }
            const itemLabels = items.map(formatContainerTransferItemForStory);
            const itemText = itemLabels.join(', ');
            const content = direction === 'out'
                ? `${actorName} retrieved ${itemText} from ${containerName}.`
                : `${actorName} put ${itemText} into ${containerName}.`;

            return {
                role: 'assistant',
                content,
                summary: content,
                type: 'container-transfer',
                locationId,
                metadata: {
                    containerId: container?.id || null,
                    containerName,
                    direction,
                    itemIds: items.map(item => item?.id || null).filter(Boolean),
                    itemNames: itemLabels
                }
            };
        }

        function recordContainerTransferChatEntry({
            direction,
            container,
            items,
            locationId = null
        } = {}) {
            const resolvedLocationId = requireLocationId(
                locationId || currentPlayer?.currentLocation,
                'container transfer entry'
            );
            const entry = buildContainerTransferChatEntry({
                direction,
                playerName: currentPlayer?.name || null,
                container,
                items,
                locationId: resolvedLocationId
            });
            return pushChatEntry(entry, null, resolvedLocationId);
        }

        const containerContentsGenerationPromises = new WeakMap();

        async function ensureContainerContentsGenerated(container, { location = null } = {}) {
            if (!container || typeof container !== 'object') {
                throw createContainerMoveError('Container contents generation requires a container.', 500);
            }
            const existingGeneration = containerContentsGenerationPromises.get(container);
            if (existingGeneration) {
                return await existingGeneration;
            }
            const pendingContents = Array.isArray(container?.containerContents)
                ? container.containerContents
                : [];
            if (!pendingContents.length) {
                return [];
            }
            if (typeof generateContainerContentsForThing !== 'function') {
                throw createContainerMoveError('Container contents generation helper is unavailable.', 500);
            }
            const generationPromise = Promise.resolve().then(async () => {
                const generated = await generateContainerContentsForThing({ container, location });
                if (things instanceof Map) {
                    things.set(container.id, container);
                    for (const item of Array.isArray(generated) ? generated : []) {
                        if (item?.id) {
                            things.set(item.id, item);
                        }
                    }
                }
                return Array.isArray(generated) ? generated : [];
            });
            containerContentsGenerationPromises.set(container, generationPromise);
            try {
                return await generationPromise;
            } finally {
                if (containerContentsGenerationPromises.get(container) === generationPromise) {
                    containerContentsGenerationPromises.delete(container);
                }
            }
        }

        async function ensurePendingContainerContentsForThings(items = []) {
            const list = Array.isArray(items) ? items : [];
            const seen = new Set();
            for (const item of list) {
                if (!item || !item.isContainer || !Array.isArray(item.containerContents) || item.containerContents.length === 0) {
                    continue;
                }
                if (item.id && seen.has(item.id)) {
                    continue;
                }
                if (item.id) {
                    seen.add(item.id);
                }
                await ensureContainerContentsGenerated(item);
            }
        }

        async function buildContainerInventoryPayload(container, { location = null } = {}) {
            if (!currentPlayer) {
                const error = new Error('No current player found');
                error.status = 404;
                throw error;
            }
            await ensureContainerContentsGenerated(container, { location });
            const playerPayload = serializeNpcForClient(currentPlayer);
            const contents = typeof container.getInventoryItems === 'function'
                ? container.getInventoryItems().map(item => (item && typeof item.toJSON === 'function' ? item.toJSON() : item))
                : [];
            return {
                success: true,
                container: typeof container.toJSON === 'function' ? container.toJSON() : { id: container.id },
                contents,
                player: playerPayload,
                playerInventory: Array.isArray(playerPayload?.inventory) ? playerPayload.inventory : [],
                location: location && typeof buildLocationResponse === 'function' ? buildLocationResponse(location) : null
            };
        }

        function parseContainerOpenResultXml(responseText) {
            if (typeof responseText !== 'string' || !responseText.trim()) {
                throw new Error('Container open-check response is empty.');
            }
            const trimmedResponse = responseText.trim();
            let xmlPayload = Utils.extractFinalXmlBlockFromResponse(trimmedResponse) || trimmedResponse;
            if (!/<containerOpenResult\b/i.test(xmlPayload)) {
                const match = trimmedResponse.match(/<containerOpenResult\b[\s\S]*<\/containerOpenResult>/i);
                if (match) {
                    xmlPayload = match[0];
                }
            }

            const parsedDocument = Utils.parseXmlDocumentStrict(sanitizeForXml(xmlPayload), 'text/xml');
            let root = parsedDocument?.documentElement || null;
            if (root && String(root.tagName || '').trim() === 'root') {
                root = getDirectChildElementByTagName(root, 'containerOpenResult');
            }
            if (!root || String(root.tagName || '').trim() !== 'containerOpenResult') {
                throw new Error('Container open-check response must contain <containerOpenResult>.');
            }

            const successText = getDirectChildTextByTagName(root, 'success').trim().toLowerCase();
            if (!successText) {
                throw new Error('Container open-check response is missing <success>.');
            }
            const success = ['true', 'yes', 'success', 'succeeded', 'open', 'opened'].includes(successText);
            const failure = ['false', 'no', 'failure', 'failed', 'fail', 'closed'].includes(successText);
            if (!success && !failure) {
                throw new Error(`Container open-check <success> must be true or false, got "${successText}".`);
            }

            const permanentlyOpenedText = getDirectChildTextByTagName(root, 'permanentlyOpened').trim().toLowerCase();
            if (!permanentlyOpenedText) {
                throw new Error('Container open-check response is missing <permanentlyOpened>.');
            }
            const permanentlyOpenedTrue = ['true', 'yes'].includes(permanentlyOpenedText);
            const permanentlyOpenedFalse = ['false', 'no'].includes(permanentlyOpenedText);
            if (!permanentlyOpenedTrue && !permanentlyOpenedFalse) {
                throw new Error(`Container open-check <permanentlyOpened> must be true or false, got "${permanentlyOpenedText}".`);
            }
            const permanentlyOpened = permanentlyOpenedTrue;

            const proseNode = getDirectChildElementByTagName(root, 'prose');
            const prose = extractProseNodeContentPreservingTags(proseNode).trim();
            if (!prose) {
                throw new Error('Container open-check response is missing non-empty <prose>.');
            }

            const timePassedNode = getDirectChildElementByTagName(root, 'timePassed');
            if (!timePassedNode) {
                throw new Error('Container open-check response is missing <timePassed>.');
            }
            const timePassedMinutes = parsePlayerActionTimePassedNode(timePassedNode, {
                fieldLabel: 'container open-check <timePassed>'
            });

            return { success, permanentlyOpened, prose, timePassedMinutes };
        }

        app.post('/api/things/:id/container/open-check', async (req, res) => {
            const newChatEntries = [];
            try {
                if (!currentPlayer) {
                    return res.status(404).json({
                        success: false,
                        error: 'No current player found'
                    });
                }

                const container = resolveRequestContainer(req.params.id);
                if (!container.requiresCheckToOpen) {
                    return res.json({
                        success: true,
                        opened: true,
                        skipped: true,
                        container: typeof container.toJSON === 'function' ? container.toJSON() : { id: container.id }
                    });
                }

                const requestBody = req.body && typeof req.body === 'object' ? req.body : {};
                const rawActionText = typeof requestBody.actionText === 'string'
                    ? requestBody.actionText.trim()
                    : '';
                const inlineRollControls = extractInlineRollControls(rawActionText);
                const actionText = typeof inlineRollControls.text === 'string'
                    ? inlineRollControls.text
                    : '';
                if (!actionText) {
                    return res.status(400).json({
                        success: false,
                        error: 'Describe how you are trying to open the container.'
                    });
                }

                const clientId = typeof requestBody.clientId === 'string' && requestBody.clientId.trim()
                    ? requestBody.clientId.trim()
                    : null;
                const requestId = typeof requestBody.requestId === 'string' && requestBody.requestId.trim()
                    ? requestBody.requestId.trim()
                    : (clientId ? `container_open_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}` : null);
                const stream = createStreamEmitter({ clientId, requestId });
                stream.status('container_open_check', `Checking ${container.name || 'container'}...`);

                const location = currentPlayer.currentLocation
                    ? resolveThingLocationById(currentPlayer.currentLocation)
                    : null;
                const baseContext = await prepareBasePromptContext({ locationOverride: location || null });
                const containerPromptContext = {
                    ...baseContext,
                    promptType: 'player-action-open-container',
                    characterName: currentPlayer.name || 'The player',
                    container: typeof container.toJSON === 'function' ? container.toJSON() : container,
                    containerOpenAction: actionText
                };
                const useTinyBrainContainerOpen = isTinyBrainPromptEnabled(
                    Globals.config,
                    'player_action_open_container'
                );
                const tinyBrain = useTinyBrainContainerOpen
                    ? configureTinyBrainPromptContext(
                        containerPromptContext,
                        'player_action_open_container'
                    )
                    : null;
                const renderedTemplate = promptEnv.render(
                    'base-context.xml.njk',
                    containerPromptContext
                );
                const parsedTemplate = parseXMLTemplate(renderedTemplate);
                if (!parsedTemplate?.systemPrompt || !parsedTemplate?.generationPrompt) {
                    throw new Error('Container open-check prompt template is missing prompts.');
                }

                const enabledChatTools = getChatToolDefinitions({ modExtensionRegistry })
                    .filter(toolDefinition => {
                        const toolName = typeof toolDefinition?.function?.name === 'string'
                            ? toolDefinition.function.name.trim()
                            : '';
                        return toolName === 'resolveSkillCheck'
                            || toolName === 'resolveOpposedSkillCheck';
                    });
                const hasSkillCheckTool = enabledChatTools.some(tool => {
                    const name = typeof tool?.function?.name === 'string' ? tool.function.name.trim() : '';
                    return name === 'resolveSkillCheck' || name === 'resolveOpposedSkillCheck';
                });
                if (!hasSkillCheckTool) {
                    throw new Error('Container open-check requires resolveSkillCheck or resolveOpposedSkillCheck to be enabled.');
                }

                const additionalPayload = {};
                if (enabledChatTools.length > 0) {
                    additionalPayload.tools = enabledChatTools;
                    additionalPayload.tool_choice = 'auto';
                }
                const requestOptions = {
                    messages: [
                        { role: 'system', content: parsedTemplate.systemPrompt },
                        { role: 'user', content: parsedTemplate.generationPrompt }
                    ],
                    metadataLabel: 'player_action_open_container',
                    expectedXmlRootTag: 'containerOpenResult',
                    validateXML: false
                };
                if (typeof parsedTemplate.temperature === 'number') {
                    requestOptions.temperature = parsedTemplate.temperature;
                }
                if (Object.keys(additionalPayload).length) {
                    requestOptions.additionalPayload = additionalPayload;
                }

                const checkResultsRecorder = createCheckResultsRecorder({
                    promptLabel: 'player_action_open_container',
                    locationId: location?.id || currentPlayer.currentLocation,
                    stream,
                    entryCollector: newChatEntries,
                    requestId
                });
                const containerToolResultCache = {
                    roundKey: [
                        'player_action_open_container',
                        currentPlayer.id || currentPlayer.name || 'player',
                        requestId || Date.now().toString(36),
                        Math.random().toString(36).slice(2, 10)
                    ].join(':'),
                    entries: new Map()
                };
                const runContainerToolLoop = stageRequestOptions => runChatCompletionWithToolLoop({
                    requestOptions: stageRequestOptions,
                    streamEmitter: stream,
                    metadataLabel: 'player_action_open_container',
                    toolResultCache: containerToolResultCache,
                    defaultToolActor: currentPlayer.name || null,
                    requestUserInput: clientId
                        ? createRequestUserInputHandler({
                            stream,
                            promptLabel: 'player_action_open_container'
                        })
                        : null,
                    forcedSkillCheckRoll: createForcedSkillCheckRollResolver({
                        enabled: inlineRollControls.forceSkillCheckRolls,
                        stream,
                        promptLabel: 'player_action_open_container'
                    }),
                    onToolCallEvent: event => checkResultsRecorder.record(event)
                });

                let rawResponse = '';
                let containerToolInvocations = [];
                let containerLiveDeslopInfo = null;
                if (useTinyBrainContainerOpen) {
                    const tinyBrainRun = await runTinyBrainNarrativePrompt({
                        family: 'player_action_open_container',
                        initialRenderedTemplate: renderedTemplate,
                        templateContext: containerPromptContext,
                        tinyBrain,
                        metadataLabel: 'player_action_open_container',
                        resultBuilders: {
                            container_open_result: buildContainerOpenResult
                        },
                        finalParser: (response, parseContext = {}) => {
                            const checkToolInvocations = Array.isArray(parseContext.toolInvocations)
                                ? parseContext.toolInvocations.filter(invocation => (
                                    invocation?.name === 'resolveSkillCheck'
                                    || invocation?.name === 'resolveOpposedSkillCheck'
                                ))
                                : [];
                            if (checkToolInvocations.length !== 1) {
                                throw new Error(
                                    `Container open-check must execute exactly one check tool; executed ${checkToolInvocations.length}.`
                                );
                            }
                            const invocation = checkToolInvocations[0];
                            if (invocation.metadata?.error === true) {
                                throw new Error('Container open-check tool execution failed.');
                            }
                            if (!checkResultsRecorder.hasRecords()) {
                                throw new Error(
                                    'Container open-check response did not call resolveSkillCheck or resolveOpposedSkillCheck.'
                                );
                            }
                            const expectedSuccess = typeof invocation.metadata?.actionResolution?.success === 'boolean'
                                ? invocation.metadata.actionResolution.success
                                : null;
                            const parsed = parseContainerOpenNarrativeResult(response, {
                                expectedToolName: invocation.name,
                                expectedSuccess
                            });
                            parseContainerOpenResultXml(parsed.normalizedResponse);
                            return parsed;
                        },
                        requestOptions,
                        completeStage: async stage => {
                            const isCheckToolCheckpoint = !stage.isFinal
                                && stage.checkpoint?.index === 0;
                            const stageRequestOptions = configureRequestChatTools(
                                stage.requestOptions,
                                isCheckToolCheckpoint ? enabledChatTools : []
                            );
                            if (isCheckToolCheckpoint) {
                                const toolLoopResult = await runContainerToolLoop(
                                    stageRequestOptions
                                );
                                return {
                                    aiResponse: toolLoopResult.aiResponse,
                                    conversationMessages: toolLoopResult.conversationMessages,
                                    toolInvocations: toolLoopResult.toolInvocations
                                };
                            }
                            const response = await LLMClient.chatCompletion(stageRequestOptions);
                            return {
                                aiResponse: response,
                                conversationMessages: [
                                    ...stage.messages.map(message => ({ ...message })),
                                    { role: 'assistant', content: response }
                                ],
                                toolInvocations: []
                            };
                        }
                    });
                    rawResponse = tinyBrainRun.result.aiResponse || '';
                    containerToolInvocations = tinyBrainRun.result.toolInvocations || [];
                    containerLiveDeslopInfo = tinyBrainRun.liveDeslopController?.getDiagnostics() || null;
                } else {
                    const toolLoopResult = await runContainerToolLoop(requestOptions);
                    rawResponse = toolLoopResult.aiResponse || '';
                    containerToolInvocations = toolLoopResult.toolInvocations || [];
                    LLMClient.logPrompt({
                        prefix: 'player_action_open_container',
                        metadataLabel: 'player_action_open_container',
                        systemPrompt: parsedTemplate.systemPrompt || '',
                        generationPrompt: parsedTemplate.generationPrompt || '',
                        response: rawResponse,
                        model: requestOptions.model,
                        endpoint: requestOptions.endpoint
                    });
                }

                const containerCheckToolInvocations = containerToolInvocations.filter(invocation => (
                    invocation?.name === 'resolveSkillCheck'
                    || invocation?.name === 'resolveOpposedSkillCheck'
                ));
                if (containerCheckToolInvocations.length !== 1) {
                    throw new Error(
                        `Container open-check must execute exactly one check tool; executed ${containerCheckToolInvocations.length}.`
                    );
                }
                if (useTinyBrainContainerOpen) {
                    parseContainerOpenNarrativeResult(rawResponse, {
                        expectedToolName: containerCheckToolInvocations[0].name
                    });
                }

                if (!checkResultsRecorder.hasRecords()) {
                    throw new Error('Container open-check response did not call resolveSkillCheck or resolveOpposedSkillCheck.');
                }

                const parsedResult = parseContainerOpenResultXml(rawResponse);
                if (parsedResult.success && parsedResult.permanentlyOpened) {
                    container.requiresCheckToOpen = false;
                    if (things instanceof Map && container.id) {
                        things.set(container.id, container);
                    }
                }
                let playerFacingProse = parsedResult.prose;
                let slopRemovalInfo = null;
                if (playerFacingProse && Globals.config?.slop_buster === true) {
                    const slopResult = await applySlopRemoval(playerFacingProse, { returnDiagnostics: true });
                    playerFacingProse = slopResult.text;
                    if (slopResult.ran) {
                        slopRemovalInfo = {
                            slopWords: slopResult.slopWords || [],
                            slopRegexes: slopResult.slopRegexes || [],
                            slopNgrams: slopResult.slopNgrams || []
                        };
                    }
                }
                if (containerLiveDeslopInfo?.ran) {
                    slopRemovalInfo = {
                        ...(slopRemovalInfo || {}),
                        slopWords: Array.from(new Set([
                            ...(slopRemovalInfo?.slopWords || []),
                            ...(containerLiveDeslopInfo.slopWords || [])
                        ])),
                        slopRegexes: Array.from(new Set([
                            ...(slopRemovalInfo?.slopRegexes || []),
                            ...(containerLiveDeslopInfo.slopRegexes || [])
                        ])),
                        slopNgrams: Array.from(new Set([
                            ...(slopRemovalInfo?.slopNgrams || []),
                            ...(containerLiveDeslopInfo.slopNgrams || [])
                        ])),
                        liveCorrections: [...(containerLiveDeslopInfo.corrections || [])]
                    };
                }
                const containerOpenTimeAdjustment = applyPlayerActionTimePassedMinutes(
                    parsedResult.timePassedMinutes,
                    { source: 'player_action_open_container' }
                );
                const containerOpenTimeProgress = containerOpenTimeAdjustment?.timeProgress || null;

                const resolvedLocationId = requireLocationId(location?.id || currentPlayer.currentLocation, 'container open-check entry');
                const chatEntry = pushChatEntry({
                    role: 'assistant',
                    content: playerFacingProse,
                    summary: playerFacingProse,
                    type: 'player-action-open-container',
                    locationId: resolvedLocationId,
                    metadata: {
                        containerId: container.id || null,
                        containerName: container.name || null,
                        opened: Boolean(parsedResult.success),
                        permanentlyOpened: Boolean(parsedResult.permanentlyOpened)
                    }
                }, newChatEntries, resolvedLocationId);

                if (slopRemovalInfo && chatEntry) {
                    recordSlopRemovalEntry({
                        data: slopRemovalInfo,
                        parentId: chatEntry.id || null,
                        locationId: resolvedLocationId
                    }, newChatEntries);
                }

                notifyVisibleProseEntryStored(chatEntry, {
                    stream,
                    clientId,
                    requestId,
                    proseType: 'player-action-open-container',
                    locationRefreshRequested: true
                });

                let eventResult = await Events.runEventChecks({
                    textToCheck: playerFacingProse,
                    actionText,
                    stream,
                    locationOverride: location || null,
                    ignoredEventKeys: ['alter_item'],
                    eventCheckIgnoreInstructions:
                        'The checked-container route already applied the authoritative lock state. '
                        + 'Do not emit alterItem for the attempted container.',
                    initialTimeProgress: containerOpenTimeProgress,
                    entryCollector: newChatEntries
                });
                if (containerOpenTimeProgress && (!eventResult || !eventResult.timeProgress)) {
                    if (!eventResult || typeof eventResult !== 'object') {
                        eventResult = {};
                    }
                    eventResult.timeProgress = { ...containerOpenTimeProgress };
                }

                if (eventResult) {
                    appendEventSummariesToChat({
                        summaryLabel: '📋 Events – Container Open Check',
                        statusLabel: '🌀 Status Changes – Container Open Check',
                        events: eventResult.structured || null,
                        experienceAwards: eventResult.experienceAwards || null,
                        currencyChanges: eventResult.currencyChanges || null,
                        environmentalDamageEvents: eventResult.environmentalDamageEvents || null,
                        needBarChanges: eventResult.needBarChanges || null,
                        dispositionChanges: eventResult.dispositionChanges || null,
                        factionReputationChanges: eventResult.factionReputationChanges || null,
                        timeProgress: eventResult.timeProgress || null,
                        timestamp: chatEntry?.timestamp || new Date().toISOString(),
                        parentId: chatEntry?.id || null,
                        locationId: resolvedLocationId
                    }, newChatEntries);
                }

                try {
                    await runAutosaveIfEnabled();
                } catch (autosaveError) {
                    console.warn('Autosave after container open-check failed:', autosaveError?.message || autosaveError);
                }

                return res.json({
                    success: true,
                    opened: Boolean(parsedResult.success),
                    permanentlyOpened: Boolean(parsedResult.permanentlyOpened),
                    prose: playerFacingProse,
                    container: typeof container.toJSON === 'function' ? container.toJSON() : { id: container.id },
                    locationRefreshRequested: true,
                    eventChecks: eventResult?.html || null,
                    timeProgress: containerOpenTimeProgress,
                    worldTime: buildWorldTimePayload({
                        transitions: Array.isArray(containerOpenTimeProgress?.transitions)
                            ? containerOpenTimeProgress.transitions
                            : []
                    }),
                    requestId
                });
            } catch (error) {
                console.error('Failed to resolve container open check:', error);
                return res.status(error.status || 500).json({
                    success: false,
                    error: error.message || 'Failed to resolve container open check'
                });
            }
        });

        app.get('/api/things/:id/container', async (req, res) => {
            try {
                const container = resolveRequestContainer(req.params.id);
                return res.json(await buildContainerInventoryPayload(container));
            } catch (error) {
                return res.status(error.status || 500).json({
                    success: false,
                    error: error.message || 'Failed to load container inventory'
                });
            }
        });

        app.post('/api/things/:id/container/move-in', async (req, res) => {
            try {
                if (!currentPlayer) {
                    return res.status(404).json({
                        success: false,
                        error: 'No current player found'
                    });
                }

                const container = resolveRequestContainer(req.params.id);
                const requestBody = req.body && typeof req.body === 'object' ? req.body : {};
                const rawSource = typeof requestBody.source === 'string' ? requestBody.source.trim().toLowerCase() : '';
                const source = rawSource === 'location' ? 'location' : 'player';
                const requestedLocationId = typeof requestBody.locationId === 'string' ? requestBody.locationId.trim() : '';
                const sourceLocation = source === 'location'
                    ? (
                        (requestedLocationId ? resolveThingLocationById(requestedLocationId) : null)
                        || (currentPlayer?.currentLocation ? resolveThingLocationById(currentPlayer.currentLocation) : null)
                    )
                    : null;
                if (source === 'location' && !sourceLocation) {
                    throw createContainerMoveError('Current location could not be resolved for container move.', 404);
                }
                const thingIds = resolveContainerMoveThingIds(req.body);
                const itemsToMove = resolveContainerMoveItems(thingIds);
                validateContainerMoveInItems(container, itemsToMove, {
                    source,
                    location: sourceLocation
                });

                for (const item of itemsToMove) {
                    container.addInventoryItem(item);
                }
                if (things instanceof Map) {
                    for (const item of itemsToMove) {
                        if (Thing.getById(item.id) === item) {
                            things.set(item.id, item);
                        }
                    }
                    things.set(container.id, container);
                }
                const chatEntry = recordContainerTransferChatEntry({
                    direction: 'in',
                    container,
                    items: itemsToMove,
                    locationId: sourceLocation?.id || currentPlayer.currentLocation
                });
                const payload = await buildContainerInventoryPayload(container, { location: sourceLocation });
                payload.chatEntry = chatEntry;
                return res.json(payload);
            } catch (error) {
                return res.status(error.status || 500).json({
                    success: false,
                    error: error.message || 'Failed to move item into container'
                });
            }
        });

        app.post('/api/things/:id/container/move-out', async (req, res) => {
            try {
                if (!currentPlayer) {
                    return res.status(404).json({
                        success: false,
                        error: 'No current player found'
                    });
                }

                const container = resolveRequestContainer(req.params.id);
                const thingIds = resolveContainerMoveThingIds(req.body);
                const itemsToMove = resolveContainerMoveItems(thingIds);
                validateContainerMoveOutItems(container, itemsToMove);

                for (const item of itemsToMove) {
                    const added = currentPlayer.addInventoryItem(item, { suppressNpcEquip: true });
                    if (!added || (Thing.getById(item.id) === item && !currentPlayer.hasInventoryItem(item.id))) {
                        throw createContainerMoveError(`Failed to move ${item.name || 'item'} into player inventory.`, 500);
                    }
                }
                if (things instanceof Map) {
                    for (const item of itemsToMove) {
                        if (Thing.getById(item.id) === item) {
                            things.set(item.id, item);
                        }
                    }
                    things.set(container.id, container);
                }
                const chatEntry = recordContainerTransferChatEntry({
                    direction: 'out',
                    container,
                    items: itemsToMove,
                    locationId: currentPlayer.currentLocation
                });
                const payload = await buildContainerInventoryPayload(container);
                payload.chatEntry = chatEntry;
                return res.json(payload);
            } catch (error) {
                return res.status(error.status || 500).json({
                    success: false,
                    error: error.message || 'Failed to move item out of container'
                });
            }
        });

        app.post('/api/things/:id/give', (req, res) => {
            try {
                const rawThingId = req.params.id;
                const thingId = typeof rawThingId === 'string' ? rawThingId.trim() : '';
                if (!thingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Thing ID is required'
                    });
                }

                const thing = things.get(thingId) || Thing.getById(thingId);
                if (!thing) {
                    return res.status(404).json({
                        success: false,
                        error: `Thing with ID '${thingId}' not found`
                    });
                }

                if (thing.thingType && thing.thingType !== 'item') {
                    return res.status(400).json({
                        success: false,
                        error: 'Only item-type things can be moved into an inventory.'
                    });
                }
                if (thing.isEquipped || thing.equippedSlot) {
                    return res.status(400).json({
                        success: false,
                        error: 'Equipped items must be unequipped before they can be moved.'
                    });
                }

                const payload = req.body && typeof req.body === 'object' ? req.body : {};

                const normalizeText = (value) => {
                    if (typeof value !== 'string') {
                        return null;
                    }
                    const trimmed = value.trim();
                    return trimmed || null;
                };

                const ownerId = normalizeText(payload.ownerId);
                const ownerType = normalizeText(payload.ownerType);
                const requestedLocationId = normalizeText(payload.locationId);

                if (!ownerId) {
                    return res.status(400).json({
                        success: false,
                        error: 'ownerId is required'
                    });
                }

                const resolveOwnerById = (candidateId) => {
                    if (!candidateId) {
                        return null;
                    }
                    if (players instanceof Map && players.has(candidateId)) {
                        return players.get(candidateId);
                    }
                    if (currentPlayer && currentPlayer.id === candidateId) {
                        return currentPlayer;
                    }
                    return null;
                };

                let owner = resolveOwnerById(ownerId);
                if (!owner && ownerType === 'player' && currentPlayer && currentPlayer.id) {
                    owner = currentPlayer.id === ownerId ? currentPlayer : owner;
                }

                if (!owner) {
                    return res.status(404).json({
                        success: false,
                        error: `Owner '${ownerId}' not found`
                    });
                }

                if (typeof owner.addInventoryItem !== 'function' || typeof owner.hasInventoryItem !== 'function') {
                    return res.status(400).json({
                        success: false,
                        error: 'Target owner cannot hold inventory items.'
                    });
                }

                const resolveLocationById = (targetId) => {
                    if (!targetId) {
                        return null;
                    }
                    let location = null;
                    if (typeof Location?.get === 'function') {
                        try {
                            location = Location.get(targetId);
                        } catch (_) {
                            location = null;
                        }
                    }
                    if (!location && gameLocations instanceof Map) {
                        location = gameLocations.get(targetId) || null;
                    }
                    return location;
                };

                const previousMetadata = thing.metadata && typeof thing.metadata === 'object' ? thing.metadata : {};
                const previousOwnerId = normalizeText(previousMetadata.ownerId || previousMetadata.ownerID || previousMetadata.owner);
                const previousLocationId = normalizeText(previousMetadata.locationId || previousMetadata.locationID);
                const isAlreadyOwnedByTarget = previousOwnerId && previousOwnerId === owner.id;

                if (previousOwnerId && previousOwnerId !== owner.id) {
                    const previousOwner = resolveOwnerById(previousOwnerId);
                    if (previousOwner && typeof previousOwner.removeInventoryItem === 'function') {
                        previousOwner.removeInventoryItem(thing.id);
                    }
                }

                const candidateLocationIds = new Set();
                // Only attempt to remove from the requested location if the item isn't already owned by the target.
                if (requestedLocationId && !isAlreadyOwnedByTarget) {
                    candidateLocationIds.add(requestedLocationId);
                }
                if (previousLocationId) {
                    candidateLocationIds.add(previousLocationId);
                }

                const touchedLocations = [];
                const removeThingFromLocation = (location) => {
                    if (!location) {
                        return false;
                    }
                    let changed = false;
                    if (typeof location.removeThingId === 'function') {
                        changed = location.removeThingId(thing.id) || changed;
                    }
                    if (!changed && Array.isArray(location.thingIds) && location.thingIds.includes(thing.id)) {
                        location.thingIds = location.thingIds.filter(id => id !== thing.id);
                        changed = true;
                    }
                    if (changed) {
                        touchedLocations.push(location);
                        if (gameLocations instanceof Map && location.id) {
                            gameLocations.set(location.id, location);
                        }
                    }
                    return changed;
                };

                let ensuredLocationRemoval = false;
                for (const locationId of candidateLocationIds) {
                    const location = resolveLocationById(locationId);
                    const changed = removeThingFromLocation(location);
                    ensuredLocationRemoval = ensuredLocationRemoval || changed;
                }
                if (requestedLocationId && !isAlreadyOwnedByTarget && !ensuredLocationRemoval) {
                    return res.status(409).json({
                        success: false,
                        error: `Thing '${thingId}' was not present in location '${requestedLocationId}'.`
                    });
                }

                const addedToOwner = owner.addInventoryItem(thing);
                const liveThing = Thing.getById(thing.id);
                const mergedThing = liveThing === thing
                    ? null
                    : Thing.findMergeTarget(thing, typeof owner.getInventoryItems === 'function' ? owner.getInventoryItems() : []);
                const responseThing = liveThing === thing ? thing : mergedThing;

                if (!addedToOwner || !responseThing || (liveThing === thing && !owner.hasInventoryItem(thing.id))) {
                    return res.status(500).json({
                        success: false,
                        error: 'Failed to move item into inventory.'
                    });
                }

                if (liveThing === thing) {
                    const updatedMetadata = { ...previousMetadata };
                    updatedMetadata.ownerId = owner.id;
                    delete updatedMetadata.owner;
                    delete updatedMetadata.ownerID;
                    delete updatedMetadata.locationId;
                    delete updatedMetadata.locationID;
                    delete updatedMetadata.containerId;
                    delete updatedMetadata.containerID;
                    delete updatedMetadata.container_id;
                    thing.metadata = updatedMetadata;
                }

                if (things instanceof Map && liveThing === thing) {
                    things.set(thing.id, thing);
                }

                let locationPayload = null;
                if (touchedLocations.length) {
                    const mostRecent = touchedLocations[touchedLocations.length - 1];
                    if (typeof buildLocationResponse === 'function') {
                        locationPayload = buildLocationResponse(mostRecent);
                    }
                }

                const responsePayload = {
                    success: true,
                    thing: typeof responseThing.toJSON === 'function' ? responseThing.toJSON() : { id: responseThing.id },
                    owner: serializeNpcForClient(owner),
                    location: locationPayload,
                    message: `${responseThing.name || thing.name || 'Item'} moved to inventory.`
                };

                res.json(responsePayload);
            } catch (error) {
                console.error('Failed to move thing into inventory:', error);
                res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to move item into inventory'
                });
            }
        });

        app.post('/api/things/:id/teleport', (req, res) => {
            try {
                const { id } = req.params;
                const thingId = typeof id === 'string' ? id.trim() : '';
                if (!thingId) {
                    return res.status(400).json({ success: false, error: 'Thing ID is required' });
                }

                const thing = things.get(thingId) || Thing.getById(thingId);
                if (!thing) {
                    return res.status(404).json({ success: false, error: 'Thing not found' });
                }
                if (thing.isEquipped || thing.equippedSlot) {
                    return res.status(400).json({
                        success: false,
                        error: 'Equipped items must be unequipped before they can be moved.'
                    });
                }

                const body = req.body && typeof req.body === 'object' ? req.body : {};
                const rawLocationId = typeof body.locationId === 'string' ? body.locationId.trim() : '';
                if (!rawLocationId) {
                    return res.status(400).json({ success: false, error: 'Destination locationId is required' });
                }

                const resolveLocationById = (targetId) => {
                    if (!targetId) {
                        return null;
                    }
                    let location = null;
                    if (typeof Location?.get === 'function') {
                        try {
                            location = Location.get(targetId);
                        } catch (_) {
                            location = null;
                        }
                    }
                    if (!location && gameLocations instanceof Map) {
                        location = gameLocations.get(targetId) || null;
                    }
                    return location;
                };

                const destinationLocation = resolveLocationById(rawLocationId);
                if (!destinationLocation) {
                    return res.status(404).json({ success: false, error: `Destination location '${rawLocationId}' not found` });
                }

                const previousMetadata = thing.metadata || {};
                const previousLocationId = typeof previousMetadata.locationId === 'string' ? previousMetadata.locationId.trim() : null;
                const previousLocation = previousLocationId ? resolveLocationById(previousLocationId) : null;

                const affectedOwnerIds = new Set();
                const removeFromActor = (actor) => {
                    if (!actor || typeof actor.removeInventoryItem !== 'function') {
                        return;
                    }
                    let removed = false;
                    try {
                        removed = actor.removeInventoryItem(thing.id, { suppressNpcEquip: Boolean(actor.isNPC) });
                    } catch (error) {
                        console.warn('Failed to remove item from actor inventory:', error?.message || error);
                    }
                    if (removed && typeof actor.unequipItemId === 'function') {
                        try {
                            actor.unequipItemId(thing.id, { suppressTimestamp: true });
                        } catch (_) {
                            /* ignore */
                        }
                    }
                    if (removed && actor.id) {
                        affectedOwnerIds.add(actor.id);
                    }
                };

                if (players instanceof Map) {
                    for (const actor of players.values()) {
                        removeFromActor(actor);
                    }
                }
                if (currentPlayer && (!players || !players.has?.(currentPlayer.id))) {
                    removeFromActor(currentPlayer);
                }

                if (previousLocation && typeof previousLocation.removeThingId === 'function') {
                    try {
                        previousLocation.removeThingId(thing.id);
                    } catch (error) {
                        console.warn('Failed to detach thing from previous location:', error?.message || error);
                    }
                    if (gameLocations instanceof Map) {
                        gameLocations.set(previousLocation.id, previousLocation);
                    }
                }

                if (typeof destinationLocation.addThingId === 'function') {
                    destinationLocation.addThingId(thing.id);
                }
                if (gameLocations instanceof Map) {
                    gameLocations.set(destinationLocation.id, destinationLocation);
                }

                const liveThing = Thing.getById(thing.id);
                const mergedThing = liveThing === thing
                    ? null
                    : Thing.findMergeTarget(
                        thing,
                        Array.isArray(destinationLocation.thingIds)
                            ? destinationLocation.thingIds.map(id => Thing.getById(id)).filter(Boolean)
                            : []
                    );
                const responseThing = liveThing === thing ? thing : (mergedThing || thing);

                if (liveThing === thing) {
                    const updatedMetadata = { ...previousMetadata };
                    delete updatedMetadata.owner;
                    delete updatedMetadata.ownerId;
                    delete updatedMetadata.ownerID;
                    delete updatedMetadata.containerId;
                    delete updatedMetadata.containerID;
                    delete updatedMetadata.container_id;
                    updatedMetadata.locationId = destinationLocation.id;
                    thing.metadata = updatedMetadata;
                }

                if (things instanceof Map && liveThing === thing) {
                    things.set(thing.id, thing);
                }

                let previousLocationPayload = null;
                if (previousLocation && typeof buildLocationResponse === 'function') {
                    try {
                        previousLocationPayload = buildLocationResponse(previousLocation);
                    } catch (error) {
                        console.warn('Failed to serialize previous location after teleport:', error?.message || error);
                    }
                }

                let destinationPayload = null;
                if (typeof buildLocationResponse === 'function') {
                    try {
                        destinationPayload = buildLocationResponse(destinationLocation);
                    } catch (error) {
                        console.warn('Failed to serialize destination location after teleport:', error?.message || error);
                    }
                }

                const responsePayload = {
                    success: true,
                    thing: typeof responseThing.toJSON === 'function' ? responseThing.toJSON() : { id: responseThing.id },
                    destination: destinationPayload,
                    previousLocation: previousLocationPayload,
                    removedOwnerIds: Array.from(affectedOwnerIds),
                    locationIds: Array.from(new Set([
                        destinationLocation.id,
                        previousLocation?.id || null
                    ].filter(Boolean))),
                    message: `${thing.name || 'Item'} teleported successfully.`
                };

                res.json(responsePayload);
            } catch (error) {
                console.error('Failed to teleport item:', error);
                res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to teleport item'
                });
            }
        });

        function detachThingFromContainingContainers(thing) {
            if (!thing?.id) {
                throw new Error('Missing item information.');
            }
            if (!Thing || typeof Thing.getAll !== 'function') {
                throw new Error('Thing registry is unavailable for container detachment.');
            }

            const touchedContainers = [];
            for (const container of Thing.getAll()) {
                if (
                    !container
                    || container.id === thing.id
                    || typeof container.hasInventoryItem !== 'function'
                    || typeof container.removeInventoryItem !== 'function'
                ) {
                    continue;
                }
                if (!container.hasInventoryItem(thing.id)) {
                    continue;
                }
                if (container.removeInventoryItem(thing.id)) {
                    touchedContainers.push(container);
                }
            }
            return touchedContainers;
        }

        app.post('/api/things/:id/drop', (req, res) => {
            try {
                const { id } = req.params;
                const thingId = typeof id === 'string' ? id.trim() : '';
                if (!thingId) {
                    return res.status(400).json({
                        success: false,
                        error: 'Thing ID is required'
                    });
                }

                const thing = things.get(thingId) || Thing.getById(thingId);
                if (!thing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }
                if (thing.isEquipped || thing.equippedSlot) {
                    return res.status(400).json({
                        success: false,
                        error: 'Equipped items must be unequipped before they can be moved.'
                    });
                }

                const body = req.body && typeof req.body === 'object' ? req.body : {};
                let { ownerId = null, ownerType = null, locationId = null } = body;

                const normalize = (value) => {
                    if (typeof value !== 'string') {
                        return null;
                    }
                    const trimmed = value.trim();
                    return trimmed || null;
                };

                ownerId = normalize(ownerId);
                ownerType = normalize(ownerType);
                locationId = normalize(locationId);

                const resolveActorById = (actorId) => {
                    if (!actorId) {
                        return null;
                    }
                    try {
                        if (players instanceof Map && players.has(actorId)) {
                            return players.get(actorId);
                        }
                    } catch (_) { }
                    if (currentPlayer && currentPlayer.id === actorId) {
                        return currentPlayer;
                    }
                    return null;
                };

                let owner = null;
                if (ownerId) {
                    owner = resolveActorById(ownerId);
                }
                if (!owner && ownerType === 'player' && currentPlayer) {
                    owner = currentPlayer;
                    ownerId = currentPlayer.id;
                }

                if (!owner) {
                    const meta = thing.metadata || {};
                    const metaOwnerId = normalize(meta.ownerId || meta.ownerID || meta.owner);
                    if (metaOwnerId) {
                        owner = resolveActorById(metaOwnerId);
                        if (owner) {
                            ownerId = owner.id || metaOwnerId;
                        }
                    }
                }

                const resolveLocationById = (targetId) => {
                    if (!targetId) {
                        return null;
                    }
                    let location = null;
                    if (Location && typeof Location.get === 'function') {
                        try {
                            location = Location.get(targetId);
                        } catch (_) {
                            location = null;
                        }
                    }
                    if (!location && gameLocations instanceof Map) {
                        location = gameLocations.get(targetId) || null;
                    }
                    return location;
                };

                let targetLocation = resolveLocationById(locationId);
                if (!targetLocation && owner && owner.currentLocation) {
                    targetLocation = resolveLocationById(owner.currentLocation);
                }
                if (!targetLocation && owner && owner.locationId) {
                    targetLocation = resolveLocationById(owner.locationId);
                }
                if (!targetLocation && currentPlayer?.currentLocation) {
                    targetLocation = resolveLocationById(currentPlayer.currentLocation);
                }

                if (!targetLocation) {
                    return res.status(400).json({
                        success: false,
                        error: 'Unable to determine drop location'
                    });
                }

                if (owner && typeof owner.removeInventoryItem === 'function') {
                    try {
                        owner.removeInventoryItem(thing.id);
                    } catch (inventoryError) {
                        console.warn('Failed to remove thing from owner inventory:', inventoryError?.message || inventoryError);
                    }
                }

                const touchedContainers = detachThingFromContainingContainers(thing);

                const existingMetadata = thing.metadata || {};
                const previousLocationId = normalize(existingMetadata.locationId);
                if (previousLocationId && previousLocationId !== targetLocation.id) {
                    const previousLocation = resolveLocationById(previousLocationId);
                    if (previousLocation && typeof previousLocation.removeThingId === 'function') {
                        previousLocation.removeThingId(thing.id);
                        if (gameLocations instanceof Map) {
                            gameLocations.set(previousLocation.id, previousLocation);
                        }
                    }
                }

                const updatedMetadata = { ...existingMetadata };
                delete updatedMetadata.owner;
                delete updatedMetadata.ownerId;
                delete updatedMetadata.ownerID;
                delete updatedMetadata.containerId;
                delete updatedMetadata.containerID;
                delete updatedMetadata.container_id;
                updatedMetadata.locationId = targetLocation.id;
                thing.metadata = updatedMetadata;

                if (typeof targetLocation.addThingId === 'function') {
                    targetLocation.addThingId(thing.id);
                }
                const liveThing = Thing.getById(thing.id);
                const mergedThing = liveThing === thing
                    ? null
                    : Thing.findMergeTarget(
                        thing,
                        Array.isArray(targetLocation.thingIds)
                            ? targetLocation.thingIds.map(id => Thing.getById(id)).filter(Boolean)
                            : []
                    );
                const responseThing = liveThing === thing ? thing : (mergedThing || thing);
                if (gameLocations instanceof Map) {
                    gameLocations.set(targetLocation.id, targetLocation);
                }
                if (things instanceof Map) {
                    for (const container of touchedContainers) {
                        if (container?.id) {
                            things.set(container.id, container);
                        }
                    }
                }

                const responsePayload = {
                    success: true,
                    thing: responseThing.toJSON ? responseThing.toJSON() : { id: responseThing.id, name: responseThing.name },
                    location: typeof buildLocationResponse === 'function' ? buildLocationResponse(targetLocation) : null,
                    message: `${responseThing.name || thing.name || 'Item'} dropped successfully.`
                };

                if (owner) {
                    responsePayload.owner = serializeNpcForClient(owner);
                }

                res.json(responsePayload);
            } catch (error) {
                console.error('Failed to drop item:', error);
                console.error(error.stack);
                res.status(500).json({
                    success: false,
                    error: error?.message || 'Failed to drop item'
                });
            }
        });

        // Delete a thing
        app.delete('/api/things/:id', (req, res) => {
            try {
                const { id } = req.params;
                const result = deleteThingById(id);
                if (!result.success) {
                    return res.status(result.status || 500).json({
                        success: false,
                        error: result.error || 'Failed to delete thing'
                    });
                }

                res.json({
                    success: true,
                    message: 'Thing deleted successfully',
                    locationIds: Array.isArray(result.locationIds) ? result.locationIds : [],
                    playerIds: Array.isArray(result.playerIds) ? result.playerIds : [],
                    npcIds: Array.isArray(result.npcIds) ? result.npcIds : [],
                    containerIds: Array.isArray(result.containerIds) ? result.containerIds : []
                });
            } catch (error) {
                console.error('Failed to delete thing:', error);
                res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to delete thing'
                });
            }
        });

        app.get('/api/things/:id/currency-conversion', (req, res) => {
            try {
                const { conversion } = resolveThingCurrencyConversionById(req.params.id);
                res.json({
                    success: true,
                    conversion
                });
            } catch (error) {
                console.warn('Failed to preview item currency conversion:', error?.message || error);
                res.status(error?.statusCode || 500).json({
                    success: false,
                    error: error?.message || 'Failed to preview item currency conversion.'
                });
            }
        });

        app.post('/api/things/:id/convert-to-currency', (req, res) => {
            try {
                const conversionPlayer = Globals.currentPlayer || currentPlayer || null;
                if (!conversionPlayer || conversionPlayer.isNPC === true) {
                    const error = new Error('No active player is available to receive the currency.');
                    error.statusCode = 409;
                    throw error;
                }
                if (typeof conversionPlayer.getCurrency !== 'function'
                    || typeof conversionPlayer.setCurrency !== 'function') {
                    throw new Error('The active player does not support currency updates.');
                }

                const { conversion } = resolveThingCurrencyConversionById(req.params.id);
                assertThingCurrencyConversionConfirmation(req.body?.expected, conversion);

                const currencyBefore = Number(conversionPlayer.getCurrency());
                const currencyAfter = currencyBefore + conversion.totalValue;
                if (!Number.isSafeInteger(currencyBefore) || !Number.isSafeInteger(currencyAfter) || currencyAfter < 0) {
                    const error = new Error('The player currency total is outside the supported range, so the item was not converted.');
                    error.statusCode = 409;
                    throw error;
                }

                const deletionResult = deleteThingById(req.params.id);
                if (!deletionResult.success) {
                    const error = new Error(deletionResult.error || 'Failed to delete the converted item.');
                    error.statusCode = deletionResult.status || 500;
                    throw error;
                }

                conversionPlayer.setCurrency(currencyAfter);
                const affectedPlayerIds = new Set(
                    Array.isArray(deletionResult.playerIds) ? deletionResult.playerIds : []
                );
                affectedPlayerIds.add(conversionPlayer.id);

                res.json({
                    success: true,
                    conversion,
                    currencyBefore,
                    currencyAfter: conversionPlayer.getCurrency(),
                    player: serializeNpcForClient(conversionPlayer),
                    message: `${conversion.thingName} was converted into ${conversion.totalValue} ${conversion.currencyLabel}.`,
                    locationIds: Array.isArray(deletionResult.locationIds) ? deletionResult.locationIds : [],
                    playerIds: Array.from(affectedPlayerIds),
                    npcIds: Array.isArray(deletionResult.npcIds) ? deletionResult.npcIds : [],
                    containerIds: Array.isArray(deletionResult.containerIds) ? deletionResult.containerIds : []
                });
            } catch (error) {
                console.warn('Failed to convert item to currency:', error?.message || error);
                res.status(error?.statusCode || 500).json({
                    success: false,
                    error: error?.message || 'Failed to convert item to currency.'
                });
            }
        });

        // Get all scenery things
        app.get('/api/things/scenery', (req, res) => {
            try {
                const sceneryThings = Array.from(things.values())
                    .filter(thing => thing.isScenery())
                    .map(thing => thing.toJSON());

                res.json({
                    success: true,
                    things: sceneryThings,
                    count: sceneryThings.length
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Get all item things
        app.get('/api/things/items', (req, res) => {
            try {
                const itemThings = Array.from(things.values())
                    .filter(thing => thing.isItem())
                    .map(thing => thing.toJSON());

                res.json({
                    success: true,
                    things: itemThings,
                    count: itemThings.length
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Generate image for a specific thing
        app.post('/api/things/:id/image', async (req, res) => {
            try {
                const { id } = req.params;
                const thing = things.get(id);

                if (!thing) {
                    return res.status(404).json({
                        success: false,
                        error: 'Thing not found'
                    });
                }

                const imageResult = await generateThingImage(thing, { force: true });

                if (imageResult.success) {
                    return res.json({
                        success: true,
                        thing: thing.toJSON(),
                        imageGeneration: imageResult,
                        message: `${thing.thingType} image generation initiated for ${thing.name}`
                    });
                }

                if (imageResult.existingJob) {
                    return res.status(202).json({
                        success: false,
                        thing: thing.toJSON(),
                        imageGeneration: imageResult,
                        message: 'Image job already in progress'
                    });
                }

                if (imageResult.skipped) {
                    return res.status(409).json({
                        success: false,
                        error: 'Image generation is not available or disabled',
                        reason: imageResult.reason,
                        thing: thing.toJSON()
                    });
                }

                res.status(500).json({
                    success: false,
                    error: imageResult.message || 'Failed to queue image generation',
                    thing: thing.toJSON()
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // ==================== SETTINGS API ENDPOINTS ====================

        // Get all settings
        app.get('/api/settings', (req, res) => {
            try {
                const allSettings = SettingInfo.getAll().map(setting => setting.toJSON());

                res.json({
                    success: true,
                    settings: allSettings,
                    count: allSettings.length
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Create a new setting
        app.post('/api/settings', (req, res) => {
            try {
                const settingData = req.body;

                // Validate required fields
                if (!settingData.name || typeof settingData.name !== 'string') {
                    return res.status(400).json({
                        success: false,
                        error: 'Setting name is required and must be a string'
                    });
                }

                // Check if setting with same name already exists
                if (SettingInfo.getByName(settingData.name)) {
                    return res.status(409).json({
                        success: false,
                        error: 'Setting with this name already exists'
                    });
                }

                const newSetting = new SettingInfo(settingData);

                res.status(201).json({
                    success: true,
                    setting: newSetting.toJSON(),
                    message: 'Setting created successfully'
                });
            } catch (error) {
                res.status(400).json({
                    success: false,
                    error: error.message
                });
            }
        });

        function buildSettingMechanicAttributeOptions() {
            let definitions = {};
            try {
                const { value } = loadMergedDefinitionFile({
                    baseDir: Globals.baseDir || __dirname,
                    filename: 'attributes.yaml'
                });
                definitions = value?.attributes || {};
            } catch (error) {
                throw new Error(`Unable to load attribute definitions for setting mechanics: ${error.message}`);
            }

            return Object.entries(definitions)
                .map(([name, definition]) => {
                    const normalizedName = typeof name === 'string' ? name.trim() : '';
                    if (!normalizedName) {
                        return null;
                    }
                    const label = typeof definition?.label === 'string' && definition.label.trim()
                        ? definition.label.trim()
                        : normalizedName
                            .split(/[_\s-]+/)
                            .filter(Boolean)
                            .map(part => part.charAt(0).toUpperCase() + part.slice(1))
                            .join(' ');
                    return {
                        name: normalizedName,
                        label,
                        abbreviation: typeof definition?.abbreviation === 'string' ? definition.abbreviation.trim() : '',
                        description: typeof definition?.description === 'string' ? definition.description.trim() : ''
                    };
                })
                .filter(Boolean);
        }

        function normalizeSettingMechanicText(value) {
            return typeof value === 'string' ? value.trim() : '';
        }

        function normalizeSettingSkillOptions(value) {
            if (Array.isArray(value)) {
                return value
                    .map(normalizeSettingMechanicText)
                    .filter(Boolean);
            }
            if (typeof value === 'string') {
                return value
                    .split(/\r?\n/)
                    .map(normalizeSettingMechanicText)
                    .filter(Boolean);
            }
            return [];
        }

        function resolveAllowedSettingMechanicValue(value, allowedValues, fieldName, { allowBlank = false } = {}) {
            const normalizedValue = normalizeSettingMechanicText(value);
            if (!normalizedValue) {
                if (allowBlank) {
                    return '';
                }
                throw new Error(`${fieldName} is required.`);
            }
            if (allowBlank && /^(none|no skill|n\/a|not applicable)$/i.test(normalizedValue)) {
                return '';
            }

            const exactMatch = allowedValues.find(allowed => allowed === normalizedValue);
            if (exactMatch) {
                return exactMatch;
            }
            const lowerValue = normalizedValue.toLowerCase();
            const caseInsensitiveMatch = allowedValues.find(allowed => allowed.toLowerCase() === lowerValue);
            if (caseInsensitiveMatch) {
                return caseInsensitiveMatch;
            }

            throw new Error(`${fieldName} "${normalizedValue}" is not defined. Allowed values: ${allowedValues.join(', ')}`);
        }

        function parseSettingHidePerceptionResponse(xmlContent) {
            if (!xmlContent || typeof xmlContent !== 'string') {
                throw new Error('AI response was empty while choosing setting hide/perception mechanics.');
            }

            const trimmed = xmlContent.trim();
            if (!trimmed) {
                throw new Error('AI response was empty while choosing setting hide/perception mechanics.');
            }

            const doc = Utils.parseXmlDocument(sanitizeForXml(trimmed), 'text/xml');
            const parserError = doc.getElementsByTagName('parsererror')[0];
            if (parserError) {
                throw new Error(`AI response XML parsing error while choosing setting hide/perception mechanics: ${parserError.textContent}`);
            }

            const mechanicsNode = doc.getElementsByTagName('settingMechanics')[0];
            if (!mechanicsNode) {
                throw new Error('AI response missing <settingMechanics> element.');
            }

            const getText = (tagName) => {
                const node = mechanicsNode.getElementsByTagName(tagName)[0];
                if (!node || typeof node.textContent !== 'string') {
                    return '';
                }
                return node.textContent.trim();
            };

            return {
                hidingAttribute: getText('hidingAttribute'),
                hidingSkill: getText('hidingSkill'),
                perceptionAttribute: getText('perceptionAttribute'),
                perceptionSkill: getText('perceptionSkill')
            };
        }

        function normalizeSettingHidePerceptionSelection(selection, { attributeOptions, skills }) {
            const attributeNames = attributeOptions.map(attribute => attribute.name).filter(Boolean);
            if (attributeNames.length === 0) {
                throw new Error('Cannot choose setting hide/perception mechanics because no attributes are defined.');
            }
            const skillOptions = normalizeSettingSkillOptions(skills);

            return {
                hidingAttribute: resolveAllowedSettingMechanicValue(selection?.hidingAttribute, attributeNames, 'hidingAttribute'),
                hidingSkill: resolveAllowedSettingMechanicValue(selection?.hidingSkill, skillOptions, 'hidingSkill', { allowBlank: true }),
                perceptionAttribute: resolveAllowedSettingMechanicValue(selection?.perceptionAttribute, attributeNames, 'perceptionAttribute'),
                perceptionSkill: resolveAllowedSettingMechanicValue(selection?.perceptionSkill, skillOptions, 'perceptionSkill', { allowBlank: true })
            };
        }

        function settingNeedsHidePerceptionSelections(settingSnapshot) {
            if (!settingSnapshot || typeof settingSnapshot !== 'object') {
                return false;
            }
            return !normalizeSettingMechanicText(settingSnapshot.hidingAttribute)
                || !normalizeSettingMechanicText(settingSnapshot.perceptionAttribute);
        }

        async function generateSettingHidePerceptionSelections(settingSnapshot) {
            const attributeOptions = buildSettingMechanicAttributeOptions();
            const skills = normalizeSettingSkillOptions(settingSnapshot?.defaultExistingSkills);
            const renderedTemplate = promptEnv.render('setting-hide-perception.xml.njk', {
                setting: settingSnapshot || {},
                attributeOptions,
                skills
            });
            const promptData = parseXMLTemplate(renderedTemplate);
            const systemPrompt = promptData.systemPrompt ? promptData.systemPrompt.trim() : '';
            const generationPrompt = promptData.generationPrompt ? promptData.generationPrompt.trim() : '';
            if (!generationPrompt) {
                throw new Error('Failed to build setting hide/perception generation prompt.');
            }

            const messages = [];
            if (systemPrompt) {
                messages.push({ role: 'system', content: systemPrompt });
            }
            messages.push({ role: 'user', content: generationPrompt });

            const requestOptions = {
                messages,
                metadataLabel: 'setting_hide_perception',
                expectedXmlRootTag: 'settingMechanics'
            };
            if (typeof promptData.temperature === 'number') {
                requestOptions.temperature = promptData.temperature;
            } else {
                const configTemperature = Number(config?.ai?.temperature);
                if (Number.isInteger(configTemperature)) {
                    requestOptions.temperature = configTemperature;
                }
            }

            const aiMessage = await LLMClient.chatCompletion(requestOptions);
            if (!aiMessage || typeof aiMessage !== 'string') {
                throw new Error('AI did not return setting hide/perception mechanics.');
            }

            LLMClient.logPrompt({
                prefix: 'setting_hide_perception',
                metadataLabel: requestOptions.metadataLabel,
                systemPrompt: systemPrompt || '',
                generationPrompt: generationPrompt || '',
                response: aiMessage || ''
            });

            const parsedSelection = parseSettingHidePerceptionResponse(aiMessage);
            return normalizeSettingHidePerceptionSelection({
                hidingAttribute: parsedSelection.hidingAttribute || settingSnapshot?.hidingAttribute || '',
                hidingSkill: parsedSelection.hidingSkill || settingSnapshot?.hidingSkill || '',
                perceptionAttribute: parsedSelection.perceptionAttribute || settingSnapshot?.perceptionAttribute || '',
                perceptionSkill: parsedSelection.perceptionSkill || settingSnapshot?.perceptionSkill || ''
            }, {
                attributeOptions,
                skills
            });
        }

        async function ensureCurrentSettingHidePerceptionSelections() {
            if (!currentSetting) {
                return { updated: false, selections: null };
            }
            const settingSnapshot = currentSetting && typeof currentSetting.toJSON === 'function'
                ? currentSetting.toJSON()
                : currentSetting;
            if (!settingNeedsHidePerceptionSelections(settingSnapshot)) {
                return { updated: false, selections: null };
            }

            const selections = await generateSettingHidePerceptionSelections(settingSnapshot);
            if (currentSetting && typeof currentSetting.update === 'function') {
                currentSetting.update(selections);
            } else if (currentSetting && typeof currentSetting === 'object') {
                Object.assign(currentSetting, selections);
            } else {
                throw new Error('Loaded setting cannot store hide/perception mechanic selections.');
            }
            console.log(
                `Filled setting hide/perception mechanics: hiding=${selections.hidingAttribute}`
                + (selections.hidingSkill ? `/${selections.hidingSkill}` : '')
                + `, perception=${selections.perceptionAttribute}`
                + (selections.perceptionSkill ? `/${selections.perceptionSkill}` : '')
            );
            return { updated: true, selections };
        }

        function normalizeSettingPayload(raw = {}) {
            const toStringValue = (value) => {
                if (value === null || value === undefined) {
                    return '';
                }
                return String(value).trim();
            };

            const toNumberString = (value) => {
                const str = toStringValue(value);
                if (!str) {
                    return '';
                }
                const parsed = parseInt(str, 10);
                return Number.isFinite(parsed) ? String(parsed) : '';
            };

            const toBoundedIntegerString = (value, fieldName, minimum, maximum = null) => {
                const str = toStringValue(value);
                if (!str) {
                    return '';
                }
                const parsed = Number(str);
                const exceedsMaximum = maximum !== null && parsed > maximum;
                if (!Number.isInteger(parsed) || parsed < minimum || exceedsMaximum) {
                    const range = maximum === null ? `at least ${minimum}` : `between ${minimum} and ${maximum}`;
                    throw new Error(`${fieldName} must be an integer ${range}.`);
                }
                return String(parsed);
            };

            const toStringArray = (value) => {
                if (!value) {
                    return [];
                }
                if (Array.isArray(value)) {
                    return value
                        .map(v => toStringValue(v))
                        .filter(v => v.length > 0);
                }
                return toStringValue(value)
                    .split(/\r?\n/)
                    .map(item => item.trim())
                    .filter(item => item.length > 0);
            };

            const toFactionArray = (value) => {
                if (value === null || value === undefined || value === '') {
                    return [];
                }
                if (Array.isArray(value)) {
                    return value;
                }
                if (typeof value !== 'string') {
                    throw new Error('defaultFactions must be an array or a JSON string.');
                }
                const trimmed = value.trim();
                if (!trimmed) {
                    return [];
                }
                let parsed;
                try {
                    parsed = JSON.parse(trimmed);
                } catch (error) {
                    throw new Error(`defaultFactions must be valid JSON: ${error.message}`);
                }
                if (!Array.isArray(parsed)) {
                    throw new Error('defaultFactions JSON must decode to an array.');
                }
                return parsed;
            };

            const toNullableCalendarDefinition = (value) => {
                if (value === null || value === undefined || value === '') {
                    return null;
                }
                let source = value;
                if (typeof value === 'string') {
                    const trimmed = value.trim();
                    if (!trimmed) {
                        return null;
                    }
                    try {
                        source = JSON.parse(trimmed);
                    } catch (error) {
                        throw new Error(`calendarDefinition must be valid JSON: ${error.message}`);
                    }
                }
                return Globals.normalizeCalendarDefinition(source);
            };

            const toBoolean = (value, fallback) => {
                if (value === undefined || value === null || value === '') {
                    return fallback;
                }
                if (typeof value === 'boolean') {
                    return value;
                }
                const normalized = String(value).trim().toLowerCase();
                if (['true', '1', 'yes', 'on'].includes(normalized)) {
                    return true;
                }
                if (['false', '0', 'no', 'off'].includes(normalized)) {
                    return false;
                }
                throw new Error(`Expected a boolean value, got "${value}".`);
            };

            const toJsonObject = (value, fieldName) => {
                if (value === undefined || value === null || value === '') {
                    return {};
                }
                let parsed = value;
                if (typeof value === 'string') {
                    try {
                        parsed = JSON.parse(value);
                    } catch (error) {
                        throw new Error(`${fieldName} must be valid JSON: ${error.message}`);
                    }
                }
                if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                    throw new Error(`${fieldName} must be a JSON object.`);
                }
                return parsed;
            };
	
            return {
                name: toStringValue(raw.name),
                description: toStringValue(raw.description),
                theme: toStringValue(raw.theme),
                genre: toStringValue(raw.genre),
                startingLocationType: toStringValue(raw.startingLocationType),
                magicLevel: toStringValue(raw.magicLevel),
                techLevel: toStringValue(raw.techLevel),
                tone: toStringValue(raw.tone),
                difficulty: toStringValue(raw.difficulty),
                currencyName: toStringValue(raw.currencyName),
                currencyNamePlural: toStringValue(raw.currencyNamePlural),
                currencyValueNotes: toStringValue(raw.currencyValueNotes),
                writingStyleNotes: toStringValue(raw.writingStyleNotes ?? raw.styleNotes),
                baseContextPreamble: toStringValue(raw.baseContextPreamble),
                characterGenInstructions: toStringValue(raw.characterGenInstructions),
                imagePromptPrefixCharacter: toStringValue(raw.imagePromptPrefixCharacter),
                imagePromptPrefixLocation: toStringValue(raw.imagePromptPrefixLocation),
                imagePromptPrefixItem: toStringValue(raw.imagePromptPrefixItem),
                imagePromptPrefixScenery: toStringValue(raw.imagePromptPrefixScenery),
                imagePromptInstructionsCharacter: toStringValue(raw.imagePromptInstructionsCharacter),
                imagePromptInstructionsLocation: toStringValue(raw.imagePromptInstructionsLocation),
                imagePromptInstructionsItem: toStringValue(raw.imagePromptInstructionsItem),
                imagePromptInstructionsScenery: toStringValue(raw.imagePromptInstructionsScenery),
                useGlobalImageGenerationSettings: toBoolean(raw.useGlobalImageGenerationSettings, true),
                useGlobalImageEditSettings: toBoolean(raw.useGlobalImageEditSettings, true),
                imageGenerationSettings: toJsonObject(raw.imageGenerationSettings, 'imageGenerationSettings'),
                imageEditSettings: toJsonObject(raw.imageEditSettings, 'imageEditSettings'),
                playerStartingLevel: toNumberString(raw.playerStartingLevel),
                defaultPlayerName: toStringValue(raw.defaultPlayerName),
                defaultPlayerDescription: toStringValue(raw.defaultPlayerDescription),
                defaultStartingLocation: toStringValue(raw.defaultStartingLocation),
                defaultStartMonth: toBoundedIntegerString(raw.defaultStartMonth, 'defaultStartMonth', 1),
                defaultStartDay: toBoundedIntegerString(raw.defaultStartDay, 'defaultStartDay', 1),
                defaultStartTime: toBoundedIntegerString(raw.defaultStartTime, 'defaultStartTime', 0, 23),
                defaultStartingCurrency: toNumberString(raw.defaultStartingCurrency),
                defaultExistingSkills: toStringArray(raw.defaultExistingSkills),
                hidingAttribute: toStringValue(raw.hidingAttribute),
                hidingSkill: toStringValue(raw.hidingSkill),
                perceptionAttribute: toStringValue(raw.perceptionAttribute),
                perceptionSkill: toStringValue(raw.perceptionSkill),
                defaultFactionCount: toNumberString(raw.defaultFactionCount),
                defaultFactions: toFactionArray(raw.defaultFactions),
                calendarDefinition: toNullableCalendarDefinition(raw.calendarDefinition),
                unifiedTonalScale: normalizeUnifiedTonalScaleSelections(raw.unifiedTonalScale),
                availableClasses: toStringArray(raw.availableClasses),
                availableRaces: toStringArray(raw.availableRaces),
                customSlopWords: toStringArray(raw.customSlopWords)
            };
        }

        function sanitizeXmlForDom(input) {
            return (`<root>${input}</root>`)
                .replace(/&(?![#a-zA-Z0-9]+;)/g, '&amp;')
                .replace(/<\s*br\s*>/gi, '<br/>')
                .replace(/<\s*hr\s*>/gi, '<hr/>');
        }

        function parseSettingXmlResponse(xmlContent) {
            if (!xmlContent || typeof xmlContent !== 'string') {
                throw new Error('AI response was empty');
            }

            const trimmed = xmlContent.trim();
            if (!trimmed) {
                throw new Error('AI response was empty');
            }

            const wrapped = sanitizeXmlForDom(trimmed);
            const doc = Utils.parseXmlDocument(wrapped, 'text/xml');
            const parserError = doc.getElementsByTagName('parsererror')[0];
            if (parserError) {
                throw new Error(`AI response XML parsing error: ${parserError.textContent}`);
            }

            const settingNode = doc.getElementsByTagName('setting')[0];
            if (!settingNode) {
                throw new Error('AI response missing <setting> element');
            }

            const getText = (tag) => {
                const node = settingNode.getElementsByTagName(tag)[0];
                if (!node || typeof node.textContent !== 'string') {
                    return '';
                }
                return node.textContent.trim();
            };

            const getList = (parentTag, childTag) => {
                const parent = settingNode.getElementsByTagName(parentTag)[0];
                if (!parent) {
                    return [];
                }
                return Array.from(parent.getElementsByTagName(childTag))
                    .map(node => (typeof node.textContent === 'string' ? node.textContent.trim() : ''))
                    .filter(text => text.length > 0);
            };

            const toNumber = (value) => {
                const parsed = parseInt(value, 10);
                return Number.isFinite(parsed) ? parsed : '';
            };

            const parseFactionEntry = (node) => {
                if (!node) {
                    return null;
                }
                const getChildText = (tagName) => {
                    const child = node.getElementsByTagName(tagName)[0];
                    if (!child || typeof child.textContent !== 'string') {
                        return '';
                    }
                    return child.textContent.trim();
                };
                const id = getChildText('id');
                const name = getChildText('name');
                if (!name) {
                    return null;
                }
                const shortDescription = getChildText('shortDescription');
                const description = getChildText('description');
                const homeRegionName = getChildText('homeRegionName');
                const tagsParent = node.getElementsByTagName('tags')[0];
                const goalsParent = node.getElementsByTagName('goals')[0];
                const relationsParent = node.getElementsByTagName('relations')[0];
                const assetsParent = node.getElementsByTagName('assets')[0];
                const reputationTiersParent = node.getElementsByTagName('reputationTiers')[0];

                const tags = tagsParent
                    ? Array.from(tagsParent.getElementsByTagName('tag'))
                        .map(tagNode => (typeof tagNode?.textContent === 'string' ? tagNode.textContent.trim() : ''))
                        .filter(Boolean)
                    : [];
                const goals = goalsParent
                    ? Array.from(goalsParent.getElementsByTagName('goal'))
                        .map(goalNode => (typeof goalNode?.textContent === 'string' ? goalNode.textContent.trim() : ''))
                        .filter(Boolean)
                    : [];

                const assets = assetsParent
                    ? Array.from(assetsParent.getElementsByTagName('asset'))
                        .map(assetNode => {
                            const assetName = assetNode.getElementsByTagName('name')[0]?.textContent?.trim() || '';
                            if (!assetName) {
                                return null;
                            }
                            const assetType = assetNode.getElementsByTagName('type')[0]?.textContent?.trim() || '';
                            const assetDescription = assetNode.getElementsByTagName('description')[0]?.textContent?.trim() || '';
                            return {
                                name: assetName,
                                type: assetType,
                                description: assetDescription
                            };
                        })
                        .filter(Boolean)
                    : [];

                const relations = {};
                if (relationsParent) {
                    const relationNodes = Array.from(relationsParent.getElementsByTagName('relation'));
                    relationNodes.forEach(relationNode => {
                        const factionId = relationNode.getElementsByTagName('factionId')[0]?.textContent?.trim() || '';
                        const status = relationNode.getElementsByTagName('status')[0]?.textContent?.trim() || '';
                        const notes = relationNode.getElementsByTagName('notes')[0]?.textContent?.trim() || '';
                        if (!factionId || !status || !notes) {
                            return;
                        }
                        relations[factionId] = { status, notes };
                    });
                }

                const reputationTiers = reputationTiersParent
                    ? Array.from(reputationTiersParent.getElementsByTagName('tier'))
                        .map(tierNode => {
                            const threshold = Number(tierNode.getElementsByTagName('threshold')[0]?.textContent?.trim() || '');
                            if (!Number.isFinite(threshold)) {
                                return null;
                            }
                            const label = tierNode.getElementsByTagName('label')[0]?.textContent?.trim() || '';
                            const perksParent = tierNode.getElementsByTagName('perks')[0];
                            const penaltiesParent = tierNode.getElementsByTagName('penalties')[0];
                            const perks = perksParent
                                ? Array.from(perksParent.getElementsByTagName('perk'))
                                    .map(perkNode => (typeof perkNode?.textContent === 'string' ? perkNode.textContent.trim() : ''))
                                    .filter(Boolean)
                                : [];
                            const penalties = penaltiesParent
                                ? Array.from(penaltiesParent.getElementsByTagName('penalty'))
                                    .map(penaltyNode => (typeof penaltyNode?.textContent === 'string' ? penaltyNode.textContent.trim() : ''))
                                    .filter(Boolean)
                                : [];
                            return { threshold, label, perks, penalties };
                        })
                        .filter(Boolean)
                    : [];

                return {
                    id,
                    name,
                    shortDescription: shortDescription || null,
                    description: description || null,
                    homeRegionName: homeRegionName || null,
                    tags,
                    goals,
                    assets,
                    relations,
                    reputationTiers
                };
            };

            const getFactionList = () => {
                const parent = settingNode.getElementsByTagName('defaultFactions')[0];
                if (!parent) {
                    return [];
                }
                return Array.from(parent.getElementsByTagName('faction'))
                    .map(node => parseFactionEntry(node))
                    .filter(Boolean);
            };

            return {
                name: getText('name'),
                description: getText('description'),
                theme: getText('theme'),
                genre: getText('genre'),
                startingLocationType: getText('startingLocationType'),
                magicLevel: getText('magicLevel'),
                techLevel: getText('techLevel'),
                tone: getText('tone'),
                difficulty: getText('difficulty'),
                currencyName: getText('currencyName'),
                currencyNamePlural: getText('currencyNamePlural'),
                currencyValueNotes: getText('currencyValueNotes'),
                writingStyleNotes: getText('writingStyleNotes') || getText('styleNotes'),
                baseContextPreamble: getText('baseContextPreamble'),
                characterGenInstructions: getText('characterGenInstructions'),
                imagePromptPrefixCharacter: getText('imagePromptPrefixCharacter'),
                imagePromptPrefixLocation: getText('imagePromptPrefixLocation'),
                imagePromptPrefixItem: getText('imagePromptPrefixItem'),
                imagePromptPrefixScenery: getText('imagePromptPrefixScenery'),
                playerStartingLevel: toNumber(getText('playerStartingLevel')),
                defaultPlayerName: getText('defaultPlayerName'),
                defaultPlayerDescription: getText('defaultPlayerDescription'),
                defaultStartingLocation: getText('defaultStartingLocation'),
                defaultStartingCurrency: toNumber(getText('defaultStartingCurrency')),
                defaultExistingSkills: getList('defaultExistingSkills', 'skill'),
                hidingAttribute: getText('hidingAttribute'),
                hidingSkill: getText('hidingSkill'),
                perceptionAttribute: getText('perceptionAttribute'),
                perceptionSkill: getText('perceptionSkill'),
                defaultFactionCount: toNumber(getText('defaultFactionCount')),
                defaultFactions: getFactionList(),
                availableClasses: getList('availableClasses', 'class'),
                availableRaces: getList('availableRaces', 'race'),
                customSlopWords: getList('customSlopWords', 'word')
            };
        }

        function isEmptySettingValue(value) {
            if (value === null || value === undefined) {
                return true;
            }
            if (typeof value === 'string') {
                return value.trim().length === 0;
            }
            if (Array.isArray(value)) {
                return value.length === 0;
            }
            return false;
        }

        function mergeSettingValues(baseSetting, generatedSetting) {
            const merged = { ...baseSetting };
            for (const [key, value] of Object.entries(generatedSetting)) {
                if (value === undefined || value === null) {
                    continue;
                }
                if (isEmptySettingValue(merged[key]) && !isEmptySettingValue(value)) {
                    merged[key] = value;
                }
            }
            return merged;
        }

        function mergeAdditionalSkills(baseSkills, generatedSkills) {
            const normalizeList = (value) => {
                if (Array.isArray(value)) {
                    return value;
                }
                if (typeof value === 'string') {
                    return value.split(/\r?\n/);
                }
                return [];
            };

            const uniqueNormalized = (list) => {
                const result = [];
                const seen = new Set();
                for (const entry of list) {
                    if (typeof entry !== 'string') {
                        continue;
                    }
                    const trimmed = entry.trim();
                    if (!trimmed) {
                        continue;
                    }
                    const key = trimmed.toLowerCase();
                    if (seen.has(key)) {
                        continue;
                    }
                    seen.add(key);
                    result.push(trimmed);
                }
                return result;
            };

            const baseNormalized = uniqueNormalized(normalizeList(baseSkills));
            const baseKeys = new Set(baseNormalized.map(skill => skill.toLowerCase()));
            const additionsNormalized = uniqueNormalized(normalizeList(generatedSkills));
            const extras = additionsNormalized.filter(skill => !baseKeys.has(skill.toLowerCase()));

            return [...baseNormalized, ...extras];
        }

        function sanitizeForAbilityXml(value) {
            if (value === null || value === undefined) {
                return '';
            }
            return String(value)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&apos;');
        }

        function buildAbilityContextForPlayer(player, { settingDescription = '', location = null, region = null } = {}) {
            if (!player || typeof player.getSkills !== 'function') {
                return null;
            }

            const lines = [];
            lines.push('<npcs>');
            lines.push('  <npc>');
            lines.push(`    <name>${sanitizeForAbilityXml(player.name || 'Unnamed Hero')}</name>`);
            lines.push(`    <description>${sanitizeForAbilityXml(player.description || '')}</description>`);
            lines.push(`    <class>${sanitizeForAbilityXml(player.class || '')}</class>`);
            lines.push(`    <race>${sanitizeForAbilityXml(player.race || '')}</race>`);
            lines.push(`    <level>${sanitizeForAbilityXml(player.level || 1)}</level>`);

            if (settingDescription) {
                lines.push(`    <setting>${sanitizeForAbilityXml(settingDescription)}</setting>`);
            }
            if (region && (region.name || region.description)) {
                lines.push(`    <regionContext>${sanitizeForAbilityXml((region.name ? `${region.name}: ` : '') + (region.description || ''))}</regionContext>`);
            }
            if (location && (location.name || location.description)) {
                lines.push(`    <locationContext>${sanitizeForAbilityXml((location.name ? `${location.name}: ` : '') + (location.description || ''))}</locationContext>`);
            }

            const skillsMap = player.getSkills();
            lines.push('    <skills>');
            if (skillsMap && typeof skillsMap.forEach === 'function') {
                skillsMap.forEach((value, key) => {
                    lines.push(`      <skill><name>${sanitizeForAbilityXml(key)}</name><rank>${sanitizeForAbilityXml(value)}</rank></skill>`);
                });
            }
            lines.push('    </skills>');
            lines.push('  </npc>');
            lines.push('</npcs>');

            return lines.join('\n');
        }

        app.post('/api/settings/fill-missing', async (req, res) => {
            try {
                const incomingSetting = req.body?.setting;
                if (!incomingSetting || typeof incomingSetting !== 'object') {
                    return res.status(400).json({
                        success: false,
                        error: 'Request body must include a setting object'
                    });
                }

                const shouldAugmentDefaultSkills = Boolean(req.body?.augmentDefaultSkills);
                const additionalInstructions = typeof req.body?.instructions === 'string'
                    ? req.body.instructions.trim()
                    : '';
                const imageDataUrl = typeof req.body?.imageDataUrl === 'string'
                    ? req.body.imageDataUrl.trim()
                    : '';
                if (imageDataUrl && !/^data:image\/[a-z0-9.+-]+;base64,/i.test(imageDataUrl)) {
                    return res.status(400).json({
                        success: false,
                        error: 'Autofill image must be a base64-encoded data URL.'
                    });
                }

                const normalizedSetting = normalizeSettingPayload(incomingSetting);

                const renderedTemplate = promptEnv.render('fill-setting-form.xml.njk', {
                    setting: {
                        ...normalizedSetting,
                        defaultExistingSkills: normalizedSetting.defaultExistingSkills,
                        availableClasses: normalizedSetting.availableClasses,
                        availableRaces: normalizedSetting.availableRaces,
                        customSlopWords: normalizedSetting.customSlopWords
                    },
                    attributeOptions: buildSettingMechanicAttributeOptions(),
                    additionalInstructions,
                    hasImage: Boolean(imageDataUrl)
                });

                const promptData = parseXMLTemplate(renderedTemplate);
                const systemPrompt = promptData.systemPrompt ? promptData.systemPrompt.trim() : '';
                const generationPrompt = promptData.generationPrompt ? promptData.generationPrompt.trim() : '';

                if (!generationPrompt) {
                    return res.status(500).json({
                        success: false,
                        error: 'Failed to build generation prompt from template'
                    });
                }

                const messages = [];
                if (systemPrompt) {
                    messages.push({ role: 'system', content: systemPrompt });
                }
                const userContent = imageDataUrl
                    ? [
                        { type: 'text', text: `${generationPrompt}\n\nUse the attached image as additional visual context when filling in missing fields.` },
                        { type: 'image_url', image_url: { url: imageDataUrl } }
                    ]
                    : generationPrompt;
                messages.push({ role: 'user', content: userContent });

                if (!config?.ai) {
                    return res.status(500).json({
                        success: false,
                        error: 'AI configuration is incomplete. Please update config.yaml.'
                    });
                }

                const requestOptions = {
                    messages,
                    metadataLabel: 'setting_autofill',
                    expectedXmlRootTag: 'setting',
                    multimodal: Boolean(imageDataUrl)
                };

                if (typeof promptData.temperature === 'number') {
                    requestOptions.temperature = promptData.temperature;
                } else {
                    const configTemperature = Number(config.ai.temperature);
                    if (Number.isInteger(configTemperature)) {
                        requestOptions.temperature = configTemperature;
                    }
                }

                const aiMessage = await LLMClient.chatCompletion(requestOptions);
                if (!aiMessage || typeof aiMessage !== 'string') {
                    throw new Error('AI did not return a usable response');
                }

                LLMClient.logPrompt({
                    prefix: requestOptions.metadataLabel,
                    metadataLabel: requestOptions.metadataLabel,
                    systemPrompt: systemPrompt || '',
                    generationPrompt: generationPrompt || '',
                    response: aiMessage || ''
                });

                const generatedSetting = parseSettingXmlResponse(aiMessage);
                const mergedSetting = mergeSettingValues(normalizedSetting, generatedSetting);
                if (shouldAugmentDefaultSkills) {
                    mergedSetting.defaultExistingSkills = mergeAdditionalSkills(
                        normalizedSetting.defaultExistingSkills,
                        generatedSetting.defaultExistingSkills
                    );
                }

                res.json({
                    success: true,
                    setting: mergedSetting,
                    raw: aiMessage
                });
            } catch (error) {
                console.error('Failed to fill setting form:', error);
                res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to generate setting details'
                });
            }
        });

        app.get('/api/settings/calendar/default', (req, res) => {
            try {
                const settingName = typeof req.query?.settingName === 'string' && req.query.settingName.trim()
                    ? req.query.settingName.trim()
                    : null;
                const calendarDefinition = Globals.generateCalendarDefinition({ settingName });
                res.json({
                    success: true,
                    calendarDefinition
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to build default calendar'
                });
            }
        });

        app.post('/api/settings/calendar/generate', async (req, res) => {
            try {
                const incomingSetting = req.body?.setting;
                if (!incomingSetting || typeof incomingSetting !== 'object' || Array.isArray(incomingSetting)) {
                    return res.status(400).json({
                        success: false,
                        error: 'Request body must include a setting object'
                    });
                }

                const settingSnapshot = normalizeSettingPayload({
                    ...incomingSetting,
                    calendarDefinition: null
                });
                const generatedCalendarDefinition = await generateCalendarDefinitionWithAi({ settingSnapshot });
                const { calendarDefinition } = await ensureCalendarSeasonImageDescriptions({
                    calendarDefinition: generatedCalendarDefinition,
                    settingSnapshot
                });
                res.json({
                    success: true,
                    calendarDefinition
                });
            } catch (error) {
                console.error('Failed to generate setting calendar:', error);
                res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to generate setting calendar'
                });
            }
        });
	
        // Get current applied setting
        app.get('/api/settings/current', (req, res) => {
            try {
                if (!currentSetting) {
                    console.log('Current setting requested: none');
                    return res.json({
                        success: true,
                        setting: null,
                        message: 'No setting currently applied'
                    });
                }

                //console.log('Current setting details:', currentSetting.toJSON());
                res.json({
                    success: true,
                    setting: currentSetting.toJSON(),
                    promptVariables: currentSetting.getPromptVariables()
                });
            } catch (error) {
                console.log('Failed to get current setting:', error);
                console.debug(error);
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Get a specific setting by ID
        app.get('/api/settings/:id', (req, res) => {
            try {
                const { id } = req.params;
                const setting = SettingInfo.getById(id);

                if (!setting) {
                    return res.status(404).json({
                        success: false,
                        error: 'Setting not found'
                    });
                }

                res.json({
                    success: true,
                    setting: setting.toJSON()
                });
            } catch (error) {
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Update a setting
        app.put('/api/settings/:id', (req, res) => {
            try {
                const { id } = req.params;
                const updates = req.body;
                const setting = SettingInfo.getById(id);

                if (!setting) {
                    const fallbackName = (updates && typeof updates.name === 'string' && updates.name.trim())
                        ? updates.name.trim()
                        : `Setting ${id}`;

                    if (SettingInfo.getByName(fallbackName)) {
                        return res.status(404).json({
                            success: false,
                            error: 'Setting not found, and a new setting with the provided name already exists.'
                        });
                    }

                    const newSetting = new SettingInfo({
                        ...updates,
                        id,
                        name: fallbackName
                    });

                    return res.status(201).json({
                        success: true,
                        setting: newSetting.toJSON(),
                        created: true,
                        message: 'Setting not found. Created a new setting instead.'
                    });
                }

                const requestedName = typeof updates?.name === 'string' ? updates.name.trim() : '';
                const isRenameRequest = requestedName.length > 0 && requestedName !== setting.name;
                if (isRenameRequest) {
                    const existingSetting = SettingInfo.getByName(requestedName);
                    if (existingSetting) {
                        return res.status(409).json({
                            success: false,
                            error: 'Setting with this name already exists'
                        });
                    }

                    const sourceData = setting.toJSON();
                    delete sourceData.id;
                    delete sourceData.createdAt;
                    delete sourceData.lastUpdated;
                    const createdSetting = new SettingInfo({
                        ...sourceData,
                        ...updates,
                        name: requestedName
                    });

                    return res.status(201).json({
                        success: true,
                        setting: createdSetting.toJSON(),
                        created: true,
                        clonedFromId: setting.id,
                        message: 'Setting name changed. Created a new setting with a new id.'
                    });
                }

                if (updates.name && updates.name !== setting.name) {
                    const existingSetting = SettingInfo.getByName(updates.name);
                    if (existingSetting && existingSetting.id !== id) {
                        return res.status(409).json({
                            success: false,
                            error: 'Setting with this name already exists'
                        });
                    }
                }

                setting.update(updates);

                res.json({
                    success: true,
                    setting: setting.toJSON(),
                    message: 'Setting updated successfully'
                });
            } catch (error) {
                res.status(400).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Delete a setting
