        // ==================== NEW GAME FUNCTIONALITY ====================

        function parseCalendarDefinitionXml(xmlContent) {
            if (!xmlContent || typeof xmlContent !== 'string' || !xmlContent.trim()) {
                throw new Error('Calendar generation response was empty.');
            }

            const trimmed = xmlContent.trim();
            const snippetMatch = trimmed.match(/<calendarDefinition[\s\S]*<\/calendarDefinition>/i);
            const xmlSnippet = snippetMatch ? snippetMatch[0] : trimmed;
            const normalizedSnippet = xmlSnippet.replace(/^\s*<\?xml[\s\S]*?\?>\s*/i, '');
            const wrapped = sanitizeXmlForDom(normalizedSnippet);
            const doc = Utils.parseXmlDocument(wrapped, 'text/xml');
            const parserError = doc.getElementsByTagName('parsererror')[0];
            if (parserError) {
                throw new Error(`Calendar XML parsing error: ${parserError.textContent || 'unknown parser error'}`);
            }

            const calendarNode = doc.getElementsByTagName('calendarDefinition')[0];
            if (!calendarNode) {
                throw new Error('Calendar XML missing <calendarDefinition> root element.');
            }

            const getDirectChild = (parent, tagName) => {
                if (!parent) {
                    return null;
                }
                const children = Array.from(parent.childNodes || []);
                return children.find(node =>
                    node
                    && node.nodeType === 1
                    && node.tagName
                    && node.tagName.toLowerCase() === tagName.toLowerCase()
                ) || null;
            };

            const getText = (parent, tagName) => {
                const node = getDirectChild(parent, tagName);
                if (!node || typeof node.textContent !== 'string') {
                    return '';
                }
                return node.textContent.trim();
            };

            const parseIntegerText = (value, fieldName) => {
                const parsed = Number.parseInt(String(value || '').trim(), 10);
                if (!Number.isFinite(parsed)) {
                    throw new Error(`Calendar XML field ${fieldName} must be a finite integer.`);
                }
                return parsed;
            };

            const parseNumberText = (value, fieldName) => {
                const parsed = Number(String(value || '').trim());
                if (!Number.isFinite(parsed)) {
                    throw new Error(`Calendar XML field ${fieldName} must be a finite number.`);
                }
                return parsed;
            };

            const monthsNode = getDirectChild(calendarNode, 'months');
            if (!monthsNode) {
                throw new Error('Calendar XML missing <months>.');
            }
            const monthNodes = Array.from(monthsNode.childNodes || []).filter(node =>
                node
                && node.nodeType === 1
                && node.tagName
                && node.tagName.toLowerCase() === 'month'
            );
            if (!monthNodes.length) {
                throw new Error('Calendar XML must define at least one <month>.');
            }
            const months = monthNodes.map((monthNode, index) => {
                const name = getText(monthNode, 'name');
                if (!name) {
                    throw new Error(`Calendar month #${index + 1} is missing <name>.`);
                }
                const lengthDays = parseIntegerText(getText(monthNode, 'lengthDays'), `months.month[${index + 1}].lengthDays`);
                const seasonName = getText(monthNode, 'seasonName');
                return {
                    name,
                    lengthDays,
                    seasonName: seasonName || null
                };
            });

            const weekdaysNode = getDirectChild(calendarNode, 'weekdays');
            if (!weekdaysNode) {
                throw new Error('Calendar XML missing <weekdays>.');
            }
            const weekdays = Array.from(weekdaysNode.childNodes || [])
                .filter(node =>
                    node
                    && node.nodeType === 1
                    && node.tagName
                    && node.tagName.toLowerCase() === 'weekday'
                )
                .map(node => (typeof node.textContent === 'string' ? node.textContent.trim() : ''))
                .filter(Boolean);
            if (!weekdays.length) {
                throw new Error('Calendar XML must define at least one <weekday>.');
            }

            const seasonsNode = getDirectChild(calendarNode, 'seasons');
            const seasons = seasonsNode
                ? Array.from(seasonsNode.childNodes || [])
                    .filter(node =>
                        node
                        && node.nodeType === 1
                        && node.tagName
                        && node.tagName.toLowerCase() === 'season'
                    )
                    .map((seasonNode, index) => {
                        const name = getText(seasonNode, 'name');
                        if (!name) {
                            throw new Error(`Calendar season #${index + 1} is missing <name>.`);
                        }
                        const description = getText(seasonNode, 'description') || null;
                        const vegetationDescription = getText(seasonNode, 'vegetationDescription') || null;
                        const interiorDescription = getText(seasonNode, 'interiorDescription') || null;
                        const startMonth = getText(seasonNode, 'startMonth') || null;
                        const startDayText = getText(seasonNode, 'startDay');
                        const dayLengthMinutesText = getText(seasonNode, 'dayLengthMinutes');
                        const startDay = startDayText ? parseIntegerText(startDayText, `seasons.season[${index + 1}].startDay`) : 1;
                        const dayLengthMinutes = dayLengthMinutesText
                            ? parseIntegerText(dayLengthMinutesText, `seasons.season[${index + 1}].dayLengthMinutes`)
                            : null;
                        const timeDescriptionsNode = getDirectChild(seasonNode, 'timeDescriptions');
                        const timeDescriptions = timeDescriptionsNode
                            ? Array.from(timeDescriptionsNode.childNodes || [])
                                .filter(node =>
                                    node
                                    && node.nodeType === 1
                                    && node.tagName
                                    && node.tagName.toLowerCase() === 'timedescription'
                                )
                                .map((timeDescriptionNode, tdIndex) => {
                                    const timeOfDayText = getText(timeDescriptionNode, 'timeOfDay');
                                    const descriptionText = getText(timeDescriptionNode, 'description');
                                    if (!timeOfDayText) {
                                        throw new Error(`Calendar season #${index + 1} timeDescription #${tdIndex + 1} is missing <timeOfDay>.`);
                                    }
                                    if (!descriptionText) {
                                        throw new Error(`Calendar season #${index + 1} timeDescription #${tdIndex + 1} is missing <description>.`);
                                    }
                                    return {
                                        timeOfDay: parseNumberText(timeOfDayText, `seasons.season[${index + 1}].timeDescriptions.timeDescription[${tdIndex + 1}].timeOfDay`),
                                        description: descriptionText
                                    };
                                })
                            : [];
                        return {
                            name,
                            description,
                            vegetationDescription,
                            interiorDescription,
                            startMonth,
                            startDay,
                            dayLengthMinutes,
                            timeDescriptions
                        };
                    })
                : [];

            const holidaysNode = getDirectChild(calendarNode, 'holidays');
            const holidays = holidaysNode
                ? Array.from(holidaysNode.childNodes || [])
                    .filter(node =>
                        node
                        && node.nodeType === 1
                        && node.tagName
                        && node.tagName.toLowerCase() === 'holiday'
                    )
                    .map((holidayNode, index) => {
                        const name = getText(holidayNode, 'name');
                        if (!name) {
                            throw new Error(`Calendar holiday #${index + 1} is missing <name>.`);
                        }
                        const description = getText(holidayNode, 'description') || null;
                        const month = getText(holidayNode, 'month') || null;
                        const dayText = getText(holidayNode, 'day');
                        const day = dayText ? parseIntegerText(dayText, `holidays.holiday[${index + 1}].day`) : null;
                        return {
                            name,
                            description,
                            month,
                            day
                        };
                    })
                : [];

            return {
                yearName: getText(calendarNode, 'yearName') || 'Common Era',
                months,
                weekdays,
                seasons,
                holidays
            };
        }

        function parseSeasonImageDescriptionsXml(xmlContent, expectedSeasons) {
            if (!xmlContent || typeof xmlContent !== 'string' || !xmlContent.trim()) {
                throw new Error('Season image description response was empty.');
            }
            if (!Array.isArray(expectedSeasons) || !expectedSeasons.length) {
                throw new Error('Season image description parsing requires at least one expected season.');
            }

            const expectedByKey = new Map();
            for (const season of expectedSeasons) {
                const name = typeof season?.name === 'string' ? season.name.trim() : '';
                if (!name) {
                    throw new Error('Season image description parsing received a season without a name.');
                }
                const key = name.toLocaleLowerCase();
                if (expectedByKey.has(key)) {
                    throw new Error(`Season image description parsing received duplicate expected season "${name}".`);
                }
                expectedByKey.set(key, name);
            }

            const trimmed = xmlContent.trim();
            const snippetMatch = trimmed.match(/<seasonImageDescriptions[\s\S]*<\/seasonImageDescriptions>/i);
            const xmlSnippet = snippetMatch ? snippetMatch[0] : trimmed;
            const doc = Utils.parseXmlDocument(sanitizeXmlForDom(xmlSnippet), 'text/xml');
            const parserError = doc.getElementsByTagName('parsererror')[0];
            if (parserError) {
                throw new Error(`Season image XML parsing error: ${parserError.textContent || 'unknown parser error'}`);
            }

            const root = doc.getElementsByTagName('seasonImageDescriptions')[0];
            if (!root) {
                throw new Error('Season image XML missing <seasonImageDescriptions> root element.');
            }
            const directChild = (parent, tagName) => Array.from(parent?.childNodes || []).find(node => (
                node
                && node.nodeType === 1
                && node.tagName
                && node.tagName.toLowerCase() === tagName.toLowerCase()
            )) || null;
            const getText = (parent, tagName) => {
                const node = directChild(parent, tagName);
                return typeof node?.textContent === 'string' ? node.textContent.trim() : '';
            };
            const seasonNodes = Array.from(root.childNodes || []).filter(node => (
                node
                && node.nodeType === 1
                && node.tagName
                && node.tagName.toLowerCase() === 'season'
            ));
            const descriptions = new Map();
            for (const seasonNode of seasonNodes) {
                const suppliedName = getText(seasonNode, 'name');
                const key = suppliedName.toLocaleLowerCase();
                const expectedName = expectedByKey.get(key);
                if (!expectedName) {
                    throw new Error(`Season image XML returned unknown season "${suppliedName || '(missing name)'}".`);
                }
                if (descriptions.has(key)) {
                    throw new Error(`Season image XML returned duplicate season "${expectedName}".`);
                }
                const vegetationDescription = getText(seasonNode, 'vegetationDescription');
                if (!vegetationDescription) {
                    throw new Error(`Season image XML season "${expectedName}" is missing <vegetationDescription>.`);
                }
                const interiorDescription = getText(seasonNode, 'interiorDescription');
                if (!interiorDescription) {
                    throw new Error(`Season image XML season "${expectedName}" is missing <interiorDescription>.`);
                }
                descriptions.set(key, { vegetationDescription, interiorDescription });
            }
            if (descriptions.size !== expectedByKey.size) {
                const missing = Array.from(expectedByKey.entries())
                    .filter(([key]) => !descriptions.has(key))
                    .map(([, name]) => name);
                throw new Error(`Season image XML is missing description(s) for: ${missing.join(', ')}.`);
            }
            return descriptions;
        }

        function buildCalendarSettingContext(settingSnapshot = null) {
            const settingDescription = describeSettingForPrompt(settingSnapshot);
            return {
                name: typeof settingSnapshot?.name === 'string' ? settingSnapshot.name : '',
                description: settingDescription,
                theme: typeof settingSnapshot?.theme === 'string' ? settingSnapshot.theme : '',
                genre: typeof settingSnapshot?.genre === 'string' ? settingSnapshot.genre : '',
                tone: typeof settingSnapshot?.tone === 'string' ? settingSnapshot.tone : '',
                magicLevel: typeof settingSnapshot?.magicLevel === 'string' ? settingSnapshot.magicLevel : '',
                techLevel: typeof settingSnapshot?.techLevel === 'string' ? settingSnapshot.techLevel : '',
                startingLocationType: typeof settingSnapshot?.startingLocationType === 'string'
                    ? settingSnapshot.startingLocationType
                    : ''
            };
        }

        async function ensureCalendarSeasonImageDescriptions({ calendarDefinition, settingSnapshot = null } = {}) {
            const normalizedCalendar = Globals.normalizeCalendarDefinition(calendarDefinition);
            const missingSeasons = normalizedCalendar.seasons.filter((season) => (
                typeof season?.vegetationDescription !== 'string' || !season.vegetationDescription.trim()
                || typeof season?.interiorDescription !== 'string' || !season.interiorDescription.trim()
            ));
            if (!missingSeasons.length) {
                return { calendarDefinition: normalizedCalendar, updated: false };
            }

            const renderedTemplate = promptEnv.render('season-image-descriptions.xml.njk', {
                setting: buildCalendarSettingContext(settingSnapshot),
                seasons: missingSeasons.map(season => ({
                    name: season.name,
                    description: season.description || ''
                }))
            });
            const parsedTemplate = parseXMLTemplate(renderedTemplate);
            const systemPrompt = typeof parsedTemplate.systemPrompt === 'string'
                ? parsedTemplate.systemPrompt.trim()
                : '';
            const generationPrompt = typeof parsedTemplate.generationPrompt === 'string'
                ? parsedTemplate.generationPrompt.trim()
                : '';
            if (!systemPrompt || !generationPrompt) {
                throw new Error('Season image description prompt template did not produce system/generation prompts.');
            }

            const requestOptions = {
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: generationPrompt }
                ],
                metadataLabel: 'season_image_descriptions',
                expectedXmlRootTag: 'seasonImageDescriptions'
            };
            if (typeof parsedTemplate.temperature === 'number') {
                requestOptions.temperature = parsedTemplate.temperature;
            }
            const responseText = await LLMClient.chatCompletion(requestOptions);
            LLMClient.logPrompt({
                metadataLabel: 'season_image_descriptions',
                systemPrompt,
                generationPrompt,
                response: responseText,
                model: requestOptions.model,
                endpoint: requestOptions.endpoint
            });

            const descriptions = parseSeasonImageDescriptionsXml(responseText, missingSeasons);
            const seasons = normalizedCalendar.seasons.map((season) => {
                const generated = descriptions.get(season.name.toLocaleLowerCase());
                if (!generated) {
                    return season;
                }
                const vegetationDescription = typeof season.vegetationDescription === 'string' && season.vegetationDescription.trim()
                    ? season.vegetationDescription
                    : generated.vegetationDescription;
                const interiorDescription = typeof season.interiorDescription === 'string' && season.interiorDescription.trim()
                    ? season.interiorDescription
                    : generated.interiorDescription;
                return { ...season, vegetationDescription, interiorDescription };
            });
            return {
                calendarDefinition: Globals.normalizeCalendarDefinition({ ...normalizedCalendar, seasons }),
                updated: true
            };
        }

        async function generateCalendarDefinitionWithAi({ settingSnapshot = null } = {}) {
            const renderedTemplate = promptEnv.render('calendar-generator.xml.njk', {
                setting: buildCalendarSettingContext(settingSnapshot)
            });
            const parsedTemplate = parseXMLTemplate(renderedTemplate);
            const systemPrompt = typeof parsedTemplate.systemPrompt === 'string'
                ? parsedTemplate.systemPrompt.trim()
                : '';
            const generationPrompt = typeof parsedTemplate.generationPrompt === 'string'
                ? parsedTemplate.generationPrompt.trim()
                : '';

            if (!systemPrompt || !generationPrompt) {
                throw new Error('Calendar generation prompt template did not produce system/generation prompts.');
            }

            const requestOptions = {
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: generationPrompt }
                ],
                metadataLabel: 'calendar_generation',
                expectedXmlRootTag: 'calendarDefinition'
            };
            if (typeof parsedTemplate.temperature === 'number') {
                requestOptions.temperature = parsedTemplate.temperature;
            }

            const responseText = await LLMClient.chatCompletion(requestOptions);
            LLMClient.logPrompt({
                metadataLabel: 'calendar_generation',
                systemPrompt,
                generationPrompt,
                response: responseText,
                model: requestOptions.model,
                endpoint: requestOptions.endpoint
            });

            return parseCalendarDefinitionXml(responseText);
        }

        async function resolveCalendarDefinitionForSetting({ settingSnapshot = null, report = null } = {}) {
            if (settingSnapshot?.calendarDefinition !== null && settingSnapshot?.calendarDefinition !== undefined) {
                const ensured = await ensureCalendarSeasonImageDescriptions({
                    calendarDefinition: settingSnapshot.calendarDefinition,
                    settingSnapshot
                });
                return ensured.calendarDefinition;
            }

            const fallback = Globals.generateCalendarDefinition({
                settingName: settingSnapshot?.name || null
            });
            try {
                const generated = await generateCalendarDefinitionWithAi({ settingSnapshot });
                const ensured = await ensureCalendarSeasonImageDescriptions({
                    calendarDefinition: generated,
                    settingSnapshot
                });
                return ensured.calendarDefinition;
            } catch (error) {
                const message = error?.message || String(error);
                console.warn('Calendar generation failed; using Gregorian fallback:', message);
                if (typeof report === 'function') {
                    report('new_game:calendar_fallback', `Calendar generation failed (${message}). Using Gregorian fallback.`);
                }
                return fallback;
            }
        }

        // Create a new game with fresh player and starting location
        app.post('/api/new-game', async (req, res) => {
            const requestStart = Date.now();
            const body = req.body || {};
            const stream = createStreamEmitter({ clientId: body.clientId, requestId: body.requestId });
            const report = (stage, message, extra = {}) => {
                if (stream && stream.isEnabled) {
                    stream.status(stage, message, { scope: 'new_game', ...(extra || {}) });
                }
            };
            const reportError = (message) => {
                if (stream && stream.isEnabled) {
                    stream.status('new_game:error', message, { scope: 'new_game' });
                }
            };

            try {
                const {
                    playerName,
                    playerDescription,
                    playerClass: playerClassInput,
                    playerRace: playerRaceInput,
                    playerLevel: playerLevelInput,
                    startMonth: startMonthInput,
                    startDay: startDayInput,
                    startTime: startTimeInput,
                    startingLocation,
                    startingCurrency: startingCurrencyInput,
                    attributes: attributesInput,
                    skills: skillsInput
                } = body;
                const hasNumSkills = Object.prototype.hasOwnProperty.call(body, 'numSkills');
                const hasExistingSkills = Object.prototype.hasOwnProperty.call(body, 'existingSkills');
                if (hasNumSkills || hasExistingSkills) {
                    const disallowed = [];
                    if (hasNumSkills) disallowed.push('numSkills');
                    if (hasExistingSkills) disallowed.push('existingSkills');
                    const errorMessage = `New game requests no longer accept ${disallowed.join(', ')}. Configure skills in Game Settings instead.`;
                    reportError(errorMessage);
                    return res.status(400).json({
                        success: false,
                        error: errorMessage
                    });
                }
                if (Object.prototype.hasOwnProperty.call(body, 'unspentSkillPoints')
                    || Object.prototype.hasOwnProperty.call(body, 'unspentAttributePoints')) {
                    const errorMessage = 'New game requests cannot set unspent points directly; they are formula-derived from level/attributes/skills.';
                    reportError(errorMessage);
                    return res.status(400).json({
                        success: false,
                        error: errorMessage
                    });
                }
                if (typeof Globals.reloadConfigAndDefs !== 'function') {
                    throw new Error('Globals.reloadConfigAndDefs is not available during new game creation.');
                }
                Globals.reloadConfigAndDefs({
                    gameConfigOverrideYaml: '',
                    needBarSentenceValidationMode: 'throw'
                });
                const activeSetting = getActiveSettingSnapshot();
                if (!activeSetting) {
                    report('new_game:setting_missing', 'No active setting is loaded. Cannot start new game.');
                    return res.status(400).json({
                        success: false,
                        error: 'No active setting is loaded. Please apply a setting before starting a new game.'
                    });
                }
                const newGameDefaults = buildNewGameDefaults(activeSetting);
                const settingDescription = describeSettingForPrompt(activeSetting);
                const rawPlayerName = typeof playerName === 'string' ? playerName.trim() : '';
                const rawPlayerDescription = typeof playerDescription === 'string' ? playerDescription.trim() : '';
                const rawPlayerClass = typeof playerClassInput === 'string' ? playerClassInput.trim() : '';
                const rawPlayerRace = typeof playerRaceInput === 'string' ? playerRaceInput.trim() : '';
                const requestedStartingLocation = typeof startingLocation === 'string' ? startingLocation.trim() : '';
                const resolvedPlayerName = rawPlayerName || newGameDefaults.playerName || 'Adventurer';
                const resolvedPlayerDescription = rawPlayerDescription || newGameDefaults.playerDescription || 'A brave soul embarking on a new adventure.';
                const resolvedPlayerClass = rawPlayerClass || newGameDefaults.playerClass || 'Adventurer';
                const resolvedPlayerRace = rawPlayerRace || newGameDefaults.playerRace || 'Human';
                const resolvedStartingLocation = requestedStartingLocation || newGameDefaults.startingLocation;
                const hasRequestedStartTime = startTimeInput !== undefined
                    && startTimeInput !== null
                    && `${startTimeInput}`.trim() !== '';
                const parsedRequestedStartTime = Number(startTimeInput);
                if (hasRequestedStartTime) {
                    const isValidRequestedStartTime = Number.isFinite(parsedRequestedStartTime)
                        && Number.isInteger(parsedRequestedStartTime)
                        && parsedRequestedStartTime >= 0
                        && parsedRequestedStartTime <= 23;
                    if (!isValidRequestedStartTime) {
                        const errorMessage = 'startTime must be an integer hour between 0 and 23.';
                        reportError(errorMessage);
                        return res.status(400).json({
                            success: false,
                            error: errorMessage
                        });
                    }
                }
                const fallbackStartTime = Number(newGameDefaults.startTime);
                const resolvedStartTime = hasRequestedStartTime
                    ? parsedRequestedStartTime
                    : (Number.isFinite(fallbackStartTime) ? fallbackStartTime : 9);
                const hasRequestedStartMonth = startMonthInput !== undefined
                    && startMonthInput !== null
                    && `${startMonthInput}`.trim() !== '';
                const parsedRequestedStartMonth = Number(startMonthInput);
                if (hasRequestedStartMonth && (!Number.isInteger(parsedRequestedStartMonth) || parsedRequestedStartMonth < 1)) {
                    const errorMessage = 'startMonth must be a positive integer.';
                    reportError(errorMessage);
                    return res.status(400).json({
                        success: false,
                        error: errorMessage
                    });
                }
                const fallbackStartMonth = Number(newGameDefaults.startMonth);
                const resolvedStartMonth = hasRequestedStartMonth
                    ? parsedRequestedStartMonth
                    : (Number.isInteger(fallbackStartMonth) && fallbackStartMonth >= 1 ? fallbackStartMonth : 1);
                const hasRequestedStartDay = startDayInput !== undefined
                    && startDayInput !== null
                    && `${startDayInput}`.trim() !== '';
                const parsedRequestedStartDay = Number(startDayInput);
                if (hasRequestedStartDay && (!Number.isInteger(parsedRequestedStartDay) || parsedRequestedStartDay < 1)) {
                    const errorMessage = 'startDay must be a positive integer.';
                    reportError(errorMessage);
                    return res.status(400).json({
                        success: false,
                        error: errorMessage
                    });
                }
                const fallbackStartDay = Number(newGameDefaults.startDay);
                const resolvedStartDay = hasRequestedStartDay
                    ? parsedRequestedStartDay
                    : (Number.isInteger(fallbackStartDay) && fallbackStartDay >= 1 ? fallbackStartDay : 1);
                const parsedStartingCurrency = Number.parseInt(startingCurrencyInput, 10);
                const fallbackStartingCurrencySource = newGameDefaults.startingCurrency;
                const fallbackStartingCurrencyParsed = Number.parseInt(fallbackStartingCurrencySource, 10);
                const fallbackStartingCurrency = Number.isFinite(fallbackStartingCurrencyParsed)
                    ? Math.max(0, fallbackStartingCurrencyParsed)
                    : 0;
                const resolvedStartingCurrency = Number.isFinite(parsedStartingCurrency)
                    ? Math.max(0, parsedStartingCurrency)
                    : fallbackStartingCurrency;
                const parsedSettingLevel = Number(activeSetting?.playerStartingLevel);
                const settingLevel = Number.isFinite(parsedSettingLevel) ? parsedSettingLevel : 1;
                const parsedRequestedLevel = Number(playerLevelInput);
                const fallbackLevel = Number.isFinite(Number(newGameDefaults.playerLevel))
                    ? Number(newGameDefaults.playerLevel)
                    : settingLevel;
                const resolvedPlayerLevel = Number.isFinite(parsedRequestedLevel)
                    ? parsedRequestedLevel
                    : fallbackLevel;
                const startingLocationStyle = resolveLocationStyle(activeSetting?.startingLocationType || resolvedStartingLocation, activeSetting);
                const settingFactionDrafts = Array.isArray(newGameDefaults.factions)
                    ? newGameDefaults.factions.filter(entry => entry && typeof entry === 'object' && !Array.isArray(entry))
                    : [];
                const parsedSettingFactionCount = Number.parseInt(newGameDefaults.factionCount, 10);
                const parsedConfigFactionCount = Number.parseInt(config?.factions?.count, 10);
                let factionCount = Number.isFinite(parsedSettingFactionCount) && parsedSettingFactionCount >= 0
                    ? parsedSettingFactionCount
                    : null;
                if (factionCount === null && settingFactionDrafts.length > 0) {
                    factionCount = settingFactionDrafts.length;
                }
                if (factionCount === null && Number.isFinite(parsedConfigFactionCount) && parsedConfigFactionCount >= 0) {
                    factionCount = parsedConfigFactionCount;
                }
                if (factionCount === null) {
                    console.warn('config.factions.count missing or invalid; defaulting to 5.');
                    factionCount = 5;
                }

                report('new_game:start', 'Preparing your adventure...');
                report('new_game:calendar', 'Generating world calendar...');
                const calendarDefinition = await resolveCalendarDefinitionForSetting({
                    settingSnapshot: activeSetting,
                    report
                });
                let startingDayIndex = null;
                try {
                    startingDayIndex = Globals.getCalendarDayIndex({
                        monthNumber: resolvedStartMonth,
                        dayOfMonth: resolvedStartDay,
                        calendarDefinition
                    });
                } catch (error) {
                    const errorMessage = `Invalid starting date: ${error.message}`;
                    reportError(errorMessage);
                    return res.status(400).json({
                        success: false,
                        error: errorMessage
                    });
                }
                report('new_game:reset', 'Clearing previous game state...');

                // Clear existing game state
                Globals.gameLoaded = false;
                resetNewGameRuntimeState({
                    players,
                    things,
                    gameLocations,
                    gameLocationExits,
                    regions,
                    factions,
                    skills,
                    stubExpansionPromises,
                    regionEntryExpansionPromises,
                    pendingRegionStubs,
                    pendingLocationImages,
                    generatedImages,
                    imageJobs,
                    activeImageJobs,
                    entityImageJobs,
                    npcGenerationPromises,
                    playerAbilitySelectionPromises,
                    playerImageGenerationPromises,
                    locationImageGenerationPromises,
                    levelUpAbilityPromises,
                    shortDescriptionBackfillByClient,
                    chatHistory,
                    jobQueue,
                    setCurrentPlayer: setActiveCurrentPlayer,
                    setIsProcessingJob: (value) => {
                        isProcessingJob = value;
                        scope.isProcessingJob = value;
                    },
                    clearCurrentTurnToken: () => {
                        currentTurnToken = null;
                        scope.currentTurnToken = null;
                    },
                    resetBaseContextMemoryCache,
                    cancelPendingPlayerInputRequests,
                    questConfirmationManager,
                    clearPlayerMoveLocks: () => {
                        activePlayerMoveLocks.clear();
                    },
                    advanceRuntimeGeneration
                });
                Globals.saveFileSaveVersion = normalizeSaveFileVersion(Globals.currentSaveVersion, 0);
                Globals.setSaveMetadata({ summaryStyle: 'scene', npcAliasesGenerated: false });
                Globals.setCurrentSaveInfo(null);
                supplementalStoryInfoTurnCounter = 0;
                plotSummaryInProgress = false;
                plotSummaryTurnCounter = 0;
                plotSummaryRunOnNextEligibleTurn = false;
                plotExpanderInProgress = false;
                plotExpanderTurnCounter = 0;
                improvementPromptTurnCounter = 0;
                tonalScaleEvaluationTurnCounter = 0;
                mysteryBoxCleanupTurnCounter = 0;
                Events.resetMaintenancePromptTurnCounters();
                resetPlotAnalysisPromptRuntime();
                Globals.setPlotAnalysis(null);
                resetOffscreenNpcActivityState();
                Globals.resetWorldTime({
                    settingName: activeSetting?.name || null,
                    calendarDefinition
                });
                const { cycleLengthMinutes } = Globals.getTimeConfig();
                Globals.elapsedTime = (startingDayIndex * cycleLengthMinutes) + (resolvedStartTime * 60);

                console.log('🎮 Starting new game...');
                report('new_game:reset_complete', 'Game state cleared. Preparing skills...');

                const rawExistingSkills = newGameDefaults.existingSkills;
                const existingSkillNames = Array.isArray(rawExistingSkills)
                    ? rawExistingSkills
                    : (typeof rawExistingSkills === 'string'
                        ? rawExistingSkills.split(/\r?\n/)
                        : []);

                const normalizedExistingSkills = existingSkillNames
                    .map(name => (typeof name === 'string' ? name.trim() : ''))
                    .filter(Boolean);

                let detailedExistingSkills = [];
                if (normalizedExistingSkills.length) {
                    try {
                        report('new_game:skills_existing', 'Integrating existing skills...');
                        detailedExistingSkills = await generateSkillsByNames({
                            skillNames: normalizedExistingSkills,
                            settingDescription
                        });
                    } catch (detailedError) {
                        console.warn('Failed to generate detailed skills by name:', detailedError.message);
                        detailedExistingSkills = [];
                    }
                }

                const combinedSkills = new Map();

                const addSkillToCombined = (skill) => {
                    if (!skill || !skill.name) {
                        return;
                    }
                    const key = skill.name.trim().toLowerCase();
                    if (!key || combinedSkills.has(key)) {
                        return;
                    }
                    combinedSkills.set(key, skill);
                };

                if (Array.isArray(detailedExistingSkills) && detailedExistingSkills.length) {
                    detailedExistingSkills.forEach(addSkillToCombined);
                }

                for (const name of normalizedExistingSkills) {
                    if (!name) continue;
                    const key = name.toLowerCase();
                    if (!combinedSkills.has(key)) {
                        combinedSkills.set(key, new Skill({
                            name,
                            description: '',
                            attribute: ''
                        }));
                    }
                }

                skills.clear();
                if (combinedSkills.size > 0) {
                    for (const skill of combinedSkills.values()) {
                        skills.set(skill.name, skill);
                    }
                    Player.setAvailableSkills(skills);
                    for (const player of players.values()) {
                        if (typeof player.syncSkillsWithAvailable === 'function') {
                            player.syncSkillsWithAvailable();
                        }
                    }
                } else {
                    Player.setAvailableSkills(new Map());
                }

                report('new_game:skills_ready', 'Skill library ready. Forging your hero...');

                let generatedFactions = [];
                const preconfiguredFactions = [];
                if (factionCount > 0) {
                    const selectedDrafts = settingFactionDrafts.slice(0, factionCount);
                    if (selectedDrafts.length > 0) {
                        report('new_game:factions_generate', `Loading ${selectedDrafts.length} preconfigured faction(s)...`);
                        for (const [index, draft] of selectedDrafts.entries()) {
                            try {
                                const faction = Faction.fromJSON(draft);
                                preconfiguredFactions.push(faction);
                            } catch (error) {
                                throw new Error(`Failed to load preconfigured faction ${index + 1}: ${error.message}`);
                            }
                        }
                    }

                    const remainingCount = Math.max(0, factionCount - preconfiguredFactions.length);
                    try {
                        if (remainingCount > 0) {
                            report('new_game:factions_generate', `Founding ${remainingCount} additional faction(s)...`);
                            generatedFactions = await generateFactionsList({
                                count: remainingCount,
                                settingDescription
                            });
                        }
                    } catch (factionError) {
                        throw new Error(`Failed to generate factions: ${factionError.message}`);
                    }

                    const combinedFactions = [...preconfiguredFactions, ...generatedFactions];
                    const duplicateNameMap = new Map();
                    for (const faction of combinedFactions) {
                        if (!faction || typeof faction.name !== 'string') {
                            continue;
                        }
                        const key = faction.name.trim().toLowerCase();
                        if (!key) {
                            continue;
                        }
                        if (duplicateNameMap.has(key)) {
                            throw new Error(`Faction name "${faction.name}" is duplicated between preconfigured/generated factions.`);
                        }
                        duplicateNameMap.set(key, faction.id);
                    }

                    const validStatuses = new Set(['allied', 'neutral', 'hostile', 'rival']);
                    const defaultRelationNotes = 'No explicit relationship provided.';
                    for (const faction of combinedFactions) {
                        if (!faction) {
                            continue;
                        }
                        const currentRelationsMap = faction.relations instanceof Map
                            ? faction.relations
                            : new Map(Object.entries(faction.relations || {}));
                        const rebuiltRelations = new Map();
                        for (const otherFaction of combinedFactions) {
                            if (!otherFaction || otherFaction.id === faction.id) {
                                continue;
                            }
                            const relation = currentRelationsMap.get(otherFaction.id);
                            const status = typeof relation?.status === 'string' ? relation.status.trim().toLowerCase() : '';
                            const notes = typeof relation?.notes === 'string' ? relation.notes.trim() : '';
                            if (status && notes && validStatuses.has(status)) {
                                rebuiltRelations.set(otherFaction.id, { status, notes });
                            } else {
                                rebuiltRelations.set(otherFaction.id, {
                                    status: 'neutral',
                                    notes: defaultRelationNotes
                                });
                            }
                        }
                        faction.relations = rebuiltRelations;
                    }

                    factions.clear();
                    for (const faction of combinedFactions) {
                        if (faction && faction.id) {
                            factions.set(faction.id, faction);
                        }
                    }
                    report('new_game:factions_ready', `Factions established (${combinedFactions.length} total).`);
                } else {
                    factions.clear();
                    report('new_game:factions_skipped', 'Faction generation disabled.');
                }

                // Create new player
                const customAttributes = attributesInput && typeof attributesInput === 'object' && !Array.isArray(attributesInput)
                    ? attributesInput
                    : null;
                const customSkills = skillsInput && typeof skillsInput === 'object' && !Array.isArray(skillsInput)
                    ? skillsInput
                    : null;
                const playerOptions = {
                    name: resolvedPlayerName,
                    description: resolvedPlayerDescription,
                    class: resolvedPlayerClass,
                    race: resolvedPlayerRace,
                    level: resolvedPlayerLevel,
                    currency: resolvedStartingCurrency,
                    attributes: customAttributes || {
                        strength: 10,
                        dexterity: 10,
                        constitution: 10,
                        intelligence: 10,
                        wisdom: 10,
                        charisma: 10
                    }
                };
                if (customSkills) {
                    playerOptions.skills = customSkills;
                }
                const newPlayer = new Player(playerOptions);
                if (typeof newPlayer.syncSkillsWithAvailable === 'function') {
                    newPlayer.syncSkillsWithAvailable();
                }
                setActiveCurrentPlayer(newPlayer);
                Globals.syncWorldTimeToPlayer(newPlayer);

                report('new_game:player_created', `Forged ${resolvedPlayerName}. Generating starting region...`);

                // Generate an initial region and choose its entrance as the starting location
                console.log('🗺️ Generating starting region...');
                const defaultRegionName = activeSetting?.name
                    ? `${activeSetting.name}`
                    : resolvedStartingLocation
                        ? `${resolvedStartingLocation} Region`
                        : 'Starting Region';

                const regionStageDetails = {
                    'region:prepare': { stage: 'new_game:region_prepare', message: 'Preparing region prompt...' },
                    'region:request': { stage: 'new_game:region_request', message: 'Requesting region layout from AI...' },
                    'region:response': { stage: 'new_game:region_response', message: 'Region layout received.' },
                    'region:parse': { stage: 'new_game:region_parse', message: 'Interpreting region blueprint...' },
                    'region:instantiate': { stage: 'new_game:region_instantiate', message: 'Placing region locations...' },
                    'region:entrance': { stage: 'new_game:region_entrance', message: 'Selecting starting entrance...' },
                    'region:npcs': { stage: 'new_game:region_npcs', message: 'Populating region with NPCs...' },
                    'region:complete': { stage: 'new_game:region_complete', message: 'Region generation complete.' }
                };

                const regionOptions = {
                    setting: settingDescription,
                    regionNotes: resolvedStartingLocation ? `${resolvedStartingLocation}` : defaultRegionName,
                    //regionNotes: startingLocationStyle || null,
                    report: (stage, info = {}) => {
                        const detail = regionStageDetails[stage] || null;
                        const targetStage = detail?.stage || 'new_game:region';
                        const message = detail?.message || info.message || 'Generating starting region...';
                        report(targetStage, message);
                    }
                };

                //console.log('🏗️  Starting region generation with regionOptions:', regionOptions);

                const regionResult = await generateRegionFromPrompt(regionOptions);
                const region = regionResult.region;

                let entranceLocationId = region.entranceLocationId || regionResult.entranceLocationId;
                if (!entranceLocationId && region.locationIds.length > 0) {
                    entranceLocationId = region.locationIds[0];
                }

                if (!entranceLocationId) {
                    throw new Error('No entrance location generated for starting region');
                }

                let entranceLocation = gameLocations.get(entranceLocationId);
                if (!entranceLocation) {
                    throw new Error('Entrance location not found in game world');
                }

                if (entranceLocation.isStub) {
                    report('new_game:location_detail', 'Detailing starting location...');
                    try {
                        const expansion = await generateLocationFromPrompt({
                            stubLocation: entranceLocation,
                            createStubs: false
                        });
                        if (expansion?.location) {
                            entranceLocation = expansion.location;
                            entranceLocationId = entranceLocation.id;
                            region.entranceLocationId = entranceLocationId;
                        }
                    } catch (expansionError) {
                        console.warn('Failed to expand entrance stub:', expansionError.message);
                    }
                }

                if (entranceLocation.baseLevel && entranceLocation.baseLevel > 3) {
                    entranceLocation.baseLevel = Math.min(3, Math.max(1, entranceLocation.baseLevel));
                } else if (!entranceLocation.baseLevel) {
                    entranceLocation.baseLevel = 1;
                }

                gameLocations.set(entranceLocation.id, entranceLocation);
                console.log(`🏠 Starting at region entrance: ${entranceLocation.name} (Level ${entranceLocation.baseLevel})`);

                // Place player in starting location
                newPlayer.setLocation(entranceLocation.id);

                // Store new player and set as current
                players.set(newPlayer.id, newPlayer);
                setActiveCurrentPlayer(newPlayer);
                Globals.syncWorldTimeToPlayer(currentPlayer);

                queueNpcAssetsForLocation(entranceLocation);

                report('new_game:inventory', 'Outfitting your character...');
                try {
                    await generateInventoryForCharacter({
                        character: newPlayer,
                        characterDescriptor: { role: 'adventurer', class: newPlayer.class, race: newPlayer.race },
                        region,
                        location: entranceLocation
                    });
                } catch (inventoryError) {
                    console.warn('Failed to generate inventory for new-game player:', inventoryError);
                }

                try {
                    report('new_game:abilities', 'Discovering unique abilities...');
                    const playerContext = buildAbilityContextForPlayer(newPlayer, {
                        settingDescription,
                        location: entranceLocation,
                        region
                    });

                    const abilityBaseMessages = playerContext
                        ? [{ role: 'assistant', content: playerContext }]
                        : [];

                    const abilityLogPath = path.join(__dirname, 'logs', `player_${newPlayer.id}_abilities.log`);
                    const abilityResult = await requestNpcAbilityAssignments({
                        baseMessages: abilityBaseMessages,
                        logPath: abilityLogPath
                    });

                    const abilityAssignments = abilityResult.assignments || new Map();
                    const abilityEntry = abilityAssignments.get((newPlayer.name || '').trim().toLowerCase());
                    if (abilityEntry && Array.isArray(abilityEntry.abilities) && abilityEntry.abilities.length) {
                        applyNpcAbilities(newPlayer, abilityEntry.abilities);
                    } else if (typeof newPlayer.setAbilities === 'function') {
                        newPlayer.setAbilities([]);
                    }
                } catch (abilityError) {
                    console.warn('Failed to generate abilities for new-game player:', abilityError.message);
                    if (typeof newPlayer.setAbilities === 'function') {
                        newPlayer.setAbilities([]);
                    }
                }

                console.log(`🧙‍♂️ Created new player: ${newPlayer.name} at ${entranceLocation.name}`);

                report('new_game:finalizing', 'Finalizing world setup...');
                Globals.gameLoaded = true;

                if (typeof resolvePlayerAbilitySelectionState !== 'function') {
                    throw new Error('resolvePlayerAbilitySelectionState helper is unavailable.');
                }
                const pendingAbilitySelection = await resolvePlayerAbilitySelectionState(newPlayer, {
                    ensureOptionsForNext: true
                });
                const introIsDeferred = pendingAbilitySelection?.pending === true;
                if (introIsDeferred) {
                    setPendingGameIntroMetadata({
                        source: 'new_game_ability_selection',
                        locationId: entranceLocation.id
                    });
                    report(
                        'new_game:ability_selection',
                        'Choose your starting abilities before the opening scene begins.',
                        {
                            gameLoaded: true,
                            pendingAbilitySelection,
                            player: serializeNpcForClient(currentPlayer)
                        }
                    );
                } else {
                    setPendingGameIntroMetadata(null);
                    report('new_game:player_ready', 'World ready. Writing opening scene...', {
                        gameLoaded: true,
                        player: serializeNpcForClient(currentPlayer)
                    });
                }

                const startingLocationData = entranceLocation.toJSON();
                startingLocationData.pendingImageJobId = pendingLocationImages.get(entranceLocation.id) || null;
                startingLocationData.npcs = buildNpcProfiles(entranceLocation);

                if (introIsDeferred) {
                    report('new_game:intro_deferred', 'Opening scene is waiting for your starting ability picks.');
                } else {
                    report('new_game:intro', 'Writing opening scene...');
                    try {
                        await runGameIntroPrompt({
                            locationOverride: entranceLocation,
                            locationId: entranceLocation.id,
                            stream
                        });
                        report('new_game:intro_ready', 'Opening scene added to chat history.');
                    } catch (introError) {
                        console.warn('Failed to generate game intro during new game:', introError?.message || introError);
                        report('new_game:intro_skipped', 'Opening scene generation failed; continuing without intro.');
                    }
                }

                report('new_game:complete', 'Adventure ready! Redirecting...');
                res.json({
                    success: true,
                    message: 'New game started successfully',
                    player: newPlayer.toJSON(),
                    startingLocation: startingLocationData,
                    region: region.toJSON(),
                    factions: generatedFactions.map(faction => (typeof faction?.toJSON === 'function' ? faction.toJSON() : faction)),
                    skills: Array.from(skills.values()).map(skill => (
                        typeof skill?.toJSON === 'function' ? skill.toJSON() : skill
                    )),
                    pendingAbilitySelection: pendingAbilitySelection || null,
                    introDeferred: introIsDeferred,
                    gameState: {
                        totalPlayers: players.size,
                        totalLocations: gameLocations.size,
                        currentLocation: entranceLocation.name,
                        regionEntranceId: entranceLocation.id
                    },
                    worldTime: buildWorldTimePayload()
                });
                const durationSeconds = (Date.now() - requestStart) / 1000;
                console.log(`✅ /api/new-game completed in ${durationSeconds.toFixed(3)}s`);

            } catch (error) {
                console.error('Error creating new game:', error);
                reportError(error?.message || 'Failed to create new game');
                res.status(500).json({
                    success: false,
                    error: 'Failed to create new game',
                    details: error.message
                });
                const durationSeconds = (Date.now() - requestStart) / 1000;
                console.log(`❌ /api/new-game failed after ${durationSeconds.toFixed(3)}s`);
            }
        });

        // ==================== SAVE/LOAD FUNCTIONALITY ====================

        const sanitizeSaveNameSegment = (value, fallback) => {
            const source = typeof value === 'string' && value.trim() ? value.trim() : fallback;
            if (!source) {
                throw new Error('Unable to derive a valid save name segment');
            }
            return source
                .replace(/[^a-zA-Z0-9_-]/g, '_')
                .replace(/_{2,}/g, '_')
                .replace(/^_+|_+$/g, '')
                || fallback;
        };

        const buildDefaultSaveName = () => {
            const settingSegment = sanitizeSaveNameSegment(currentSetting?.name, 'Setting');
            const playerSegment = sanitizeSaveNameSegment(currentPlayer.name, currentPlayer.id || 'Player');
            const currentLocationId = currentPlayer.currentLocation || null;
            const currentLocation = currentLocationId
                ? (gameLocations.get(currentLocationId) || Location.get(currentLocationId) || null)
                : null;
            const locationSegment = sanitizeSaveNameSegment(
                currentLocation?.name
                || currentLocation?.description
                || currentLocationId
                || 'Location',
                'Location'
            );
            const timestampFragment = Date.now().toString(36);
            const baseIdFragment = currentPlayer.id || timestampFragment;
            const uniqueSegment = sanitizeSaveNameSegment(
                `${baseIdFragment}-${timestampFragment}`,
                `Save-${timestampFragment}`
            );
            return `${settingSegment}-${playerSegment}-${locationSegment}-${uniqueSegment}`;
        };

        const resolveBaseDirectory = () => (Globals?.baseDir ? path.resolve(Globals.baseDir) : __dirname);

        const resolveSaveRootPath = (rootOption, baseDirectory = null) => {
            const baseDir = baseDirectory || resolveBaseDirectory();
            if (rootOption === null || rootOption === undefined) {
                return path.join(baseDir, 'saves');
            }
            if (typeof rootOption !== 'string') {
                const error = new Error('Save root must be a string path when provided');
                error.code = 'INVALID_SAVE_ROOT';
                throw error;
            }
            const trimmed = rootOption.trim();
            if (!trimmed) {
                const error = new Error('Save root cannot be an empty path');
                error.code = 'INVALID_SAVE_ROOT';
                throw error;
            }
            return path.isAbsolute(trimmed)
                ? trimmed
                : path.join(baseDir, trimmed);
        };

        const resolveMostRecentSaveDir = (saveRootPath) => {
            if (!saveRootPath || typeof saveRootPath !== 'string') {
                throw new Error('Save root path is required to locate the most recent save.');
            }
            if (!fs.existsSync(saveRootPath)) {
                return null;
            }
            const dirEntries = fs.readdirSync(saveRootPath, { withFileTypes: true })
                .filter(entry => entry.isDirectory());
            if (!dirEntries.length) {
                return null;
            }
            let latest = null;
            for (const entry of dirEntries) {
                const fullPath = path.join(saveRootPath, entry.name);
                let stats = null;
                try {
                    stats = fs.statSync(fullPath);
                } catch (error) {
                    console.warn('Failed to stat save directory:', fullPath, error?.message || error);
                    continue;
                }
                const modifiedAt = Number.isFinite(stats.mtimeMs) ? stats.mtimeMs : 0;
                if (!latest || modifiedAt > latest.modifiedAt) {
                    latest = { path: fullPath, modifiedAt };
                }
            }
            return latest ? latest.path : null;
        };

        const resolveLatestSaveDirByMetadataTimestamp = (saveRootPath) => {
            if (!saveRootPath || typeof saveRootPath !== 'string') {
                throw new Error('Save root path is required to locate the latest save.');
            }
            if (!fs.existsSync(saveRootPath)) {
                return null;
            }
            const candidates = fs.readdirSync(saveRootPath, { withFileTypes: true })
                .filter(entry => entry.isDirectory())
                .map(entry => {
                    const fullPath = path.join(saveRootPath, entry.name);
                    let modifiedAt = 0;
                    try {
                        modifiedAt = fs.statSync(fullPath).mtimeMs || 0;
                    } catch (error) {
                        console.warn('Failed to stat save directory:', fullPath, error?.message || error);
                        return null;
                    }
                    let metadataTimestamp = 0;
                    const metadataPath = path.join(fullPath, 'metadata.json');
                    if (fs.existsSync(metadataPath)) {
                        try {
                            const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
                            const parsedTimestamp = new Date(metadata?.timestamp || '').getTime();
                            metadataTimestamp = Number.isFinite(parsedTimestamp) ? parsedTimestamp : 0;
                        } catch (error) {
                            console.warn('Failed to read save metadata timestamp:', metadataPath, error?.message || error);
                        }
                    }
                    return {
                        path: fullPath,
                        sortTimestamp: metadataTimestamp || modifiedAt
                    };
                })
                .filter(Boolean)
                .sort((a, b) => b.sortTimestamp - a.sortTimestamp);
            return candidates[0]?.path || null;
        };

        const getActiveEnabledModNames = () => normalizeEnabledModNames(
            getEnabledModDirectoryNames(resolveBaseDirectory()),
            'active enabled mods'
        );

        const readSaveMetadataFile = (saveDir) => {
            if (typeof saveDir !== 'string' || !saveDir.trim()) {
                throw new Error('Save directory is required to read metadata.');
            }
            const metadataPath = path.join(saveDir, 'metadata.json');
            if (!fs.existsSync(metadataPath)) {
                const error = new Error(`Save metadata not found: ${metadataPath}`);
                error.code = 'SAVE_METADATA_NOT_FOUND';
                throw error;
            }
            let parsed;
            try {
                parsed = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
            } catch (parseError) {
                const error = new Error(`Failed to parse save metadata: ${parseError.message}`);
                error.code = 'SAVE_METADATA_INVALID';
                throw error;
            }
            if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                const error = new Error('Save metadata must contain a JSON object.');
                error.code = 'SAVE_METADATA_INVALID';
                throw error;
            }
            return parsed;
        };

        const resolveSaveDirForRequest = (requestedSaveName, saveRoot) => {
            const normalizedName = assertSafeSaveDirectoryName(requestedSaveName);
            const baseDir = resolveBaseDirectory();
            const saveRootPath = resolveSaveRootPath(saveRoot, baseDir);
            const saveDir = path.join(saveRootPath, normalizedName);
            if (!fs.existsSync(saveDir)) {
                const directoryLabel = path.basename(saveRootPath) || 'saves';
                const error = new Error(`Save '${normalizedName}' not found in ${directoryLabel}`);
                error.code = 'SAVE_NOT_FOUND';
                throw error;
            }
            return {
                baseDir,
                normalizedName,
                saveDir,
                saveRootPath
            };
        };

        const buildModMismatchLoadError = (diff) => {
            const error = new Error(
                'Enabled mods for this save differ from the currently active mods. Choose whether to apply the save configuration, keep the current configuration, or cancel the load.'
            );
            error.code = 'MOD_ENABLEMENT_MISMATCH';
            error.modMismatch = diff;
            return error;
        };

        const resolveSaveEnabledModDiff = (metadata) => {
            if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) {
                return null;
            }
            if (!Object.prototype.hasOwnProperty.call(metadata, 'enabledMods')) {
                return null;
            }
            const savedEnabledMods = normalizeEnabledModNames(metadata?.enabledMods, 'save metadata.enabledMods');
            return diffEnabledMods({
                activeEnabledMods: getActiveEnabledModNames(),
                savedEnabledMods
            });
        };

        const assertSaveEnabledModsCompatible = (metadata, { modMismatchChoice = null } = {}) => {
            const diff = resolveSaveEnabledModDiff(metadata);
            if (!diff || !diff.hasMismatch || modMismatchChoice === 'keep-current') {
                return diff;
            }
            throw buildModMismatchLoadError(diff);
        };

        const readLastChatHistoryEntryId = (saveDir) => {
            if (!saveDir || typeof saveDir !== 'string') {
                throw new Error('Save directory is required to read chat history.');
            }
            const filePath = path.join(saveDir, 'chatHistory.json');
            if (!fs.existsSync(filePath)) {
                return null;
            }
            try {
                const raw = fs.readFileSync(filePath, 'utf8');
                const parsed = JSON.parse(raw);
                if (!Array.isArray(parsed) || !parsed.length) {
                    return null;
                }
                const lastEntry = parsed[parsed.length - 1];
                const id = typeof lastEntry?.id === 'string' ? lastEntry.id.trim() : '';
                return id || null;
            } catch (error) {
                console.warn('Failed to read chatHistory.json from save:', saveDir, error?.message || error);
                return null;
            }
        };

        const normalizeNpcAliasesGeneratedFlag = (value) => value === true;

        const updateRuntimeSaveMetadata = (updater) => {
            if (typeof updater !== 'function') {
                throw new Error('updateRuntimeSaveMetadata requires an updater function.');
            }
            const currentMetadata = (typeof Globals.getSaveMetadata === 'function'
                ? Globals.getSaveMetadata()
                : Globals.saveMetadata) || {};
            if (!currentMetadata || typeof currentMetadata !== 'object' || Array.isArray(currentMetadata)) {
                throw new Error('Current save metadata must be an object.');
            }
            const nextMetadata = { ...currentMetadata };
            updater(nextMetadata);
            Globals.setSaveMetadata(nextMetadata);
            return nextMetadata;
        };

        const persistCurrentSaveMetadata = async (metadata) => {
            if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) {
                throw new Error('persistCurrentSaveMetadata requires a metadata object.');
            }
            const saveInfo = typeof Globals.getCurrentSaveInfo === 'function'
                ? Globals.getCurrentSaveInfo()
                : Globals.currentSaveInfo;
            if (!saveInfo || typeof saveInfo !== 'object') {
                return false;
            }
            const saveDir = typeof saveInfo.saveDir === 'string' ? saveInfo.saveDir.trim() : '';
            if (!saveDir) {
                return false;
            }
            if (!fs.existsSync(saveDir)) {
                throw new Error(`Save directory does not exist: ${saveDir}`);
            }
            const metadataPath = path.join(saveDir, 'metadata.json');
            await Utils.writeFileAtomic(metadataPath, JSON.stringify(metadata, null, 2));
            return true;
        };

        const markNpcAliasesGenerated = async ({ persist = false } = {}) => {
            const metadata = updateRuntimeSaveMetadata((nextMetadata) => {
                nextMetadata.npcAliasesGenerated = true;
            });
            const persisted = persist ? await persistCurrentSaveMetadata(metadata) : false;
            return { metadata, persisted };
        };

        const normalizePendingGameIntroMetadata = (value) => {
            if (!value || typeof value !== 'object' || Array.isArray(value)) {
                return null;
            }
            const locationId = typeof value.locationId === 'string' ? value.locationId.trim() : '';
            if (!locationId) {
                return null;
            }
            const source = typeof value.source === 'string' && value.source.trim()
                ? value.source.trim()
                : 'new_game';
            return {
                source,
                locationId
            };
        };

        const getPendingGameIntroMetadata = () => {
            const metadata = (typeof Globals.getSaveMetadata === 'function'
                ? Globals.getSaveMetadata()
                : Globals.saveMetadata) || null;
            return normalizePendingGameIntroMetadata(metadata?.pendingGameIntro);
        };

        const setActiveCurrentPlayer = (player) => {
            const normalizedPlayer = player || null;
            currentPlayer = normalizedPlayer;
            scope.currentPlayer = normalizedPlayer;
            Globals.currentPlayer = normalizedPlayer;
            Globals.setInCombat(Boolean(normalizedPlayer?.inCombat));
            return normalizedPlayer;
        };

        const setPendingGameIntroMetadata = (value) => {
            const normalized = normalizePendingGameIntroMetadata(value);
            updateRuntimeSaveMetadata((nextMetadata) => {
                if (normalized) {
                    nextMetadata.pendingGameIntro = normalized;
                    return;
                }
                delete nextMetadata.pendingGameIntro;
            });
            return normalized;
        };

        async function performGameSave({ requestedSaveName = null, saveRoot = null } = {}) {
            if (!currentPlayer) {
                const error = new Error('No current player to save');
                error.code = 'NO_PLAYER';
                throw error;
            }

            const baseDir = resolveBaseDirectory();
            const saveRootPath = resolveSaveRootPath(saveRoot, baseDir);
            const baseSaveName = requestedSaveName
                ? sanitizeSaveNameSegment(requestedSaveName, null)
                : buildDefaultSaveName();

            if (!baseSaveName) {
                const error = new Error('Failed to resolve a valid save name');
                error.code = 'INVALID_SAVE_NAME';
                throw error;
            }

            const timestampPrefix = new Date().toISOString().replace(/[:.]/g, '-');
            const saveName = `${timestampPrefix}_${baseSaveName}`;

            const saveDir = path.join(saveRootPath, saveName);

            // Record a permanent, player-visible but non-LLM-visible marker in the
            // chat log for manual saves, so the timeline shows where the game was
            // saved. It is added before serialization so it lives inside this save.
            // Autosaves are frequent and intentionally skip the marker.
            const isAutosaveTarget = path.basename(saveRootPath) === 'autosaves';
            if (!isAutosaveTarget && currentPlayer && typeof Globals.appendChatEntry === 'function') {
                try {
                    // role 'system' is unconditionally excluded from LLM prompt
                    // history (even under includeAllHistoryEntryTypes); the
                    // excludeFromBaseContextHistory metadata is belt-and-suspenders.
                    // The client dispatches rendering on the 'save-notice' type, so
                    // the entry still displays despite the system role.
                    Globals.appendChatEntry({
                        role: 'system',
                        type: 'save-notice',
                        content: `💾 Game saved as "${baseSaveName}".`,
                        metadata: {
                            excludeFromBaseContextHistory: true,
                            saveName
                        }
                    }, {
                        locationId: currentPlayer.currentLocation || null,
                        emitClientRefresh: true,
                        refreshPayload: { reason: 'game-saved' }
                    });
                } catch (error) {
                    console.warn('Failed to append save marker chat entry:', error.message);
                }
            }

            const serialized = Utils.serializeGameState({
                currentPlayer,
                gameLocations,
                gameLocationExits,
                regions,
                chatHistory,
                generatedImages,
                things,
                players,
                skills,
                factions,
                currentSetting,
                pendingRegionStubs,
                enabledMods: getActiveEnabledModNames(),
                gameConfigOverrideYaml: typeof Globals.getGameConfigOverrideYaml === 'function'
                    ? Globals.getGameConfigOverrideYaml()
                    : ''
            });

            if (path.basename(saveRootPath) === 'autosaves') {
                const mostRecentSaveDir = resolveMostRecentSaveDir(saveRootPath);
                if (mostRecentSaveDir) {
                    const lastSavedEntryId = readLastChatHistoryEntryId(mostRecentSaveDir);
                    const currentHistory = Array.isArray(serialized.chatHistory) ? serialized.chatHistory : [];
                    const currentLastEntry = currentHistory.length ? currentHistory[currentHistory.length - 1] : null;
                    const currentLastEntryId = typeof currentLastEntry?.id === 'string'
                        ? currentLastEntry.id.trim()
                        : '';
                    if (lastSavedEntryId && currentLastEntryId && lastSavedEntryId === currentLastEntryId) {
                        serialized.chatHistory = currentHistory.slice(0, -1);
                    }
                }
            }

            const metadata = serialized.metadata || {};
            serialized.metadata = metadata;
            metadata.saveName = saveName;
            metadata.timestamp = metadata.timestamp || new Date().toISOString();
            metadata.totalPlayers = players.size;
            metadata.totalThings = things.size;
            metadata.totalLocations = gameLocations.size;
            metadata.totalLocationExits = gameLocationExits.size;
            metadata.totalRegions = regions.size;
            metadata.totalFactions = factions.size;
            metadata.totalMysteryBoxes = MysteryBox.getAll().length;
            metadata.totalMysteryThreads = MysteryThread.getAll().length;
            metadata.totalTrackers = Tracker.getAll().length;
            metadata.chatHistoryLength = Array.isArray(serialized.chatHistory)
                ? serialized.chatHistory.length
                : (metadata.chatHistoryLength || 0);
            metadata.totalGeneratedImages = generatedImages.size;
            metadata.totalSkills = skills.size;
            metadata.currentSettingId = currentSetting?.id || metadata.currentSettingId || null;
            metadata.currentSettingName = currentSetting?.name || metadata.currentSettingName || null;
            const runtimeMetadata = (typeof Globals.getSaveMetadata === 'function'
                ? Globals.getSaveMetadata()
                : Globals.saveMetadata) || {};
            metadata.npcAliasesGenerated = normalizeNpcAliasesGeneratedFlag(
                runtimeMetadata?.npcAliasesGenerated ?? metadata.npcAliasesGenerated
            );
            metadata.saveFileSaveVersion = normalizeSaveFileVersion(Globals.saveFileSaveVersion, 0);
            const summaryStyle = normalizeSummaryStyle(
                (typeof Globals.getSaveMetadata === 'function' ? Globals.getSaveMetadata() : Globals.saveMetadata)?.summaryStyle
            );
            if (summaryStyle) {
                metadata.summaryStyle = summaryStyle;
            } else if (metadata.summaryStyle !== undefined) {
                metadata.summaryStyle = normalizeSummaryStyle(metadata.summaryStyle);
            }
            metadata.plotSummaryTurnCounter = Number.isInteger(plotSummaryTurnCounter) && plotSummaryTurnCounter >= 0
                ? plotSummaryTurnCounter
                : 0;
            metadata.plotExpanderTurnCounter = Number.isInteger(plotExpanderTurnCounter) && plotExpanderTurnCounter >= 0
                ? plotExpanderTurnCounter
                : 0;
            metadata.improvementPromptTurnCounter = Number.isInteger(improvementPromptTurnCounter) && improvementPromptTurnCounter >= 0
                ? improvementPromptTurnCounter
                : 0;
            metadata.tonalScaleEvaluationTurnCounter = Number.isInteger(tonalScaleEvaluationTurnCounter) && tonalScaleEvaluationTurnCounter >= 0
                ? tonalScaleEvaluationTurnCounter
                : 0;
            metadata.plotAnalysisTurnCounter = Number.isInteger(plotAnalysisTurnCounter) && plotAnalysisTurnCounter >= 0
                ? plotAnalysisTurnCounter
                : 0;
            if (
                typeof metadata.tonalScaleEvaluationResult === 'string'
                && metadata.tonalScaleEvaluationResult.trim()
            ) {
                const resultCounter = Number(metadata.tonalScaleEvaluationResultTurnCounter);
                metadata.tonalScaleEvaluationResultTurnCounter = Number.isInteger(resultCounter) && resultCounter >= 0
                    ? resultCounter
                    : metadata.tonalScaleEvaluationTurnCounter;
            }
            metadata.mysteryBoxCleanupTurnCounter = Number.isInteger(mysteryBoxCleanupTurnCounter) && mysteryBoxCleanupTurnCounter >= 0
                ? mysteryBoxCleanupTurnCounter
                : 0;
            const maintenancePromptTurnCounters = Events.getMaintenancePromptTurnCounters();
            metadata.housekeepingTurnCounter = maintenancePromptTurnCounters.housekeepingTurnCounter;
            metadata.questCheckTurnCounter = maintenancePromptTurnCounters.questCheckTurnCounter;
            const lastHousekeepingTurnId = getLastHousekeepingTurnId();
            if (lastHousekeepingTurnId) {
                metadata.lastHousekeepingTurnId = lastHousekeepingTurnId;
            } else {
                delete metadata.lastHousekeepingTurnId;
            }
            metadata.offscreenNpcActivityState = normalizeOffscreenNpcActivityState(offscreenNpcActivityState);
            const currentLocationId = currentPlayer.currentLocation || null;
            const currentLocation = currentLocationId
                ? (gameLocations.get(currentLocationId) || Location.get(currentLocationId) || null)
                : null;
            metadata.currentLocationId = currentLocationId || metadata.currentLocationId || null;
            metadata.currentLocationName = currentLocation?.name || metadata.currentLocationName || null;
            metadata.source = path.basename(saveRootPath) === 'autosaves' ? 'autosaves' : 'saves';

            await Utils.writeSerializedGameState(saveDir, serialized);
            console.log(`[save] Saved game '${saveName}' (${metadata.source}) at ${saveDir}`);

            return { saveName, saveDir, metadata };
        }

        function reconcileCurrentPlayerPartyLocationState(player) {
            if (!player || typeof player.getPartyMembers !== 'function') {
                return {
                    membersChecked: 0,
                    membersClearedFromLocationLists: 0,
                    locationEntriesRemoved: 0,
                    membersWithLocationCleared: 0
                };
            }

            const rawPartyMembers = player.getPartyMembers();
            const partyMemberIds = Array.isArray(rawPartyMembers)
                ? rawPartyMembers
                : (rawPartyMembers instanceof Set ? Array.from(rawPartyMembers) : []);

            let membersChecked = 0;
            let membersClearedFromLocationLists = 0;
            let locationEntriesRemoved = 0;
            let membersWithLocationCleared = 0;

            for (const rawMemberId of partyMemberIds) {
                if (typeof rawMemberId !== 'string' || !rawMemberId.trim()) {
                    continue;
                }
                const memberId = rawMemberId.trim();
                membersChecked += 1;

                const member = players.get(memberId)
                    || (typeof Player.getById === 'function' ? Player.getById(memberId) : null);
                if (!member) {
                    console.warn(`Skipping party-location reconciliation for missing member '${memberId}'.`);
                    continue;
                }

                member.wasEverInPlayerParty = true;

                const removedCount = Player.removeNpcFromAllLocations(member.id);
                if (removedCount > 0) {
                    membersClearedFromLocationLists += 1;
                    locationEntriesRemoved += removedCount;
                }

                if (member.currentLocation) {
                    if (typeof member.setLocation !== 'function') {
                        throw new Error(
                            `Unable to clear location for party member '${member.name || member.id}' during load reconciliation: setLocation is not available.`
                        );
                    }
                    member.setLocation(null);
                    membersWithLocationCleared += 1;
                }
            }

            return {
                membersChecked,
                membersClearedFromLocationLists,
                locationEntriesRemoved,
                membersWithLocationCleared
            };
        }

        function reconcileFactionReferencesOnLoad() {
            const normalizeFactionId = (value) => {
                if (typeof value !== 'string') {
                    return '';
                }
                return value.trim();
            };

            const validFactionIds = new Set(
                Array.from(factions.keys())
                    .map(normalizeFactionId)
                    .filter(Boolean)
            );

            const stats = {
                playersChecked: 0,
                playersFactionCleared: 0,
                playersStandingsEntriesRemoved: 0,
                locationsChecked: 0,
                locationsFactionCleared: 0,
                regionsChecked: 0,
                regionsFactionCleared: 0,
                pendingRegionStubsChecked: 0,
                pendingRegionStubsFactionCleared: 0,
                factionRelationsChecked: 0,
                factionRelationsRemoved: 0
            };

            for (const player of players.values()) {
                if (!player) {
                    continue;
                }
                stats.playersChecked += 1;

                const playerFactionId = normalizeFactionId(player.factionId);
                if (playerFactionId && !validFactionIds.has(playerFactionId)) {
                    player.factionId = null;
                    stats.playersFactionCleared += 1;
                }

                if (typeof player.getFactionStandings === 'function' && typeof player.setFactionStandings === 'function') {
                    const standings = player.getFactionStandings() || {};
                    const cleanedStandings = {};
                    let removedEntries = 0;

                    for (const [rawFactionId, standingValue] of Object.entries(standings)) {
                        const standingFactionId = normalizeFactionId(rawFactionId);
                        if (!standingFactionId || !validFactionIds.has(standingFactionId)) {
                            removedEntries += 1;
                            continue;
                        }
                        cleanedStandings[standingFactionId] = standingValue;
                    }

                    if (removedEntries > 0) {
                        player.setFactionStandings(cleanedStandings);
                        stats.playersStandingsEntriesRemoved += removedEntries;
                    }
                }
            }

            for (const location of gameLocations.values()) {
                if (!location) {
                    continue;
                }
                stats.locationsChecked += 1;
                const controllingFactionId = normalizeFactionId(location.controllingFactionId);
                if (controllingFactionId && !validFactionIds.has(controllingFactionId)) {
                    location.controllingFactionId = null;
                    stats.locationsFactionCleared += 1;
                }
            }

            for (const region of regions.values()) {
                if (!region) {
                    continue;
                }
                stats.regionsChecked += 1;
                const controllingFactionId = normalizeFactionId(region.controllingFactionId);
                if (controllingFactionId && !validFactionIds.has(controllingFactionId)) {
                    region.controllingFactionId = null;
                    stats.regionsFactionCleared += 1;
                }
            }

            if (pendingRegionStubs instanceof Map) {
                for (const pendingStub of pendingRegionStubs.values()) {
                    if (!pendingStub || typeof pendingStub !== 'object') {
                        continue;
                    }
                    stats.pendingRegionStubsChecked += 1;
                    const controllingFactionId = normalizeFactionId(pendingStub.controllingFactionId);
                    if (controllingFactionId && !validFactionIds.has(controllingFactionId)) {
                        pendingStub.controllingFactionId = null;
                        stats.pendingRegionStubsFactionCleared += 1;
                    }
                }
            }

            for (const faction of factions.values()) {
                if (!faction || typeof faction.id !== 'string') {
                    continue;
                }

                const sourceRelations = faction.relations;
                const relationEntries = sourceRelations instanceof Map
                    ? Array.from(sourceRelations.keys())
                    : [];
                stats.factionRelationsChecked += relationEntries.length;

                for (const rawTargetId of relationEntries) {
                    const targetId = normalizeFactionId(rawTargetId);
                    const relationReferencesSelf = targetId === faction.id;
                    if (!targetId || relationReferencesSelf || !validFactionIds.has(targetId)) {
                        if (typeof faction.removeRelation === 'function') {
                            const removed = faction.removeRelation(rawTargetId);
                            if (removed) {
                                stats.factionRelationsRemoved += 1;
                            }
                        }
                    }
                }
            }

            return stats;
        }

        async function persistLoadedGameStateAfterSettingBackfill(saveDir, metadata = {}) {
            if (!currentPlayer) {
                throw new Error('Cannot persist loaded setting backfill before current player is resolved.');
            }
            const serializedBackfill = Utils.serializeGameState({
                currentPlayer,
                gameLocations,
                gameLocationExits,
                regions,
                chatHistory,
                generatedImages,
                things,
                players,
                skills,
                factions,
                currentSetting,
                pendingRegionStubs,
                enabledMods: getActiveEnabledModNames(),
                gameConfigOverrideYaml: typeof Globals.getGameConfigOverrideYaml === 'function'
                    ? Globals.getGameConfigOverrideYaml()
                    : ''
            });
            serializedBackfill.metadata = {
                ...(serializedBackfill.metadata || {}),
                ...(metadata && typeof metadata === 'object' ? metadata : {}),
                currentSettingId: currentSetting?.id || metadata?.currentSettingId || null,
                currentSettingName: currentSetting?.name || metadata?.currentSettingName || null
            };
            await Utils.writeSerializedGameState(saveDir, serializedBackfill);
        }

        async function performGameLoad(requestedSaveName, {
            skipSummary = false,
            saveRoot = null,
            clientId = null,
            modMismatchChoice = null,
            loadLatest = false
        } = {}) {
            if (gameLoadInProgress) {
                const error = new Error('Another game load is already in progress.');
                error.code = 'GAME_LOAD_IN_PROGRESS';
                throw error;
            }
            gameLoadInProgress = true;
            try {
            const cancelRuntimeForLoad = reason => abortRuntimeWorkBeforeGameLoad({
                reason,
                advanceRuntimeGeneration,
                clearCurrentTurnToken: () => {
                    currentTurnToken = null;
                    scope.currentTurnToken = null;
                },
                cancelAllPrompts: cancellationReason => LLMClient.cancelAllPrompts(cancellationReason),
                waitForPromptDrain: options => LLMClient.waitForPromptDrain(options),
                waitForActiveTurns: waitForActiveChatTurnDrain,
                cancelAllImageJobs,
                cancelPendingPlayerInputRequests: cancellationReason => cancelPendingPlayerInputRequests(
                    null,
                    cancellationReason,
                    'game_load_started'
                ),
                rejectQuestConfirmations: cancellationReason => questConfirmationManager.rejectAll(cancellationReason),
                clearPlayerMoveLocks: () => activePlayerMoveLocks.clear()
            });

            let targetSaveName = requestedSaveName;
            let runtimeCancellation = null;
            if (loadLatest === true) {
                runtimeCancellation = await cancelRuntimeForLoad(
                    'Loading the latest autosave; previous runtime work cancelled.'
                );
                const latestSaveDir = resolveLatestSaveDirByMetadataTimestamp(resolveSaveRootPath('autosaves'));
                if (!latestSaveDir) {
                    const error = new Error('No autosaves are available to restore.');
                    error.code = 'AUTOSAVE_NOT_FOUND';
                    throw error;
                }
                targetSaveName = path.basename(latestSaveDir);
                saveRoot = 'autosaves';
            }

            const {
                baseDir,
                normalizedName,
                saveDir,
                saveRootPath
            } = resolveSaveDirForRequest(targetSaveName, saveRoot);

            if (!runtimeCancellation) {
                runtimeCancellation = await cancelRuntimeForLoad(
                    `Loading game "${normalizedName}"; previous runtime work cancelled.`
                );
            }

            const serialized = Utils.loadSerializedGameState(saveDir);
            assertSaveEnabledModsCompatible(serialized.metadata, { modMismatchChoice });
            const savedGameConfigOverrideYaml = typeof serialized.gameConfigOverrideYaml === 'string'
                ? serialized.gameConfigOverrideYaml
                : '';

            if (typeof Globals.reloadConfigAndDefs !== 'function') {
                throw new Error('Globals.reloadConfigAndDefs is not available during game load.');
            }
            Globals.reloadConfigAndDefs({
                gameConfigOverrideYaml: savedGameConfigOverrideYaml,
                needBarSentenceValidationMode: 'throw'
            });

            Globals.gameLoaded = false;

            jobQueue.length = 0;
            imageJobs.clear();
            activeImageJobs.clear();
            entityImageJobs.clear();
            pendingLocationImages.clear();
            generatedImages.clear();
            stubExpansionPromises.clear();
            regionEntryExpansionPromises.clear();
            npcGenerationPromises.clear();
            playerAbilitySelectionPromises.clear();
            playerImageGenerationPromises.clear();
            locationImageGenerationPromises.clear();
            levelUpAbilityPromises.clear();
            shortDescriptionBackfillByClient.clear();
            isProcessingJob = false;

            const hydrationResult = Utils.hydrateGameState(serialized, {
                gameLocations,
                gameLocationExits,
                regions,
                chatHistoryRef: chatHistory,
                generatedImages,
                things,
                players,
                skills,
                factions,
                jobQueue,
                imageJobs,
                pendingLocationImages,
                npcGenerationPromises,
                pendingRegionStubs
            });
            backfillTraveledToLocationIdsOnLoad(chatHistory);

            let metadata = hydrationResult.metadata || {};
            if (!metadata || typeof metadata !== 'object') {
                metadata = {};
            }
            metadata.saveName = metadata.saveName || normalizedName;
            metadata.source = metadata.source || (path.basename(saveRootPath) === 'autosaves' ? 'autosaves' : 'saves');
            Globals.saveFileSaveVersion = normalizeSaveFileVersion(metadata.saveFileSaveVersion, 0);
            console.log(`💾 Loaded save file version: ${Globals.saveFileSaveVersion} (metadata: ${metadata.saveFileSaveVersion ?? 'missing'})`);
            metadata.summaryStyle = normalizeSummaryStyle(metadata.summaryStyle);
            metadata.npcAliasesGenerated = normalizeNpcAliasesGeneratedFlag(metadata.npcAliasesGenerated);
            Globals.setSaveMetadata(metadata);
            Events.hydrateMaintenancePromptTurnCounters(metadata);
            {
                const hasStoredPlotSummaryCounter = Object.prototype.hasOwnProperty.call(metadata, 'plotSummaryTurnCounter');
                const parsedPlotSummaryCounter = Number(metadata.plotSummaryTurnCounter);
                if (Number.isInteger(parsedPlotSummaryCounter) && parsedPlotSummaryCounter >= 0) {
                    plotSummaryTurnCounter = parsedPlotSummaryCounter;
                    plotSummaryRunOnNextEligibleTurn = false;
                } else {
                    plotSummaryTurnCounter = 0;
                    plotSummaryRunOnNextEligibleTurn = !hasStoredPlotSummaryCounter;
                }
            }
            plotSummaryInProgress = false;
            {
                const parsedPlotExpanderCounter = Number(metadata.plotExpanderTurnCounter);
                if (Number.isInteger(parsedPlotExpanderCounter) && parsedPlotExpanderCounter >= 0) {
                    plotExpanderTurnCounter = parsedPlotExpanderCounter;
                } else {
                    plotExpanderTurnCounter = 0;
                }
            }
            plotExpanderInProgress = false;
            {
                const parsedImprovementPromptCounter = Number(metadata.improvementPromptTurnCounter);
                if (Number.isInteger(parsedImprovementPromptCounter) && parsedImprovementPromptCounter >= 0) {
                    improvementPromptTurnCounter = parsedImprovementPromptCounter;
                } else {
                    improvementPromptTurnCounter = 0;
                }
            }
            {
                const parsedTonalScaleEvaluationCounter = Number(metadata.tonalScaleEvaluationTurnCounter);
                if (Number.isInteger(parsedTonalScaleEvaluationCounter) && parsedTonalScaleEvaluationCounter >= 0) {
                    tonalScaleEvaluationTurnCounter = parsedTonalScaleEvaluationCounter;
                } else {
                    tonalScaleEvaluationTurnCounter = 0;
                }
            }
            {
                const parsedPlotAnalysisCounter = Number(metadata.plotAnalysisTurnCounter);
                if (Number.isInteger(parsedPlotAnalysisCounter) && parsedPlotAnalysisCounter >= 0) {
                    plotAnalysisTurnCounter = parsedPlotAnalysisCounter;
                } else {
                    plotAnalysisTurnCounter = 0;
                }
            }
            {
                const parsedMysteryBoxCleanupCounter = Number(metadata.mysteryBoxCleanupTurnCounter);
                if (Number.isInteger(parsedMysteryBoxCleanupCounter) && parsedMysteryBoxCleanupCounter >= 0) {
                    mysteryBoxCleanupTurnCounter = parsedMysteryBoxCleanupCounter;
                } else {
                    mysteryBoxCleanupTurnCounter = 0;
                }
            }
            resetPlotAnalysisPromptRuntime();
            offscreenNpcActivityState = normalizeOffscreenNpcActivityState(metadata.offscreenNpcActivityState);
            Globals.setCurrentSaveInfo({
                saveName: metadata.saveName || normalizedName,
                saveDir,
                source: metadata.source || null
            });

            const loadedSetting = hydrationResult.setting || null;
            if (loadedSetting) {
                if (currentSetting && typeof currentSetting.updateFromJSON === 'function') {
                    try {
                        currentSetting.updateFromJSON(loadedSetting);
                    } catch (settingError) {
                        console.warn('Failed to apply loaded setting:', settingError.message);
                    }
                } else if (typeof SettingInfo?.fromJSON === 'function') {
                    try {
                        currentSetting = SettingInfo.fromJSON(loadedSetting);
                    } catch (settingError) {
                        console.warn('Failed to instantiate setting from save:', settingError.message);
                        currentSetting = loadedSetting;
                    }
                } else {
                    currentSetting = loadedSetting;
                }
            } else {
                currentSetting = null;
            }

            const hidePerceptionBackfillResult = await ensureCurrentSettingHidePerceptionSelections();

            const saveMissingCalendarDefinition = serialized.calendarDefinition === null
                || serialized.calendarDefinition === undefined;
            if (saveMissingCalendarDefinition) {
                const settingSnapshot = currentSetting && typeof currentSetting.toJSON === 'function'
                    ? currentSetting.toJSON()
                    : currentSetting;
                const generatedCalendarDefinition = await resolveCalendarDefinitionForSetting({
                    settingSnapshot
                });
                const existingWorldTime = Globals.getSerializedWorldTime();
                Globals.hydrateWorldTime({
                    worldTime: existingWorldTime,
                    calendarDefinition: generatedCalendarDefinition,
                    settingName: settingSnapshot?.name || null
                });
            }
            const loadedCalendarSettingSnapshot = currentSetting && typeof currentSetting.toJSON === 'function'
                ? currentSetting.toJSON()
                : currentSetting;
            const seasonImageBackfillResult = await ensureCalendarSeasonImageDescriptions({
                calendarDefinition: Globals.getSerializedCalendarDefinition(),
                settingSnapshot: loadedCalendarSettingSnapshot
            });
            if (seasonImageBackfillResult.updated) {
                Globals.setCalendarDefinition(seasonImageBackfillResult.calendarDefinition);
                for (const location of gameLocations.values()) {
                    clearLocationImageVariants(location);
                }
            }

            const factionReconciliation = reconcileFactionReferencesOnLoad();
            const factionRepairsApplied = (
                factionReconciliation.playersFactionCleared
                + factionReconciliation.playersStandingsEntriesRemoved
                + factionReconciliation.locationsFactionCleared
                + factionReconciliation.regionsFactionCleared
                + factionReconciliation.pendingRegionStubsFactionCleared
                + factionReconciliation.factionRelationsRemoved
            ) > 0;
            if (factionRepairsApplied) {
                console.log(
                    `🧹 Reconciled faction references on load: `
                    + `cleared player faction on ${factionReconciliation.playersFactionCleared} player(s), `
                    + `removed ${factionReconciliation.playersStandingsEntriesRemoved} invalid faction standing entry/entries, `
                    + `cleared location faction on ${factionReconciliation.locationsFactionCleared} location(s), `
                    + `cleared region faction on ${factionReconciliation.regionsFactionCleared} region(s), `
                    + `cleared pending region stub faction on ${factionReconciliation.pendingRegionStubsFactionCleared} stub(s), `
                    + `removed ${factionReconciliation.factionRelationsRemoved} invalid faction relation(s).`
                );
            }

            let resolvedPlayer = null;
            if (metadata.playerId && players.has(metadata.playerId)) {
                resolvedPlayer = players.get(metadata.playerId);
            }
            if (!resolvedPlayer) {
                const iterator = players.values();
                resolvedPlayer = iterator.next().value || null;
            }
            if (!resolvedPlayer) {
                const error = new Error('No players found in save file');
                error.code = 'PLAYER_NOT_FOUND';
                throw error;
            }

            setActiveCurrentPlayer(resolvedPlayer);
            if (typeof Player.register === 'function') {
                Player.register(currentPlayer);
            }

            const partyReconciliation = reconcileCurrentPlayerPartyLocationState(currentPlayer);
            if (partyReconciliation.locationEntriesRemoved > 0 || partyReconciliation.membersWithLocationCleared > 0) {
                console.log(
                    `🧹 Reconciled party/location state on load: checked ${partyReconciliation.membersChecked} member(s), removed ${partyReconciliation.locationEntriesRemoved} location entry/entries, cleared explicit location on ${partyReconciliation.membersWithLocationCleared} member(s).`
                );
            }

            Globals.syncWorldTimeToPlayer(currentPlayer);

            const KNOWN_EXTENSIONS = ['.png', '.jpg', '.jpeg', '.webp', '.gif'];
            const hasImage = (imageId) => {
                if (!imageId) {
                    return false;
                }
                if (generatedImages.has(imageId)) {
                    return true;
                }
                const imagesDir = path.join(baseDir, 'public', 'generated-images');
                return KNOWN_EXTENSIONS.some(ext => fs.existsSync(path.join(imagesDir, `${imageId}${ext}`)));
            };

            const ensureInventoryImages = (character) => {
                if (!character || typeof character.getInventoryItems !== 'function') {
                    return;
                }
                const items = character.getInventoryItems();
                if (!Array.isArray(items)) {
                    return;
                }
                for (const item of items) {
                    if (!item) {
                        continue;
                    }
                    if (item.imageId && !hasImage(item.imageId)) {
                        item.imageId = null;
                    }
                }
            };

            for (const thing of things.values()) {
                if (thing && thing.imageId && !hasImage(thing.imageId)) {
                    thing.imageId = null;
                }
            }

            for (const player of players.values()) {
                if (!player) {
                    continue;
                }
                if (player.imageId && !hasImage(player.imageId)) {
                    player.imageId = null;
                }
                ensureInventoryImages(player);
            }

            if (currentPlayer) {
                if (currentPlayer.imageId && !hasImage(currentPlayer.imageId)) {
                    currentPlayer.imageId = null;
                }
                ensureInventoryImages(currentPlayer);
            }

            const currentLocationId = currentPlayer?.currentLocation || null;
            if (currentLocationId && gameLocations.has(currentLocationId)) {
                const location = gameLocations.get(currentLocationId);
                try {
                    queueNpcAssetsForLocation(location);
                } catch (npcQueueError) {
                    console.warn('Failed to queue NPC assets after load:', npcQueueError.message);
                }
                try {
                    queueLocationThingImages(location);
                } catch (thingQueueError) {
                    console.warn('Failed to queue location thing images after load:', thingQueueError.message);
                }

                const npcIds = Array.isArray(location.npcIds) ? location.npcIds : [];
                for (const npcId of npcIds) {
                    const npc = players.get(npcId);
                    if (!npc) {
                        continue;
                    }
                    if (npc.imageId && !hasImage(npc.imageId)) {
                        npc.imageId = null;
                    }
                    ensureInventoryImages(npc);
                }
            }

            metadata.playerId = metadata.playerId || currentPlayer.id;
            metadata.playerName = metadata.playerName || currentPlayer.name;
            try {
                if (typeof currentPlayer.getCurrentLocation === 'function') {
                    const locationId = currentPlayer.currentLocation;
                    if (locationId && gameLocations.has(locationId)) {
                        scope.currentLocation = gameLocations.get(locationId);
                    }
                }
            } catch (locationError) {
                console.warn('Failed to resolve current location after load:', locationError.message);
            }

            metadata.playerLevel = metadata.playerLevel || currentPlayer.level;
            metadata.timestamp = metadata.timestamp || new Date().toISOString();
            metadata.currentSettingId = currentSetting?.id || metadata.currentSettingId || null;
            metadata.currentSettingName = currentSetting?.name || metadata.currentSettingName || null;
            metadata.totalPlayers = players.size;
            metadata.totalThings = things.size;
            metadata.totalLocations = gameLocations.size;
            metadata.totalLocationExits = gameLocationExits.size;
            metadata.totalRegions = regions.size;
            metadata.totalFactions = factions.size;
            metadata.totalMysteryBoxes = MysteryBox.getAll().length;
            metadata.totalMysteryThreads = MysteryThread.getAll().length;
            metadata.totalTrackers = Tracker.getAll().length;
            metadata.chatHistoryLength = Array.isArray(chatHistory)
                ? chatHistory.length
                : (metadata.chatHistoryLength || 0);
            metadata.totalGeneratedImages = generatedImages.size;
            metadata.totalSkills = skills.size;

            if (hidePerceptionBackfillResult.updated || saveMissingCalendarDefinition || seasonImageBackfillResult.updated) {
                await persistLoadedGameStateAfterSettingBackfill(saveDir, metadata);
            }

            if (!skipSummary) {
                const summaryConfig = getSummaryConfig();
                if (summaryConfig.summarize_on_load !== false) {
                    await summarizeChatBacklog(chatHistory);
                }
            }

            const ensureShortDescriptionsOnLoad = async () => {
                const isMissingShortDescription = (value) => !value || !String(value).trim();
                const resolveStubShortDescription = (location) => {
                    if (!location || typeof location !== 'object') {
                        return '';
                    }
                    const stubMeta = location.stubMetadata || {};
                    const stubShort = typeof stubMeta.stubShortDescription === 'string'
                        ? stubMeta.stubShortDescription.trim()
                        : '';
                    if (stubShort) {
                        return stubShort;
                    }
                    const legacyShort = typeof stubMeta.shortDescription === 'string'
                        ? stubMeta.shortDescription.trim()
                        : '';
                    return legacyShort;
                };
                const hasLocationShortDescription = (location) => {
                    if (!location || typeof location !== 'object') {
                        return false;
                    }
                    if (!isMissingShortDescription(location.shortDescription)) {
                        return true;
                    }
                    return Boolean(resolveStubShortDescription(location));
                };
                const resolveShortDescriptionCounts = ({
                    thingsToCheck,
                    locationsToCheck,
                    regionsToCheck,
                    abilitiesToCheck
                }) => ({
                    pendingThings: thingsToCheck.filter(item => isMissingShortDescription(item?.shortDescription)).length,
                    pendingLocations: locationsToCheck.filter(loc => !hasLocationShortDescription(loc)).length,
                    pendingRegions: regionsToCheck.filter(region => isMissingShortDescription(region?.shortDescription)).length,
                    pendingAbilities: abilitiesToCheck.filter(ability => isMissingShortDescription(ability?.shortDescription)).length
                });
                const resolveShortDescriptionBatchSize = () => {
                    const configured = Number(Globals?.config?.short_description?.max_items_per_prompt);
                    if (Number.isFinite(configured) && configured > 0) {
                        return Math.floor(configured);
                    }
                    return 100;
                };
                const resolveRegionForLocationEstimate = (location) => {
                    if (!location || typeof location !== 'object') {
                        return null;
                    }
                    if (typeof location.region === 'object' && location.region) {
                        return location.region;
                    }
                    const regionId = typeof location.regionId === 'string' ? location.regionId.trim() : '';
                    if (regionId && regions.has(regionId)) {
                        return regions.get(regionId);
                    }
                    const regionKey = typeof location.region === 'string' ? location.region.trim() : '';
                    if (regionKey && regions.has(regionKey)) {
                        return regions.get(regionKey);
                    }
                    return null;
                };
                const estimateLocationPromptCount = (locations, maxBatchSize) => {
                    if (!Array.isArray(locations) || locations.length === 0) {
                        return 0;
                    }
                    const regionCounts = new Map();
                    for (const location of locations) {
                        if (hasLocationShortDescription(location)) {
                            continue;
                        }
                        const region = resolveRegionForLocationEstimate(location);
                        const regionName = (region?.name && String(region.name).trim())
                            ? String(region.name).trim()
                            : 'Unknown Region';
                        const regionKey = regionName.toLowerCase();
                        regionCounts.set(regionKey, (regionCounts.get(regionKey) || 0) + 1);
                    }
                    let promptCount = 0;
                    let current = 0;
                    for (const count of regionCounts.values()) {
                        if (count <= 0) {
                            continue;
                        }
                        if (count > maxBatchSize) {
                            if (current > 0) {
                                promptCount += 1;
                                current = 0;
                            }
                            promptCount += Math.ceil(count / maxBatchSize);
                            continue;
                        }
                        if (current + count > maxBatchSize && current > 0) {
                            promptCount += 1;
                            current = 0;
                        }
                        current += count;
                    }
                    if (current > 0) {
                        promptCount += 1;
                    }
                    return promptCount;
                };
                if (typeof Globals.ensureThingShortDescriptions !== 'function') {
                    throw new Error('Short description helpers are unavailable (ensureThingShortDescriptions).');
                }
                if (typeof Globals.ensureLocationShortDescriptions !== 'function') {
                    throw new Error('Short description helpers are unavailable (ensureLocationShortDescriptions).');
                }
                if (typeof Globals.ensureRegionShortDescriptions !== 'function') {
                    throw new Error('Short description helpers are unavailable (ensureRegionShortDescriptions).');
                }
                if (typeof Globals.ensureAbilityShortDescriptions !== 'function') {
                    throw new Error('Short description helpers are unavailable (ensureAbilityShortDescriptions).');
                }

                const thingsToCheck = Array.from(things.values());
                const locationsToCheck = Array.from(gameLocations.values());
                const regionsToCheck = Array.from(regions.values());
                const abilitiesToCheck = [];
                for (const player of players.values()) {
                    if (!player || typeof player.getAbilities !== 'function' || typeof player.setAbilities !== 'function') {
                        continue;
                    }
                    const abilities = player.getAbilities();
                    if (!Array.isArray(abilities) || abilities.length === 0) {
                        continue;
                    }
                    abilitiesToCheck.push(...abilities);
                }

                for (const location of locationsToCheck) {
                    if (!location || typeof location !== 'object') {
                        continue;
                    }
                    if (!isMissingShortDescription(location.shortDescription)) {
                        continue;
                    }
                    const stubShort = resolveStubShortDescription(location);
                    if (stubShort) {
                        location.shortDescription = stubShort;
                    }
                }

                const counts = resolveShortDescriptionCounts({
                    thingsToCheck,
                    locationsToCheck,
                    regionsToCheck,
                    abilitiesToCheck
                });
                const totalPending = counts.pendingThings + counts.pendingLocations + counts.pendingRegions + counts.pendingAbilities;

                const resolvedClientId = typeof clientId === 'string' && clientId.trim() ? clientId.trim() : null;
                if (!resolvedClientId) {
                    console.warn('Client ID missing; short description backfill prompt will not be shown.');
                    return;
                }

                if (totalPending > 0) {
                    const maxBatchSize = resolveShortDescriptionBatchSize();
                    const promptsForThings = counts.pendingThings > 0
                        ? Math.ceil(counts.pendingThings / maxBatchSize)
                        : 0;
                    const promptsForRegions = counts.pendingRegions > 0
                        ? Math.ceil(counts.pendingRegions / maxBatchSize)
                        : 0;
                    const promptsForAbilities = counts.pendingAbilities > 0
                        ? Math.ceil(counts.pendingAbilities / maxBatchSize)
                        : 0;
                    const promptsForLocations = estimateLocationPromptCount(locationsToCheck, maxBatchSize);
                    shortDescriptionBackfillByClient.set(resolvedClientId, {
                        counts: {
                            items: counts.pendingThings,
                            locations: counts.pendingLocations,
                            regions: counts.pendingRegions,
                            abilities: counts.pendingAbilities
                        },
                        prompts: {
                            items: promptsForThings,
                            locations: promptsForLocations,
                            regions: promptsForRegions,
                            abilities: promptsForAbilities
                        },
                        totalPending,
                        batchSize: maxBatchSize,
                        createdAt: new Date().toISOString()
                    });
                } else {
                    shortDescriptionBackfillByClient.delete(resolvedClientId);
                    updateSaveFileVersionAtLeast(1);
                }

            };

            await ensureShortDescriptionsOnLoad();

            if (currentPlayer && !currentPlayer.isNPC) {
                if (typeof resolvePlayerAbilitySelectionState !== 'function') {
                    throw new Error('resolvePlayerAbilitySelectionState helper is unavailable.');
                }
                await resolvePlayerAbilitySelectionState(currentPlayer, {
                    ensureOptionsForNext: false
                });
            }

            Globals.gameLoaded = true;

            const loadedData = {
                currentPlayer: currentPlayer ? serializeNpcForClient(currentPlayer) : null,
                totalPlayers: players.size,
                totalThings: things.size,
                totalLocations: gameLocations.size,
                totalLocationExits: gameLocationExits.size,
                chatHistoryLength: Array.isArray(chatHistory) ? chatHistory.length : 0,
                totalGeneratedImages: generatedImages.size,
                currentSetting: currentSetting && typeof currentSetting.toJSON === 'function'
                    ? currentSetting.toJSON()
                    : (currentSetting || null),
                worldTime: buildWorldTimePayload()
            };

            return {
                saveName: normalizedName,
                metadata,
                loadedData,
                runtimeCancellation
            };
            } finally {
                gameLoadInProgress = false;
            }
        }

        scope.performGameSave = performGameSave;
        scope.performGameLoad = performGameLoad;

        const NEW_GAME_SETTINGS_DIRNAME = 'new-game-settings';
        const NEW_GAME_SETTINGS_PAYLOAD_FILENAME = 'settings.json';
        const NEW_GAME_SETTINGS_METADATA_FILENAME = 'metadata.json';
        const NEW_GAME_SETTINGS_SAVE_VERSION = 1;

        const normalizeNewGameSettingsString = (value, fieldName) => {
            if (value === undefined || value === null) {
                return '';
            }
            if (typeof value !== 'string') {
                const error = new Error(`${fieldName} must be a string.`);
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }
            return value.trim();
        };

        const normalizeNewGameSettingsNumericRecord = (value, fieldName) => {
            if (value === undefined || value === null) {
                return {};
            }
            if (!value || typeof value !== 'object' || Array.isArray(value)) {
                const error = new Error(`${fieldName} must be an object.`);
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }
            const result = {};
            for (const [rawKey, rawValue] of Object.entries(value)) {
                if (typeof rawKey !== 'string') {
                    continue;
                }
                const trimmedKey = rawKey.trim();
                if (!trimmedKey) {
                    const error = new Error(`${fieldName} contains an empty key.`);
                    error.code = 'INVALID_NEW_GAME_SETTINGS';
                    throw error;
                }
                const numericValue = Number(rawValue);
                if (!Number.isFinite(numericValue)) {
                    const error = new Error(`${fieldName}.${trimmedKey} must be a finite number.`);
                    error.code = 'INVALID_NEW_GAME_SETTINGS';
                    throw error;
                }
                result[trimmedKey] = numericValue;
            }
            return result;
        };

        const normalizeNewGameSettingsPayload = (settings) => {
            if (!settings || typeof settings !== 'object' || Array.isArray(settings)) {
                const error = new Error('settings must be an object.');
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }

            const parsedLevel = Number(settings.playerLevel);
            const hasPlayerLevel = settings.playerLevel !== undefined && settings.playerLevel !== null && settings.playerLevel !== '';
            if (hasPlayerLevel && !Number.isFinite(parsedLevel)) {
                const error = new Error('playerLevel must be a finite number.');
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }

            const parsedStartingCurrency = Number.parseInt(settings.startingCurrency, 10);
            const hasStartingCurrency = settings.startingCurrency !== undefined && settings.startingCurrency !== null && settings.startingCurrency !== '';
            if (hasStartingCurrency && !Number.isFinite(parsedStartingCurrency)) {
                const error = new Error('startingCurrency must be a finite integer.');
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }

            const parsedStartTime = Number(settings.startTime);
            const hasStartTime = settings.startTime !== undefined && settings.startTime !== null && settings.startTime !== '';
            if (hasStartTime) {
                const isValidStartTime = Number.isFinite(parsedStartTime)
                    && Number.isInteger(parsedStartTime)
                    && parsedStartTime >= 0
                    && parsedStartTime <= 23;
                if (!isValidStartTime) {
                    const error = new Error('startTime must be an integer hour between 0 and 23.');
                    error.code = 'INVALID_NEW_GAME_SETTINGS';
                    throw error;
                }
            }

            const parsedStartMonth = Number(settings.startMonth);
            const hasStartMonth = settings.startMonth !== undefined && settings.startMonth !== null && settings.startMonth !== '';
            if (hasStartMonth && (!Number.isInteger(parsedStartMonth) || parsedStartMonth < 1)) {
                const error = new Error('startMonth must be a positive integer.');
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }

            const parsedStartDay = Number(settings.startDay);
            const hasStartDay = settings.startDay !== undefined && settings.startDay !== null && settings.startDay !== '';
            if (hasStartDay && (!Number.isInteger(parsedStartDay) || parsedStartDay < 1)) {
                const error = new Error('startDay must be a positive integer.');
                error.code = 'INVALID_NEW_GAME_SETTINGS';
                throw error;
            }

            return {
                playerName: normalizeNewGameSettingsString(settings.playerName, 'playerName'),
                playerDescription: normalizeNewGameSettingsString(settings.playerDescription, 'playerDescription'),
                playerClass: normalizeNewGameSettingsString(settings.playerClass, 'playerClass'),
                playerRace: normalizeNewGameSettingsString(settings.playerRace, 'playerRace'),
                playerLevel: hasPlayerLevel ? parsedLevel : 1,
                startMonth: hasStartMonth ? parsedStartMonth : 1,
                startDay: hasStartDay ? parsedStartDay : 1,
                startTime: hasStartTime ? parsedStartTime : 9,
                startingLocation: normalizeNewGameSettingsString(settings.startingLocation, 'startingLocation'),
                startingCurrency: hasStartingCurrency ? parsedStartingCurrency : 0,
                attributes: normalizeNewGameSettingsNumericRecord(settings.attributes, 'attributes'),
                skills: normalizeNewGameSettingsNumericRecord(settings.skills, 'skills')
            };
        };

        const resolveNewGameSettingsRootPath = (baseDirectory = null) => {
            const baseDir = baseDirectory || resolveBaseDirectory();
            return path.join(baseDir, NEW_GAME_SETTINGS_DIRNAME);
        };

        const validateNewGameSettingsSaveName = (rawSaveName) => {
            const normalized = typeof rawSaveName === 'string' ? rawSaveName.trim() : '';
            if (!normalized) {
                const error = new Error('Save name is required.');
                error.code = 'SAVE_NAME_REQUIRED';
                throw error;
            }
            if (normalized.includes('/') || normalized.includes('\\') || normalized.includes('..')) {
                const error = new Error('Save name contains invalid path characters.');
                error.code = 'INVALID_SAVE_NAME';
                throw error;
            }
            return normalized;
        };

        const buildDefaultNewGameSettingsSaveName = (settings) => {
            const settingSegment = sanitizeSaveNameSegment(currentSetting?.name, 'Setting');
            const playerSegment = sanitizeSaveNameSegment(settings?.playerName, 'Adventurer');
            const levelValue = Number(settings?.playerLevel);
            const levelSegment = Number.isFinite(levelValue)
                ? sanitizeSaveNameSegment(`Level-${levelValue}`, 'Level-1')
                : 'Level-1';
            return `${settingSegment}-${playerSegment}-${levelSegment}`;
        };

        const performNewGameSettingsSave = async ({ requestedSaveName = null, settings } = {}) => {
            const normalizedSettings = normalizeNewGameSettingsPayload(settings);
            const baseDir = resolveBaseDirectory();
            const saveRootPath = resolveNewGameSettingsRootPath(baseDir);
            fs.mkdirSync(saveRootPath, { recursive: true });

            const trimmedRequestedName = typeof requestedSaveName === 'string' ? requestedSaveName.trim() : '';
            const baseSaveName = trimmedRequestedName
                ? sanitizeSaveNameSegment(trimmedRequestedName, null)
                : buildDefaultNewGameSettingsSaveName(normalizedSettings);
            if (!baseSaveName) {
                const error = new Error('Failed to resolve a valid save name for new game settings.');
                error.code = 'INVALID_SAVE_NAME';
                throw error;
            }

            const timestampPrefix = new Date().toISOString().replace(/[:.]/g, '-');
            const saveName = `${timestampPrefix}_${baseSaveName}`;
            const saveDir = path.join(saveRootPath, saveName);
            const settingsPath = path.join(saveDir, NEW_GAME_SETTINGS_PAYLOAD_FILENAME);
            const metadataPath = path.join(saveDir, NEW_GAME_SETTINGS_METADATA_FILENAME);

            if (fs.existsSync(saveDir)) {
                const error = new Error(`Save '${saveName}' already exists.`);
                error.code = 'SAVE_ALREADY_EXISTS';
                throw error;
            }

            const metadata = {
                saveName,
                timestamp: new Date().toISOString(),
                source: 'new_game_settings',
                saveFileSaveVersion: NEW_GAME_SETTINGS_SAVE_VERSION,
                playerName: normalizedSettings.playerName || null,
                playerLevel: normalizedSettings.playerLevel,
                startingLocation: normalizedSettings.startingLocation || null,
                currentSettingId: currentSetting?.id || null,
                currentSettingName: currentSetting?.name || null,
                totalAttributes: Object.keys(normalizedSettings.attributes || {}).length,
                totalSkills: Object.keys(normalizedSettings.skills || {}).length
            };

            await fs.promises.mkdir(saveDir, { recursive: false });
            await Utils.writeFileAtomic(settingsPath, JSON.stringify(normalizedSettings, null, 2));
            await Utils.writeFileAtomic(metadataPath, JSON.stringify(metadata, null, 2));

            return {
                saveName,
                saveDir,
                metadata,
                settings: normalizedSettings
            };
        };

        const performNewGameSettingsLoad = (requestedSaveName) => {
            const normalizedName = validateNewGameSettingsSaveName(requestedSaveName);
            const baseDir = resolveBaseDirectory();
            const saveRootPath = resolveNewGameSettingsRootPath(baseDir);
            const saveDir = path.join(saveRootPath, normalizedName);

            if (!fs.existsSync(saveDir)) {
                const error = new Error(`Saved new game settings '${normalizedName}' not found.`);
                error.code = 'SAVE_NOT_FOUND';
                throw error;
            }

            const settingsPath = path.join(saveDir, NEW_GAME_SETTINGS_PAYLOAD_FILENAME);
            if (!fs.existsSync(settingsPath)) {
                const error = new Error(`Save '${normalizedName}' is missing ${NEW_GAME_SETTINGS_PAYLOAD_FILENAME}.`);
                error.code = 'SETTINGS_FILE_MISSING';
                throw error;
            }

            let parsedSettings;
            try {
                const rawSettings = fs.readFileSync(settingsPath, 'utf8');
                parsedSettings = JSON.parse(rawSettings);
            } catch (error) {
                const wrapped = new Error(`Failed to read saved settings '${normalizedName}': ${error.message}`);
                wrapped.code = 'INVALID_NEW_GAME_SETTINGS';
                throw wrapped;
            }
            const normalizedSettings = normalizeNewGameSettingsPayload(parsedSettings);

            const metadataPath = path.join(saveDir, NEW_GAME_SETTINGS_METADATA_FILENAME);
            let metadata = {
                saveName: normalizedName,
                timestamp: null,
                source: 'new_game_settings',
                saveFileSaveVersion: NEW_GAME_SETTINGS_SAVE_VERSION
            };
            if (fs.existsSync(metadataPath)) {
                try {
                    const parsedMetadata = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
                    if (parsedMetadata && typeof parsedMetadata === 'object' && !Array.isArray(parsedMetadata)) {
                        metadata = {
                            ...metadata,
                            ...parsedMetadata,
                            saveName: parsedMetadata.saveName || normalizedName
                        };
                    }
                } catch (error) {
                    const wrapped = new Error(`Failed to read metadata for '${normalizedName}': ${error.message}`);
                    wrapped.code = 'INVALID_NEW_GAME_SETTINGS';
                    throw wrapped;
                }
            }

            return {
                saveName: normalizedName,
                saveDir,
                metadata,
                settings: normalizedSettings
            };
        };

        const listNewGameSettingsSaves = () => {
            const baseDir = resolveBaseDirectory();
            const saveRootPath = resolveNewGameSettingsRootPath(baseDir);
            if (!fs.existsSync(saveRootPath)) {
                return {
                    saves: [],
                    directory: saveRootPath
                };
            }

            const saveDirectories = fs.readdirSync(saveRootPath)
                .filter(item => {
                    const itemPath = path.join(saveRootPath, item);
                    try {
                        return fs.statSync(itemPath).isDirectory();
                    } catch (_) {
                        return false;
                    }
                });

            const saves = saveDirectories.map(saveName => {
                const saveDir = path.join(saveRootPath, saveName);
                const metadataPath = path.join(saveDir, NEW_GAME_SETTINGS_METADATA_FILENAME);
                if (!fs.existsSync(metadataPath)) {
                    const error = new Error(`Saved settings '${saveName}' is missing ${NEW_GAME_SETTINGS_METADATA_FILENAME}.`);
                    error.code = 'SETTINGS_METADATA_MISSING';
                    throw error;
                }

                try {
                    const parsed = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
                    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                        const error = new Error(`Saved settings '${saveName}' has invalid metadata format.`);
                        error.code = 'INVALID_NEW_GAME_SETTINGS';
                        throw error;
                    }
                    return {
                        saveName,
                        timestamp: null,
                        source: 'new_game_settings',
                        saveFileSaveVersion: NEW_GAME_SETTINGS_SAVE_VERSION,
                        playerName: null,
                        playerLevel: null,
                        currentSettingName: null,
                        totalAttributes: null,
                        totalSkills: null,
                        ...parsed,
                        saveName: parsed.saveName || saveName
                    };
                } catch (error) {
                    if (error?.code === 'INVALID_NEW_GAME_SETTINGS') {
                        throw error;
                    }
                    const wrapped = new Error(`Failed to parse metadata for saved settings '${saveName}': ${error.message}`);
                    wrapped.code = 'INVALID_NEW_GAME_SETTINGS';
                    throw wrapped;
                }
            }).sort((a, b) => {
                const first = new Date(a.timestamp || '').getTime();
                const second = new Date(b.timestamp || '').getTime();
                const safeFirst = Number.isFinite(first) ? first : 0;
                const safeSecond = Number.isFinite(second) ? second : 0;
                return safeSecond - safeFirst;
            });

            return {
                saves,
                directory: saveRootPath
            };
        };

        async function processShortDescriptionBackfill() {
            if (shortDescriptionBackfillInProgress) {
                throw new Error('Short description backfill is already in progress.');
            }
            if (!Globals.gameLoaded) {
                throw new Error('Game must be loaded before processing short descriptions.');
            }
            if (typeof Globals.ensureThingShortDescriptions !== 'function') {
                throw new Error('Short description helpers are unavailable (ensureThingShortDescriptions).');
            }
            if (typeof Globals.ensureLocationShortDescriptions !== 'function') {
                throw new Error('Short description helpers are unavailable (ensureLocationShortDescriptions).');
            }
            if (typeof Globals.ensureRegionShortDescriptions !== 'function') {
                throw new Error('Short description helpers are unavailable (ensureRegionShortDescriptions).');
            }
            if (typeof Globals.ensureAbilityShortDescriptions !== 'function') {
                throw new Error('Short description helpers are unavailable (ensureAbilityShortDescriptions).');
            }

            shortDescriptionBackfillInProgress = true;
            try {
                const thingsToCheck = Array.from(things.values());
                const locationsToCheck = Array.from(gameLocations.values());
                const regionsToCheck = Array.from(regions.values());
                const abilityBundles = [];
                const abilitiesToCheck = [];
                for (const player of players.values()) {
                    if (!player || typeof player.getAbilities !== 'function' || typeof player.setAbilities !== 'function') {
                        continue;
                    }
                    const abilities = player.getAbilities();
                    if (!Array.isArray(abilities) || abilities.length === 0) {
                        continue;
                    }
                    abilityBundles.push({ player, abilities });
                    abilitiesToCheck.push(...abilities);
                }

                if (thingsToCheck.length) {
                    await Globals.ensureThingShortDescriptions(thingsToCheck);
                }
                if (locationsToCheck.length) {
                    await Globals.ensureLocationShortDescriptions(locationsToCheck);
                }
                if (regionsToCheck.length) {
                    await Globals.ensureRegionShortDescriptions(regionsToCheck);
                }

                if (abilitiesToCheck.length) {
                    const missingAbilities = abilitiesToCheck.some(ability => !ability?.shortDescription || !String(ability.shortDescription).trim());
                    if (missingAbilities) {
                        await Globals.ensureAbilityShortDescriptions(abilitiesToCheck);
                        for (const bundle of abilityBundles) {
                            bundle.player.setAbilities(bundle.abilities);
                        }
                    }
                }
                updateSaveFileVersionAtLeast(1);
            } finally {
                shortDescriptionBackfillInProgress = false;
            }
        }

        app.post('/api/new-game/settings/save', async (req, res) => {
            try {
                const body = req.body && typeof req.body === 'object' ? req.body : {};
                const { saveName = null, settings = null } = body;
                const result = await performNewGameSettingsSave({
                    requestedSaveName: saveName,
                    settings
                });
                return res.json({
                    success: true,
                    saveName: result.saveName,
                    saveDir: result.saveDir,
                    metadata: result.metadata,
                    message: `New game form settings saved as: ${result.saveName}`
                });
            } catch (error) {
                console.error('Error saving new game form settings:', error);
                const statusCode = (
                    error.code === 'INVALID_NEW_GAME_SETTINGS'
                    || error.code === 'INVALID_SAVE_NAME'
                    || error.code === 'SAVE_ALREADY_EXISTS'
                ) ? 400 : 500;
                return res.status(statusCode).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/new-game/settings/load', (req, res) => {
            try {
                const { saveName = null } = req.body || {};
                const result = performNewGameSettingsLoad(saveName);
                return res.json({
                    success: true,
                    saveName: result.saveName,
                    metadata: result.metadata,
                    settings: result.settings,
                    message: `New game form settings loaded from: ${result.saveName}`
                });
            } catch (error) {
                console.error('Error loading new game form settings:', error);
                let statusCode = 500;
                if (error.code === 'SAVE_NAME_REQUIRED' || error.code === 'INVALID_SAVE_NAME') {
                    statusCode = 400;
                } else if (error.code === 'SAVE_NOT_FOUND' || error.code === 'SETTINGS_FILE_MISSING') {
                    statusCode = 404;
                } else if (error.code === 'INVALID_NEW_GAME_SETTINGS') {
                    statusCode = 400;
                }
                return res.status(statusCode).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.get('/api/new-game/settings/saves', (req, res) => {
            try {
                const result = listNewGameSettingsSaves();
                return res.json({
                    success: true,
                    saves: result.saves,
                    count: result.saves.length,
                    directory: result.directory
                });
            } catch (error) {
                console.error('Error listing new game form settings saves:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.get('/api/mods/manager', (req, res) => {
            try {
                const baseDir = resolveBaseDirectory();
                return res.json({
                    success: true,
                    modState: buildModManagerState(baseDir, { runtimeConfig: config })
                });
            } catch (error) {
                console.error('Error loading mod manager state:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.put('/api/mods/enabled', (req, res) => {
            try {
                const baseDir = resolveBaseDirectory();
                const enabledMods = normalizeEnabledModNames(req.body?.enabledMods, 'enabledMods');
                const updateResult = updateConfigYamlModEnablement(baseDir, enabledMods);
                if (typeof Globals.reloadConfigAndDefs !== 'function') {
                    throw new Error('Globals.reloadConfigAndDefs is not available to reload mod configuration.');
                }
                const reloadResult = Globals.reloadConfigAndDefs({
                    gameConfigOverrideYaml: typeof Globals.getGameConfigOverrideYaml === 'function'
                        ? Globals.getGameConfigOverrideYaml()
                        : '',
                    needBarSentenceValidationMode: 'warn'
                });
                const modState = buildModManagerState(baseDir, { runtimeConfig: config });
                return res.json({
                    success: true,
                    enabledMods: updateResult.enabledMods,
                    modState,
                    reloadResult,
                    restartRequired: modState.restartRequired
                });
            } catch (error) {
                console.error('Error updating enabled mods:', error);
                return res.status(400).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.get('/api/pending-load', (req, res) => {
            try {
                return res.json({
                    success: true,
                    pendingLoad: readPendingLoadIntent(resolveBaseDirectory())
                });
            } catch (error) {
                console.error('Error reading pending load intent:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.delete('/api/pending-load', (req, res) => {
            try {
                const cleared = clearPendingLoadIntent(resolveBaseDirectory());
                return res.json({
                    success: true,
                    cleared
                });
            } catch (error) {
                console.error('Error clearing pending load intent:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/mods/apply-save-config', async (req, res) => {
            try {
                const { saveName, saveType } = req.body || {};
                const normalizedType = typeof saveType === 'string' && saveType.toLowerCase() === 'autosaves'
                    ? 'autosaves'
                    : 'saves';
                const { baseDir, normalizedName, saveDir } = resolveSaveDirForRequest(saveName, normalizedType);
                const metadata = readSaveMetadataFile(saveDir);
                if (!Object.prototype.hasOwnProperty.call(metadata, 'enabledMods')) {
                    const error = new Error('This save does not contain enabled mod metadata; its mod configuration cannot be applied automatically.');
                    error.code = 'SAVE_MOD_METADATA_NOT_FOUND';
                    throw error;
                }
                const savedEnabledMods = normalizeEnabledModNames(metadata.enabledMods, 'save metadata.enabledMods');
                const updateResult = updateConfigYamlModEnablement(baseDir, savedEnabledMods);
                if (typeof Globals.reloadConfigAndDefs !== 'function') {
                    throw new Error('Globals.reloadConfigAndDefs is not available to reload mod configuration.');
                }
                const reloadResult = Globals.reloadConfigAndDefs({
                    gameConfigOverrideYaml: typeof Globals.getGameConfigOverrideYaml === 'function'
                        ? Globals.getGameConfigOverrideYaml()
                        : '',
                    needBarSentenceValidationMode: 'warn'
                });
                const pendingLoad = writePendingLoadIntent(baseDir, {
                    saveName: normalizedName,
                    saveType: normalizedType,
                    reason: 'mod-config-change'
                });
                const modState = buildModManagerState(baseDir, { runtimeConfig: config });
                let restartResult = {
                    started: false,
                    manualRestartRequired: true
                };

                if (config?.server?.allowSelfRestart === true) {
                    if (typeof requestServerRestart !== 'function') {
                        throw new Error('Self restart is enabled, but requestServerRestart is not available.');
                    }
                    restartResult = await requestServerRestart({
                        reason: 'mod-config-change',
                        saveName: normalizedName,
                        saveType: normalizedType
                    });
                }

                return res.json({
                    success: true,
                    enabledMods: updateResult.enabledMods,
                    modState,
                    reloadResult,
                    pendingLoad,
                    restartRequired: true,
                    selfRestartStarted: restartResult?.started === true,
                    manualRestartRequired: restartResult?.started !== true,
                    restartResult
                });
            } catch (error) {
                console.error('Error applying save mod configuration:', error);
                let statusCode = 400;
                if (error.code === 'SAVE_NOT_FOUND') {
                    statusCode = 404;
                } else if (error.code === 'SAVE_METADATA_INVALID') {
                    statusCode = 422;
                }
                return res.status(statusCode).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Save current game state
        app.post('/api/save', async (req, res) => {
            try {
                const result = await performGameSave();
                res.json({
                    success: true,
                    saveName: result.saveName,
                    saveDir: result.saveDir,
                    metadata: result.metadata,
                    message: `Game saved successfully as: ${result.saveName}`
                });
            } catch (error) {
                console.error('Error saving game:', error);
                const statusCode = (error.code === 'NO_PLAYER' || error.code === 'INVALID_SAVE_ROOT') ? 400 : 500;
                res.status(statusCode).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // Load game state from a save
        app.post('/api/load', async (req, res) => {
            try {
                const { saveName, saveType, clientId, modMismatchChoice } = req.body || {};
                const normalizedType = typeof saveType === 'string' && saveType.toLowerCase() === 'autosaves'
                    ? 'autosaves'
                    : 'saves';
                const result = await performGameLoad(saveName, {
                    saveRoot: normalizedType,
                    clientId,
                    modMismatchChoice
                });
                res.json({
                    success: true,
                    saveName: result.saveName,
                    source: normalizedType,
                    metadata: result.metadata,
                    loadedData: result.loadedData,
                    runtimeCancellation: result.runtimeCancellation,
                    message: `Game loaded successfully from: ${result.saveName}`
                });
            } catch (error) {
                console.error('Error loading game:', error);
                let statusCode = 500;
                if (error.code === 'SAVE_NAME_REQUIRED' || error.code === 'INVALID_SAVE_NAME') {
                    statusCode = 400;
                } else if (error.code === 'SAVE_NOT_FOUND') {
                    statusCode = 404;
                } else if (error.code === 'PLAYER_NOT_FOUND') {
                    statusCode = 404;
                } else if (error.code === 'MOD_ENABLEMENT_MISMATCH') {
                    statusCode = 409;
                } else if (error.code === 'GAME_LOAD_IN_PROGRESS') {
                    statusCode = 409;
                } else if (error.code === 'ACTIVE_TURN_DRAIN_TIMEOUT'
                    || String(error?.message || '').includes('Timed out waiting for prompt drain')) {
                    statusCode = 408;
                }
                const responsePayload = {
                    success: false,
                    error: error.message,
                    stack: typeof error?.stack === 'string' ? error.stack : null
                };
                if (error.code === 'MOD_ENABLEMENT_MISMATCH') {
                    responsePayload.code = error.code;
                    responsePayload.modMismatch = error.modMismatch;
                }
                res.status(statusCode).json(responsePayload);
            }
        });

        app.post('/api/turn/cancel-and-rollback', async (req, res) => {
            try {
                const body = req.body && typeof req.body === 'object' ? req.body : {};
                const clientId = typeof body.clientId === 'string' && body.clientId.trim()
                    ? body.clientId.trim()
                    : null;
                const result = await performGameLoad(null, {
                    saveRoot: 'autosaves',
                    clientId,
                    loadLatest: true
                });
                return res.json({
                    success: true,
                    saveName: result.saveName,
                    source: 'autosaves',
                    metadata: result.metadata,
                    loadedData: result.loadedData,
                    runtimeCancellation: result.runtimeCancellation,
                    message: `Stopped active work and restored autosave: ${result.saveName}`
                });
            } catch (error) {
                console.error('Error cancelling turn and restoring latest autosave:', error);
                let statusCode = 500;
                if (error.code === 'AUTOSAVE_NOT_FOUND' || error.code === 'SAVE_NOT_FOUND') {
                    statusCode = 404;
                } else if (error.code === 'GAME_LOAD_IN_PROGRESS') {
                    statusCode = 409;
                } else if (error.code === 'ACTIVE_TURN_DRAIN_TIMEOUT'
                    || String(error?.message || '').includes('Timed out waiting for prompt drain')) {
                    statusCode = 408;
                } else if (error.code === 'MOD_ENABLEMENT_MISMATCH') {
                    statusCode = 409;
                }
                const responsePayload = {
                    success: false,
                    error: error?.message || 'Failed to cancel the turn and restore the latest autosave.',
                    stack: typeof error?.stack === 'string' ? error.stack : null
                };
                if (error.code === 'MOD_ENABLEMENT_MISMATCH') {
                    responsePayload.code = error.code;
                    responsePayload.modMismatch = error.modMismatch;
                }
                return res.status(statusCode).json(responsePayload);
            }
        });

        app.post('/api/summaries/style', async (req, res) => {
            try {
                const { style } = req.body || {};
                const normalized = normalizeSummaryStyle(style);
                if (!normalized) {
                    return res.status(400).json({
                        success: false,
                        error: 'summary style must be "line" or "scene".'
                    });
                }

                const metadata = typeof Globals.getSaveMetadata === 'function'
                    ? Globals.getSaveMetadata()
                    : Globals.saveMetadata;
                if (!metadata || typeof metadata !== 'object') {
                    return res.status(400).json({
                        success: false,
                        error: 'No save metadata available. Load or start a game first.'
                    });
                }

                metadata.summaryStyle = normalized;
                Globals.setSaveMetadata(metadata);

                let persisted = false;
                const saveInfo = typeof Globals.getCurrentSaveInfo === 'function'
                    ? Globals.getCurrentSaveInfo()
                    : Globals.currentSaveInfo;
                if (saveInfo?.saveDir && typeof saveInfo.saveDir === 'string') {
                    if (!fs.existsSync(saveInfo.saveDir)) {
                        throw new Error('Save directory does not exist for metadata update.');
                    }
                    const metadataPath = path.join(saveInfo.saveDir, 'metadata.json');
                    await Utils.writeFileAtomic(metadataPath, JSON.stringify(metadata, null, 2));
                    persisted = true;
                }

                return res.json({
                    success: true,
                    summaryStyle: normalized,
                    persisted
                });
            } catch (error) {
                console.error('Failed to update summary style:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message || 'Failed to update summary style.'
                });
            }
        });

        app.get('/api/short-descriptions/pending', (req, res) => {
            try {
                const clientId = typeof req.query?.clientId === 'string' ? req.query.clientId.trim() : '';
                if (!clientId) {
                    return res.status(400).json({
                        success: false,
                        error: 'clientId is required.'
                    });
                }
                const plan = shortDescriptionBackfillByClient.get(clientId) || null;
                return res.json({
                    success: true,
                    pending: Boolean(plan),
                    plan
                });
            } catch (error) {
                console.error('Error checking short description backfill:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/short-descriptions/process', async (req, res) => {
            try {
                const { clientId, action } = req.body || {};
                const normalizedClientId = typeof clientId === 'string' ? clientId.trim() : '';
                if (!normalizedClientId) {
                    return res.status(400).json({
                        success: false,
                        error: 'clientId is required.'
                    });
                }
                const normalizedAction = typeof action === 'string' ? action.trim().toLowerCase() : '';
                if (!normalizedAction) {
                    return res.status(400).json({
                        success: false,
                        error: 'action is required.'
                    });
                }

                if (normalizedAction === 'skip' || normalizedAction === 'dismiss') {
                    shortDescriptionBackfillByClient.delete(normalizedClientId);
                    return res.json({
                        success: true,
                        skipped: true
                    });
                }

                if (normalizedAction !== 'run' && normalizedAction !== 'process') {
                    return res.status(400).json({
                        success: false,
                        error: 'action must be run or skip.'
                    });
                }

                if (!shortDescriptionBackfillByClient.has(normalizedClientId)) {
                    return res.status(404).json({
                        success: false,
                        error: 'No pending short description backfill for this client.'
                    });
                }
                if (shortDescriptionBackfillInProgress) {
                    return res.status(409).json({
                        success: false,
                        error: 'Short description backfill is already running.'
                    });
                }

                await processShortDescriptionBackfill();
                shortDescriptionBackfillByClient.clear();
                return res.json({
                    success: true,
                    processed: true
                });
            } catch (error) {
                console.error('Error processing short description backfill:', error);
                return res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        // List available saves
        app.get('/api/saves', (req, res) => {
            try {
                let requestedType = req.query?.type;
                if (Array.isArray(requestedType)) {
                    requestedType = requestedType[0];
                }
                const normalizedType = typeof requestedType === 'string'
                    ? requestedType.toLowerCase()
                    : 'saves';

                if (normalizedType !== 'saves' && normalizedType !== 'autosaves') {
                    return res.status(400).json({
                        success: false,
                        error: 'Invalid save type requested'
                    });
                }

                const directoryName = normalizedType === 'autosaves' ? 'autosaves' : 'saves';
                const savesDir = path.join(__dirname, directoryName);

                if (!fs.existsSync(savesDir)) {
                    return res.json({
                        success: true,
                        type: normalizedType,
                        saves: [],
                        count: 0,
                        message: `No ${normalizedType === 'autosaves' ? 'autosaves' : 'saves'} directory found`
                    });
                }

                const saveDirectories = fs.readdirSync(savesDir)
                    .filter(item => {
                        const itemPath = path.join(savesDir, item);
                        try {
                            return fs.statSync(itemPath).isDirectory();
                        } catch (_) {
                            return false;
                        }
                    });

                const saves = saveDirectories.map(saveName => {
                    const saveDir = path.join(savesDir, saveName);
                    const metadataPath = path.join(saveDir, 'metadata.json');

                    const metadata = {
                        saveName: saveName,
                        timestamp: 'Unknown',
                        playerName: 'Unknown',
                        playerLevel: 'Unknown',
                        source: normalizedType,
                        isAutosave: normalizedType === 'autosaves'
                    };

                    if (fs.existsSync(metadataPath)) {
                        try {
                            const metadataContent = JSON.parse(fs.readFileSync(metadataPath, 'utf8'));
                            Object.assign(metadata, metadataContent);
                        } catch (error) {
                            console.error(`Error reading metadata for ${directoryName.slice(0, -1)} ${saveName}:`, error);
                        }
                    }

                    return metadata;
                }).sort((a, b) => {
                    const safeTime = (value) => {
                        const parsed = new Date(value || '').getTime();
                        return Number.isFinite(parsed) ? parsed : 0;
                    };
                    return safeTime(b.timestamp) - safeTime(a.timestamp);
                });

                res.json({
                    success: true,
                    type: normalizedType,
                    saves,
                    count: saves.length,
                    message: `Found ${saves.length} ${normalizedType === 'autosaves' ? 'autosave(s)' : 'save(s)'}`
                });

            } catch (error) {
                console.error('Error listing saves:', error);
                res.status(500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        function createSlashCommandHttpError(message, statusCode = 400) {
            const error = new Error(message);
            error.statusCode = statusCode;
            return error;
        }

        function normalizeSlashCommandRequest(rawRequest = {}) {
            if (!rawRequest || typeof rawRequest !== 'object') {
                throw createSlashCommandHttpError('Slash command request body must be an object.');
            }

            const command = typeof rawRequest.command === 'string'
                ? rawRequest.command.trim()
                : '';
            if (!command) {
                throw createSlashCommandHttpError('Command name is required.');
            }

            const args = (rawRequest.args && typeof rawRequest.args === 'object' && !Array.isArray(rawRequest.args))
                ? { ...rawRequest.args }
                : {};
            const argsText = typeof rawRequest.argsText === 'string' ? rawRequest.argsText : '';
            const userId = typeof rawRequest.userId === 'string' && rawRequest.userId.trim()
                ? rawRequest.userId.trim()
                : null;
            const clientId = typeof rawRequest.clientId === 'string' && rawRequest.clientId.trim()
                ? rawRequest.clientId.trim()
                : null;

            return {
                command,
                args,
                argsText,
                userId,
                clientId
            };
        }

        function resolveSlashCommandInvocation({ command, args = {}, argsText = '', requireUploadHandler = false } = {}) {
            const trimmedCommand = typeof command === 'string' ? command.trim() : '';
            if (!trimmedCommand) {
                throw createSlashCommandHttpError('Command name is required.');
            }

            const CommandModule = SlashCommandRegistry.getSlashCommandModule(trimmedCommand);
            if (!CommandModule) {
                throw createSlashCommandHttpError(`Slash command '${trimmedCommand}' not found.`, 404);
            }
            if (requireUploadHandler && typeof CommandModule.handleUpload !== 'function') {
                throw createSlashCommandHttpError(`Slash command '${trimmedCommand}' does not accept file uploads.`);
            }

            const providedArgs = (args && typeof args === 'object' && !Array.isArray(args))
                ? { ...args }
                : {};

            const argDefinitions = Array.isArray(CommandModule.args) ? CommandModule.args : [];
            if (argsText && argDefinitions.length) {
                const tokens = [];
                const regex = /"([^"]*)"|(\S+)/g;
                let match;
                while ((match = regex.exec(argsText)) !== null) {
                    const value = match[1] !== undefined ? match[1] : match[2];
                    if (value !== undefined) {
                        tokens.push(value);
                    }
                }

                for (const definition of argDefinitions) {
                    const argName = definition?.name;
                    if (!argName) {
                        continue;
                    }
                    if (Object.prototype.hasOwnProperty.call(providedArgs, argName)) {
                        continue;
                    }
                    if (!tokens.length) {
                        break;
                    }
                    const rawToken = tokens.shift();
                    let parsedValue = rawToken;
                    switch ((definition.type || '').toLowerCase()) {
                        case 'integer': {
                            const numeric = Number.parseInt(rawToken, 10);
                            if (!Number.isInteger(numeric)) {
                                throw createSlashCommandHttpError(`Argument "${argName}" must be an integer.`);
                            }
                            parsedValue = numeric;
                            break;
                        }
                        case 'boolean': {
                            const lower = rawToken.trim().toLowerCase();
                            if (lower === 'true') {
                                parsedValue = true;
                            } else if (lower === 'false') {
                                parsedValue = false;
                            } else {
                                throw createSlashCommandHttpError(`Argument "${argName}" must be a boolean.`);
                            }
                            break;
                        }
                        case 'string':
                        default:
                            parsedValue = rawToken;
                            break;
                    }
                    providedArgs[argName] = parsedValue;
                }
            }

            const validationErrors = typeof CommandModule.validateArgs === 'function'
                ? CommandModule.validateArgs(providedArgs)
                : [];
            if (validationErrors.length) {
                const error = createSlashCommandHttpError('Slash command arguments failed validation.');
                error.validationErrors = validationErrors;
                throw error;
            }

            return {
                commandName: trimmedCommand,
                CommandModule,
                providedArgs
            };
        }

        function normalizeSlashCommandReplyAction(rawAction = {}) {
            if (!rawAction || typeof rawAction !== 'object' || Array.isArray(rawAction)) {
                throw new Error('Slash command reply action must be an object.');
            }

            const type = typeof rawAction.type === 'string'
                ? rawAction.type.trim()
                : '';
            if (!type) {
                throw new Error('Slash command reply action type is required.');
            }

            if (type !== 'request_file_upload' && type !== 'reload_page') {
                throw new Error(`Unsupported slash command reply action type "${type}".`);
            }

            const normalized = { type };

            if (type === 'reload_page') {
                if (Object.prototype.hasOwnProperty.call(rawAction, 'delayMs')) {
                    if (!Number.isInteger(rawAction.delayMs) || rawAction.delayMs < 0) {
                        throw new Error('Slash command reply action field "delayMs" must be a non-negative integer.');
                    }
                    normalized.delayMs = rawAction.delayMs;
                }
                return normalized;
            }

            const optionalStringFields = ['title', 'description', 'accept', 'uploadMessage', 'submitLabel', 'cancelLabel'];
            for (const field of optionalStringFields) {
                if (!Object.prototype.hasOwnProperty.call(rawAction, field)) {
                    continue;
                }
                if (typeof rawAction[field] !== 'string') {
                    throw new Error(`Slash command reply action field "${field}" must be a string.`);
                }
                const trimmed = rawAction[field].trim();
                if (trimmed) {
                    normalized[field] = trimmed;
                }
            }

            if (Object.prototype.hasOwnProperty.call(rawAction, 'multiple')) {
                if (typeof rawAction.multiple !== 'boolean') {
                    throw new Error('Slash command reply action field "multiple" must be a boolean.');
                }
                normalized.multiple = rawAction.multiple;
            }

            return normalized;
        }

        function normalizeSlashCommandReplyPayload(payload) {
            if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
                throw new Error('Slash command reply payload must be an object.');
            }

            const normalized = {};
            if (Object.prototype.hasOwnProperty.call(payload, 'content')) {
                if (typeof payload.content !== 'string') {
                    throw new Error('Slash command reply content must be a string.');
                }
                normalized.content = payload.content;
            }
            if (Object.prototype.hasOwnProperty.call(payload, 'ephemeral')) {
                if (typeof payload.ephemeral !== 'boolean') {
                    throw new Error('Slash command reply ephemeral flag must be a boolean.');
                }
                normalized.ephemeral = payload.ephemeral;
            }
            if (Object.prototype.hasOwnProperty.call(payload, 'action')) {
                normalized.action = normalizeSlashCommandReplyAction(payload.action);
            }

            if (!Object.prototype.hasOwnProperty.call(normalized, 'content')
                && !Object.prototype.hasOwnProperty.call(normalized, 'action')) {
                throw new Error('Slash command reply must include content or an action.');
            }

            if (!Object.prototype.hasOwnProperty.call(normalized, 'content')) {
                normalized.content = '';
            }
            if (!Object.prototype.hasOwnProperty.call(normalized, 'ephemeral')) {
                normalized.ephemeral = false;
            }

            return normalized;
        }

        function resolveSlashCommandExecutionOptions(CommandModule) {
            if (!CommandModule || (typeof CommandModule !== 'function' && typeof CommandModule !== 'object')) {
                return { showExecutionOverlay: true };
            }

            const rawShowExecutionOverlay = CommandModule.showExecutionOverlay;
            if (rawShowExecutionOverlay === undefined) {
                return { showExecutionOverlay: true };
            }
            if (typeof rawShowExecutionOverlay !== 'boolean') {
                throw new Error('Slash command showExecutionOverlay metadata must be a boolean.');
            }

            return {
                showExecutionOverlay: rawShowExecutionOverlay
            };
        }

        function normalizeSlashCommandUploads(rawUploads) {
            const uploadEntries = Array.isArray(rawUploads)
                ? rawUploads
                : (rawUploads && typeof rawUploads === 'object' ? [rawUploads] : []);

            return uploadEntries.map((entry, index) => {
                if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
                    throw createSlashCommandHttpError(`Upload entry #${index + 1} must be an object.`);
                }

                const filename = typeof entry.filename === 'string' ? entry.filename.trim() : '';
                if (!filename) {
                    throw createSlashCommandHttpError(`Upload entry #${index + 1} is missing a filename.`);
                }
                if (typeof entry.content !== 'string') {
                    throw createSlashCommandHttpError(`Upload entry "${filename}" is missing string content.`);
                }

                const mimeType = typeof entry.mimeType === 'string' && entry.mimeType.trim()
                    ? entry.mimeType.trim()
                    : null;
                const size = Number.isFinite(entry.size) && entry.size >= 0
                    ? entry.size
                    : null;

                return {
                    filename,
                    content: entry.content,
                    mimeType,
                    size
                };
            });
        }

        function locationContextRepresentsVehicle(location) {
            if (!location || typeof location !== 'object') {
                return false;
            }

            const locationRepresentsVehicle = Boolean(
                location.isVehicle === true
                || (location.vehicleInfo && typeof location.vehicleInfo === 'object' && !Array.isArray(location.vehicleInfo))
            );
            if (locationRepresentsVehicle) {
                return true;
            }

            const sourceRegion = typeof findRegionByLocationId === 'function' && location.id
                ? findRegionByLocationId(location.id)
                : null;
            return Boolean(
                sourceRegion
                && (
                    sourceRegion.isVehicle === true
                    || (sourceRegion.vehicleInfo && typeof sourceRegion.vehicleInfo === 'object' && !Array.isArray(sourceRegion.vehicleInfo))
                )
            );
        }

        function resolveExitTravelTimeForTraversal({ exit, sourceLocation } = {}) {
            if (!exit || typeof exit !== 'object') {
                return 0;
            }
            const travelTimeMinutes = Number(exit.travelTimeMinutes);
            if (!Number.isFinite(travelTimeMinutes) || !Number.isInteger(travelTimeMinutes) || travelTimeMinutes <= 0) {
                return 0;
            }
            if (locationContextRepresentsVehicle(sourceLocation)) {
                return 0;
            }
            return travelTimeMinutes;
        }

        function resolveFastTravelTimeForTraversal({ sourceLocation, destinationLocation } = {}) {
            if (!sourceLocation || !destinationLocation) {
                return 0;
            }

            const shortestTravelTimeMinutes = Location.findShortestTravelTimeMinutes(sourceLocation, destinationLocation);
            if (shortestTravelTimeMinutes === null) {
                return 0;
            }
            if (!Number.isFinite(shortestTravelTimeMinutes) || !Number.isInteger(shortestTravelTimeMinutes) || shortestTravelTimeMinutes < 0) {
                throw new Error('Fast-travel route resolution produced an invalid minute value.');
            }

            return shortestTravelTimeMinutes;
        }

        function resolvemoveTurnResultPlayerMoveTimeMinutes({
            originLocation = null,
            destinationLocation = null,
            promptTravelTimeMinutes = null,
            suppressTimeAdvance = false
        } = {}) {
            if (suppressTimeAdvance || !originLocation || !destinationLocation) {
                return 0;
            }
            if (locationContextRepresentsVehicle(originLocation)) {
                return 0;
            }

            const shortestTravelTimeMinutes = Location.findShortestTravelTimeMinutes(originLocation, destinationLocation);
            if (shortestTravelTimeMinutes !== null && shortestTravelTimeMinutes !== undefined) {
                if (!Number.isFinite(shortestTravelTimeMinutes)
                    || !Number.isInteger(shortestTravelTimeMinutes)
                    || shortestTravelTimeMinutes < 0) {
                    throw new Error('Travel-prose route resolution produced an invalid minute value.');
                }
                return shortestTravelTimeMinutes;
            }

            if (promptTravelTimeMinutes === null || promptTravelTimeMinutes === undefined) {
                return 0;
            }

            const promptMinutes = Number(promptTravelTimeMinutes);
            if (!Number.isFinite(promptMinutes) || !Number.isInteger(promptMinutes) || promptMinutes < 0) {
                throw new Error('Travel-prose prompt travel time must be a non-negative integer minute amount.');
            }
            return promptMinutes;
        }

        function buildFastTravelSummaryItem({
            originLocation,
            destinationLocation,
            travelTimeMinutes,
            includeDuration = true
        } = {}) {
            const advancedMinutes = Number(travelTimeMinutes);
            const hasPositiveDuration = Number.isFinite(advancedMinutes) && advancedMinutes > 0;
            if (includeDuration && !hasPositiveDuration) {
                return null;
            }

            const originName = typeof originLocation?.name === 'string' && originLocation.name.trim()
                ? originLocation.name.trim()
                : null;
            const destinationName = typeof destinationLocation?.name === 'string' && destinationLocation.name.trim()
                ? destinationLocation.name.trim()
                : null;
            if (!originName || !destinationName) {
                return null;
            }

            const durationText = hasPositiveDuration
                ? Utils.formatMinutesAsNaturalDuration(Math.round(advancedMinutes))
                : '';
            if (includeDuration && !durationText) {
                return null;
            }

            const baseDescription = `Traveled from ${originName} to ${destinationName}.`;
            return {
                icon: '🚶',
                description: includeDuration && durationText
                    ? `${baseDescription} ${durationText} passed.`
                    : baseDescription,
                category: 'travel',
                sourceType: 'travel_move'
            };
        }

        async function adjustWorldTimeByMinutes(minutes, {
            source = 'world_time_adjustment',
            emitClientRefresh = false,
            locationRefreshRequested = false,
            clientId = null
        } = {}) {
            const deltaMinutes = Number(minutes);
            if (!Number.isFinite(deltaMinutes) || !Number.isInteger(deltaMinutes)) {
                throw new Error('World-time adjustments require an integer minute amount.');
            }

            const previous = Globals.getWorldTimeContext();
            let timeProgress;
            let vehicleArrivals = [];
            let scheduledEvents = [];
            let statusNeedAdjustments = [];

            if (deltaMinutes >= 0) {
                timeProgress = Globals.advanceTime(deltaMinutes, { source });
                statusNeedAdjustments = Player.applyStatusEffectNeedBarsToAll() || [];
                vehicleArrivals = await processDueVehicleArrivals();
                scheduledEvents = await processDueScheduledEvents({
                    clientId,
                    source
                });
            } else {
                const currentTotalMinutes = Globals.getTotalWorldMinutes();
                const targetTotalMinutes = currentTotalMinutes + deltaMinutes;
                if (targetTotalMinutes < 0) {
                    throw new Error('Cannot rewind time before day 0, 12:00 AM.');
                }

                Globals.elapsedTime = targetTotalMinutes;
                const current = Globals.getWorldTimeContext();
                timeProgress = {
                    source,
                    advancedMinutes: deltaMinutes,
                    transitions: [],
                    previous,
                    current
                };
            }

            const worldTime = buildWorldTimePayload({
                transitions: Array.isArray(timeProgress?.transitions) ? timeProgress.transitions : []
            });
            if (scheduledEvents.some(event => event?.locationRefreshRequested)) {
                locationRefreshRequested = true;
            }

            if (emitClientRefresh) {
                try {
                    Globals.emitToClient(clientId, 'chat_history_updated', {
                        worldTime,
                        locationRefreshRequested
                    });
                } catch (emitError) {
                    console.warn('Failed to emit world-time refresh after adjustment:', emitError?.message || emitError);
                }
            }

            return {
                deltaMinutes,
                timeProgress,
                statusNeedAdjustments,
                vehicleArrivals,
                scheduledEvents,
                worldTime
            };
        }

        async function adjustSlashCommandWorldTimeByMinutes(minutes, { source = 'slash_command_time' } = {}) {
            return adjustWorldTimeByMinutes(minutes, {
                source,
                emitClientRefresh: true,
                locationRefreshRequested: Number(minutes) > 0,
                clientId: null
            });
        }

        async function runSlashCommandQuestCheckPrompt() {
            if (Globals.config?.quest_checks?.enabled !== true) {
                throw new Error('Quest checks are disabled in the current configuration.');
            }
            if (!currentPlayer) {
                throw new Error('Quest checking requires an active player.');
            }

            const activeQuests = Quest.filterActiveQuests(currentPlayer.currentQuests, {
                includePaused: false
            });
            if (!activeQuests.length) {
                throw new Error('There are no active, unpaused quests to check.');
            }

            const response = await Events.runQuestChecks({
                allowWithoutEventChecks: true,
                bypassInterval: true
            });
            if (typeof response !== 'string' || !response.trim()) {
                throw new Error('Quest check prompt did not produce a response.');
            }
            Events.resetQuestCheckTurnCounter();

            const parsedEntries = Events.parseQuestObjectiveStatusXml(response);
            if (!Array.isArray(parsedEntries)) {
                throw new Error('Quest check response did not parse into an objective list.');
            }

            const location = currentPlayer.currentLocation
                ? (Location.get(currentPlayer.currentLocation) || null)
                : null;
            const regionReference = location?.regionId || location?.region || null;
            const region = regionReference && typeof regionReference === 'object'
                ? regionReference
                : (regionReference ? (Region.get(regionReference) || null) : null);
            const processingContext = {
                player: currentPlayer,
                location,
                region,
                stream: null,
                experienceAwards: [],
                currencyChanges: [],
                environmentalDamageEvents: [],
                needBarChanges: [],
                dispositionChanges: [],
                factionStandingChanges: [],
                questCompletionRewards: [],
                questCompletionErrors: [],
                completedQuestObjectives: [],
                followupResults: [],
                allowEnvironmentalEffects: false,
                isNpcTurn: false
            };

            if (parsedEntries.length) {
                await Events.processQuestObjectiveCompletionEntries(
                    parsedEntries,
                    processingContext
                );
            }

            return {
                response,
                parsedEntries,
                completedObjectives: processingContext.completedQuestObjectives,
                rewards: processingContext.questCompletionRewards,
                errors: processingContext.questCompletionErrors,
                experienceAwards: processingContext.experienceAwards,
                currencyChanges: processingContext.currencyChanges,
                dispositionChanges: processingContext.dispositionChanges,
                factionStandingChanges: processingContext.factionStandingChanges,
                followupResults: processingContext.followupResults
            };
        }

        function buildSlashCommandInteractionContext({ userId = null, clientId = null, argsText = '', replies = [] } = {}) {
            const getChatHistory = () => chatHistory;
            const getHistory = (query, startIndexOrOptions = null, countArg = null) => {
                let startIndex = null;
                let count = null;

                if (startIndexOrOptions && typeof startIndexOrOptions === 'object' && !Array.isArray(startIndexOrOptions)) {
                    if (Object.prototype.hasOwnProperty.call(startIndexOrOptions, 'startIndex')) {
                        startIndex = startIndexOrOptions.startIndex;
                    }
                    if (Object.prototype.hasOwnProperty.call(startIndexOrOptions, 'count')) {
                        count = startIndexOrOptions.count;
                    }
                } else {
                    startIndex = startIndexOrOptions;
                    count = countArg;
                }

                return collectHistoryMatches({
                    query,
                    startIndex,
                    count,
                    includeFullContent: true
                }).entries;
            };
            const normalizedClientId = typeof clientId === 'string' && clientId.trim()
                ? clientId.trim()
                : null;
            const requestedClientRefresh = {
                locationRefreshRequested: false,
                relationshipGraphRefreshRequested: false
            };

            return {
                user: { id: userId },
                clientId: normalizedClientId,
                argsText,
                chatHistory,
                getChatHistory,
                getHistory,
                performGameSave,
                currentPlayer,
                adjustWorldTimeByMinutes: adjustSlashCommandWorldTimeByMinutes,
                parseThingsXml: typeof parseThingsXml === 'function' ? parseThingsXml : null,
                findRegionByLocationId: typeof findRegionByLocationId === 'function' ? findRegionByLocationId : null,
                runPlotSummaryPrompt: async ({ parentEntryId = null, locationId = null } = {}) => {
                    const resolvedLocationId = requireLocationId(
                        locationId || currentPlayer?.currentLocation,
                        'runplotsummary slash command'
                    );
                    return runPlotSummaryPrompt({
                        parentEntryId,
                        locationId: resolvedLocationId
                    });
                },
                runPlotExpanderPrompt: async ({
                    parentEntryId = null,
                    locationId = null,
                    specificPlot = null
                } = {}) => {
                    const resolvedLocationId = requireLocationId(
                        locationId || currentPlayer?.currentLocation,
                        'runplotexpander slash command'
                    );
                    return runPlotExpanderPrompt({
                        parentEntryId,
                        locationId: resolvedLocationId,
                        specificPlot
                    });
                },
                runHousekeepingPrompt: async ({ instructions = '' } = {}) => {
                    if (!normalizedClientId) {
                        throw new Error('Housekeeping slash command requires an active client connection.');
                    }
                    const housekeepingStream = createStreamEmitter({
                        clientId: normalizedClientId,
                        requestId: `slash-housekeeping-${randomUUID()}`
                    });
                    return runHousekeepingPrompt({
                        stream: housekeepingStream,
                        housekeepingInstructions: instructions
                    });
                },
                runQuestCheckPrompt: runSlashCommandQuestCheckPrompt,
                runMysteryBoxCleanupPrompt: async () => runMysteryBoxCleanupPrompt({
                    locationOverride: currentPlayer?.currentLocation
                        ? (Location.get(currentPlayer.currentLocation) || null)
                        : null
                }),
                runTonalScaleEvaluationPrompt: async ({ storeChatEntry = false } = {}) => runTonalScaleEvaluationPrompt({
                    locationOverride: currentPlayer?.currentLocation
                        ? (Location.get(currentPlayer.currentLocation) || null)
                        : null,
                    storeChatEntry,
                    clientId: normalizedClientId
                }),
                generateSkillsByNames: typeof generateSkillsByNames === 'function'
                    ? generateSkillsByNames
                    : null,
                generatePlayerImage: typeof generatePlayerImage === 'function'
                    ? generatePlayerImage
                    : null,
                getActiveSettingSnapshot: typeof getActiveSettingSnapshot === 'function'
                    ? getActiveSettingSnapshot
                    : null,
                describeSettingForPrompt: typeof describeSettingForPrompt === 'function'
                    ? describeSettingForPrompt
                    : null,
                backfillRegionExitTravelTimes: typeof backfillRegionExitTravelTimes === 'function'
                    ? backfillRegionExitTravelTimes
                    : null,
                skillRegistry: skills instanceof Map ? skills : null,
                thingRegistry: things instanceof Map ? things : null,
                requestClientRefresh({
                    locationRefreshRequested = false,
                    relationshipGraphRefreshRequested = false
                } = {}) {
                    requestedClientRefresh.locationRefreshRequested = Boolean(
                        requestedClientRefresh.locationRefreshRequested || locationRefreshRequested
                    );
                    requestedClientRefresh.relationshipGraphRefreshRequested = Boolean(
                        requestedClientRefresh.relationshipGraphRefreshRequested || relationshipGraphRefreshRequested
                    );
                },
                getRequestedClientRefresh() {
                    return {
                        locationRefreshRequested: Boolean(requestedClientRefresh.locationRefreshRequested),
                        relationshipGraphRefreshRequested: Boolean(requestedClientRefresh.relationshipGraphRefreshRequested)
                    };
                },
                reply(payload) {
                    replies.push(normalizeSlashCommandReplyPayload(payload));
                    return Promise.resolve();
                }
            };
        }

        app.post('/api/slash-command', async (req, res) => {
            try {
                const request = normalizeSlashCommandRequest(req.body || {});
                const { CommandModule, providedArgs } = resolveSlashCommandInvocation(request);
                const replies = [];
                const executionOptions = resolveSlashCommandExecutionOptions(CommandModule);
                const interaction = buildSlashCommandInteractionContext({
                    userId: request.userId,
                    clientId: request.clientId,
                    argsText: request.argsText,
                    replies
                });

                await CommandModule.execute(interaction, providedArgs);

                const requestedClientRefresh = typeof interaction.getRequestedClientRefresh === 'function'
                    ? interaction.getRequestedClientRefresh()
                    : null;
                if (
                    request.clientId
                    && (
                        requestedClientRefresh?.locationRefreshRequested
                        || requestedClientRefresh?.relationshipGraphRefreshRequested
                    )
                ) {
                    Globals.emitToClient(request.clientId, 'chat_history_updated', {
                        locationRefreshRequested: Boolean(requestedClientRefresh.locationRefreshRequested),
                        relationshipGraphRefreshRequested: Boolean(requestedClientRefresh.relationshipGraphRefreshRequested)
                    });
                }

                return res.json({ success: true, replies, executionOptions });
            } catch (error) {
                console.error('Slash command execution failed:', error);
                if (Array.isArray(error?.validationErrors) && error.validationErrors.length) {
                    return res.status(error.statusCode || 400).json({
                        success: false,
                        errors: error.validationErrors
                    });
                }
                return res.status(error.statusCode || 500).json({
                    success: false,
                    error: error.message
                });
            }
        });

        app.post('/api/slash-command/upload', async (req, res) => {
            try {
                const request = normalizeSlashCommandRequest(req.body || {});
                const uploads = normalizeSlashCommandUploads(req.body?.uploads);
                if (!uploads.length) {
                    throw createSlashCommandHttpError('At least one uploaded file is required.');
                }

                const { CommandModule, providedArgs } = resolveSlashCommandInvocation({
                    ...request,
                    requireUploadHandler: true
                });
                const replies = [];
                const interaction = buildSlashCommandInteractionContext({
                    userId: request.userId,
                    clientId: request.clientId,
                    argsText: request.argsText,
                    replies
                });

                await CommandModule.handleUpload(interaction, providedArgs, uploads);

                return res.json({ success: true, replies });
            } catch (error) {
                console.error('Slash command upload failed:', error);
                if (Array.isArray(error?.validationErrors) && error.validationErrors.length) {
                    return res.status(error.statusCode || 400).json({
                        success: false,
                        errors: error.validationErrors
                    });
                }
                return res.status(error.statusCode || 500).json({
                    success: false,
                    error: error.message
                });
            }
        });

